// File: sagemaker.tf
resource "aws_sagemaker_notebook_instance" "privesc-sagemakerNotebook" {
  name          = "privesc-sagemakerNotebook"
  role_arn      = aws_iam_role.privesc-sagemaker-role.arn
  instance_type = "ml.t2.medium"

  tags = {
    Name = "foo"
  }
}


resource "aws_iam_role" "privesc-sagemaker-role" {
  name               = "privesc-sagemaker-role"
  assume_role_policy = data.aws_iam_policy_document.example.json
}

data "aws_iam_policy_document" "example" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["sagemaker.amazonaws.com"]
    }
  }
}


resource "aws_iam_policy" "privesc-high-priv-sagemaker-policy" {
  name        = "privesc-high-priv-sagemaker-policy2"
  path        = "/"
  description = "High priv policy used by sagemaker"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "*"
        Effect   = "Allow"
        Resource = "*"
      },
    ]
  })
}


resource "aws_iam_role_policy_attachment" "example-AWSSagemakerServiceRole" {
  policy_arn = aws_iam_policy.privesc-high-priv-sagemaker-policy.arn
  role       = aws_iam_role.privesc-sagemaker-role.name
}

// File: variables.tf
variable "aws_assume_role_arn" {
  description = "This is the arn of an already existing principal that can assume into any roles that are created"
  type        = string
  default     = ""
}

// File: server_side_encryption_enabled.tf
# Test that server side encryption is used with a KMS key and aws:kms algorithm
# https://www.terraform.io/docs/providers/aws/r/s3_bucket.html#kms_master_key_id
# https://www.terraform.io/docs/providers/aws/r/s3_bucket.html#sse_algorithm

provider "aws" {
  region = "us-east-1"
}

# Setup Helper
resource "aws_kms_key" "test_key" {
}

# PASS: A KMS key is provided and sse_algorithm is aws:kms
resource "aws_s3_bucket" "server_side_encryption_configuration_set" {
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        kms_master_key_id = aws_kms_key.test_key.arn
        sse_algorithm     = "aws:kms"
      }
    }
  }
}

# WARN: No KMS key is specified
resource "aws_s3_bucket" "server_side_encryption_configuration_set_no_key" {
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "aws:kms"
      }
    }
  }
}

# WARN: No KMS key is specified
resource "aws_s3_bucket" "server_side_encryption_configuration_set_no_key_aes256" {
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

# FAIL: No server_side_encryption_configuration provided
# WARN: kms_master_key_id and sse_algorithm not set
resource "aws_s3_bucket" "server_side_encryption_configuration_not_set" {
}

