// File: main.tf
terraform {
  required_version = ">= 1.1.0"
}

provider "aws" {
  region = "eu-north-1"
}

data "aws_caller_identity" "current" {}

locals {
  aws_account = data.aws_caller_identity.current.account_id
}

resource "aws_s3_bucket" "bucket2" {
  bucket = "${data.aws_caller_identity.current.account_id}-bucket2"
}

output "bucket2" {
  value = aws_s3_bucket.bucket2.bucket
}

resource "aws_s3_bucket" "bucketX" {
  count  = 2
  bucket = "${data.aws_caller_identity.current.account_id}-bucket${count.index + 3}"
}

output "bucketX" {
  value = ["${aws_s3_bucket.bucketX.*.bucket}"]
}

locals {
  buckets = {
    bucket101 = "bucket101"
    bucket102 = "bucket102"
  }
}

resource "aws_s3_bucket" "bucketE" {
  for_each = local.buckets
  bucket   = "${local.aws_account}-${each.value}"
}

output "bucketE" {
    value = toset([
        for bucketE in aws_s3_bucket.bucketE : bucketE.bucket
    ])
}

locals {
  bucketlist = [
      "bucket103",
      "bucket104"
  ]
}

resource "aws_s3_bucket" "bucketL" {
  for_each = toset(local.bucketlist)
  bucket = "${local.aws_account}-${each.key}"
}

output "bucketL" {
    value = toset([
        for bucketL in aws_s3_bucket.bucketL : bucketL.bucket
    ])
}

// File: ecr.tf
resource "aws_ecr_repository" "repo" {
  name                 = "reactjs-app-repo"
  image_tag_mutability = "MUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }
}

// File: iamRole.tf
resource "aws_iam_role" "ecsTaskExecutionRole" {
  name               = "ecsTaskExecutionRole"
  assume_role_policy = data.aws_iam_policy_document.assume_role_policy.json
}

data "aws_iam_policy_document" "assume_role_policy" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role_policy_attachment" "ecsTaskExecutionRole_policy" {
  role       = aws_iam_role.ecsTaskExecutionRole.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

// File: main.tf
resource "aws_ecr_repository" "main" {
  name                 = var.ecr_repository_name
  image_tag_mutability = "MUTABLE"

  image_scanning_configuration {
    scan_on_push = false
  }
  tags = var.tags
}

resource "aws_ecr_lifecycle_policy" "main" {
  repository = aws_ecr_repository.main.name

  policy = <<EOF
{
    "rules": [
        {
            "rulePriority": 1,
            "description": "Expire images older than 14 days",
            "selection": {
                "tagStatus": "untagged",
                "countType": "sinceImagePushed",
                "countUnit": "days",
                "countNumber": 14
            },
            "action": {
                "type": "expire"
            }
        },
        {
            "rulePriority": 2,
            "description": "Keep last 30 images",
            "selection": {
                "tagStatus": "any",
                "countType": "imageCountMoreThan",
                "countNumber": 30
            },
            "action": {
                "type": "expire"
            }
        }
    ]
}
EOF
}

// File: outputs.tf
output "repository_url" {
  value = aws_ecr_repository.main.repository_url
}

output "registry_id" {
  value = aws_ecr_repository.main.registry_id
}

// File: variables.tf
variable "ecr_repository_name" {
  description = "ECR repository name"
  type = string
  default = "illumidesk"
}

variable "tags" {
  description = "Tags for resources"
  type        = map(string)
  default     = {
    Name    = "illumidesk-eks"
    Environment = "dev"
  }
}

// File: main.tf
locals {
  create_instance          = var.create_instance
  create_ami_from_instance = var.create_ami_from_instance
}

data "aws_ami" "amazon-linux" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023*kernel-6.1-x86_64"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

resource "aws_instance" "terraform" {
  count         = local.create_instance ? 1 : 0
  ami           = data.aws_ami.amazon-linux.id
  instance_type = var.instance_type

  tags = {
    Name       = "terraform-instance"
    created_by = "mohammad"
  }
}

resource "aws_ami_from_instance" "my_own_ami" {
  count              = local.create_instance && local.create_ami_from_instance ? 1 : 0
  name               = "my-own-ami"
  source_instance_id = aws_instance.terraform[0].id
}

// File: variables.tf
variable "create_instance" {
  type    = bool
  default = true
}

variable "create_ami_from_instance" {
  type    = bool
  default = true
}

variable "instance_type" {
  type    = string
  default = "t2.micro"
}

// File: versions.tf
terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.20"
    }
  }
}

// File: main.tf
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
locals {
  account_id  = data.aws_caller_identity.current.account_id
  region      = data.aws_region.current.name

  tags = {
    team     = "devops"
    solution = "jenkins"
  }
}

resource "aws_s3_bucket" "this" {
  bucket = var.state_bucket_name

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm     = "AES256"
      }
    }
  }

  versioning {
    enabled = true
  }

  tags = local.tags
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_dynamodb_table" "this" {
  name = var.state_lock_table_name
  hash_key = "LockID"
  billing_mode     = "PAY_PER_REQUEST"

  attribute {
    name = "LockID"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  # tags {
  #   Name = "DynamoDB Terraform State Lock Table"
  # }
}

// File: outputs.tf
output s3_state_bucket_name {
  value       = aws_s3_bucket.this.id
  description = "S3 state bucket name"
}

output dynamodb_state_lock_table_name {
  value       = aws_dynamodb_table.this.id
  description = "Dynamodb state lock table name"
}

// File: variables.tf
variable state_bucket_name {
  type    = string
  # A random bucket name by default
  default = "jenkins-fargate-demo" 
}

variable state_lock_table_name {
  type    = string
  default = "tf-serverless-jenkins-lock"
}

// File: main.tf
provider "aws" {
  region = var.aws_region
}

resource "aws_vpc" "main_vpc" {
  cidr_block = var.vpc_cidr_block
  enable_dns_support = true
  enable_dns_hostnames = true
  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "main_subnet" {
  count = length(var.subnet_cidr_blocks)
  vpc_id = aws_vpc.main_vpc.id
  cidr_block = element(var.subnet_cidr_blocks, count.index)
  availability_zone = element(var.availability_zones, count.index)
  tags = {
    Name = "main-subnet-${count.index}"
  }
}

// File: outputs.tf
output "vpc_id" {
  value = aws_vpc.main_vpc.id
}

output "subnet_ids" {
  value = aws_subnet.main_subnet[*].id
}

// File: variables.tf
variable "aws_region" {
  description = "The AWS region to deploy to"
  type = string
  default = "us-east-1"
}

variable "vpc_cidr_block" {
  description = "The CIDR block for the VPC"
  type = string
  default = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "List of CIDR blocks for the subnets"
  type = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "availability_zones" {
  description = "List of availability zones for the subnets"
  type = list(string)
  default = ["us-east-1a", "us-east-1b"]
}

// File: main.tf
resource "aws_api_gateway_rest_api" "this" {
  name        = "HelloWorldAPI"
  description = "API Gateway for Hello World Lambda"
}

resource "aws_api_gateway_resource" "this" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  parent_id   = aws_api_gateway_rest_api.this.root_resource_id
  path_part   = "hello"
}

resource "aws_api_gateway_method" "this" {
  rest_api_id   = aws_api_gateway_rest_api.this.id
  resource_id   = aws_api_gateway_resource.this.id
  http_method   = "ANY"
  authorization = "NONE"
}

// File: outputs.tf
output "api_gateway_rest_api_id" {
  value = aws_api_gateway_rest_api.this.id
}

output "api_gateway_resource_id" {
  value = aws_api_gateway_resource.this.id
}

output "api_gateway_resource_path" {
  value = aws_api_gateway_resource.this.path
}

output "api_gateway_http_method" {
  value = aws_api_gateway_method.this.http_method
}

output "api_gateway_rest_api_execution_arn" {
  value = aws_api_gateway_rest_api.this.execution_arn
}

// File: versions.tf
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.64"
    }
  }

  required_version = "< 2"
}

provider "aws" {
  # we set AWS_PROFILE from the command line
}

// File: main.tf
provider "aws" {
  shared_config_files      = ["~/.aws/config"]
  shared_credentials_files = ["~/.aws/credentials"]
}

resource "aws_vpc" "fis-vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "public_subnet" {
  cidr_block = "10.0.1.0/24"
  vpc_id     = aws_vpc.fis-vpc.id
}

resource "aws_subnet" "private_subnet" {
  cidr_block = "10.0.2.0/24"
  vpc_id     = aws_vpc.fis-vpc.id
}

// Create an internet gateway to allow the VPC to connect to the internet
resource "aws_internet_gateway" "fis_public_internet_gateway" {
  vpc_id = aws_vpc.fis-vpc.id
}

// Create a route table for the public subnet to route traffic to the internet gateway
resource "aws_route_table" "fis_public_subnet_route_table" {
  vpc_id = aws_vpc.fis-vpc.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.fis_public_internet_gateway.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.fis_public_internet_gateway.id
  }
}

