// File: main.tf
terraform {
  required_version = ">= 1.0.0, < 2.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-2"
}

# Create a KMS Customer Managed Key (CMK)
resource "aws_kms_key" "cmk" {
  policy = data.aws_iam_policy_document.cmk_admin_policy.json

  # We set a short deletion window, as these keys are only used
  # for testing/learning, and we want to minimize the AWS charges
  deletion_window_in_days = 7
}

# A simple policy that makes the current IAM user the admin
# of the CMK
data "aws_iam_policy_document" "cmk_admin_policy" {
  statement {
    effect    = "Allow"
    resources = ["*"]
    actions   = ["kms:*"]
    principals {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.self.arn]
    }
  }
}

# Look up the details of the current user
data "aws_caller_identity" "self" {}

# Create an alias for the CMK
resource "aws_kms_alias" "cmk" {
  name          = "alias/${var.alias}"
  target_key_id = aws_kms_key.cmk.id
}

// File: outputs.tf
output "cmk_arn" {
  value       = aws_kms_key.cmk.arn
  description = "The ARN of the CMK"
}

output "cmk_alias" {
  value       = aws_kms_alias.cmk.name
  description = "The alias of the CMK"
}

// File: variables.tf
# ---------------------------------------------------------------------------------------------------------------------
# OPTIONAL PARAMETERS
# These parameters have reasonable defaults.
# ---------------------------------------------------------------------------------------------------------------------

variable "alias" {
  description = "The alias to use for the CMK"
  type        = string
  default     = "kms-cmk-example"
}

// File: data.tf
data "aws_iam_policy_document" "deployment_group_role_policy" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["codedeploy.amazonaws.com"]
    }
  }
}

// File: main.tf
resource "aws_codedeploy_app" "codedeploy_app" {
  name             = "nightscout__deploy_app"
  compute_platform = "Server"
  tags             = var.tags
}

resource "aws_iam_role" "codedeploy_role" {
  name               = "nightscout__codedeploy_role"
  tags               = var.tags
  description        = "Allow CodeDeploy to adopt role"
  assume_role_policy = data.aws_iam_policy_document.deployment_group_role_policy.json
}

resource "aws_iam_role_policy_attachment" "attach_codedeploy_role" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeDeployRole"
  role       = aws_iam_role.codedeploy_role.name
}

resource "aws_codedeploy_deployment_group" "codedeploy_group" {
  app_name              = aws_codedeploy_app.codedeploy_app.name
  deployment_group_name = "nightscout__deployment_group"
  service_role_arn      = aws_iam_role.codedeploy_role.arn

  ec2_tag_set {
    ec2_tag_filter {
      key   = "env"
      type  = "KEY_AND_VALUE"
      value = "prod"
    }

    ec2_tag_filter {
      key   = "app"
      type  = "KEY_AND_VALUE"
      value = "nightscout"
    }
  }


  auto_rollback_configuration {
    enabled = true
    events  = ["DEPLOYMENT_FAILURE"]
  }
}

// File: outputs.tf
output "app_name" {
  value = "${aws_codedeploy_app.codedeploy_app.name}"
}

// File: variables.tf
variable "tags" {
  type        = map(string)
  default     = {}
  description = "tags for all the resources, if any"
}

// File: s3-bucket.tf
resource "aws_s3_bucket" "artifactory_s3_bucket" {
  bucket = "ashrafk-artifactory-bucket"

  tags = {
    provisioned_by = "terraform"
  }
}

resource "aws_s3_bucket_ownership_controls" "artifactory_s3_ownership" {
  bucket = aws_s3_bucket.artifactory_s3_bucket.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "artifactory_s3_acl" {
  depends_on = [aws_s3_bucket_ownership_controls.artifactory_s3_ownership]
  bucket = aws_s3_bucket.artifactory_s3_bucket.id
  acl    = "private"
}

// File: s3-iam-role.tf
resource "aws_iam_role" "artifactory-s3-full-access" {
  name = "eks-pod-s3-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Action = "sts:AssumeRoleWithWebIdentity",
        Effect = "Allow",
        Principal = {
          Federated = "<YOUR-EKS-OIDC>" // Replace with OIDC of your EKS
        },
        Condition = {
          StringEquals = {
            "<YOUR-EKS-OIDC>": [ // Replace with OIDC of your EKS
                "sts.amazonaws.com"
            ]
          }
        }
      }
    ]
  })

  tags = {
    provisioned_by = "terraform"
  }
}

resource "aws_iam_policy" "s3_full_access_policy" { 
  name        = "s3_full_access_policy"
  description = "Policy for full S3 access"
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Action   = "s3:*",
        Effect   = "Allow",
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "s3_full_access_attachment" {
  policy_arn = aws_iam_policy.s3_full_access_policy.arn
  role = aws_iam_role.artifactory-s3-full-access.name
}

// File: sqs.tf
provider "aws" {
  region = "ap-northeast-2"
}

data "aws_caller_identity" "current" {}

# Define the SQS queue
resource "aws_sqs_queue" "notification_queue" {
  name                       = "notificationQueue"
  delay_seconds              = 0
  max_message_size           = 2048
  message_retention_seconds  = 345600
  visibility_timeout_seconds = 30
}

resource "aws_sqs_queue_policy" "sqs_policy" {
  queue_url = aws_sqs_queue.notification_queue.id
  policy    = data.aws_iam_policy_document.sqs_policy_document.json
}

data "aws_iam_policy_document" "sqs_policy_document" {
  statement {
    sid    = "sqs_policy"
    effect = "Allow"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions   = ["sqs:*"]
    resources = [aws_sqs_queue.notification_queue.arn]
  }
}

// File: main.tf
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "role" {
  name = "role"

  assume_role_policy = <<EOF
    {
      "Version": "2012-10-17",
      "Statement": [
        {
          "Action": "sts:AssumeRole",
          "Principal": {
            "Service": "ec2.amazonaws.com"
          },
          "Effect": "Allow",
          "Sid": ""
        }
      ]
    }
EOF
}

resource "aws_iam_role_policy" "allow-policy-1" {
  name = "allow-policy-1"
  role = aws_iam_role.role.id

  policy = <<-EOF
  {
    "Version": "2012-10-17",
    "Statement": [
      {
        "Action": [
          "iam:passrole"
        ],
        "Effect": "Allow",
        "Resource": "*"
      }
    ]
  }
  EOF
}

resource "aws_iam_role_policy" "allow-policy-2" {
  name = "allow-policy-2"
  role = aws_iam_role.role.id

  policy = <<-EOF
  {
    "Version": "2012-10-17",
    "Statement": [
      {
        "Action": [
          "lambda:createfunction", "lambda:invokefunc*"
        ],
        "Effect": "Allow",
        "Resource": "*"
      }
    ]
  }
  EOF
}

