// File: main.tf
provider "aws" {
}

locals {
  bucket_name      = "transition-bucket-${random_string.this.id}"
  logs_bucket_name = "transition-bucket-logs-${random_string.this.id}"
}

data "aws_caller_identity" "current" {}

# data "aws_canonical_user_id" "current" {}

resource "random_string" "this" {
  length  = 5
  special = false
  upper   = false
}

resource "aws_kms_key" "bucket_objects_key" {
  #TODO: Need to bring in the upstream KMS module here as a source
  #checkov:skip=CKV2_AWS_64: Ensure KMS key Policy is defined
  description             = "KMS key is used to encrypt bucket objects"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

#checkov:skip=CKV_TF_2: "Ensure Terraform module sources use a tag with a version number"
module "logs_bucket" {
  #checkov:skip=CKV_TF_2: "Ensure Terraform module sources use a tag with a version number"
  # tflint-ignore: terraform_module_pinned_source
  source = "github.com/star3am/terraform-modules-library//terraform/aws/modules/terraform-aws-s3-bucket?ref=main"
  #checkov:skip=CKV_AWS_18: Ensure the S3 bucket has access logging enabled
  #checkov:skip=CKV2_AWS_61: Ensure that an S3 bucket has a lifecycle configuration
  #checkov:skip=CKV_TF_1: Ensure Terraform module sources use a commit hash
  #tfsec:ignore:aws-s3-encryption-customer-key

  bucket = local.logs_bucket_name

  force_destroy = true

  control_object_ownership = true

  # object_ownership = "BucketOwnerPreferred"

  expected_bucket_owner = data.aws_caller_identity.current.account_id

  # attach_policy                         = true
  attach_deny_insecure_transport_policy = true
  attach_require_latest_tls_policy      = true
  attach_access_log_delivery_policy     = true

  access_log_delivery_policy_source_accounts = [data.aws_caller_identity.current.account_id]
  access_log_delivery_policy_source_buckets  = ["arn:aws:s3:::${local.bucket_name}"]

  allowed_kms_key_arn = aws_kms_key.bucket_objects_key.arn

  server_side_encryption_configuration = {
    rule = {
      apply_server_side_encryption_by_default = {
        kms_master_key_id = aws_kms_key.bucket_objects_key.arn
        sse_algorithm     = "aws:kms"
      }
    }
  }

}

#checkov:skip=CKV_TF_2: "Ensure Terraform module sources use a tag with a version number"
module "transition_bucket" {
  # tflint-ignore: terraform_module_pinned_source
  source = "github.com/star3am/terraform-modules-library//terraform/aws/modules/terraform-aws-s3-bucket?ref=main"
  #checkov:skip=CKV_AWS_18: Ensure the S3 bucket has access logging enabled
  #checkov:skip=CKV2_AWS_61: Ensure that an S3 bucket has a lifecycle configuration
  #checkov:skip=CKV_TF_1: Ensure Terraform module sources use a commit hash
  #tfsec:ignore:aws-s3-encryption-customer-key

  bucket = local.bucket_name

  force_destroy = true

  control_object_ownership = true

  # object_ownership = "BucketOwnerPreferred"

  expected_bucket_owner = data.aws_caller_identity.current.account_id

  # attach_policy                            = true
  attach_deny_insecure_transport_policy    = true
  attach_require_latest_tls_policy         = true
  attach_deny_incorrect_encryption_headers = true
  attach_deny_incorrect_kms_key_sse        = true
  attach_deny_unencrypted_object_uploads   = true

  allowed_kms_key_arn = aws_kms_key.bucket_objects_key.arn

  logging = {
    target_bucket = module.logs_bucket.s3_bucket_id
    target_prefix = "log/"
    target_object_key_format = {
      partitioned_prefix = {
        partition_date_source = "DeliveryTime" # "EventTime"
      }
      # simple_prefix = {}
    }
  }

  versioning = {
    status     = true
    mfa_delete = false
  }

  lifecycle_rule = [
    {
      id                                     = "object_lifecycle_1"
      enabled                                = true
      abort_incomplete_multipart_upload_days = 7

      noncurrent_version_transition = [
        {
          days          = 90
          storage_class = "STANDARD_IA"
        },
        {
          days          = 180
          storage_class = "ONEZONE_IA"
        },
        {
          days          = 360
          storage_class = "GLACIER"
        },
      ]

      noncurrent_version_expiration = {
        days = 390
      }
    },
  ]

  server_side_encryption_configuration = {
    rule = {
      apply_server_side_encryption_by_default = {
        kms_master_key_id = aws_kms_key.bucket_objects_key.arn
        sse_algorithm     = "aws:kms"
      }
    }
  }

}

// File: versions.tf
terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.27"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.6.0"
    }
  }
}

// File: main.tf
# Get Availability Zones
resource "tls_private_key" "key" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "random_pet" "key_prefix" {}

# Create a Key Pair
resource "aws_key_pair" "key_pair" {
  key_name   = "${var.key_prefix}-${random_pet.key_prefix.id}"
  public_key = tls_private_key.key.public_key_openssh

  provisioner "local-exec" {
    command = <<-EOT
      echo "${tls_private_key.key.private_key_pem}" > ../"${var.key_prefix}-${random_pet.key_prefix.id}".pem
      chmod 600 ../"${var.key_prefix}-${random_pet.key_prefix.id}".pem
    EOT
  }
}

// File: outputs.tf
output "key_name" {
  value = aws_key_pair.key_pair.key_name
}

output "key_id" {
  value = aws_key_pair.key_pair.id
}

// File: variables.tf
variable "key_prefix" {
  default = "key"
}

// File: i.tf
provider "aws" {
  region = "ap-northeast-1"
}

resource "aws_route53_zone" "inkaku_ink" {
  name = "inkaku.ink"
}

resource "aws_s3_bucket" "inkaku_ink" {
  bucket        = "inkaku.ink"
  acl           = "public-read"
  force_destroy = true

  website {
    index_document = "index.html"
    error_document = "error.html"
  }

  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "",
      "Effect": "Allow",
      "Principal": {
        "AWS": "*"
      },
      "Action": "s3:GetObject",
      "Resource": "arn:aws:s3:::inkaku.ink/*"
    }
  ]
}
EOF
}

resource "aws_route53_record" "inkaku_ink_root" {
  zone_id = "${aws_route53_zone.inkaku_ink.zone_id}"
  name    = "inkaku.ink"
  type    = "A"

  alias {
    name                   = "${aws_s3_bucket.inkaku_ink.website_domain}"
    zone_id                = "${aws_s3_bucket.inkaku_ink.hosted_zone_id}"
    evaluate_target_health = false
  }
}

// File: main.tf
variable "enable" {
  description = "Whether to create the resources in the module"
  type        = bool
  default     = true
}

variable "create_aws_key" {
  type    = bool
  default = false
}

resource "tls_private_key" "some_key" {
  count = var.enable ? 1 : 0

  algorithm   = "ECDSA"
  ecdsa_curve = "P384"
}

resource "local_file" "priv_key_on_disk" {
  count = var.enable ? 1 : 0

  filename          = "${local.ssh_dir}/priv-key.pem"
  sensitive_content = local.private_key
  file_permission   = "0400"
}

resource "local_file" "pub_key_on_disk" {
  count = var.enable ? 1 : 0

  filename          = "${local.ssh_dir}/pub-key.pem"
  sensitive_content = local.public_key
  file_permission   = "0600"
}

resource "aws_key_pair" "some_key_pair" {
  count = var.enable && var.create_aws_key ? 1 : 0

  key_name   = "some-key"
  public_key = local.public_key
}

output "fingerprint" {
  value = local.fingerprint
}

output "aws_key_id" {
  value = local.aws_key_id
}

locals {
  home_dir = pathexpand("~")
  ssh_dir  = "${local.home_dir}/.ssh"

  aws_key_id = join("", aws_key_pair.some_key_pair.*.id)

  public_key  = try(tls_private_key.some_key[0].public_key_pem, "NA")
  private_key = try(tls_private_key.some_key[0].private_key_pem, "NA")
  fingerprint = try(tls_private_key.some_key[0].public_key_fingerprint_md5, "NA")
}

// File: kms.tf
data "aws_caller_identity" "current" {}

resource "aws_kms_key" "foo_kms" {
  description              = "KMS key template"
  deletion_window_in_days  = 10
  customer_master_key_spec = "SYMMETRIC_DEFAULT" # Must be configured
  key_usage                = "ENCRYPT_DECRYPT"
  # SaC Testing - Severity: Critical - Set enable_key_rotation to false
  enable_key_rotation      = false
  is_enabled               = true
  policy = <<POLICY
  {
  "Version": "2012-10-17",
  "Statement": [
    {
      "Action": [
        "*"
      ],
      "Effect": "Allow",
      "Principal": {
        "AWS": [
          "*"
        ]
      },
      "Resource": [
        "*"
      ]
    }
  ]
}
POLICY
}

resource "aws_kms_alias" "foo_kms" {
  # All options # Must be configured
  name          = "alias/bar"
  target_key_id = aws_kms_key.foo_kms.id
}

// File: main.tf
provider "aws" {
  region = "us-east-1"
}

locals {
  cidr_block       = "10.0.0.0/24"
}


resource "aws_vpc" "vpc" {
  cidr_block = local.cidr_block

}

resource "aws_security_group" "default" {
  name        = "examplerulename"
  vpc_id      = aws_vpc.vpc.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/24"]
    description = "ingress"
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
    description = "egress"
  }

  tags = {
    Name = "example_rule_with_descriptions"
  }
}

resource "aws_subnet" "subnet" {
  vpc_id     = aws_vpc.vpc.id
  cidr_block = local.cidr_block

}


data "aws_ami" "ubuntu" {
  most_recent = true

  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-xenial-16.04-amd64-server-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  owners = ["099720109477"] # Canonical
}

resource "aws_instance" "ec2" {
  ami = data.aws_ami.ubuntu.id
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.subnet.id
  vpc_security_group_ids  = [aws_security_group.default.id]

}

