// File: cloudwatch_metric_alarm_test.tf
provider "aws" {
  region                      = "us-east-1"
  skip_credentials_validation = true
  skip_requesting_account_id  = true
  access_key                  = "mock_access_key"
  secret_key                  = "mock_secret_key"
}

resource "aws_cloudwatch_metric_alarm" "standard" {
  alarm_name                = "terraform-test-alarm"
  comparison_operator       = "GreaterThanOrEqualToThreshold"
  evaluation_periods        = "2"
  metric_name               = "CPUUtilization"
  namespace                 = "AWS/EC2"
  period                    = "120"
  statistic                 = "Average"
  threshold                 = "80"
  alarm_description         = "This metric monitors ec2 cpu utilization"
  insufficient_data_actions = []
}

resource "aws_cloudwatch_metric_alarm" "high" {
  alarm_name                = "terraform-test-alarm"
  comparison_operator       = "GreaterThanOrEqualToThreshold"
  evaluation_periods        = "1"
  metric_name               = "CPUUtilization"
  namespace                 = "AWS/EC2"
  period                    = "10"
  statistic                 = "Average"
  threshold                 = "80"
  alarm_description         = "This metric monitors ec2 cpu utilization"
  insufficient_data_actions = []
}

resource "aws_cloudwatch_metric_alarm" "expression" {
  alarm_name                = "terraform-test-expression"
  comparison_operator       = "GreaterThanOrEqualToThreshold"
  evaluation_periods        = "2"
  threshold                 = "10"
  alarm_description         = "Request error rate has exceeded 10%"
  insufficient_data_actions = []

  metric_query {
    id          = "e1"
    expression  = "m2/m1*100"
    label       = "Error Rate"
    return_data = "true"
  }

  metric_query {
    id = "m1"

    metric {
      metric_name = "RequestCount"
      namespace   = "AWS/ApplicationELB"
      period      = "120"
      stat        = "Sum"
      unit        = "Count"

      dimensions = {
        LoadBalancer = "app/web"
      }
    }
  }

  metric_query {
    id = "m2"

    metric {
      metric_name = "HTTPCode_ELB_5XX_Count"
      namespace   = "AWS/ApplicationELB"
      period      = "120"
      stat        = "Sum"
      unit        = "Count"

      dimensions = {
        LoadBalancer = "app/web"
      }
    }
  }
}

resource "aws_cloudwatch_metric_alarm" "anomaly_detection" {
  alarm_name                = "terraform-test-foobar"
  comparison_operator       = "GreaterThanUpperThreshold"
  evaluation_periods        = "2"
  threshold_metric_id       = "e1"
  alarm_description         = "This metric monitors ec2 cpu utilization"
  insufficient_data_actions = []

  metric_query {
    id          = "e1"
    expression  = "ANOMALY_DETECTION_BAND(m1)"
    label       = "CPUUtilization (Expected)"
    return_data = "true"
  }

  metric_query {
    id          = "m1"
    return_data = "true"
    metric {
      metric_name = "CPUUtilization"
      namespace   = "AWS/EC2"
      period      = "30"
      stat        = "Average"
      unit        = "Count"

      dimensions = {
        InstanceId = "i-abc123"
      }
    }
  }
}

// File: main.tf
resource "aws_iam_role" "this" {
  assume_role_policy = data.aws_iam_policy_document.trust.json
  name               = var.name

  tags = merge(
    var.tags,
    { "grafana.workspace.${var.grafana_workspace_name}" = "true" }
  )
}

resource "aws_iam_role_policy_attachment" "grafana" {
  policy_arn = aws_iam_policy.grafana.arn
  role       = aws_iam_role.this.name
}

resource "aws_iam_role_policy_attachment" "cloudwatch" {
  policy_arn = data.aws_iam_policy.cloudwatch.arn
  role       = aws_iam_role.this.name
}

resource "aws_iam_policy" "grafana" {
  name   = var.name
  policy = data.aws_iam_policy_document.grafana.json
  tags   = var.tags
}

data "aws_iam_policy_document" "grafana" {
  statement {
    sid       = "AllowPrometheus"
    resources = ["*"]

    actions = [
      "aps:DescribeWorkspace",
      "aps:GetAlertManagerStatus",
      "aps:GetLabels",
      "aps:GetMetricMetadata",
      "aps:GetSeries",
      "aps:ListAlertManagerAlertGroups",
      "aps:ListAlertManagerAlerts",
      "aps:ListAlertManagerSilences",
      "aps:ListWorkspaces",
      "aps:ListRules",
      "aps:QueryMetrics",
    ]
  }
}

data "aws_iam_policy_document" "trust" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type = "AWS"

      identifiers = [
        for account_id in local.monitoring_account_ids :
        "arn:aws:iam::${account_id}:root"
      ]
    }

    condition {
      test     = "StringEquals"
      variable = "iam:ResourceTag/grafana.workspace.${var.grafana_workspace_name}"
      values   = ["true"]
    }
  }
}

data "aws_iam_policy" "cloudwatch" {
  name = "AmazonGrafanaCloudWatchAccess"
}

data "aws_caller_identity" "this" {}

locals {
  monitoring_account_ids = coalesce(var.monitoring_account_ids, [data.aws_caller_identity.this.account_id])
}

// File: outputs.tf
output "arn" {
  description = "ARN of the created IAM role"
  value       = aws_iam_role.this.arn
}

// File: variables.tf
variable "grafana_workspace_name" {
  description = "Name of the AWS Managed Grafana workspace allowed to assume this role"
  type        = string
  default     = "Grafana"
}

variable "monitoring_account_ids" {
  description = "AWS account IDs in which Grafana will run"
  type        = list(string)
  default     = null
}

variable "name" {
  description = "Name of the IAM role for Grafana"
  type        = string
  default     = "grafana"
}

variable "tags" {
  description = "Tags to be applied to created resources"
  type        = map(string)
  default     = {}
}

// File: versions.tf
terraform {
  required_version = ">= 0.14.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}

// File: main.tf
provider "aws" {
  region = "us-east-1"
}

resource "aws_sns_topic" "test" {
  name = "my-topic-with-policy"
}

resource "aws_sns_topic_policy" "default" {
  arn = aws_sns_topic.test.arn

  policy = data.aws_iam_policy_document.sns_topic_policy.json
}

resource "aws_sns_topic" "test2" {
  name = "my-topic-with-policy2"
}

resource "aws_sns_topic_policy" "default2" {
  arn = aws_sns_topic.test2.arn

  policy = data.aws_iam_policy_document.sns_topic_policy.json
}

data "aws_iam_policy_document" "sns_topic_policy" {
  policy_id = "__default_policy_ID"

  statement {
    actions = [
      "SNS:Subscribe",
      "SNS:SetTopicAttributes",
      "SNS:RemovePermission",
      "SNS:Receive",
      "SNS:Publish",
      "SNS:ListSubscriptionsByTopic",
      "SNS:GetTopicAttributes",
      "SNS:DeleteTopic",
      "SNS:AddPermission",
    ]

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceOwner"
      values = []
    }

    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    resources = [
      aws_sns_topic.test.arn,
    ]

    sid = "__default_statement_ID"
  }
}

resource "aws_sns_topic" "user_updates" {
  name = "user-updates-topic"
  delivery_policy = <<EOF
{
  "http": {
    "defaultHealthyRetryPolicy": {
      "minDelayTarget": 20,
      "maxDelayTarget": 20,
      "numRetries": 3,
      "numMaxDelayRetries": 0,
      "numNoDelayRetries": 0,
      "numMinDelayRetries": 0,
      "backoffFunction": "linear"
    },
    "disableSubscriptionOverrides": false,
    "defaultThrottlePolicy": {
      "maxReceivesPerSecond": 1
    }
  }
}
EOF
}

// File: main.tf
data "aws_region" "current" {}

resource "aws_api_gateway_rest_api" "rest" {
  name = "sns ingest"
}

resource "aws_api_gateway_resource" "ingest" {
  rest_api_id = aws_api_gateway_rest_api.rest.id
  parent_id   = aws_api_gateway_rest_api.rest.root_resource_id
  path_part   = "ingest"
}

resource "aws_api_gateway_method" "method" {
  rest_api_id   = aws_api_gateway_rest_api.rest.id
  resource_id   = aws_api_gateway_resource.ingest.id
  http_method   = "POST"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "integration" {
  rest_api_id             = aws_api_gateway_rest_api.rest.id
  resource_id             = aws_api_gateway_resource.ingest.id
  http_method             = aws_api_gateway_method.method.http_method
  integration_http_method = "POST"
  type                    = "AWS"
  credentials             = aws_iam_role.sns_publish.arn
  uri                     = "arn:aws:apigateway:${data.aws_region.current.name}:sns:path//"

  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }

  request_templates = {
    "application/json" = "Action=Publish&TopicArn=$util.urlEncode('${aws_sns_topic.topic.arn}')&Message=$util.urlEncode($input.body)"
  }
}

resource "aws_api_gateway_method_response" "response_200" {
  rest_api_id = aws_api_gateway_rest_api.rest.id
  resource_id = aws_api_gateway_resource.ingest.id
  http_method = aws_api_gateway_method.method.http_method
  status_code = "200"
}

resource "aws_api_gateway_integration_response" "integration_response" {
  rest_api_id = aws_api_gateway_rest_api.rest.id
  resource_id = aws_api_gateway_resource.ingest.id
  http_method = aws_api_gateway_method.method.http_method
  status_code = aws_api_gateway_method_response.response_200.status_code

  depends_on = [aws_api_gateway_integration.integration]

  response_templates = {
    "application/json" = <<EOF
{"status": "message published"}
EOF
  }
}

resource "aws_sns_topic" "topic" {
  name = "event-topic"
}

resource "aws_iam_role" "sns_publish" {
  name               = "sns-publish-role"
  assume_role_policy = data.aws_iam_policy_document.apigw.json
}

data "aws_iam_policy_document" "apigw" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type = "Service"
      identifiers = [
        "apigateway.amazonaws.com"
      ]
    }
  }
}

resource "aws_iam_role_policy" "sns_publish" {
  name   = "SNS-Publish"
  role   = aws_iam_role.sns_publish.id
  policy = data.aws_iam_policy_document.sns_publish.json
}

data "aws_iam_policy_document" "sns_publish" {
  statement {
    actions = [
      "sns:Publish",
    ]

    resources = [
      aws_sns_topic.topic.arn
    ]
  }
}

// File: cloudformation_stack.tf
#---------------------------------------------------
# AWS cloudformation
#---------------------------------------------------
resource "aws_cloudformation_stack" "cloudformation_stack" {
  count = var.enable_cloudformation_stack ? 1 : 0

  name = var.cloudformation_stack_name != "" ? lower(var.cloudformation_stack_name) : "${lower(var.name)}-cloudformation-stack-${lower(var.environment)}"

  template_body      = var.cloudformation_stack_template_body
  template_url       = var.cloudformation_stack_template_url
  capabilities       = var.cloudformation_stack_capabilities
  disable_rollback   = var.cloudformation_stack_disable_rollback
  notification_arns  = var.cloudformation_stack_notification_arns
  on_failure         = var.cloudformation_stack_on_failure
  policy_body        = var.cloudformation_stack_policy_body
  policy_url         = var.cloudformation_stack_policy_url
  iam_role_arn       = var.cloudformation_stack_iam_role_arn
  timeout_in_minutes = var.cloudformation_stack_timeout_in_minutes

  parameters = var.cloudformation_stack_parameters

  tags = merge(
    {
      Name = var.cloudformation_stack_name != "" ? lower(var.cloudformation_stack_name) : "${lower(var.name)}-cloudformation-stack-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: cloudformation_stack_set.tf
#---------------------------------------------------
# AWS cloudformation stack set
#---------------------------------------------------
resource "aws_cloudformation_stack_set" "cloudformation_stack_set" {
  count = var.enable_cloudformation_stack_set ? 1 : 0

  name                    = var.cloudformation_stack_set_name != "" ? lower(var.cloudformation_stack_set_name) : "${lower(var.name)}-cloudformation-stack-set-${lower(var.environment)}"
  administration_role_arn = var.cloudformation_stack_set_administration_role_arn

  capabilities        = var.cloudformation_stack_set_capabilities
  description         = var.cloudformation_stack_set_description
  execution_role_name = var.cloudformation_stack_set_execution_role_name
  parameters          = var.cloudformation_stack_set_parameters
  template_body       = var.cloudformation_stack_set_template_body
  template_url        = var.cloudformation_stack_set_template_url

  dynamic "timeouts" {
    iterator = timeouts
    for_each = length(keys(var.cloudformation_stack_set_timeouts)) > 0 ? [var.cloudformation_stack_set_timeouts] : []

    content {
      update = lookup(timeouts.value, "update", null)
    }
  }

  tags = merge(
    {
      Name = var.cloudformation_stack_set_name != "" ? lower(var.cloudformation_stack_set_name) : "${lower(var.name)}-cloudformation-stack-set-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: cloudformation_stack_set_instance.tf
#---------------------------------------------------
# AWS cloudformation stack set instance
#---------------------------------------------------
resource "aws_cloudformation_stack_set_instance" "cloudformation_stack_set_instance" {
  count = var.enable_cloudformation_stack_set_instance ? 1 : 0

  stack_set_name = var.cloudformation_stack_set_instance_stack_set_name != "" && !var.enable_cloudformation_stack_set ? var.cloudformation_stack_set_instance_stack_set_name : element(concat(aws_cloudformation_stack_set.cloudformation_stack_set.*.name, [""]), 0)

  account_id          = var.cloudformation_stack_set_instance_account_id
  parameter_overrides = var.cloudformation_stack_set_instance_parameter_overrides
  region              = var.region
  retain_stack        = var.cloudformation_stack_set_instance_retain_stack

  dynamic "timeouts" {
    iterator = timeouts
    for_each = length(keys(var.cloudformation_stack_set_instance_timeouts)) > 0 ? [var.cloudformation_stack_set_instance_timeouts] : []

    content {
      create = lookup(timeouts.value, "create", null)
      update = lookup(timeouts.value, "update", null)
      delete = lookup(timeouts.value, "delete", null)
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_cloudformation_stack_set.cloudformation_stack_set
  ]
}

