// File: workspaces_directory.tf
#---------------------------------------------------
# AWS Workspaces directory
#---------------------------------------------------
resource "aws_workspaces_directory" "workspaces_directory" {
  count = var.enable_workspaces_directory ? length(var.workspaces_directory_directory_ids) : 0

  directory_id = var.workspaces_directory_directory_ids[count.index]

  subnet_ids   = var.workspaces_directory_subnet_ids
  ip_group_ids = var.workspaces_directory_ip_group_ids

  dynamic "self_service_permissions" {
    iterator = self_service_permissions
    for_each = var.workspaces_directory_self_service_permissions

    content {
      change_compute_type  = lookup(self_service_permissions.value, "change_compute_type", false)
      increase_volume_size = lookup(self_service_permissions.value, "increase_volume_size", false)
      rebuild_workspace    = lookup(self_service_permissions.value, "rebuild_workspace", false)
      restart_workspace    = lookup(self_service_permissions.value, "restart_workspace", true)
      switch_running_mode  = lookup(self_service_permissions.value, "switch_running_mode", false)
    }
  }

  dynamic "workspace_access_properties" {
    iterator = workspace_access_properties
    for_each = var.workspaces_directory_workspace_access_properties

    content {
      device_type_android    = lookup(workspace_access_properties.value, "device_type_android", null)
      device_type_chromeos   = lookup(workspace_access_properties.value, "device_type_chromeos", null)
      device_type_ios        = lookup(workspace_access_properties.value, "device_type_ios", null)
      device_type_osx        = lookup(workspace_access_properties.value, "device_type_osx", null)
      device_type_web        = lookup(workspace_access_properties.value, "device_type_web", null)
      device_type_windows    = lookup(workspace_access_properties.value, "device_type_windows", null)
      device_type_zeroclient = lookup(workspace_access_properties.value, "device_type_zeroclient", null)
    }
  }

  dynamic "workspace_creation_properties" {
    iterator = workspace_creation_properties
    for_each = var.workspaces_directory_workspace_creation_properties

    content {
      custom_security_group_id            = lookup(workspace_creation_properties.value, "custom_security_group_id", null)
      default_ou                          = lookup(workspace_creation_properties.value, "default_ou", null)
      enable_internet_access              = lookup(workspace_creation_properties.value, "enable_internet_access", null)
      enable_maintenance_mode             = lookup(workspace_creation_properties.value, "enable_maintenance_mode", null)
      user_enabled_as_local_administrator = lookup(workspace_creation_properties.value, "user_enabled_as_local_administrator", null)
    }
  }

  tags = merge(
    {
      Name = var.workspaces_directory_name != "" ? lower(var.workspaces_directory_name) : "${lower(var.name)}-workspaces-directory-${lower(var.environment)}-${count.index + 1}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: workspaces_ip_group.tf
#---------------------------------------------------
# AWS Workspaces ip group
#---------------------------------------------------
resource "aws_workspaces_ip_group" "workspaces_ip_group" {
  count = var.enable_workspaces_ip_group ? 1 : 0

  name = var.workspaces_ip_group_name != "" ? var.workspaces_ip_group_name : "${lower(var.name)}-workspaces-ip-group-${lower(var.environment)}"

  description = var.workspaces_ip_group_description

  dynamic "rules" {
    iterator = rules
    for_each = var.workspaces_ip_group_rules

    content {
      source      = lookup(rules.value, "source", null)
      description = lookup(rules.value, "description", null)
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: workspaces_workspace.tf
#---------------------------------------------------
# AWS Workspaces workspace
#---------------------------------------------------
resource "aws_workspaces_workspace" "workspaces_workspace" {
  count = var.enable_workspaces_workspace ? 1 : 0

  directory_id = var.workspaces_workspace_directory_id != "" ? var.workspaces_workspace_directory_id : (var.enable_workspaces_directory ? aws_workspaces_directory.workspaces_directory[count.index].id : null)
  bundle_id    = var.workspaces_workspace_bundle_id
  user_name    = var.workspaces_workspace_user_name

  root_volume_encryption_enabled = var.workspaces_workspace_root_volume_encryption_enabled
  user_volume_encryption_enabled = var.workspaces_workspace_user_volume_encryption_enabled
  volume_encryption_key          = var.workspaces_workspace_volume_encryption_key

  dynamic "workspace_properties" {
    iterator = workspace_properties
    for_each = var.workspaces_workspace_workspace_properties

    content {
      compute_type_name                         = lookup(workspace_properties.value, "compute_type_name", null)
      user_volume_size_gib                      = lookup(workspace_properties.value, "user_volume_size_gib", null)
      root_volume_size_gib                      = lookup(workspace_properties.value, "root_volume_size_gib", null)
      running_mode                              = lookup(workspace_properties.value, "running_mode", null)
      running_mode_auto_stop_timeout_in_minutes = lookup(workspace_properties.value, "running_mode_auto_stop_timeout_in_minutes", null)
    }
  }

  dynamic "timeouts" {
    iterator = timeouts
    for_each = length(keys(var.workspaces_workspace_timeouts)) > 0 ? [var.workspaces_workspace_timeouts] : []

    content {
      create = lookup(timeouts.value, "create", null)
      update = lookup(timeouts.value, "update", null)
      delete = lookup(timeouts.value, "delete", null)
    }
  }

  tags = merge(
    {
      Name = var.workspaces_workspace_name != "" ? lower(var.workspaces_workspace_name) : "${lower(var.name)}-workspaces-workspace-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = false
    ignore_changes        = [volume_encryption_key]
  }

  depends_on = []
}

// File: main.tf
provider "aws" {
  region = "us-east-1"
}
terraform {
  required_version = ">= 1.0.0, < 2.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 4.0"
    }
  }
}

resource "aws_s3_bucket" "terraform_state" {

  bucket = var.bucket_name

  // This is only here so we can destroy the bucket as part of automated tests. You should not copy this for production
  // usage
  force_destroy = true

}

# Enable versioning so you can see the full revision history of your
# state files
resource "aws_s3_bucket_versioning" "enabled" {
  bucket = aws_s3_bucket.terraform_state.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Enable server-side encryption by default
resource "aws_s3_bucket_server_side_encryption_configuration" "default" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# Explicitly block all public access to the S3 bucket
resource "aws_s3_bucket_public_access_block" "public_access" {
  bucket                  = aws_s3_bucket.terraform_state.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_dynamodb_table" "terraform_locks" {
  name         = var.table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }
}

// File: outputs.tf
output "s3_bucket_arn" {
  value       = aws_s3_bucket.terraform_state.arn
  description = "The ARN of the S3 bucket"
}

output "dynamodb_table_name" {
  value       = aws_dynamodb_table.terraform_locks.name
  description = "The name of the DynamoDB table"
}

// File: variables.tf
variable "bucket_name" {
  description = "The name of the S3 bucket. Must be globally unique."
  type        = string
  default = "tungleo-terraform-state-s3"
}

variable "table_name" {
  description = "The name of the DynamoDB table. Must be unique in this AWS account."
  type        = string
  default = "terraform-up-and-running-locks"
}

// File: cloud.tf
resource "aws_s3_bucket" "access" {
  bucket = "${var.access_url}"
  acl = "public-read"
  cors_rule {
      allowed_headers = ["*"]
      allowed_methods = ["PUT","POST"]
      allowed_origins = ["*"]
      expose_headers = ["ETag"]
      max_age_seconds = 3000
  }
  website {
    index_document = "index.html"
    error_document = "index.html"
  }
}

locals {
  s3_origin_id = "S3-Website-${var.access_url}.s3-website-us-east-1.amazonaws.com"
}

resource "aws_cloudfront_distribution" "access" {
  origin {
    domain_name = "${aws_s3_bucket.access.website_endpoint}"
    origin_id   = "${local.s3_origin_id}"
    custom_origin_config {
      http_port              = "80"
      https_port             = "443"
      origin_protocol_policy = "http-only"
      origin_ssl_protocols   = ["TLSv1", "TLSv1.1", "TLSv1.2"]
    }
  }

  enabled             = true
  is_ipv6_enabled     = true
  default_root_object = "index.html"

  aliases = ["${var.access_url}"]

  default_cache_behavior {
    allowed_methods  = ["DELETE", "GET", "HEAD", "OPTIONS", "PATCH", "POST", "PUT"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "${local.s3_origin_id}"

    forwarded_values {
      query_string = false

      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "allow-all"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
  }

  price_class = "PriceClass_200"

  tags = {
    Environment = "production"
  }

  viewer_certificate {
    acm_certificate_arn = "${var.access_cert}"
    cloudfront_default_certificate = true
    ssl_support_method = "sni-only"
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }
}

// File: variables.tf
variable "access_url" {
  default = ""
}

variable "access_cert" {
  default = ""
}

// File: appautoscaling_policy.tf
#---------------------------------------------------
# AWS appautoscaling policy
#---------------------------------------------------
resource "aws_appautoscaling_policy" "appautoscaling_policy" {
  count = var.enable_appautoscaling_policy ? 1 : 0

  name               = var.appautoscaling_policy_name != "" ? lower(var.appautoscaling_policy_name) : "${lower(var.name)}-appautoscaling-policy-${lower(var.environment)}"
  policy_type        = var.appautoscaling_policy_policy_type
  resource_id        = var.appautoscaling_policy_resource_id != "" && !var.enable_appautoscaling_target ? var.appautoscaling_policy_resource_id : element(concat(aws_appautoscaling_target.appautoscaling_target.*.resource_id, [""]), 0)
  scalable_dimension = var.appautoscaling_policy_scalable_dimension != "" && !var.enable_appautoscaling_target ? var.appautoscaling_policy_scalable_dimension : element(concat(aws_appautoscaling_target.appautoscaling_target.*.scalable_dimension, [""]), 0)
  service_namespace  = var.appautoscaling_policy_service_namespace != "" && !var.enable_appautoscaling_target ? var.appautoscaling_policy_service_namespace : element(concat(aws_appautoscaling_target.appautoscaling_target.*.service_namespace, [""]), 0)

  dynamic "step_scaling_policy_configuration" {
    iterator = stepscalingpolicy
    for_each = var.appautoscaling_policy_policy_type == "StepScaling" ? var.appautoscaling_policy_step_scaling_policy_configuration : []

    content {
      adjustment_type = lookup(stepscalingpolicy.value, "adjustment_type", null)
      cooldown        = lookup(stepscalingpolicy.value, "cooldown", null)

      metric_aggregation_type  = lookup(stepscalingpolicy.value, "metric_aggregation_type", null)
      min_adjustment_magnitude = lookup(stepscalingpolicy.value, "min_adjustment_magnitude", null)

      dynamic "step_adjustment" {
        iterator = step_adjustment
        for_each = length(keys(lookup(stepscalingpolicy.value, "step_adjustment", {}))) > 0 ? [lookup(stepscalingpolicy.value, "step_adjustment", {})] : []

        content {
          scaling_adjustment = lookup(step_adjustment.value, "scaling_adjustment", null)

          metric_interval_lower_bound = lookup(step_adjustment.value, "metric_interval_lower_bound", null)
          metric_interval_upper_bound = lookup(step_adjustment.value, "metric_interval_upper_bound", null)
        }
      }
    }
  }

  dynamic "target_tracking_scaling_policy_configuration" {
    iterator = targettrackingscalingpolicy
    for_each = var.appautoscaling_policy_policy_type == "TargetTrackingScaling" ? var.appautoscaling_policy_target_tracking_scaling_policy_configuration : []

    content {
      target_value = lookup(targettrackingscalingpolicy.value, "target_value", null)

      disable_scale_in   = lookup(targettrackingscalingpolicy.value, "disable_scale_in", false)
      scale_in_cooldown  = lookup(targettrackingscalingpolicy.value, "scale_in_cooldown", null)
      scale_out_cooldown = lookup(targettrackingscalingpolicy.value, "scale_out_cooldown", null)

      dynamic "customized_metric_specification" {
        iterator = customized_metric_specification
        for_each = length(keys(lookup(targettrackingscalingpolicy.value, "customized_metric_specification", {}))) > 0 ? [lookup(targettrackingscalingpolicy.value, "customized_metric_specification", {})] : []

        content {
          metric_name = lookup(customized_metric_specification.value, "metric_name", null)
          namespace   = lookup(customized_metric_specification.value, "namespace", null)
          statistic   = lookup(customized_metric_specification.value, "statistic", null)

          unit = lookup(customized_metric_specification.value, "unit", null)

          dynamic "dimensions" {
            iterator = dimensions
            for_each = lookup(customized_metric_specification.value, "dimensions", [])

            content {
              name  = lookup(dimensions.value, "name", null)
              value = lookup(dimensions.value, "value", null)
            }
          }
        }
      }

      dynamic "predefined_metric_specification" {
        iterator = predefined_metric_specification
        for_each = length(keys(lookup(targettrackingscalingpolicy.value, "predefined_metric_specification", {}))) > 0 ? [lookup(targettrackingscalingpolicy.value, "predefined_metric_specification", {})] : []

        content {
          predefined_metric_type = lookup(predefined_metric_specification.value, "predefined_metric_type", null)

          resource_label = lookup(predefined_metric_specification.value, "resource_label", null)
        }
      }

    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_appautoscaling_target.appautoscaling_target
  ]
}

// File: appautoscaling_scheduled_action.tf
#---------------------------------------------------
# AWS appautoscaling scheduled action
#---------------------------------------------------
resource "aws_appautoscaling_scheduled_action" "appautoscaling_scheduled_action" {
  count = var.enable_appautoscaling_scheduled_action ? 1 : 0

  name               = var.appautoscaling_scheduled_action_name != "" ? lower(var.appautoscaling_scheduled_action_name) : "${lower(var.name)}-appautoscaling-scheduled-action-${lower(var.environment)}"
  resource_id        = var.appautoscaling_scheduled_action_resource_id != "" && !var.enable_appautoscaling_target ? var.appautoscaling_scheduled_action_resource_id : element(concat(aws_appautoscaling_target.appautoscaling_target.*.resource_id, [""]), 0)
  scalable_dimension = var.appautoscaling_scheduled_action_scalable_dimension != "" && !var.enable_appautoscaling_target ? var.appautoscaling_scheduled_action_scalable_dimension : element(concat(aws_appautoscaling_target.appautoscaling_target.*.scalable_dimension, [""]), 0)
  service_namespace  = var.appautoscaling_scheduled_action_service_namespace != "" && !var.enable_appautoscaling_target ? var.appautoscaling_scheduled_action_service_namespace : element(concat(aws_appautoscaling_target.appautoscaling_target.*.service_namespace, [""]), 0)

  schedule   = var.appautoscaling_scheduled_action_schedule
  start_time = var.appautoscaling_scheduled_action_start_time
  end_time   = var.appautoscaling_scheduled_action_end_time

  dynamic "scalable_target_action" {
    iterator = scalabletarget
    for_each = var.appautoscaling_scheduled_action_scalable_target_action

    content {
      min_capacity = lookup(scalabletarget.value, "min_capacity", null)
      max_capacity = lookup(scalabletarget.value, "max_capacity", null)
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_appautoscaling_target.appautoscaling_target
  ]
}

// File: appautoscaling_target.tf
#---------------------------------------------------
# AWS appautoscaling target
#---------------------------------------------------
resource "aws_appautoscaling_target" "appautoscaling_target" {
  count = var.enable_appautoscaling_target ? 1 : 0

  max_capacity       = var.appautoscaling_target_max_capacity
  min_capacity       = var.appautoscaling_target_min_capacity
  resource_id        = var.appautoscaling_target_resource_id
  scalable_dimension = var.appautoscaling_target_scalable_dimension
  service_namespace  = var.appautoscaling_target_service_namespace

  role_arn = var.appautoscaling_target_role_arn

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: outputs.tf
#---------------------------------------------------
# AWS appautoscaling target
#---------------------------------------------------
output "appautoscaling_target_id" {
  description = "The ID for appautoscaling target"
  value       = element(concat(aws_appautoscaling_target.appautoscaling_target.*.id, [""]), 0)
}

# output "appautoscaling_target_arn" {
