// File: main.tf
provider "aws" {
}

resource "aws_s3_bucket" "my_bucket" {
  bucket = var.bucket_name

}

resource "aws_s3_bucket_versioning" "version" {
  count = var.versioning ? 1:0
  bucket = aws_s3_bucket.my_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "my_oc" {
  bucket = aws_s3_bucket.my_bucket.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "private_acl" {
  count = var.public_acl ? 0:1

  bucket = aws_s3_bucket.my_bucket.id

  depends_on = [ aws_s3_bucket_ownership_controls.my_oc ]

  acl = "private"
}

resource "aws_s3_bucket_public_access_block" "s3_access_block" {
  #Only executes if user inputs true, else count becomes zero.
  count = var.public_acl ? 1:0

  bucket = aws_s3_bucket.my_bucket.id

  block_public_acls = false
  block_public_policy = false
  restrict_public_buckets = false
  ignore_public_acls = false
}

resource "aws_s3_bucket_acl" "public_acl" {
   count = var.public_acl ? 1:0

  bucket = aws_s3_bucket.my_bucket.id

  depends_on = [ aws_s3_bucket_ownership_controls.my_oc , aws_s3_bucket_public_access_block.s3_access_block ]

  acl = "public-read"
}

// File: outputs.tf
output "bucket_id" {
    value = aws_s3_bucket.my_bucket.id
    description = "Name of the created S3 bucket"
}

output "bucket_arn" {
  value = aws_s3_bucket.my_bucket.arn
  description = "The unique Amazon Resource Name (ARN) of the bucket"
}

// File: variables.tf
variable "bucket_name" {
    type = string
    description = "Please provide a globally unique name for your bucket."
    default = "akiraabucket12345648"
}


variable "versioning" {
    type = bool
    description = "Enter true to enable versioning. Has False as value by default"
    default = false
}

variable "public_acl" {
    type = bool
    description = "Set to true to enable Public"
    default = false
}

// File: data.tf
data "aws_region" "current" {}

// File: locals.tf
locals {
  region = data.aws_region.current.name
}

// File: outputs.tf
output "public_subnet_ids" {
  description = "A list of the VPC's public subnets."
  value       = module.vpc.public_subnets
}

output "private_subnet_ids" {
  description = "A list of the VPC's private subnets."
  value       = module.vpc.private_subnets
}

output "vpc_id" {
  description = "VPC ID"
  value       = module.vpc.vpc_id
}

output "private_subnets_cidr_blocks" {
  description = "A list of cidr_blocks of private subnets."
  value       = module.vpc.private_subnets_cidr_blocks
}

// File: security_groups.tf
resource "aws_security_group" "ssh" {
  name        = "allow-ssh"
  description = "Allow inbound SSH traffic"
  vpc_id      = module.vpc.vpc_id
}

resource "aws_vpc_security_group_ingress_rule" "allow_ssh" {
  security_group_id = aws_security_group.ssh.id
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "tcp"
  from_port         = 22
  to_port           = 22
}

resource "aws_vpc_security_group_egress_rule" "allow_all_outbound" {
  security_group_id = aws_security_group.ssh.id
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "-1"
}

