terraform {
  required_version = ">= 1.8"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.3"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

// File: vpc.tf
module "vpc" {
  source = "github.com/terraform-aws-modules/terraform-aws-vpc?ref=v5.1.2"

  name = "trade-tariff-development-vpc"
  cidr = "10.0.0.0/16"

  azs = [
    "${local.region}d",
    "${local.region}f",
  ]

  private_subnets = [
    "10.0.4.0/24",
    "10.0.5.0/24",
    "10.0.6.0/24"
  ]

  public_subnets = [
    "10.0.104.0/24",
    "10.0.105.0/24",
    "10.0.106.0/24"
  ]

  enable_dns_hostnames = true
  enable_dns_support   = true

  enable_nat_gateway = true
  single_nat_gateway = true
}

// File: locals.tf
locals {
  rfc1918_cidrs = ["10.0.0.0/8", "192.168.0.0/16", "172.16.0.0/12"]
  default       = "0.0.0.0/0"
}

// File: main.tf
#---------------------------------------------------------------------------
# Crate Route Table private to a NI
#---------------------------------------------------------------------------
# Create routes to NI in RTs
resource "aws_route" "r_private_to_ni_default" {
  for_each = var.ni_rt_ids

  route_table_id         = each.value
  destination_cidr_block = var.destination_cidr_block
  network_interface_id   = var.ni_id
}
#---------------------------------------------------------------------------
# Crate Route Table private to a TGW
#---------------------------------------------------------------------------
resource "aws_route" "r_private_to_tgw_default" {
  for_each = var.tgw_rt_ids

  route_table_id         = each.value
  destination_cidr_block = var.destination_cidr_block
  transit_gateway_id     = var.tgw_id
}
#---------------------------------------------------------------------------
# Crate Route Table private to a GWLBe
#---------------------------------------------------------------------------
resource "aws_route" "r_private_to_gwlb_default" {
  for_each = var.gwlb_rt_ids

  route_table_id         = each.value
  destination_cidr_block = var.destination_cidr_block
  vpc_endpoint_id        = var.gwlbe_id
}
#---------------------------------------------------------------------------
# Crate Route Table private to a Core Network
#---------------------------------------------------------------------------
resource "aws_route" "r_private_to_core_net_default" {
  for_each = var.core_network_rt_ids

  route_table_id         = each.value
  destination_cidr_block = var.destination_cidr_block
  core_network_arn       = var.core_network_arn
}
#---------------------------------------------------------------------------
# Crate Route Table private to NAT GW
#---------------------------------------------------------------------------
resource "aws_route" "r_private_to_natgw_default" {
  for_each = var.natgw_rt_ids

  route_table_id         = each.value
  destination_cidr_block = var.destination_cidr_block
  nat_gateway_id         = var.natgw_id
}

// File: variables.tf
variable "region" {
  description = "AWS region, necessay if provider alias is used"
  type        = string
  default     = null
}

variable "admin_cidr" {
  description = "Created for future use"
  type        = string
