}

// File: main.tf
# VPC Section
resource "aws_vpc" "myvpc" {
    cidr_block              = var.vpc_cidr
    enable_dns_support      = true
    tags = {
        Name = var.vpctag
    }
}

# Web Subnet
resource "aws_subnet" "web" {
    vpc_id                  = aws_vpc.myvpc.id
    cidr_block              = cidrsubnet(var.vpc_cidr,8,0)
    availability_zone       = format("%s%s",var.region,var.availabilty_zones[0])

    tags = {
        Name = var.subnet_tags[0]
    }

}

resource "aws_subnet" "app" {
    vpc_id                  = aws_vpc.myvpc.id
    cidr_block              = cidrsubnet(var.vpc_cidr,8,1)
    availability_zone       = format("%s%s",var.region,var.availabilty_zones[1])

    tags = {
        Name = var.subnet_tags[1]
    }

}

resource "aws_subnet" "db" {
    vpc_id                  = aws_vpc.myvpc.id
    cidr_block              = cidrsubnet(var.vpc_cidr,8,2)
    availability_zone       = format("%s%s",var.region,var.availabilty_zones[2])

    tags = {
        Name = var.subnet_tags[2]
    }

}

resource "aws_subnet" "mgmt" {
    vpc_id                  = aws_vpc.myvpc.id
    cidr_block              = cidrsubnet(var.vpc_cidr,8,3)
    availability_zone       = format("%s%s",var.region,var.availabilty_zones[3])

    tags = {
        Name = var.subnet_tags[3]
    }

}

// File: providers.tf
provider "aws" {
    region = var.region
}

// File: main.tf
locals {
  # S3 Bucket Policy
  create_s3_bucket_policy = length(var.bucket_policies) > 0
}

################################################################################
# S3 Bucket
################################################################################

resource "aws_s3_bucket" "this" {
  bucket              = var.bucket
  force_destroy       = var.bucket_force_destroy
  object_lock_enabled = var.bucket_object_lock_enabled

  tags = var.tags
}

################################################################################
# S3 Bucket Policy
################################################################################

data "aws_iam_policy_document" "this" {
  for_each = local.create_s3_bucket_policy ? var.bucket_policies : {}

  policy_id = each.value.id
  version   = each.value.version

  dynamic "statement" {
    for_each = each.value.statements

    content {
      sid       = statement.value.sid
      actions   = statement.value.actions
      effect    = statement.value.effect
      resources = statement.value.resources

      dynamic "principals" {
        for_each = statement.value.principals
        iterator = principal

        content {
          identifiers = principal.value.identifiers
          type        = principal.value.type
        }
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  for_each = local.create_s3_bucket_policy ? data.aws_iam_policy_document.this : {}

  bucket = aws_s3_bucket.this.id
  policy = each.value.json
}

// File: outputs.tf
################################################################################
# S3 Bucket
################################################################################

output "bucket_id" {
  description = "Name of the bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "ARN of the bucket."
  value       = aws_s3_bucket.this.arn
}

// File: variables.tf
################################################################################
# S3 Bucket
################################################################################

variable "bucket" {
  description = "(Optional, Forces new resource) Name of the bucket."
  type        = string
  default     = null
}

variable "bucket_force_destroy" {
  description = "(Optional, Default:false) Boolean that indicates all objects (including any locked objects) should be deleted from the bucket when the bucket is destroyed so that the bucket can be destroyed without error."
  type        = bool
  nullable    = false
  default     = false
}

variable "bucket_object_lock_enabled" {
  description = "(Optional, Forces new resource) Indicates whether this bucket has an Object Lock configuration enabled."
  type        = bool
  nullable    = false
  default     = false
}

variable "tags" {
  description = "(Optional) Map of tags to assign to the bucket."
  type        = map(string)
  nullable    = false
  default     = {}
}

################################################################################
# S3 Bucket Policy
################################################################################

variable "bucket_policies" {
  description = "(Optional) Map of bucket policies to attach to the S3 bucket."
  type = map(object({
    id      = optional(string, null)
    version = optional(string, null)
    statements = optional(list(object({
      sid       = optional(string, null)
      actions   = optional(set(string), [])
      effect    = optional(string, "Allow")
      resources = optional(set(string), [])
      principals = optional(list(object({
        identifiers = set(string)
        type        = string
      })), [])
    })), [])
  }))
  nullable = false
  default  = {}
}

// File: version.tf
terraform {
  required_version = ">= 1.6.0"
}

// File: main.tf
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

data "aws_eks_cluster" "main" {
  for_each = var.cluster_service_accounts

  name = each.key
}

data "aws_iam_policy_document" "assume_role_with_oidc" {
  dynamic "statement" {
    # https://aws.amazon.com/blogs/security/announcing-an-update-to-iam-role-trust-policy-behavior/
    for_each = var.allow_self_assume_role ? [1] : []

    content {
      sid     = "ExplicitSelfRoleAssumption"
      effect  = "Allow"
      actions = ["sts:AssumeRole"]

      principals {
        type        = "AWS"
        identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:role${var.role_path}${var.role_name}"]
      }
    }
  }

  dynamic "statement" {
    for_each = var.cluster_service_accounts

    content {
      effect  = "Allow"
      actions = ["sts:AssumeRoleWithWebIdentity"]

      principals {
        type = "Federated"

        identifiers = [
          "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:oidc-provider/${replace(data.aws_eks_cluster.main[statement.key].identity[0].oidc[0].issuer, "https://", "")}"
        ]
      }

      condition {
        test     = "StringEquals"
        variable = "${replace(data.aws_eks_cluster.main[statement.key].identity[0].oidc[0].issuer, "https://", "")}:sub"
        values   = [for s in statement.value : "system:serviceaccount:${s}"]
      }
    }
  }
}

resource "aws_iam_role" "this" {
  count = var.create_role ? 1 : 0

  assume_role_policy    = data.aws_iam_policy_document.assume_role_with_oidc.json
  description           = var.role_description
  force_detach_policies = var.force_detach_policies
  max_session_duration  = var.max_session_duration
  name                  = var.role_name
  name_prefix           = var.role_name_prefix
  path                  = var.role_path
  permissions_boundary  = var.role_permissions_boundary_arn
  tags                  = var.tags
}

resource "aws_iam_role_policy_attachment" "this" {
  for_each = { for k, v in var.role_policy_arns : k => v if var.create_role }

  role       = aws_iam_role.this[0].name
  policy_arn = each.value
}

// File: outputs.tf
output "iam_role_arn" {
  description = "ARN of IAM role"
  value       = try(aws_iam_role.this[0].arn, "")
}

output "iam_role_name" {
  description = "Name of IAM role"
  value       = try(aws_iam_role.this[0].name, "")
}

output "iam_role_path" {
  description = "Path of IAM role"
  value       = try(aws_iam_role.this[0].path, "")
}

output "iam_role_unique_id" {
  description = "Unique ID of IAM role"
  value       = try(aws_iam_role.this[0].unique_id, "")
}

// File: variables.tf
variable "create_role" {
  description = "Whether to create a role"
  type        = bool
  default     = true
}

variable "role_name" {
  description = "Name of IAM role"
  type        = string
  default     = null
}

variable "role_path" {
  description = "Path of IAM role"
  type        = string
  default     = "/"
}

variable "role_permissions_boundary_arn" {
  description = "Permissions boundary ARN to use for IAM role"
  type        = string
  default     = ""
}

variable "role_description" {
  description = "IAM Role description"
  type        = string
  default     = ""
}

variable "role_name_prefix" {
  description = "IAM role name prefix"
  type        = string
  default     = null
}

variable "role_policy_arns" {
  description = "ARNs of any policies to attach to the IAM role"
  type        = map(string)
  default     = {}
}

variable "cluster_service_accounts" {
  description = "EKS cluster and k8s ServiceAccount pairs. Each EKS cluster can have multiple k8s ServiceAccount. See README for details"
  type        = map(list(string))
  default     = {}
}

variable "tags" {
  description = "A map of tags to add the the IAM role"
