// File: versions.tf
terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.30"
    }
  }
}

// File: client.tf
resource "aws_cognito_user_pool_client" "client" {
  name         = var.user_pool_client
  user_pool_id = aws_cognito_user_pool.user-pool.id
}

// File: iam-policy.tf
resource "aws_iam_role_policy" "authenticated" {
  name = "authenticated_policy"
  role = aws_iam_role.authenticated.id

  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": [
        "mobileanalytics:PutEvents",
        "cognito-sync:*",
        "cognito-identity:*"
      ],
      "Resource": [
        "*"
      ]
    }
  ]
}
EOF
}

// File: iam-role.tf
resource "aws_iam_role" "authenticated" {
  name = "cognito_authenticated"

  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Federated": "cognito-identity.amazonaws.com"
      },
      "Action": "sts:AssumeRoleWithWebIdentity",
      "Condition": {
        "StringEquals": {
          "cognito-identity.amazonaws.com:aud": "${aws_cognito_identity_pool.identity-pool.id}"
        },
        "ForAnyValue:StringLike": {
          "cognito-identity.amazonaws.com:amr": "authenticated"
        }
      }
    }
  ]
}
EOF
}

// File: identity-pool.tf
resource "aws_cognito_identity_pool" "identity-pool" {
  identity_pool_name               = var.identity_pool_name
  allow_unauthenticated_identities = var.allow_unauthenticated_identities
  allow_classic_flow               = var.allow_classic_flow

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.client.id
    provider_name           = aws_cognito_user_pool.user-pool.endpoint
    server_side_token_check = false
  }
}

// File: roles-attachment.tf
resource "aws_cognito_identity_pool_roles_attachment" "main" {
  identity_pool_id = aws_cognito_identity_pool.identity-pool.id
  roles = {
    "authenticated" = aws_iam_role.authenticated.arn
  }
}

// File: user-pool.tf
resource "aws_cognito_user_pool" "user-pool" {
  name = var.user_pool_name
}

// File: variables.tf
variable "identity_pool_name" {
  type        = string
  default     = "my-identity-pool"
  description = "The Cognito Identity Pool name."
}

variable "allow_unauthenticated_identities" {
  type        = bool
  default     = false
  description = "Whether the identity pool supports unauthenticated logins or not."
}

variable "allow_classic_flow" {
  type        = bool
  default     = false
  description = "Enables or disables the classic / basic authentication flow."
}

variable "user_pool_name" {
  type        = string
  default     = "my-user-pool"
  description = "Name of the user pool that will be created."
}

variable "user_pool_client" {
  type        = string
  default     = "user1"
  description = "A user pool client name."
}

// File: link.tf
resource "aws_oam_link" "this" {
  count           = var.enable_cw_oam_link ? 1 : 0
  label_template  = var.label_template
  resource_types  = var.resource_types
  sink_identifier = var.sink_identifier
  tags            = merge(local.tags, var.tags)
}

// File: main.tf
locals {
  tags = {
    cost    = "shared"
    creator = "terraform"
    git     = var.git
  }
}

// File: outputs.tf
output "sink_id" {
  description = "ID string that AWS generated as part of the sink ARN."
  value       = var.enable_cw_oam_sink ? aws_oam_sink.this[0].id : null
}

// File: sink.tf
resource "aws_oam_sink" "this" {
  count = var.enable_cw_oam_sink ? 1 : 0
  name  = "${var.name}-sink"
  tags  = var.tags
}

resource "aws_oam_sink_policy" "this" {
  count           = var.enable_cw_oam_sink ? 1 : 0
  sink_identifier = aws_oam_sink.this[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action    = ["oam:CreateLink", "oam:UpdateLink"]
        Effect    = "Allow"
        Resource  = "*"
        Principal = "*"
        Condition = {
          "ForAllValues:StringEquals" = {
            "oam:ResourceTypes" = var.resource_types
          }
          "ForAnyValue:StringEquals" = {
            "aws:PrincipalOrgID" = var.principal_org_ids
          }
        }
      }
    ]
  })
}

// File: variables.tf
variable "tags" {
  description = "Tags to assign to resources"
  type        = map(string)
  default     = {}
}

variable "name" {
  description = "https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/oam_sink#name"
  type        = string
  default     = "cloudwatch-oam"
}

variable "git" {
  description = "Name of the Git repo"
  type        = string
  default     = "terraform-aws-cloudwatch-oam"
}

variable "principal_org_ids" {
  description = "org ids that will be allowed to send log and metric resources to monitoring account"
  type        = list(string)
  default     = []
}

variable "resource_types" {
  description = "https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/oam_link#resource_types"
  type        = list(string)
  default     = ["AWS::CloudWatch::Metric", "AWS::Logs::LogGroup"]
}

variable "enable_cw_oam_link" {
  description = "enable cloudwatch oam link"
  type        = bool
  default     = false
}

variable "enable_cw_oam_sink" {
  description = "enable cloudwatch oam sink"
  type        = bool
  default     = false
}

variable "sink_identifier" {
  description = "https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/oam_link#sink_identifier"
  type        = string
  default     = ""
}

variable "label_template" {
  description = "https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/oam_link#label_template"
  type        = string
  default     = "$AccountName"
}

// File: athena_database.tf
#---------------------------------------------------
# AWS athena database
#---------------------------------------------------
resource "aws_athena_database" "athena_database" {
  count = var.enable_athena_database ? 1 : 0

  name   = var.athena_database_name != "" ? var.athena_database_name : "${lower(var.name)}-athena-db-${lower(var.environment)}"
  bucket = var.athena_database_bucket

  force_destroy = var.athena_database_force_destroy

  dynamic "encryption_configuration" {
    iterator = encryption_configuration
    for_each = var.athena_database_encryption_configuration

    content {
      encryption_option = lookup(encryption_configuration.value, "encryption_option", null)

      kms_key = lookup(encryption_configuration.value, "kms_key", null)
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: athena_named_query.tf
#---------------------------------------------------
# AWS athena named query
#---------------------------------------------------
resource "aws_athena_named_query" "athena_named_query" {
  count = var.enable_athena_named_query ? 1 : 0

  name     = var.athena_named_query_name != "" ? lower(var.athena_named_query_name) : "${lower(var.name)}-athena-query-${lower(var.environment)}"
  database = var.athena_named_query_database != "" && !var.enable_athena_database ? var.athena_named_query_database : element(concat(aws_athena_database.athena_database.*.name, [""]), 0)
  query    = var.athena_named_query_query

  description = var.athena_named_query_description != "" ? var.athena_named_query_description : null
  workgroup   = var.athena_named_query_workgroup != "" && !var.enable_athena_workgroup ? var.athena_named_query_workgroup : element(concat(aws_athena_workgroup.athena_workgroup.*.id, [""]), 0)

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_athena_workgroup.athena_workgroup,
    aws_athena_database.athena_database
  ]
}

// File: athena_workgroup.tf
#---------------------------------------------------
# AWS athena workgroup
#---------------------------------------------------
resource "aws_athena_workgroup" "athena_workgroup" {
  count = var.enable_athena_workgroup ? 1 : 0

  name = var.athena_workgroup_name != "" ? lower(var.athena_workgroup_name) : "${lower(var.name)}-athena-workgroup-${lower(var.environment)}"

  description   = var.athena_workgroup_description
  state         = upper(var.athena_workgroup_state)
  force_destroy = var.athena_workgroup_force_destroy

  dynamic "configuration" {
    iterator = configuration
    for_each = var.athena_workgroup_configuration

    content {
      bytes_scanned_cutoff_per_query     = lookup(configuration.value, "bytes_scanned_cutoff_per_query", null)
      enforce_workgroup_configuration    = lookup(configuration.value, "enforce_workgroup_configuration", null)
      publish_cloudwatch_metrics_enabled = lookup(configuration.value, "publish_cloudwatch_metrics_enabled", null)

      dynamic "result_configuration" {
        iterator = result_configuration
        for_each = length(keys(lookup(configuration.value, "result_configuration", {}))) > 0 ? [lookup(configuration.value, "result_configuration", {})] : []

        content {
          output_location = lookup(result_configuration.value, "output_location", null)

          dynamic "encryption_configuration" {
            iterator = encryption_configuration
            for_each = length(keys(lookup(result_configuration.value, "encryption_configuration", {}))) > 0 ? [lookup(result_configuration.value, "encryption_configuration", {})] : []

            content {
              encryption_option = lookup(encryption_configuration.value, "encryption_option", null)
              kms_key_arn       = lookup(encryption_configuration.value, "kms_key_arn", null)
            }
          }
        }
      }
    }
  }

  tags = merge(
    {
      Name = var.athena_workgroup_name != "" ? lower(var.athena_workgroup_name) : "${lower(var.name)}-athena-workgroup-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

