// File: versions.tf
terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.40"
    }
  }
}

provider "aws" {
  region = "ap-southeast-1"
}

variable "s3_bucket_name" {
  description = "Name of the S3 bucket"
  type        = string
  default     = "my-bucket-0fiesvn0oj"
}

locals {
  bucket_domain_name = aws_s3_bucket.main.bucket_regional_domain_name
}

resource "aws_s3_bucket" "main" {
  bucket = var.s3_bucket_name
}

resource "aws_s3_bucket_policy" "main" {
  bucket = aws_s3_bucket.main.id

  policy = jsonencode({
    Version = "2008-10-17"
    Id      = "PolicyForCloudFrontPrivateContent"
    Statement = [
      {
        Sid    = "AllowCloudFrontServicePrincipal"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action   = "s3:GetObject"
        Resource = "arn:aws:s3:::${aws_s3_bucket.main.bucket}/*"
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.main.arn
          }
        }
      }
    ]
  })
}

resource "aws_cloudfront_origin_access_control" "main" {
  name                              = local.bucket_domain_name
  description                       = local.bucket_domain_name
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

resource "aws_cloudfront_distribution" "main" {
  default_root_object = "index.html"
  enabled             = true
  default_cache_behavior {
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD", "OPTIONS"]
    target_origin_id       = local.bucket_domain_name
    viewer_protocol_policy = "redirect-to-https"
    forwarded_values {
      query_string = true
      cookies {
        forward = "all"
      }
    }
  }
  origin {
    domain_name              = local.bucket_domain_name
    origin_id                = local.bucket_domain_name
    origin_access_control_id = aws_cloudfront_origin_access_control.main.id
  }
  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }
  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

output "s3_bucket_name" {
  value = aws_s3_bucket.main.bucket
}

output "cloudfront_domain_name" {
  value = aws_cloudfront_distribution.main.domain_name
}

// File: inputs.tf
variable primary_network_cidr {
  type        = string
  default     = "10.10.0.0/16"
  description = "address range of primary"
}

variable primary_subnets {
  type        = list(string)
  default     = ["web", "app", "db", "mgmt", "web2", "app2", "db2"]
  description = "subnet names of the primary"
}

variable route_table_names {
  type        = list(string)
  default     = ["public", "private"]
  description = "Route tables for ntier subnet"
}

variable associations {
  type        = map

  default     = {
    public    = [ 0,3,4 ]
    private   = [ 1,2,5,6] 
  }
}

// File: locals.tf
locals {
  dbsubnets = ["db", "db2"]
  public_subnets        = lookup(var.associations, "public")
  private_subnets       = lookup(var.associations, "private")
}

// File: main.tf
# primary vpc
resource "aws_vpc" "ntier" {
    cidr_block  = var.primary_network_cidr
    tags        = {
        Name    = "ntier primary"
    }
}

# subnets
resource "aws_subnet" "subnets" {
    vpc_id      = aws_vpc.ntier.id
    count       = length(var.primary_subnets)
    cidr_block  = cidrsubnet(var.primary_network_cidr, 8, count.index)
    tags        = {
        Name    = var.primary_subnets[count.index]
    }
}

# internet gateway
resource "aws_internet_gateway" "igw" {
    vpc_id      = aws_vpc.ntier.id
    tags        = {
        Name    = "ntier primary"
    }

    depends_on  = [
        aws_subnet.subnets
    ]

}

# public route table and private route table
resource "aws_route_table" "route_tables" {
    vpc_id          = aws_vpc.ntier.id
    count           = length(var.route_table_names)

    route {
        cidr_block  = "0.0.0.0/0"
        gateway_id  = aws_internet_gateway.igw.id
    }

    tags        = {
        Name    =  var.route_table_names[count.index]
    }
}


## associate public subnets
resource "aws_route_table_association" "public-associations" {
    subnet_id           = aws_subnet.subnets[local.public_subnets[count.index]].id
    route_table_id      = aws_route_table.route_tables[0].id
    count               = length(local.public_subnets)
}

## associate private subnets

resource "aws_route_table_association" "private-associations" {
    subnet_id           = aws_subnet.subnets[local.private_subnets[count.index]].id
    route_table_id      = aws_route_table.route_tables[1].id
    count               = length(local.private_subnets)
}

// File: outputs.tf
output primary_vpc_id {
  value       = aws_vpc.ntier.id
  description = "This represents vpc id"
  depends_on  = []
}

output subnets {
  value       = aws_subnet.subnets[*].id
  description = "all subnet ids"
}

// File: main.tf
locals {
  tgw    = var.existing_tgw == null ? aws_ec2_transit_gateway.tgw[0] : length(var.existing_tgw) == 0 ? aws_ec2_transit_gateway.tgw[0] : data.aws_ec2_transit_gateway.tgw[0]
  tgw_id = local.tgw.id
}

## Transit gateway
data "aws_ec2_transit_gateway" "tgw" {
  count = var.existing_tgw == null ? 0 : length(var.existing_tgw) == 0 ? 0 : 1

  id = lookup(var.existing_tgw, "id", null)
  dynamic "filter" {
    for_each = lookup(var.existing_tgw, "filter", {})
    content {
      name   = filter.key
      values = filter.value
    }
  }
}

resource "aws_ec2_transit_gateway" "tgw" {
  count = var.existing_tgw == null ? 1 : length(var.existing_tgw) == 0 ? 1 : 0

  amazon_side_asn                 = var.amazon_side_asn
  auto_accept_shared_attachments  = var.auto_accept_shared_attachments
  default_route_table_association = var.default_route_table_association
  default_route_table_propagation = var.default_route_table_propagation
  vpn_ecmp_support                = var.vpn_ecmp_support
  dns_support                     = var.dns_support
  description                     = var.tgw_description
  tags = merge(
    {
      Name = var.tgw_name
    },
    lookup(var.tags, "general", {}),
    lookup(var.tags, "tgw", {})
  )
}

## Transit gateway VPC attachment
resource "aws_ec2_transit_gateway_vpc_attachment" "tgw_attachments" {
  for_each = var.tgw_attachments

  subnet_ids                                      = each.value.subnet_ids
  transit_gateway_id                              = local.tgw_id
  vpc_id                                          = each.value.vpc_id
  appliance_mode_support                          = lookup(each.value, "appliance_mode_support", "disable")
  dns_support                                     = lookup(each.value, "dns_support", "enable")
  ipv6_support                                    = lookup(each.value, "ipv6_support", "disable")
  transit_gateway_default_route_table_association = lookup(each.value, "transit_gateway_default_route_table_association", true)
  transit_gateway_default_route_table_propagation = lookup(each.value, "transit_gateway_default_route_table_propagation", true)
  tags = merge(
    {
      Name = each.key
    },
    lookup(var.tags, "general", {}),
    lookup(var.tags, "tgw_attachment", {})
  )
}

// File: outputs.tf
output "tgw" {
  value = local.tgw
}

output "tgw_attachments" {
  value = {
    for tgw_attachment in aws_ec2_transit_gateway_vpc_attachment.tgw_attachments :
    tgw_attachment.tags.Name => tgw_attachment.id
  }
}

// File: variables.tf
## Transit gateway
variable "existing_tgw" {
  description = <<-EOF
    Using existing Transit gateway. 
    If the id is specified, will use this Transit gateway ID. Otherwise, will search the Transit gateway based on the given infomation.
    Options:
        - id         :  ID of the specific Transit gateway.
        - filter     :  Map of the filters. Value should be a list.     
    Example:
    ```
    existing_tgw = {
        filter = {
            "options.amazon-side-asn" = ["64512"]
        }
    }
    ```
    EOF
  type        = any
  default     = null
  validation {
    condition = var.existing_tgw == null ? true : alltrue([
      for k, v in var.existing_tgw : contains([
        "id",
        "filter"
      ], k)
    ])
    error_message = "One or more argument(s) can not be identified, available options: id, filter."
  }
}

variable "tgw_name" {
  description = "Transit gateway name"
  default     = ""
  type        = string
}

variable "amazon_side_asn" {
  description = "Private Autonomous System Number (ASN) for the Amazon side of a BGP session. The range is 64512 to 65534 for 16-bit ASNs and 4200000000 to 4294967294 for 32-bit ASNs. Default value: 64512."
  default     = "64512"
  type        = string
}

variable "auto_accept_shared_attachments" {
  description = "Whether resource attachment requests are automatically accepted. Valid values: disable, enable. Default value: disable."
  default     = "disable"
  type        = string
}

variable "default_route_table_association" {
  description = "Whether resource attachments are automatically associated with the default association route table. Valid values: disable, enable. Default value: enable."
  default     = "enable"
  type        = string
}

variable "default_route_table_propagation" {
  description = "Whether resource attachments automatically propagate routes to the default propagation route table. Valid values: disable, enable. Default value: enable."
  default     = "enable"
  type        = string
}

variable "vpn_ecmp_support" {
  description = "Whether VPN Equal Cost Multipath Protocol support is enabled. Valid values: disable, enable. Default value: enable."
  default     = "enable"
  type        = string
}

variable "dns_support" {
  description = "Whether DNS support is enabled. Valid values: disable, enable. Default value: enable."
  default     = "enable"
  type        = string
}

variable "tgw_description" {
  description = "Description of the EC2 Transit Gateway."
  default     = ""
  type        = string
}

## Transit gateway attachment
variable "tgw_attachments" {
  description = <<-EOF
    Transit gateway VPC attachments for the Transit gateway. 
    Format:
    ```
        tgw_attachments = {
            \<Attachment name\> = {
                subnet_ids         = \<Subnet_id\>  
                transit_gateway_id = \<Transit_gateway_id\>
                vpc_id             = \<VPC_id\> 
                \<Option\> = \<Option value\>
            }
        }
    ```
    Options:
        - subnet_ids                                      : (Required|list) Identifiers of EC2 Subnets.
        - vpc_id                                          : (Required|string) Identifier of EC2 VPC.
        - appliance_mode_support                          : (Optional|string) Whether Appliance Mode support is enabled. If enabled, a traffic flow between a source and destination uses the same Availability Zone for the VPC attachment for the lifetime of that flow. Valid values: disable, enable. Default value: disable.
        - dns_support                                     : (Optional|string) Whether DNS support is enabled. Valid values: disable, enable. Default value: enable.
        - ipv6_support                                    : (Optional|string) Whether IPv6 support is enabled. Valid values: disable, enable. Default value: disable.
        - transit_gateway_default_route_table_association : (Optional|bool) Boolean whether the VPC Attachment should be associated with the EC2 Transit Gateway association default route table. This cannot be configured or perform drift detection with Resource Access Manager shared EC2 Transit Gateways. Default value: true.
        - transit_gateway_default_route_table_propagation : (Optional|bool) Boolean whether the VPC Attachment should propagate routes with the EC2 Transit Gateway propagation default route table. This cannot be configured or perform drift detection with Resource Access Manager shared EC2 Transit Gateways. Default value: true.

    Example:
    ```
    tgw_attachments = {
        security_vpc = {
            subnet_ids         = \<Subnet_id\>  
            vpc_id             = \<VPC_id\> 
        }
    }
    ```
    EOF
  type        = any
  default     = {}
  validation {
    condition = length(var.tgw_attachments) == 0 ? true : alltrue([
      for k, v in var.tgw_attachments : alltrue([
        for sk, sv in v : contains([
          "subnet_ids",
          "vpc_id",
          "appliance_mode_support",
          "dns_support",
          "ipv6_support",
          "transit_gateway_default_route_table_association",
          "transit_gateway_default_route_table_propagation"
        ], sk)
      ])
    ])
    error_message = "One or more argument(s) can not be identified, available options: subnet_ids, vpc_id, appliance_mode_support, dns_support, ipv6_support, transit_gateway_default_route_table_association, transit_gateway_default_route_table_propagation."
  }
}

## Tag related
variable "tags" {
  description = <<-EOF
  Tags that applies to related resources.
  Format:
  ```
    tags = {
        \<Option\> = \<Option value\>
    }
  ```
  Options:
    - general         :  Tags will add to all resources.
    - tgw             :  Tags for Transit gateway.
    - tgw_attachment  :  Tags for Transit gateway attachment.

  Example:
  ```
  tags = {
    general = {
      Created_from = "Terraform"
    },
    tgw = {
      Used_to = "ASG"
    }
  }
  ```
  EOF

  default = {}
  type    = map(map(string))
  validation {
    condition = var.tags == null ? true : alltrue([
      for k, v in var.tags : contains([
        "general",
        "tgw",
        "tgw_attachment"
      ], k)
    ])
    error_message = "One or more argument(s) can not be identified, available options: general, tgw, tgw_attachment."
  }
}

// File: versions.tf
terraform {
  required_providers {
    aws = {
      source = "hashicorp/aws"
    }
  }
  required_version = ">= 1.3, < 2.0.0"
}

// File: datasource.tf
# Global 
data "aws_region" "current" {}
data "aws_availability_zones" "available" {}
data "aws_caller_identity" "current" {}

// File: outputs.tf
output "region" {
  value = data.aws_region.current.description
}

output "account_id" {
  value = data.aws_caller_identity.current.id
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public_subnets[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private_subnets[*].id
}

output "vpc_cidr" {
  value = var.vpc_cidr
}

output "public_subnet_cidrs" {
  value = var.public_subnet_cidrs
}

output "private_subnet_cidrs" {
  value = var.private_subnet_cidrs
}

// File: subnets.tf
# Public subnets
resource "aws_subnet" "public_subnets" {
  count                   = length(var.public_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.public_subnet_cidrs, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(var.common_tags, {
    Name   = "${var.env}-public-subnet-${count.index + 1}"
    Region = "Region: ${var.region}"
  })
}

resource "aws_route_table" "public_subnets" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(var.common_tags, {
    Name   = "${var.env}-route-public-subnets"
    Region = "Region: ${var.region}"
  })
}

resource "aws_route_table_association" "public_routes" {
  count          = length(aws_subnet.public_subnets[*].id)
  route_table_id = aws_route_table.public_subnets.id
  subnet_id      = element(aws_subnet.public_subnets[*].id, count.index)
}

# Private subnets
resource "aws_subnet" "private_subnets" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.private_subnet_cidrs, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(var.common_tags, {
    Name   = "${var.env}-private-subnet-${count.index + 1}"
    Region = "Region: ${var.region}"
  })
}

resource "aws_eip" "nat" {
  count = length(var.private_subnet_cidrs)

  tags = merge(var.common_tags, {
    Name   = "${var.env}-nat-eip-${count.index + 1}"
    Region = "Region: ${var.region}"
  })
}

resource "aws_nat_gateway" "nat" {
  count         = length(var.private_subnet_cidrs)
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = element(aws_subnet.public_subnets[*].id, count.index)

  tags = merge(var.common_tags, {
    Name   = "${var.env}-nat-gw-${count.index + 1}"
    Region = "Region: ${var.region}"
  })
}

resource "aws_route_table" "private_subnets" {
  count  = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_nat_gateway.nat[count.index].id
  }

  tags = merge(var.common_tags, {
    Name   = "${var.env}-route-private-subnets-${count.index + 1}"
    Region = "Region: ${var.region}"
  })
}

resource "aws_route_table_association" "private_routes" {
  count          = length(aws_subnet.private_subnets[*].id)
  route_table_id = aws_route_table.private_subnets[count.index].id
  subnet_id      = element(aws_subnet.private_subnets[*].id, count.index)
}

// File: variables.tf
variable "region" {
  default = "us-east-1"
}

variable "env" {
  default = "test"
}

variable "vpc_cidr" {
  default = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  default = [
    "10.0.10.0/24",
    "10.0.11.0/24"
  ]
}

variable "private_subnet_cidrs" {
  default = [
    "10.0.20.0/24",
    "10.0.21.0/24"
  ]
}

variable "common_tags" {
  default = {
    Owner: "Valerii Vasianovych"
    Project: "Terraform AWS"
  }
}

// File: vpc.tf
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = merge(var.common_tags, {
    Name   = "${var.env}-vpc"
    Region = "Region: ${var.region}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.common_tags, {
    Name   = "${var.env}-igw"
    Region = "Region: ${var.region}"
  })
}

// File: acm_certificate.tf
#---------------------------------------------------
# AWS ACM (Amazon Certificate Manager) certificate
#---------------------------------------------------
resource "aws_acm_certificate" "acm_certificate" {
  count = var.enable_acm_certificate && !var.enable_acm_certificate_private_ca && !var.enable_import_existing_certificate ? 1 : 0

  domain_name       = var.acm_certificate_domain_name != "" ? var.acm_certificate_domain_name : "${lower(var.name)}-acm-cert-${lower(var.environment)}"
  validation_method = upper(var.acm_certificate_validation_method)

  subject_alternative_names = var.acm_certificate_subject_alternative_names

  dynamic "options" {
    iterator = options
    for_each = var.acm_certificate_options

    content {
      certificate_transparency_logging_preference = lookup(options.value, "certificate_transparency_logging_preference", null)
    }
  }

  tags = merge(
    {
      Name = var.acm_certificate_domain_name != "" ? var.acm_certificate_domain_name : "${lower(var.name)}-acm-cert-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

#---------------------------------------------------
# AWS ACM (Amazon Certificate Manager) certificate for private CA
#---------------------------------------------------
resource "aws_acm_certificate" "acm_certificate_private_ca" {
  count = var.enable_acm_certificate_private_ca && !var.enable_acm_certificate && !var.enable_import_existing_certificate ? 1 : 0

  domain_name               = var.acm_certificate_domain_name != "" ? var.acm_certificate_domain_name : "${lower(var.name)}-acm-cert-${lower(var.environment)}"
  certificate_authority_arn = var.acm_certificate_certificate_authority_arn

  subject_alternative_names = var.acm_certificate_subject_alternative_names

  tags = merge(
    {
      Name = var.acm_certificate_domain_name != "" ? var.acm_certificate_domain_name : "${lower(var.name)}-acm-cert-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

#---------------------------------------------------
# AWS ACM (Amazon Certificate Manager) certificate for exististing certificate
#---------------------------------------------------
resource "aws_acm_certificate" "acm_certificate_exist" {
  count = var.enable_import_existing_certificate && !var.enable_acm_certificate && !var.enable_acm_certificate_private_ca ? 1 : 0

  private_key       = var.acm_certificate_private_key
  certificate_body  = var.acm_certificate_certificate_body
  certificate_chain = var.acm_certificate_certificate_chain

  tags = merge(
    {
      Name = var.acm_certificate_domain_name != "" ? var.acm_certificate_domain_name : "${lower(var.name)}-acm-cert-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: acm_certificate_validation.tf
#---------------------------------------------------
# AWS ACM (Amazon Certificate Manager) certificate validation
#---------------------------------------------------
resource "aws_acm_certificate_validation" "acm_certificate_validation" {
  count = var.enable_acm_certificate_validation ? 1 : 0

  certificate_arn = var.acm_certificate_validation_certificate_arn

  validation_record_fqdns = var.acm_certificate_validation_record_fqdns

  dynamic "timeouts" {
    iterator = timeouts
    for_each = length(keys(var.acm_certificate_validation_timeouts)) > 0 ? [var.acm_certificate_validation_timeouts] : []

    content {
      create = lookup(timeouts.value, "create", null)
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: acmpca_certificate_authority.tf
#---------------------------------------------------
# AWS Certificate Manager Private Certificate Authorities (ACM PCA Certificate Authorities)
#---------------------------------------------------
resource "aws_acmpca_certificate_authority" "acmpca_certificate_authority" {
  count = var.enable_acmpca_certificate_authority ? 1 : 0

  enabled = var.acmpca_certificate_authority_enabled

  permanent_deletion_time_in_days = var.acmpca_certificate_authority_permanent_deletion_time_in_days

  dynamic "certificate_authority_configuration" {
    iterator = certificate_authority_configuration
    for_each = length(keys(var.acmpca_certificate_authority_certificate_authority_configuration)) > 0 ? [var.acmpca_certificate_authority_certificate_authority_configuration] : []

    content {
      key_algorithm     = lookup(certificate_authority_configuration.value, "key_algorithm", null)
      signing_algorithm = lookup(certificate_authority_configuration.value, "signing_algorithm", null)

      dynamic "subject" {
        iterator = subject
        for_each = length(keys(lookup(certificate_authority_configuration.value, "subject", {}))) > 0 ? [lookup(certificate_authority_configuration.value, "subject", {})] : []

        content {
          common_name                  = lookup(subject.value, "common_name", null)
          country                      = lookup(subject.value, "country", null)
          distinguished_name_qualifier = lookup(subject.value, "distinguished_name_qualifier", null)
          generation_qualifier         = lookup(subject.value, "generation_qualifier", null)
          given_name                   = lookup(subject.value, "given_name", null)
          initials                     = lookup(subject.value, "initials", null)
          locality                     = lookup(subject.value, "locality", null)
          organization                 = lookup(subject.value, "organization", null)
          organizational_unit          = lookup(subject.value, "organizational_unit", null)
          pseudonym                    = lookup(subject.value, "pseudonym", null)
          state                        = lookup(subject.value, "state", null)
          surname                      = lookup(subject.value, "surname", null)
          title                        = lookup(subject.value, "title", null)
        }
      }
    }
  }

  dynamic "revocation_configuration" {
    iterator = revocation_configuration
    for_each = length(keys(var.acmpca_certificate_authority_revocation_configuration)) > 0 ? [var.acmpca_certificate_authority_revocation_configuration] : []

    content {
      dynamic "crl_configuration" {
        iterator = crl_configuration
        for_each = length(keys(lookup(revocation_configuration.value, "crl_configuration", {}))) > 0 ? [lookup(revocation_configuration.value, "crl_configuration", {})] : []

        content {
          expiration_in_days = lookup(crl_configuration.value, "expiration_in_days", null)

          custom_cname   = lookup(crl_configuration.value, "custom_cname", null)
          enabled        = lookup(crl_configuration.value, "enabled", null)
          s3_bucket_name = lookup(crl_configuration.value, "s3_bucket_name", null)
        }
      }
    }
  }

  dynamic "timeouts" {
    iterator = timeouts
    for_each = length(keys(var.acmpca_certificate_authority_timeouts)) > 0 ? [var.acmpca_certificate_authority_timeouts] : []

    content {
      create = lookup(timeouts.value, "create", null)
    }
  }

  tags = merge(
    {
      Name = var.acmpca_certificate_authority_name != "" ? var.acmpca_certificate_authority_name : "${lower(var.name)}-acmpca-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: acmpca_certificate_authority_certificate.tf
#---------------------------------------------------
# AWS Certificate Manager Private Certificate Authorities (certificate authority certificate)
#---------------------------------------------------

# https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/acmpca_certificate_authority_certificate

// File: acmpca_permission.tf
#---------------------------------------------------
# AWS Certificate Manager Private Certificate Authorities (permission)
#---------------------------------------------------

# https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/acmpca_permission

// File: acmpca_policy.tf
#---------------------------------------------------
# AWS Certificate Manager Private Certificate Authorities (policy)
#---------------------------------------------------

# https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/acmpca_policy

// File: outputs.tf
#---------------------------------------------------
# acm certificate
#---------------------------------------------------
output "aws_acm_certificate_id" {
  description = "The ARN of the certificate"
  value = element(concat(
    aws_acm_certificate.acm_certificate.*.id,
    aws_acm_certificate.acm_certificate_private_ca.*.id,
    aws_acm_certificate.acm_certificate_exist.*.id,
    [""]),
  0)
}

output "aws_acm_certificate_arn" {
  description = "The ARN of the certificate"
  value = element(concat(
    aws_acm_certificate.acm_certificate.*.arn,
    aws_acm_certificate.acm_certificate_private_ca.*.arn,
    aws_acm_certificate.acm_certificate_exist.*.arn,
    [""]),
  0)
}

output "aws_acm_certificate_domain_name" {
  description = "The domain name for which the certificate is issued"
  value = element(concat(
    aws_acm_certificate.acm_certificate.*.domain_name,
    aws_acm_certificate.acm_certificate_private_ca.*.domain_name,
    aws_acm_certificate.acm_certificate_exist.*.domain_name,
    [""]),
  0)
}

output "aws_acm_certificate_domain_validation_options" {
  description = "A list of attributes to feed into other resources to complete certificate validation. Can have more than one element, e.g. if SANs are defined. Only set if DNS-validation was used"
  value = element(concat(
    aws_acm_certificate.acm_certificate.*.domain_validation_options,
    aws_acm_certificate.acm_certificate_private_ca.*.domain_validation_options,
    aws_acm_certificate.acm_certificate_exist.*.domain_validation_options,
    [""]),
  0)
}

#---------------------------------------------------
# AWS ACM (Amazon Certificate Manager) certificate validation
#---------------------------------------------------
output "acm_certificate_validation_id" {
  description = "The time at which the certificate was issued"
