  display_name    = var.sns_topic_display_name != "" ? var.sns_topic_display_name : "${lower(var.name)}-sns-${lower(var.environment)}"
  policy          = var.sns_topic_policy
  delivery_policy = var.sns_topic_delivery_policy

  application_success_feedback_role_arn    = var.sns_topic_application_success_feedback_role_arn
  application_success_feedback_sample_rate = var.sns_topic_application_success_feedback_sample_rate
  application_failure_feedback_role_arn    = var.sns_topic_application_failure_feedback_role_arn

  http_success_feedback_role_arn    = var.sns_topic_http_success_feedback_role_arn
  http_success_feedback_sample_rate = var.sns_topic_http_success_feedback_sample_rate
  http_failure_feedback_role_arn    = var.sns_topic_http_failure_feedback_role_arn

  kms_master_key_id = var.sns_topic_kms_master_key_id

  lambda_success_feedback_role_arn    = var.sns_topic_lambda_success_feedback_role_arn
  lambda_success_feedback_sample_rate = var.sns_topic_lambda_success_feedback_sample_rate
  lambda_failure_feedback_role_arn    = var.sns_topic_lambda_failure_feedback_role_arn

  sqs_success_feedback_role_arn    = var.sns_topic_sqs_success_feedback_role_arn
  sqs_success_feedback_sample_rate = var.sns_topic_sqs_success_feedback_sample_rate
  sqs_failure_feedback_role_arn    = var.sns_topic_sqs_failure_feedback_role_arn

  tags = merge(
    {
      Name = var.sns_topic_display_name != "" ? var.sns_topic_display_name : "${lower(var.name)}-sns-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: sns_topic_policy.tf
#---------------------------------------------------
# AWS SNS topic policies
#---------------------------------------------------
resource "aws_sns_topic_policy" "sns_topic_policy" {
  count = var.enable_sns_topic_policy ? 1 : 0

  arn    = var.sns_topic_policy_topic_arn != null ? var.sns_topic_policy_topic_arn : (var.enable_sns_topic ? element(concat(aws_sns_topic.sns_topic.*.arn, [""]), 0) : null)
  policy = var.sns_topic_policy_policy

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_sns_topic.sns_topic
  ]
}

// File: sns_topic_subscription.tf
#---------------------------------------------------
# AWS SNS topic subscription
#---------------------------------------------------
resource "aws_sns_topic_subscription" "sns_topic_subscription" {
  count = var.enable_sns_topic_subscription ? length(var.sns_topic_subscription_sns_endpoints) : 0

  topic_arn = var.sns_topic_subscription_topic_arn != "" ? var.sns_topic_subscription_topic_arn : element(concat(aws_sns_topic.sns_topic.*.arn, [""]), 0)

  confirmation_timeout_in_minutes = var.sns_topic_subscription_confirmation_timeout_in_minutes
  endpoint_auto_confirms          = var.sns_topic_subscription_endpoint_auto_confirms
  raw_message_delivery            = var.sns_topic_subscription_raw_message_delivery

  protocol = var.sns_topic_subscription_sns_protocol
  endpoint = var.sns_topic_subscription_sns_endpoints[count.index]

  filter_policy   = var.sns_topic_subscription_filter_policy
  delivery_policy = var.sns_topic_subscription_delivery_policy

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_sns_topic.sns_topic
  ]
}

// File: variables.tf
#-----------------------------------------------------------
# Global or/and default variables
#-----------------------------------------------------------
variable "name" {
  description = "Name to be used on all resources as prefix"
  default     = "TEST"
}

variable "environment" {
  description = "Environment for service"
  default     = "STAGE"
}

variable "tags" {
  description = "A list of tag blocks. Each element should have keys named key, value, etc."
  type        = map(string)
  default     = {}
}

#-----------------------------------------------------------
# SNS topic
#-----------------------------------------------------------
variable "enable_sns_topic" {
  description = "Enable SNS topic usage"
  default     = false
}

variable "sns_topic_name" {
  description = "The friendly name for the SNS topic. By default generated by Terraform."
  default     = ""
}

variable "sns_topic_name_prefix" {
  description = "(Optional) The friendly name for the SNS topic. Conflicts with sns_topic_name."
  default     = ""
}

variable "sns_topic_display_name" {
  description = "(Optional) The display name for the SNS topic"
  default     = ""
}

variable "sns_topic_delivery_policy" {
  description = "(Optional) The SNS delivery policy."
  default     = ""
}

variable "sns_topic_policy" {
  description = "(Optional) The fully-formed AWS policy as JSON. For more information about building AWS IAM policy documents with Terraform"
  default     = null
}

variable "sns_application_success_feedback_role_arn" {
  description = "(Optional) The IAM role permitted to receive success feedback for this topic"
  default     = null
}

variable "sns_application_success_feedback_sample_rate" {
  description = "(Optional) Percentage of success to sample"
  default     = null
}

variable "sns_application_failure_feedback_role_arn" {
  description = "(Optional) IAM role for failure feedback"
  default     = null
}

variable "sns_topic_http_success_feedback_role_arn" {
  description = "(Optional) The IAM role permitted to receive success feedback for this topic"
  default     = null
}

variable "sns_topic_http_success_feedback_sample_rate" {
  description = "(Optional) Percentage of success to sample"
  default     = null
}

variable "sns_topic_http_failure_feedback_role_arn" {
  description = "(Optional) IAM role for failure feedback"
  default     = null
}

variable "sns_topic_kms_master_key_id" {
  description = "(Optional) The ID of an AWS-managed customer master key (CMK) for Amazon SNS or a custom CMK."
  default     = null
}

variable "sns_topic_lambda_success_feedback_role_arn" {
  description = "(Optional) The IAM role permitted to receive success feedback for this topic"
  default     = null
}

variable "sns_topic_lambda_success_feedback_sample_rate" {
  description = "(Optional) Percentage of success to sample"
  default     = null
}

variable "sns_topic_lambda_failure_feedback_role_arn" {
  description = "(Optional) IAM role for failure feedback"
  default     = null
}

variable "sns_topic_sqs_success_feedback_role_arn" {
  description = "description"
  default     = null
}

variable "sns_topic_sqs_success_feedback_sample_rate" {
  description = "description"
  default     = null
}

variable "sns_topic_sqs_failure_feedback_role_arn" {
  description = "(Optional) IAM role for failure feedback"
  default     = null
}

#-----------------------------------------------------------
# SNS topic policy
#-----------------------------------------------------------
variable "enable_sns_topic_policy" {
  description = "Enable sns topic policy usage"
  default     = false
}

variable "sns_topic_policy_policy" {
  description = "(Required) The fully-formed AWS policy as JSON. For more information about building AWS IAM policy documents with Terraform, see the AWS IAM Policy Document Guide."
  default     = ""
}

variable "sns_topic_policy_topic_arn" {
  description = "The ARN of the SNS topic"
  default     = null
}


#-----------------------------------------------------------
# SNS topic subscription
#-----------------------------------------------------------
variable "enable_sns_topic_subscription" {
  description = "Enable sns topic subscription usage"
  default     = false
}

variable "sns_topic_subscription_topic_arn" {
  description = "(Required) The ARN of the SNS topic to subscribe to"
  default     = ""
}


variable "sns_topic_subscription_sns_protocol" {
  description = "The protocol to use. The possible values for this are: sqs, sms, lambda, application. (http or https are partially supported, see below) (email is option but unsupported)."
  default     = "sqs"
}

variable "sns_topic_subscription_sns_endpoints" {
  description = "The list of endpoints to send data to, the contents will vary with the protocol."
  default     = []
}

variable "sns_topic_subscription_confirmation_timeout_in_minutes" {
  description = "Set timeout in minutes. Integer indicating number of minutes to wait in retying mode for fetching subscription arn before marking it as failure. Only applicable for http and https protocols (default is 1 minute)."
  default     = 1
}

variable "sns_topic_subscription_endpoint_auto_confirms" {
  description = "Enable endpoint auto confirms. Boolean indicating whether the end point is capable of auto confirming subscription e.g., PagerDuty (default is false)"
  default     = false
}

variable "sns_topic_subscription_raw_message_delivery" {
  description = "Set raw message delivery.Boolean indicating whether or not to enable raw message delivery (the original message is directly passed, not wrapped in JSON with the original message in the message property) (default is false)."
  default     = false
}

variable "sns_topic_subscription_filter_policy" {
  description = "(Optional) JSON String with the filter policy that will be used in the subscription to filter messages seen by the target resource."
  default     = ""
}

variable "sns_topic_subscription_delivery_policy" {
  description = "(Optional) JSON String with the delivery policy (retries, backoff, etc.) that will be used in the subscription - this only applies to HTTP/S subscriptions. Refer to the SNS docs for more details."
  default     = ""
}

variable "sns_topic_application_success_feedback_role_arn" {
  description = "(Optional) The IAM role permitted to receive success feedback for this topic"
  default     = null
}

variable "sns_topic_application_success_feedback_sample_rate" {
  description = "(Optional) Percentage of success to sample"
  default     = null
}

variable "sns_topic_application_failure_feedback_role_arn" {
  description = "(Optional) IAM role for failure feedback"
  default     = null
}

#---------------------------------------------------
# SNS sms preferences
#---------------------------------------------------
variable "enable_sns_sms_preferences" {
  description = "Enable sns sms preferences usage"
  default     = false
}

variable "sns_sms_preferences_monthly_spend_limit" {
  description = "(Optional) The maximum amount in USD that you are willing to spend each month to send SMS messages."
  default     = null
}

variable "sns_sms_preferences_delivery_status_iam_role_arn" {
  description = "(Optional) The ARN of the IAM role that allows Amazon SNS to write logs about SMS deliveries in CloudWatch Logs."
  default     = null
}

variable "sns_sms_preferences_delivery_status_success_sampling_rate" {
  description = "(Optional) The percentage of successful SMS deliveries for which Amazon SNS will write logs in CloudWatch Logs. The value must be between 0 and 100."
  default     = null
}

variable "sns_sms_preferences_default_sender_id" {
  description = "(Optional) A string, such as your business brand, that is displayed as the sender on the receiving device."
  default     = null
}

variable "sns_sms_preferences_default_sms_type" {
  description = "(Optional) The type of SMS message that you will send by default. Possible values are: Promotional, Transactional"
  default     = null
}

variable "sns_sms_preferences_usage_report_s3_bucket" {
  description = "(Optional) The name of the Amazon S3 bucket to receive daily SMS usage reports from Amazon SNS."
  default     = null
}

#---------------------------------------------------
# SNS sms preferences
#---------------------------------------------------
variable "enable_sns_platform_application" {
  description = "Enable sns platform application usage"
  default     = false
}

variable "sns_platform_application_name" {
  description = "The friendly name for the SNS platform application"
  default     = ""
}

variable "sns_platform_application_platform" {
  description = "(Required) The platform that the app is registered with."
  default     = ""
}

variable "sns_platform_application_platform_credential" {
  description = "(Required) Application Platform credential. "
  default     = ""
}

variable "sns_platform_application_event_delivery_failure_topic_arn" {
  description = "(Optional) SNS Topic triggered when a delivery to any of the platform endpoints associated with your platform application encounters a permanent failure."
  default     = null
}

variable "sns_platform_application_event_endpoint_created_topic_arn" {
  description = "(Optional) SNS Topic triggered when a new platform endpoint is added to your platform application."
  default     = null
}

variable "sns_platform_application_event_endpoint_deleted_topic_arn" {
  description = "(Optional) SNS Topic triggered when an existing platform endpoint is deleted from your platform application."
  default     = null
}

variable "sns_platform_application_event_endpoint_updated_topic_arn" {
  description = "(Optional) SNS Topic triggered when an existing platform endpoint is changed from your platform application."
  default     = null
}

variable "sns_platform_application_failure_feedback_role_arn" {
  description = "(Optional) The IAM role permitted to receive failure feedback for this application."
  default     = null
}

variable "sns_platform_application_platform_principal" {
  description = "(Optional) Application Platform principal."
  default     = null
}

variable "sns_platform_application_success_feedback_role_arn" {
  description = "(Optional) The IAM role permitted to receive success feedback for this application."
  default     = null
}

variable "sns_platform_application_success_feedback_sample_rate" {
  description = "(Optional) The percentage of success to sample (0-100)"
  default     = null
}

// File: main.tf
data "aws_region" "current" {}
data "aws_caller_identity" "current" {}

resource "random_pet" "random" {
  length    = 2
  separator = "-"
}

resource "aws_iam_role" "execution_role" {
  name               = "api-gateway-sqs-execution-role"
  assume_role_policy = <<EOF
{
    "Version": "2012-10-17",
    "Statement": [
        {
        "Sid": "",
        "Effect": "Allow",
        "Principal": {
            "Service": "apigateway.amazonaws.com"
        },
        "Action": "sts:AssumeRole"
        }
    ]
}
EOF
}

resource "aws_iam_role_policy_attachment" "execution_role" {
  role       = aws_iam_role.execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSQSFullAccess"
}

resource "aws_apigatewayv2_api" "websocket_api" {
  name                       = random_pet.random.id
  protocol_type              = "WEBSOCKET"
  route_selection_expression = "$request.body.action"
}

resource "aws_sqs_queue" "sqs_queue" {
  name = random_pet.random.id
}

resource "aws_apigatewayv2_integration" "sqs_integration" {
  api_id                 = aws_apigatewayv2_api.websocket_api.id
  credentials_arn        = aws_iam_role.execution_role.arn
  integration_type       = "AWS"
  payload_format_version = "1.0"
  integration_method     = "POST"
  integration_uri        = "arn:aws:apigateway:${data.aws_region.current.name}:sqs:path/${data.aws_caller_identity.current.account_id}/${aws_sqs_queue.sqs_queue.name}"
  passthrough_behavior   = "NEVER"
  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }
  request_templates = {
    "default" : "Action=SendMessage&MessageBody=$util.urlEncode($input.body)"
  }
  template_selection_expression = "default"
}

resource "aws_apigatewayv2_integration" "mock_integration" {
  api_id           = aws_apigatewayv2_api.websocket_api.id
  integration_type = "MOCK"

  request_templates = {
    "default" = <<EOF
{
  "statusCode": 200
}
EOF
  }
  template_selection_expression = "default"
}

resource "aws_apigatewayv2_integration" "disconnect_sqs_integration" {
  api_id                 = aws_apigatewayv2_api.websocket_api.id
  credentials_arn        = aws_iam_role.execution_role.arn
  integration_type       = "AWS"
  payload_format_version = "1.0"
  integration_method     = "POST"
  integration_uri        = "arn:aws:apigateway:${data.aws_region.current.name}:sqs:path/${data.aws_caller_identity.current.account_id}/${aws_sqs_queue.sqs_queue.name}"
  passthrough_behavior   = "NEVER"
  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }
  request_templates = {
    "default" : "Action=SendMessage&MessageBody=$util.urlEncode('Client disconnected')"
  }
  template_selection_expression = "default"
}

resource "aws_apigatewayv2_route" "connect_route" {
  api_id    = aws_apigatewayv2_api.websocket_api.id
  route_key = "$connect"
  target    = "integrations/${aws_apigatewayv2_integration.mock_integration.id}"
}

resource "aws_apigatewayv2_route" "default_route" {
  api_id    = aws_apigatewayv2_api.websocket_api.id
  route_key = "$default"
  target    = "integrations/${aws_apigatewayv2_integration.sqs_integration.id}"
}

resource "aws_apigatewayv2_route" "disconnect_route" {
  api_id    = aws_apigatewayv2_api.websocket_api.id
  route_key = "$disconnect"
  target    = "integrations/${aws_apigatewayv2_integration.disconnect_sqs_integration.id}"
}

resource "aws_apigatewayv2_route_response" "connect_route_response" {
  api_id             = aws_apigatewayv2_api.websocket_api.id
  route_id           = aws_apigatewayv2_route.connect_route.id
  route_response_key = "$default"
}

resource "aws_apigatewayv2_integration_response" "mock_response" {
  api_id                   = aws_apigatewayv2_api.websocket_api.id
  integration_id           = aws_apigatewayv2_integration.mock_integration.id
  integration_response_key = "$default"
  response_templates = {
    "$default" = "{'statusCode': 200}"
  }
}

resource "aws_apigatewayv2_route_response" "default_route_response" {
  api_id             = aws_apigatewayv2_api.websocket_api.id
  route_id           = aws_apigatewayv2_route.default_route.id
  route_response_key = "$default"
}

resource "aws_apigatewayv2_integration_response" "sqs_response" {
  api_id                   = aws_apigatewayv2_api.websocket_api.id
  integration_id           = aws_apigatewayv2_integration.sqs_integration.id
  integration_response_key = "$default"
  response_templates = {
    "$default" = "$input.body"
  }
}

resource "aws_cloudwatch_log_group" "apigw_logs" {
  name              = "/aws/apigateway/${aws_apigatewayv2_api.websocket_api.name}"
  retention_in_days = 1
}

resource "aws_iam_role_policy" "apigw_logs" {
  name = "APIGWLogsPolicy"
  role = aws_iam_role.execution_role.id

  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": [
        "logs:CreateLogGroup",
        "logs:CreateLogStream",
        "logs:DescribeLogGroups",
        "logs:DescribeLogStreams",
        "logs:PutLogEvents",
        "logs:GetLogEvents",
        "logs:FilterLogEvents"
      ],
      "Resource": "*"
    }
  ]
}
EOF
}

resource "aws_apigatewayv2_stage" "stage" {
  api_id      = aws_apigatewayv2_api.websocket_api.id
  name        = "dev"
  auto_deploy = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.apigw_logs.arn
    format          = "$context.identity.sourceIp $context.identity.caller $context.identity.user [$context.requestTime] \"$context.httpMethod $context.routeKey $context.protocol\" $context.status $context.responseLength $context.requestId"
  }
}

output "ws_endpoint" {
  value = "${aws_apigatewayv2_api.websocket_api.api_endpoint}/${aws_apigatewayv2_stage.stage.name}"
}

// File: main.tf
# pass: enabled=false (required)
resource "aws_cloudfront_distribution" "example_pass_disabled" {
  enabled = false # disabled

  origin {
    domain_name = "example.data.mediastore.amazonaws.com" # contains dangerous domain name
    origin_id   = "custom-origin-example"

    custom_origin_config {
      origin_protocol_policy = "match-viewer"  # Does not enforce HTTPS only, matches RQL condition to fail
      http_port              = 80
      https_port             = 443
      origin_ssl_protocols   = ["TLSv1", "TLSv1.1", "TLSv1.2"]
    }
  }

  default_cache_behavior {
    target_origin_id       = "custom-origin-example"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD"]
    cached_methods  = ["GET", "HEAD"]

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    min_ttl = 0
    default_ttl = 3600
    max_ttl = 86400
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}


