// File: clients.tf
resource "aws_cognito_user_pool_client" "client" {
  for_each = toset(var.clients)

  name            = each.value
  generate_secret = var.generate_secret
  user_pool_id    = aws_cognito_user_pool.pool.id

  access_token_validity                = var.access_token_validity
  allowed_oauth_flows_user_pool_client = var.allowed_oauth_flows_user_pool_client
  enable_token_revocation              = var.enable_token_revocation
  explicit_auth_flows                  = var.explicit_auth_flows
  id_token_validity                    = var.id_token_validity
  prevent_user_existence_errors        = var.prevent_user_existence_errors
  read_attributes                      = var.read_attributes
  refresh_token_validity               = var.refresh_token_validity
  write_attributes                     = var.write_attributes
  callback_urls                        = var.callback_urls
  logout_urls                          = var.logout_urls
  allowed_oauth_flows                  = var.allowed_oauth_flows
  allowed_oauth_scopes                 = var.allowed_oauth_scopes
  supported_identity_providers         = var.supported_identity_providers
  token_validity_units {
    access_token  = var.token_validity_units.access_token
    id_token      = var.token_validity_units.id_token
    refresh_token = var.token_validity_units.refresh_token
  }
}

// File: domain.tf
resource "aws_cognito_user_pool_domain" "main" {
  count = (var.domain != "") ? 1 : 0

  domain          = var.domain
  certificate_arn = var.cert_arn
  user_pool_id    = aws_cognito_user_pool.pool.id
}

resource "aws_route53_record" "auth-cognito-A" {
  count = var.create_route53_record ? 1 : 0

  name    = aws_cognito_user_pool_domain.main[0].domain
  type    = "A"
  zone_id = var.zone_id
  alias {
    evaluate_target_health = false
    name                   = aws_cognito_user_pool_domain.main[0].cloudfront_distribution_arn
    # This zone_id is fixed
    zone_id = "Z2FDTNDATAQYW2"
  }
}

// File: group.tf
resource "aws_cognito_user_group" "group" {
  count = (var.user_group != "") ? 1 : 0

  name         = var.user_group
  user_pool_id = aws_cognito_user_pool.pool.id
  precedence   = var.precedence
  role_arn     = var.role_arn
}

// File: output.tf
output "arn" {
  value       = aws_cognito_user_pool.pool.arn
  description = "AWS Cognito User Pool ARN"
}

output "clients_id" {
  value = values(tomap(aws_cognito_user_pool_client.client)).*.id
}

// File: pool.tf
resource "aws_cognito_user_pool" "pool" {
  name = var.name

  alias_attributes           = var.alias_attributes
  auto_verified_attributes   = var.auto_verified_attributes
  email_verification_message = var.email_verification_message
  email_verification_subject = var.email_verification_subject
  mfa_configuration          = var.mfa_configuration
  sms_authentication_message = var.sms_authentication_message
  sms_verification_message   = var.sms_verification_message

  dynamic "sms_configuration" {
    for_each = (var.sms_configuration.external_id != "" && var.sms_configuration.sns_caller_arn != "") ? [1] : []

    content {
      external_id    = var.sms_configuration.external_id
      sns_caller_arn = var.sms_configuration.sns_caller_arn
    }
  }

  verification_message_template {
    email_message_by_link = var.verification_message_template.email_message_by_link
    email_subject_by_link = var.verification_message_template.email_subject_by_link
  }

  account_recovery_setting {
    dynamic "recovery_mechanism" {
      for_each = var.recovery_mechanism

      content {
        name     = recovery_mechanism.value.name
        priority = recovery_mechanism.value.priority
      }
    }
  }

  admin_create_user_config {
    allow_admin_create_user_only = var.allow_admin_create_user_only

    invite_message_template {
      email_message = var.invite_message_template.email_message
      email_subject = var.invite_message_template.email_subject
      sms_message   = var.invite_message_template.sms_message
    }
  }

  dynamic "device_configuration" {
    for_each = (var.challenge_required_on_new_device != null || var.device_only_remembered_on_user_prompt != null) ? [{
      challenge_required_on_new_device      = var.challenge_required_on_new_device
      device_only_remembered_on_user_prompt = var.device_only_remembered_on_user_prompt
    }] : []

    content {
      challenge_required_on_new_device      = device_configuration.value.challenge_required_on_new_device
      device_only_remembered_on_user_prompt = device_configuration.value.device_only_remembered_on_user_prompt
    }
  }

  dynamic "lambda_config" {
    for_each = length(keys(var.lambda_config)) != 0 ? [1] : []

    content {
      kms_key_id                     = try(var.lambda_config.kms_key_id, null)
      create_auth_challenge          = try(var.lambda_config.create_auth_challenge, null)
      define_auth_challenge          = try(var.lambda_config.define_auth_challenge, null)
      verify_auth_challenge_response = try(var.lambda_config.verify_auth_challenge_response, null)

      dynamic "custom_email_sender" {
        for_each = (try(var.lambda_config.custom_email_sender.lambda_arn, null) != null && try(var.lambda_config.custom_email_sender.lambda_version, null) != null) ? [1] : []

        content {
          lambda_arn     = var.lambda_config.custom_email_sender.lambda_arn
          lambda_version = var.lambda_config.custom_email_sender.lambda_version
        }
      }
    }
  }

  dynamic "schema" {
    for_each = [for item in var.schema : item if(try(item.string_attribute_constraints.max_length, null) != null && try(item.string_attribute_constraints.min_length, null) != null)]

    content {
      attribute_data_type      = schema.value.attribute_data_type
      developer_only_attribute = schema.value.developer_only_attribute
      mutable                  = schema.value.mutable
      name                     = schema.value.name
      required                 = schema.value.required

      string_attribute_constraints {
        max_length = schema.value.string_attribute_constraints.max_length
        min_length = schema.value.string_attribute_constraints.min_length
      }
    }
  }

  dynamic "schema" {
    for_each = [for item in var.schema : item if(try(item.string_attribute_constraints.max_length, null) == null || try(item.string_attribute_constraints.min_length, null) == null)]

    content {
      attribute_data_type      = schema.value.attribute_data_type
      developer_only_attribute = schema.value.developer_only_attribute
      mutable                  = schema.value.mutable
      name                     = schema.value.name
      required                 = schema.value.required

      string_attribute_constraints {}
    }
  }

  dynamic "software_token_mfa_configuration" {
    for_each = (var.software_token_mfa_configuration == true || var.software_token_mfa_configuration == false) ? [1] : []

    content {
      enabled = var.software_token_mfa_configuration
    }
  }

  dynamic "username_configuration" {
    for_each = (var.case_sensitive == true || var.case_sensitive == false) ? [1] : []

    content {
      case_sensitive = var.case_sensitive
    }
  }

  lifecycle {
    ignore_changes = [
      estimated_number_of_users
    ]
  }
}

// File: variables.tf
variable "name" {
  type        = string
  default     = "Pool name"
  description = "Name of the pool that will be created"
}

variable "clients" {
  type        = list(string)
  default     = []
  description = "List of client names"
}

variable "generate_secret" {
  type        = bool
  default     = false
  description = "Should an application secret be generated."
}

variable "alias_attributes" {
  type        = list(string)
  default     = ["email", "phone_number"]
  description = "Attributes supported as an alias for this user pool."
}

variable "auto_verified_attributes" {
  type        = list(string)
  default     = []
  description = "Attributes to be auto-verified, can be email and phone_number."
}

variable "email_verification_message" {
  type        = string
  default     = "Some message {####}"
  description = "String representing the email verification message."
}

variable "email_verification_subject" {
  type        = string
  default     = "Some subject"
  description = "String representing the email verification subject."
}

variable "mfa_configuration" {
  type        = string
  default     = "OPTIONAL"
  description = "Multi-Factor Authentication (MFA) configuration for the User Pool."
}

variable "sms_authentication_message" {
  type        = string
  default     = "SMS authentication message {####}"
  description = "String representing the SMS authentication message. The Message must contain the {####} placeholder, which will be replaced with the code."
}

variable "sms_verification_message" {
  type        = string
  default     = "SMS verification message {####}"
  description = "String representing the SMS verification message."
}

variable "verification_message_template" {
  type = map(any)
  default = {
    "email_message_by_link" = "Please click the link below to verify your email address. {##Verify Email##} "
    "email_subject_by_link" = "Your verification link. {##Verify Email##}"
  }
  description = "email_message_by_link is an email message template for sending a confirmation link to the user, it must contain the {##Click Here##} placeholder. email_subject_by_link is an email message template for sending a confirmation link to the user, it must contain the {##Click Here##} placeholder."
}

variable "sms_configuration" {
  type = map(any)
  default = {
    external_id    = ""
    sns_caller_arn = ""
  }
  description = "external_id is external ID used in IAM role trust relationships. sns_caller_arn is ARN of the Amazon SNS caller."
}

variable "recovery_mechanism" {
  default = [
    {
      "name"     = "verified_email"
      "priority" = 2
    },
    {
      "name"     = "verified_phone_number"
      "priority" = 1
    }
  ]
  description = "Name is the recovery method for a user. Priority is a positive integer specifying priority of a method with 1 being the highest priority."
}

variable "invite_message_template" {
  default = {
    email_message = "Your username is {username} and temporary password is {####}. "
    email_subject = "Your temporary password"
    sms_message   = "Your username is {username} and temporary password is {####}. "
  }
  description = "email_message is a message template for email messages. Must contain {username} and {####} placeholders, for username and temporary password, respectively. email_subject is a subject line for email messages. sms_message is a message template for SMS messages. Must contain {username} and {####} placeholders, for username and temporary password, respectively."
}

variable "challenge_required_on_new_device" {
  type        = bool
  default     = null
  description = "Whether a challenge is required on a new device. Only applicable to a new device."
}

variable "device_only_remembered_on_user_prompt" {
  type        = bool
  default     = null
  description = "Whether a device is only remembered on user prompt."
}

variable "lambda_config" {
  type    = any # TODO: add description for each field in this config and also add all of them into pool resource
  default = {}
}

variable "schema" {
  default = [
    {
      "attribute_data_type"      = "String"
      "developer_only_attribute" = false
      "mutable"                  = true
      "name"                     = "email"
      "required"                 = true
      string_attribute_constraints = {
        max_length = ""
        min_length = ""
      }
    },
  ]
}

variable "software_token_mfa_configuration" {
  type        = bool
  default     = true
  description = "Whether to enable software token Multi-Factor (MFA) tokens, such as Time-based One-Time Password (TOTP)."
}

variable "case_sensitive" {
  type        = bool
  default     = null
  description = "Whether username case sensitivity will be applied for all users in the user pool through Cognito APIs."
}

variable "user_group" {
  type        = string
  default     = ""
  description = "The name of the user group."
}

variable "precedence" {
  type        = number
  default     = 0
  description = "The precedence of the user group."
}

variable "role_arn" {
  type        = string
  default     = ""
  description = "The ARN of the IAM role to be associated with the user group."
}

variable "domain" {
  type        = string
  default     = ""
  description = "The domain string."
}

variable "cert_arn" {
  type        = string
  default     = ""
  description = "The ARN of an ISSUED ACM certificate in us-east-1 for a custom domain."
}

variable "zone_id" {
  type        = string
  default     = ""
  description = "R53 zone."
}

variable "access_token_validity" {
  type        = number
  default     = 120
  description = "Time limit, between 5 minutes and 1 day, after which the access token is no longer valid and cannot be used. This value will be overridden if you have entered a value in token_validity_units."
}

variable "allowed_oauth_flows_user_pool_client" {
  type        = bool
  default     = false
  description = "Whether the client is allowed to follow the OAuth protocol when interacting with Cognito user pools."
}

variable "enable_token_revocation" {
  type        = bool
  default     = true
  description = "Enables or disables token revocation."
}

variable "explicit_auth_flows" {
  type = list(string)
  default = [
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_USER_SRP_AUTH",
  ]
  description = "List of authentication flows."
}

variable "id_token_validity" {
  type        = number
  default     = 120
  description = "Time limit, between 5 minutes and 1 day, after which the ID token is no longer valid and cannot be used. This value will be overridden if you have entered a value in token_validity_units."
}

variable "prevent_user_existence_errors" {
  type        = string
  default     = "LEGACY"
  description = "Choose which errors and responses are returned by Cognito APIs during authentication, account confirmation, and password recovery when the user does not exist in the user pool."
}

variable "read_attributes" {
  type = list(string)
  default = [
    "address",
    "birthdate",
    "email",
    "email_verified",
    "family_name",
    "gender",
    "given_name",
    "locale",
    "middle_name",
    "name",
    "nickname",
    "phone_number",
    "phone_number_verified",
    "picture",
    "preferred_username",
    "profile",
    "updated_at",
    "website",
    "zoneinfo",
  ]
  description = "List of user pool attributes the application client can read from."
}

variable "refresh_token_validity" {
  type        = number
  default     = 7
  description = "Time limit in days refresh tokens are valid for."
}

variable "write_attributes" {
  type = list(string)
  default = [
    "address",
    "birthdate",
    "email",
    "family_name",
    "gender",
    "given_name",
    "locale",
    "middle_name",
    "name",
    "nickname",
    "phone_number",
    "picture",
    "preferred_username",
    "profile",
    "updated_at",
    "website",
    "zoneinfo",
  ]
  description = "List of user pool attributes the application client can write to."
}

variable "token_validity_units" {
  type = map(any)
  default = {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }
  description = "access_token is time unit in for the value in access_token_validity. id_token is time unit in for the value in id_token_validity. refresh_token is time unit in for the value in refresh_token_validity."
}

variable "callback_urls" {
  type        = list(string)
  default     = []
  description = "List of allowed callback URLs for the identity providers."
}

variable "logout_urls" {
  type        = list(string)
  default     = []
  description = "List of allowed logout URLs for the identity providers."
}

variable "allowed_oauth_flows" {
  type        = list(string)
  default     = []
  description = "List of allowed OAuth flows (code, implicit, client_credentials)."
}

variable "allowed_oauth_scopes" {
  type        = list(string)
  default     = []
  description = "List of allowed OAuth scopes (phone, email, openid, profile, and aws.cognito.signin.user.admin)."
}

variable "supported_identity_providers" {
  type        = list(string)
  default     = []
  description = "List of provider names for the identity providers that are supported on this client."
}

variable "create_route53_record" {
  type        = bool
  default     = false
  description = "Create Route53 Record for custom domain"
}

variable "allow_admin_create_user_only" {
  type        = bool
  default     = false
  description = "(Optional) Set to True if only the administrator is allowed to create user profiles. Set to False if users can sign themselves up via an app."
}

// File: versions.tf
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 3.31"
    }
  }
}

// File: main.tf
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
}

data "aws_iam_policy_document" "assume_role" {
  dynamic "statement" {
    # https://aws.amazon.com/blogs/security/announcing-an-update-to-iam-role-trust-policy-behavior/
    for_each = var.allow_self_assume_role && var.create_admin_role ? [1] : []

    content {
      sid     = "ExplicitSelfAdminRoleAssumption"
      effect  = "Allow"
      actions = ["sts:AssumeRole"]

      principals {
        type        = "AWS"
        identifiers = ["*"]
      }

      condition {
        test     = "ArnLike"
        variable = "aws:PrincipalArn"
        values   = ["arn:${local.partition}:iam::${local.account_id}:role${var.admin_role_path}${var.admin_role_name}"]
      }
    }
  }

  dynamic "statement" {
    # https://aws.amazon.com/blogs/security/announcing-an-update-to-iam-role-trust-policy-behavior/
    for_each = var.allow_self_assume_role && var.create_poweruser_role ? [1] : []

    content {
      sid     = "ExplicitSelfPowerUserRoleAssumption"
      effect  = "Allow"
      actions = ["sts:AssumeRole"]

      principals {
        type        = "AWS"
        identifiers = ["*"]
      }

      condition {
        test     = "ArnLike"
        variable = "aws:PrincipalArn"
        values   = ["arn:${local.partition}:iam::${local.account_id}:role${var.poweruser_role_path}${var.poweruser_role_name}"]
      }
    }
  }

  dynamic "statement" {
    # https://aws.amazon.com/blogs/security/announcing-an-update-to-iam-role-trust-policy-behavior/
    for_each = var.allow_self_assume_role && var.create_readonly_role ? [1] : []

    content {
      sid     = "ExplicitSelfReadOnlyRoleAssumption"
      effect  = "Allow"
      actions = ["sts:AssumeRole"]

      principals {
        type        = "AWS"
        identifiers = ["*"]
      }

      condition {
        test     = "ArnLike"
        variable = "aws:PrincipalArn"
        values   = ["arn:${local.partition}:iam::${local.account_id}:role${var.readonly_role_path}${var.readonly_role_name}"]
      }
    }
  }

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = var.trusted_role_arns
    }

    principals {
      type        = "Service"
      identifiers = var.trusted_role_services
    }
  }
}

data "aws_iam_policy_document" "assume_role_with_mfa" {
  dynamic "statement" {
    # https://aws.amazon.com/blogs/security/announcing-an-update-to-iam-role-trust-policy-behavior/
    for_each = var.allow_self_assume_role && var.create_admin_role ? [1] : []

    content {
      sid     = "ExplicitSelfAdminRoleAssumption"
      effect  = "Allow"
      actions = ["sts:AssumeRole"]

      principals {
        type        = "AWS"
        identifiers = ["*"]
      }

      condition {
        test     = "ArnLike"
        variable = "aws:PrincipalArn"
        values   = ["arn:${local.partition}:iam::${local.account_id}:role${var.admin_role_path}${var.admin_role_name}"]
      }
    }
  }

  dynamic "statement" {
    # https://aws.amazon.com/blogs/security/announcing-an-update-to-iam-role-trust-policy-behavior/
    for_each = var.allow_self_assume_role && var.create_poweruser_role ? [1] : []

    content {
      sid     = "ExplicitSelfPowerUserRoleAssumption"
      effect  = "Allow"
      actions = ["sts:AssumeRole"]

      principals {
        type        = "AWS"
        identifiers = ["*"]
      }

      condition {
        test     = "ArnLike"
        variable = "aws:PrincipalArn"
        values   = ["arn:${local.partition}:iam::${local.account_id}:role${var.poweruser_role_path}${var.poweruser_role_name}"]
      }
    }
  }

  dynamic "statement" {
    # https://aws.amazon.com/blogs/security/announcing-an-update-to-iam-role-trust-policy-behavior/
    for_each = var.allow_self_assume_role && var.create_readonly_role ? [1] : []

    content {
      sid     = "ExplicitSelfReadOnlyRoleAssumption"
      effect  = "Allow"
      actions = ["sts:AssumeRole"]

      principals {
        type        = "AWS"
        identifiers = ["*"]
      }

      condition {
        test     = "ArnLike"
        variable = "aws:PrincipalArn"
        values   = ["arn:${local.partition}:iam::${local.account_id}:role${var.readonly_role_path}${var.readonly_role_name}"]
      }
    }
  }

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = var.trusted_role_arns
    }

    principals {
      type        = "Service"
      identifiers = var.trusted_role_services
    }

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }

    condition {
      test     = "NumericLessThan"
      variable = "aws:MultiFactorAuthAge"
      values   = [var.mfa_age]
    }
  }
}

# Admin
resource "aws_iam_role" "admin" {
  count = var.create_admin_role ? 1 : 0

  name                 = var.admin_role_name
  path                 = var.admin_role_path
  max_session_duration = var.max_session_duration

  force_detach_policies = var.force_detach_policies
  permissions_boundary  = var.admin_role_permissions_boundary_arn

  assume_role_policy = var.admin_role_requires_mfa ? data.aws_iam_policy_document.assume_role_with_mfa.json : data.aws_iam_policy_document.assume_role.json

  tags = var.admin_role_tags
}

resource "aws_iam_role_policy_attachment" "admin" {
  count = var.create_admin_role ? length(var.admin_role_policy_arns) : 0

  role       = aws_iam_role.admin[0].name
  policy_arn = element(var.admin_role_policy_arns, count.index)
}

# Poweruser
resource "aws_iam_role" "poweruser" {
  count = var.create_poweruser_role ? 1 : 0

  name                 = var.poweruser_role_name
  path                 = var.poweruser_role_path
  max_session_duration = var.max_session_duration

  force_detach_policies = var.force_detach_policies
  permissions_boundary  = var.poweruser_role_permissions_boundary_arn

  assume_role_policy = var.poweruser_role_requires_mfa ? data.aws_iam_policy_document.assume_role_with_mfa.json : data.aws_iam_policy_document.assume_role.json

  tags = var.poweruser_role_tags
}

resource "aws_iam_role_policy_attachment" "poweruser" {
  count = var.create_poweruser_role ? length(var.poweruser_role_policy_arns) : 0

  role       = aws_iam_role.poweruser[0].name
  policy_arn = element(var.poweruser_role_policy_arns, count.index)
}

# Readonly
resource "aws_iam_role" "readonly" {
  count = var.create_readonly_role ? 1 : 0

  name                 = var.readonly_role_name
  path                 = var.readonly_role_path
  max_session_duration = var.max_session_duration

  force_detach_policies = var.force_detach_policies
  permissions_boundary  = var.readonly_role_permissions_boundary_arn

  assume_role_policy = var.readonly_role_requires_mfa ? data.aws_iam_policy_document.assume_role_with_mfa.json : data.aws_iam_policy_document.assume_role.json

  tags = var.readonly_role_tags
}

resource "aws_iam_role_policy_attachment" "readonly" {
  count = var.create_readonly_role ? length(var.readonly_role_policy_arns) : 0

  role       = aws_iam_role.readonly[0].name
  policy_arn = element(var.readonly_role_policy_arns, count.index)
}

