// File: iam.tf
resource "aws_iam_user" "this" {
  count = var.create_iam_user ? 1 : 0

  name          = local.aws_iam_username
  path          = var.path
  force_destroy = var.force_destroy
}

resource "aws_iam_access_key" "this" {
  count = var.create_iam_user ? 1 : 0

  user = aws_iam_user.this[0].name
}

resource "aws_iam_policy" "this" {
  name        = local.aws_iam_policy
  description = local.aws_iam_policy

  policy = <<EOF
{
    "Version": "2012-10-17",
    "Statement": [
        {
            "Effect": "Allow",
            "Action": [
                "s3:GetObject"
            ],
            "Resource": [
                "${aws_s3_bucket.this.arn}/*"
            ]
        },
        {
            "Effect": "Allow",
            "Action": [
                "s3:ListBucket"
            ],
            "Resource": [
                "${aws_s3_bucket.this.arn}"
            ]
        }
    ]
}
EOF
}

resource "aws_iam_policy_attachment" "this" {
  name       = local.aws_iam_username
  users      = [aws_iam_user.this[0].name]
  policy_arn = aws_iam_policy.this.arn
}

# If var.random_suffix = true, append with random string to avoid duplication
locals {
  aws_iam_username = var.random_suffix ? "${var.aws_iam_username}-${random_string.this[0].id}" : var.aws_iam_username
  aws_iam_policy   = var.random_suffix ? "${var.aws_iam_policy}-${random_string.this[0].id}" : var.aws_iam_policy
}

// File: main.tf
data "aws_region" "current" {}

resource "random_string" "this" {
  count = var.random_suffix ? 1 : 0

  length  = var.random_string_length
  numeric = true
  special = false
  upper   = false
}

resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name
  force_destroy = true

  tags = {
    Name = local.bucket_name
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  ignore_public_acls      = true
  block_public_policy     = true
  restrict_public_buckets = true
}

resource "aws_s3_object" "this" {
  count = var.upload_image ? 1 : 0

  bucket = aws_s3_bucket.this.id
  key    = local.s3_key
  source = "${path.cwd}/${var.image_filename}"
}

# If var.random_suffix = true, append with random string to avoid duplication
locals {
  bucket_name         = var.random_suffix ? "${var.bucket_name}-${random_string.this[0].id}" : var.bucket_name
  s3_key              = var.create_folder ? "${var.s3_folder}/${var.image_filename}" : var.image_filename
  s3_dpath            = var.create_folder ? "${aws_s3_bucket.this.bucket}/${var.s3_folder}" : aws_s3_bucket.this.bucket
  s3_fqdn_path_url    = "https://s3.${data.aws_region.current.name}.amazonaws.com"
  s3_fqdn_virtual_url = "https://${aws_s3_bucket.this.bucket}.s3.${data.aws_region.current.name}.amazonaws.com"
}

// File: outputs.tf
output "s3_region_name" {
  description = "AWS S3 region name"
  value       = data.aws_region.current.name
}

output "s3_bucket_name" {
  description = "AWS S3 bucket name."
  value       = aws_s3_bucket.this.bucket
}

output "s3_bucket_path" {
  description = "AWS S3 bucket path."
  value       = var.s3_folder
}

output "s3_image_name" {
  description = "Image filename."
  value       = var.image_filename
}

output "s3_fqdn_path_url" {
  description = "FQDN path-style S3 URL."
  value       = local.s3_fqdn_path_url
}

output "s3_fqdn_virtual_url" {
  description = "FQDN virtual-hosted–style S3 URL."
  value       = local.s3_fqdn_virtual_url
}

output "aws_access_key_id" {
  description = "AWS Access Key ID."
  value       = var.create_iam_user ? aws_iam_access_key.this[0].id : null
}

output "aws_access_secret" {
  description = "AWS Access Secret."
  value       = var.create_iam_user ? aws_iam_access_key.this[0].secret : null
  sensitive   = true
}

output "zcli_datastore_command_fmt" {
  description = "zCLI command"
  value       = "zcli datastore create <name> [--title=<title>] --dstype=<dstype> [--fqdn=<fqdn>] [--region=<region>] [--apikey=<apikey>] [--apipass=<password>] [--dpath=<dpath>]"
}

output "zcli_datastore_command" {
  description = "zCLI command"
  value       = var.create_iam_user ? "zcli datastore create ${var.zedcloud_datastore_name} --title=${var.zedcloud_datastore_name} --dstype=AWSS3 --fqdn=${local.s3_fqdn_path_url} --region=${data.aws_region.current.name} --apikey=${aws_iam_access_key.this[0].id} --apipass=${aws_iam_access_key.this[0].secret} --dpath=${local.s3_dpath}" : null
  sensitive   = true
}

output "zcli_image_command_fmt" {
  description = "zCLI command"
  value       = "zcli image create <name> --datastore-name=<datastore> --arch=[AMD64|ARM64] --image-format=[raw|qcow|qcow2|vhd|vmdk|ova|vhdx|container] [--image-url=<rel_url>] [--title=<title>] [--type=[Eve|Application|EvePrivate]]"
}

output "zcli_image_command" {
  description = "zCLI command"
  value       = "zcli image create ${var.zedcloud_image_name} --title=${var.zedcloud_image_name} --datastore-name=${var.zedcloud_datastore_name} --arch=AMD64 --image-format=${var.image_format} --image-url=<rel_url> --type=Application"
}

// File: variables.tf
# Boolean to determine if name will be appended with random string
variable "random_suffix" {
  description = "Set to true to append random suffix."
  type        = bool
  default     = true
}

# Length of random string to be appended to the name
variable "random_string_length" {
  description = "Random string length."
  type        = number
  default     = 4
}

variable "create_iam_user" {
  description = "Set to true to create a new the IAM user."
  type        = bool
  default     = true
}

variable "create_folder" {
  description = "Set to true create a folder."
  type        = bool
  default     = true
}

variable "upload_image" {
  description = "Set to true to upload image."
  type        = bool
  default     = false
}

variable "aws_iam_username" {
  description = "IAM user name"
  type        = string
  default     = "zedcloud-s3-user"
}

variable "aws_iam_policy" {
  description = "S3 read-only IAM policy name"
  type        = string
  default     = "zedcloud-s3-policy"
}

variable "path" {
  description = "Desired path for the IAM user."
  type        = string
  default     = "/"
}

variable "force_destroy" {
  description = "When destroying IAM user, destroy even if it has non-Terraform-managed IAM access keys, login profile or MFA devices. Without force_destroy a user with non-Terraform-managed access keys and login profile will fail to be destroyed."
  type        = bool
  default     = true
}

variable "bucket_name" {
  description = "S3 bucket name."
  type        = string
  default     = "zedcloud"
}

variable "s3_folder" {
  description = "S3 bucket folder."
  type        = string
  default     = "my-folder"
}

variable "zedcloud_datastore_name" {
  description = "Zedcloud Data Store name."
  type        = string
  default     = "my-s3-data-store"
}

variable "zedcloud_image_name" {
  description = "Zededa App Image name."
  type        = string
  default     = "my-image"
}

variable "image_filename" {
  description = "Image filename."
  type        = string
  default     = "my-file.qcow2"
}

variable "image_format" {
  description = "Image format."
  type        = string
  default     = "qcow2"
}

// File: versions.tf
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.33.0"
    }
  }
}

// File: kms_alias.tf
#---------------------------------------------------
# AWS KMS alias
#---------------------------------------------------
resource "aws_kms_alias" "kms_alias" {
  count = var.enable_kms_alias ? 1 : 0

  name          = var.kms_alias_name
  name_prefix   = var.kms_alias_name_prefix
  target_key_id = var.kms_alias_target_key_id != "" ? var.kms_alias_target_key_id : (var.enable_kms_key ? element(concat(aws_kms_key.kms_key.*.key_id, [""]), 0) : null)

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_kms_key.kms_key
  ]
}

// File: kms_ciphertext.tf
#---------------------------------------------------
# KSM ciphertext
#---------------------------------------------------
resource "aws_kms_ciphertext" "kms_ciphertext" {
  count = var.enable_kms_ciphertext ? 1 : 0

  key_id    = var.kms_ciphertext_key_id != "" ? var.kms_ciphertext_key_id : (var.enable_kms_key ? element(aws_kms_key.kms_key.*.key_id, 0) : null)
  plaintext = var.kms_ciphertext_plaintext

  context = var.kms_ciphertext_context

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: kms_external_key.tf
#---------------------------------------------------
# KSM external key
#---------------------------------------------------
resource "aws_kms_external_key" "kms_external_key" {
  count = var.enable_kms_external_key ? 1 : 0

  description             = var.kms_external_key_description
  enabled                 = var.kms_external_key_enabled
  policy                  = var.kms_external_key_policy
  valid_to                = var.kms_external_key_valid_to
  deletion_window_in_days = var.kms_external_key_deletion_window_in_days
  key_material_base64     = var.kms_external_key_key_material_base64

  tags = merge(
    {
      Name = var.kms_external_key_name != "" ? var.kms_external_key_name : "${lower(var.name)}-kms-external-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: kms_grant.tf
#---------------------------------------------------
# KSM grant
#---------------------------------------------------
resource "aws_kms_grant" "kms_grant" {
  count = var.enable_kms_grant ? 1 : 0

  name              = var.kms_grant_name != "" ? var.kms_grant_name : "${var.name}-kms-grant-${var.environment}"
  key_id            = var.kms_grant_key_id != "" ? var.kms_grant_key_id : (var.enable_kms_key ? element(aws_kms_key.kms_key.*.key_id, 0) : null)
  grantee_principal = var.kms_grant_grantee_principal
  operations        = var.kms_grant_operations

  retiring_principal    = var.kms_grant_retiring_principal
  grant_creation_tokens = var.kms_grant_grant_creation_tokens
  retire_on_delete      = var.kms_grant_retire_on_delete

  dynamic "constraints" {
    iterator = constraints
    for_each = var.kms_grant_constraints

    content {
      encryption_context_equals = lookup(constraints.value, "encryption_context_equals", null)
      encryption_context_subset = lookup(constraints.value, "encryption_context_subset", null)
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_kms_key.kms_key
  ]
}

// File: kms_key.tf
#---------------------------------------------------
# AWS KMS key
#---------------------------------------------------
resource "aws_kms_key" "kms_key" {
  count = var.enable_kms_key ? 1 : 0

  description             = var.kms_key_description
  deletion_window_in_days = var.kms_key_deletion_window_in_days
  key_usage               = upper(var.kms_key_key_usage)

  is_enabled               = var.kms_key_is_enabled
  policy                   = var.kms_key_policy
  enable_key_rotation      = var.kms_key_enable_key_rotation
  customer_master_key_spec = var.kms_key_customer_master_key_spec

  tags = merge(
    {
      Name = var.kms_key_name != "" ? var.kms_key_name : "${lower(var.name)}-kms-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: outputs.tf
#---------------------------------------------------
# AWS KMS key
#---------------------------------------------------
output "kms_key_arn" {
  description = "The globally unique identifier for the key."
  value       = element(concat(aws_kms_key.kms_key.*.arn, [""]), 0)
}

output "kms_key_id" {
  description = "The globally unique identifier for the key."
  value       = element(concat(aws_kms_key.kms_key.*.key_id, [""]), 0)
}

#---------------------------------------------------
# AWS KMS alias
#---------------------------------------------------
output "kms_alias_id" {
  description = "ID of KMS alias"
  value       = element(concat(aws_kms_alias.kms_alias.*.id, [""]), 0)
}

output "kms_alias_arn" {
  description = "The Amazon Resource Name (ARN) of the key alias."
  value       = element(concat(aws_kms_alias.kms_alias.*.arn, [""]), 0)
}

output "kms_alias_target_key_arn" {
  description = "The Amazon Resource Name (ARN) of the target key identifier."
  value       = element(concat(aws_kms_alias.kms_alias.*.target_key_arn, [""]), 0)
}

#---------------------------------------------------
# KSM grant
#---------------------------------------------------
output "kms_grant_id" {
  description = "ID of KMS grant"
  value       = element(concat(aws_kms_grant.kms_grant.*.id, [""]), 0)
}

output "kms_grant_grant_id" {
  description = "The unique identifier for the grant."
  value       = element(concat(aws_kms_grant.kms_grant.*.grant_id, [""]), 0)
}

output "kms_grant_token" {
  description = "The grant token for the created grant. For more information, see Grant Tokens."
  value       = element(concat(aws_kms_grant.kms_grant.*.grant_token, [""]), 0)
}

#---------------------------------------------------
# KSM external key
#---------------------------------------------------
output "kms_external_key_id" {
  description = "The unique identifier for the key."
  value       = element(concat(aws_kms_external_key.kms_external_key.*.id, [""]), 0)
}

output "kms_external_key_arn" {
  description = "The Amazon Resource Name (ARN) of the key."
  value       = element(concat(aws_kms_external_key.kms_external_key.*.arn, [""]), 0)
}

output "kms_external_key_expiration_model" {
  description = "Whether the key material expires. Empty when pending key material import, otherwise KEY_MATERIAL_EXPIRES or KEY_MATERIAL_DOES_NOT_EXPIRE."
  value       = element(concat(aws_kms_external_key.kms_external_key.*.expiration_model, [""]), 0)
}

output "kms_external_key_state" {
  description = "The state of the CMK."
  value       = element(concat(aws_kms_external_key.kms_external_key.*.key_state, [""]), 0)
}

output "kms_external_key_usage" {
  description = "The cryptographic operations for which you can use the CMK."
  value       = element(concat(aws_kms_external_key.kms_external_key.*.key_usage, [""]), 0)
}

#---------------------------------------------------
# KSM ciphertext
#---------------------------------------------------
output "kms_ciphertext_id" {
  description = "The unique identifier for the ciphertext."
  value       = element(concat(aws_kms_ciphertext.kms_ciphertext.*.id, [""]), 0)
}

output "kms_ciphertext_ciphertext_blob" {
  description = "Base64 encoded ciphertext"
  value       = element(concat(aws_kms_ciphertext.kms_ciphertext.*.ciphertext_blob, [""]), 0)
}

// File: variables.tf
#-----------------------------------------------------------
# Global or/and default variables
#-----------------------------------------------------------
variable "name" {
  description = "Name to be used on all resources as prefix"
  default     = "TEST"
}

variable "environment" {
  description = "Environment for service"
  default     = "STAGE"
}

variable "tags" {
  description = "A list of tag blocks."
  type        = map(string)
  default     = {}
}

#-----------------------------------------------------------
# KMS key
#-----------------------------------------------------------
variable "enable_kms_key" {
  description = "Allow to create kms_key"
  default     = false
}

variable "kms_key_name" {
  description = "Name for KMS"
  default     = ""
}

variable "kms_key_deletion_window_in_days" {
  description = "Duration in days after which the key is deleted after destruction of the resource, must be between 7 and 30 days. Defaults to 30 days."
  default     = null
}

variable "kms_key_description" {
  description = "The description of the key as viewed in AWS console."
  default     = "This key is used to encrypt <___> AWS service"
}

variable "kms_key_key_usage" {
  description = "Specifies the intended use of the key. Defaults to ENCRYPT_DECRYPT, and only symmetric encryption and decryption are supported"
  default     = "ENCRYPT_DECRYPT"
}

variable "kms_key_is_enabled" {
  description = "Specifies whether the key is enabled. Defaults to true."
  default     = true
}

variable "kms_key_enable_key_rotation" {
  description = "Specifies whether key rotation is enabled. Defaults to false."
  default     = false
}

variable "kms_key_policy" {
  description = "Set policy"
  default     = ""
}

variable "kms_key_customer_master_key_spec" {
  description = "(Optional) Specifies whether the key contains a symmetric key or an asymmetric key pair and the encryption algorithms or signing algorithms that the key supports. Valid values: SYMMETRIC_DEFAULT, RSA_2048, RSA_3072, RSA_4096, ECC_NIST_P256, ECC_NIST_P384, ECC_NIST_P521, or ECC_SECG_P256K1. Defaults to SYMMETRIC_DEFAULT. For help with choosing a key spec, see the AWS KMS Developer Guide."
  default     = null
}

#-----------------------------------------------------------
# KMS alias
#-----------------------------------------------------------
variable "enable_kms_alias" {
  description = "Allow to create kms_alias"
  default     = false
}

variable "kms_alias_name" {
  description = "(Optional) The display name of the alias. The name must start with the word 'alias' followed by a forward slash (alias/)"
  default     = null
}

variable "kms_alias_name_prefix" {
  description = "(Optional) Creates an unique alias beginning with the specified prefix. The name must start with the word 'alias' followed by a forward slash (alias/). Conflicts with name."
  default     = null
}

variable "kms_alias_target_key_id" {
  description = "(Required) Identifier for the key for which the alias is for, can be either an ARN or key_id."
  default     = ""
}

#---------------------------------------------------
# KSM grant
#---------------------------------------------------
variable "enable_kms_grant" {
  description = "Enable kms grant usage"
  default     = false
}

variable "kms_grant_name" {
  description = "(Optional, Forces new resources) A friendly name for identifying the grant."
  default     = ""
}

variable "kms_grant_key_id" {
  description = "The unique identifier for the customer master key (CMK) that the grant applies to. Specify the key ID or the Amazon Resource Name (ARN) of the CMK. To specify a CMK in a different AWS account, you must use the key ARN."
  default     = ""
}

variable "kms_grant_grantee_principal" {
  description = "(Required, Forces new resources) The principal that is given permission to perform the operations that the grant permits in ARN format. Note that due to eventual consistency issues around IAM principals, terraform's state may not always be refreshed to reflect what is true in AWS."
  default     = null
}

variable "kms_grant_operations" {
  description = "(Required, Forces new resources) A list of operations that the grant permits. The permitted values are: Decrypt, Encrypt, GenerateDataKey, GenerateDataKeyWithoutPlaintext, ReEncryptFrom, ReEncryptTo, CreateGrant, RetireGrant, DescribeKey"
  default     = []
}

variable "kms_grant_retiring_principal" {
  description = "(Optional, Forces new resources) The principal that is given permission to retire the grant by using RetireGrant operation in ARN format. Note that due to eventual consistency issues around IAM principals, terraform's state may not always be refreshed to reflect what is true in AWS."
  default     = null
}

variable "kms_grant_grant_creation_tokens" {
  description = "(Optional, Forces new resources) A list of grant tokens to be used when creating the grant. See Grant Tokens for more information about grant tokens."
  default     = null
}

variable "kms_grant_retire_on_delete" {
  description = "(Defaults to false, Forces new resources) If set to false (the default) the grants will be revoked upon deletion, and if set to true the grants will try to be retired upon deletion. Note that retiring grants requires special permissions, hence why we default to revoking grants. See RetireGrant for more information."
  default     = null
}

variable "kms_grant_constraints" {
  description = "(Optional, Forces new resources) A structure that you can use to allow certain operations in the grant only when the desired encryption context is present. For more information about encryption context, see Encryption Context."
  default     = []
}

#---------------------------------------------------
# KSM external key
#---------------------------------------------------
variable "enable_kms_external_key" {
  description = "Enable kms external key usage"
  default     = false
}

variable "kms_external_key_name" {
  description = "Set name for external key"
  default     = ""
}

variable "kms_external_key_description" {
  description = "(Optional) Description of the key."
  default     = null
}

variable "kms_external_key_deletion_window_in_days" {
  description = "(Optional) Duration in days after which the key is deleted after destruction of the resource. Must be between 7 and 30 days. Defaults to 30."
  default     = null
}

variable "kms_external_key_enabled" {
  description = "(Optional) Specifies whether the key is enabled. Keys pending import can only be false. Imported keys default to true unless expired."
  default     = null
}

variable "kms_external_key_key_material_base64" {
  description = "(Optional) Base64 encoded 256-bit symmetric encryption key material to import. The CMK is permanently associated with this key material. The same key material can be reimported, but you cannot import different key material."
  default     = null
}

variable "kms_external_key_policy" {
  description = "(Optional) A key policy JSON document. If you do not provide a key policy, AWS KMS attaches a default key policy to the CMK."
  default     = null
}

variable "kms_external_key_valid_to" {
  description = "(Optional) Time at which the imported key material expires. When the key material expires, AWS KMS deletes the key material and the CMK becomes unusable. If not specified, key material does not expire. Valid values: RFC3339 time string (YYYY-MM-DDTHH:MM:SSZ)"
  default     = null
}

#---------------------------------------------------
# KSM ciphertext
#---------------------------------------------------
variable "enable_kms_ciphertext" {
  description = "Enable kms ciphertext usage"
  default     = false
}

variable "kms_ciphertext_key_id" {
  description = "Globally unique key ID for the customer master key."
  default     = ""
}

variable "kms_ciphertext_plaintext" {
  description = "(Required) Data to be encrypted. Note that this may show up in logs, and it will be stored in the state file."
  default     = null
}

variable "kms_ciphertext_context" {
  description = "(Optional) An optional mapping that makes up the encryption context."
  default     = null
}

// File: default.tf
# default variables

locals {
  default_lifecycle_policy = {
    rules = [{
      rulePriority = 1
      description  = "Only keep 2 images"
      selection = {
        tagStatus   = "any"
        countType   = "imageCountMoreThan"
        countNumber = 2
      }
      action = {
        type = "expire"
      }
    }]
  }
}

// File: labels.tf
### frigga name
module "frigga" {
  source  = "Young-ook/spinnaker/aws//modules/frigga"
  version = "2.3.5"
  name    = var.name == null || var.name == "" ? "ecr" : var.name
  petname = var.name == null || var.name == "" ? true : false
}

locals {
  name = join("-", compact([var.namespace, module.frigga.name]))
  repo = join("/", compact([var.namespace, module.frigga.name]))
  default-tags = merge(
    { "terraform.io" = "managed" },
    { "Name" = local.repo },
  )
}

// File: main.tf
## managed container image registry service

# security/policy
resource "aws_iam_policy" "read" {
  name        = format("%s-ecr-read", local.name)
  description = format("Allow to read images from the ECR")
  path        = "/"
  policy = jsonencode({
    Statement = [{
      Action = [
        "ecr:BatchCheckLayerAvailability",
        "ecr:BatchGetImage",
        "ecr:DescribeImages",
        "ecr:DescribeRepositories",
        "ecr:GetAuthorizationToken",
        "ecr:GetDownloadUrlForLayer",
        "ecr:ListImages",
      ]
      Effect   = "Allow"
      Resource = [aws_ecr_repository.repo.arn]
    }]
    Version = "2012-10-17"
  })
}

resource "aws_iam_policy" "write" {
  name        = format("%s-ecr-write", local.name)
  description = format("Allow to push and write images to the ECR")
  path        = "/"
  policy = jsonencode({
    Statement = [{
      Action = [
        "ecr:PutImage",
        "ecr:UploadLayerPart",
        "ecr:InitiateLayerUpload",
        "ecr:CompleteLayerUpload",
      ]
      Effect   = "Allow"
      Resource = [aws_ecr_repository.repo.arn]
    }]
    Version = "2012-10-17"
  })
}

data "aws_caller_identity" "current" {}

resource "aws_ecr_repository_policy" "repo" {
  repository = aws_ecr_repository.repo.name
  policy = jsonencode({
    Statement = [{
      Sid = "AllowCrossAccountAccess"
      Action = [
        "ecr:BatchCheckLayerAvailability",
        "ecr:BatchGetImage",
        "ecr:DescribeImages",
        "ecr:DescribeRepositories",
        "ecr:GetAuthorizationToken",
        "ecr:GetDownloadUrlForLayer",
        "ecr:GetRepositoryPolicy",
        "ecr:ListImages",
      ]
      Effect = "Allow"
      Principal = {
        AWS = flatten([
          data.aws_caller_identity.current.account_id,
          var.trusted_accounts,
        ])
      }
    }]
    Version = "2012-10-17"
  })
}

resource "aws_ecr_lifecycle_policy" "repo" {
  count      = var.lifecycle_policy != null ? 1 : 0
  repository = aws_ecr_repository.repo.name
  policy     = var.lifecycle_policy == null ? jsonencode(local.default_lifecycle_policy) : var.lifecycle_policy
}

resource "aws_ecr_repository" "repo" {
  name = local.repo
  tags = merge(var.tags, local.default-tags)

  image_tag_mutability = var.image_tag_mutability
  image_scanning_configuration {
    scan_on_push = var.scan_on_push
  }
}

// File: outputs.tf
output "name" {
  description = "A name of generated ECR repository"
  value       = aws_ecr_repository.repo.id
}

output "arn" {
  description = "An ARN of generated ECR repository"
  value       = aws_ecr_repository.repo.arn
}

output "url" {
  description = "A URL of generated ECR repository"
  value       = aws_ecr_repository.repo.repository_url
}

output "policy_arns" {
  description = "A map of IAM polices to allow access this ECR repository. If you want to make an IAM role or instance-profile has permissions to manage this repository, please attach the `poliy_arn` of this output on your side."
  value       = zipmap(["read", "write"], [aws_iam_policy.read.arn, aws_iam_policy.write.arn])
}

// File: variables.tf
### security
variable "trusted_accounts" {
  description = "A list of AWS Account IDs you want to allow them access to the ECR repository"
  type        = list(string)
  default     = []
}

variable "image_tag_mutability" {
  description = "The tag mutability setting for the repository. Must be one of: MUTABLE or IMMUTABLE. Defaults to MUTABLE."
  type        = string
  default     = "MUTABLE"
}

variable "scan_on_push" {
  description = "Indicates whether images are scanned after being pushed to the repository (true) or not scanned (false)."
  type        = bool
  default     = false
}

variable "lifecycle_policy" {
  description = "Lifecycle policy JSON document"
  type        = string
  default     = null
}

variable "namespace" {
  description = "Namespace of container image repository"
  type        = string
  default     = ""
}

### description
variable "name" {
  description = "Name of container image repository"
  type        = string
  default     = null
}

### tags
variable "tags" {
  description = "The key-value maps for tagging"
  type        = map(string)
  default     = {}
}

// File: versions.tf
## requirements

terraform {
  required_version = ">= 0.13"
}

// File: main.tf
locals {
  principals_readonly_access_non_empty = length(var.principals_readonly_access) > 0 ? true : false
  principals_full_access_non_empty     = length(var.principals_full_access) > 0 ? true : false
  ecr_need_policy                      = length(var.principals_full_access) + length(var.principals_readonly_access) > 0 ? true : false
}

################################################################################
# Private Repository
################################################################################
resource "aws_ecr_repository" "this" {
  count                = var.enable && var.enable_private_ecr ? 1 : 0
  name                 = var.repository_name
  tags                 = var.tags
  image_tag_mutability = var.image_tag_mutability
  force_delete         = var.repository_force_delete

  encryption_configuration {
    encryption_type = var.encryption_type
    kms_key         = var.kms_key
  }

  image_scanning_configuration {
    scan_on_push = var.scan_on_push
  }

  dynamic "timeouts" {
    for_each = var.timeouts
    content {
      delete = lookup(timeouts.value.delete, null)
    }
  }
}

resource "aws_ecr_lifecycle_policy" "private" {
  count      = var.enable && var.enable_private_ecr ? 1 : 0
  repository = join("", aws_ecr_repository.this[*].name)

  policy = <<EOF
{
  "rules": [
    {
      "rulePriority": 1,
      "description": "Remove untagged images",
      "selection": {
        "tagStatus": "untagged",
        "countType": "imageCountMoreThan",
        "countNumber": ${var.max_untagged_image_count}
      },
      "action": {
        "type": "expire"
      }
    },
    {
      "rulePriority": 2,
      "description": "Rotate images when reach ${var.max_image_count} images stored",
      "selection": {
        "tagStatus": "any",
        "countType": "imageCountMoreThan",
        "countNumber": ${var.max_image_count}
      },
      "action": {
        "type": "expire"
      }
    }
  ]
}
EOF
}

################################################################################
# Public Repository
################################################################################
resource "aws_ecrpublic_repository" "this" {
  count = var.enable && var.enable_public_ecr ? 1 : 0

  repository_name = var.repository_name

  dynamic "catalog_data" {
    for_each = length(var.public_repository_catalog_data) > 0 ? [var.public_repository_catalog_data] : []

    content {
      about_text        = try(catalog_data.value.about_text, null)
      architectures     = try(catalog_data.value.architectures, null)
      description       = try(catalog_data.value.description, null)
      logo_image_blob   = try(catalog_data.value.logo_image_blob, null)
      operating_systems = try(catalog_data.value.operating_systems, null)
      usage_text        = try(catalog_data.value.usage_text, null)
    }
  }
  tags = var.tags
}

################################################################################
# Private ECR IAM Policies
################################################################################
data "aws_iam_policy_document" "resource_readonly_access_private" {
  count = var.enable ? 1 : 0
  statement {
    sid    = "ReadonlyAccess"
    effect = "Allow"

    principals {
      type = "AWS"

      identifiers = var.principals_readonly_access
    }

    actions = [
      "ecr:GetRegistryPolicy",
      "ecr:DescribeImageScanFindings",
      "ecr:GetLifecyclePolicyPreview",
      "ecr:GetDownloadUrlForLayer",
      "ecr:DescribeRegistry",
      "ecr:DescribePullThroughCacheRules",
      "ecr:DescribeImageReplicationStatus",
      "ecr:GetAuthorizationToken",
      "ecr:ListTagsForResource",
      "ecr:ListImages",
      "ecr:BatchGetRepositoryScanningConfiguration",
      "ecr:GetRegistryScanningConfiguration",
      "ecr:BatchGetImage",
      "ecr:DescribeImages",
      "ecr:DescribeRepositories",
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetRepositoryPolicy",
      "ecr:GetLifecyclePolicy",
    ]
  }
}

data "aws_iam_policy_document" "resource_full_access_private" {
  count = var.enable ? 1 : 0
  statement {
    sid    = "FullAccess"
    effect = "Allow"

    principals {
      type = "AWS"

      identifiers = var.principals_full_access
    }

    actions = [
      "ecr:*"
    ]
  }
}

data "aws_iam_policy_document" "resource_private" {
  count                     = var.enable ? 1 : 0
  source_policy_documents   = [local.principals_readonly_access_non_empty ? join("", data.aws_iam_policy_document.resource_readonly_access_private[*].json) : join("", data.aws_iam_policy_document.empty[*].json)]
  override_policy_documents = [local.principals_full_access_non_empty ? join("", data.aws_iam_policy_document.resource_full_access_private[*].json) : join("", data.aws_iam_policy_document.empty[*].json)]
}

resource "aws_ecr_repository_policy" "private" {
  count      = var.enable && local.ecr_need_policy && var.enable_private_ecr ? 1 : 0
  repository = join("", aws_ecr_repository.this[*].name)
  policy     = join("", data.aws_iam_policy_document.resource_private[*].json)
}

################################################################################
# Public ECR IAM Policies
################################################################################
data "aws_iam_policy_document" "resource_readonly_access_public" {
  count = var.enable ? 1 : 0
  statement {
    sid    = "ReadonlyAccess"
    effect = "Allow"

    principals {
      type = "AWS"

      identifiers = var.principals_readonly_access
    }

    actions = [
      "ecr-public:DescribeImageTags",
      "ecr-public:DescribeImages",
      "ecr-public:DescribeRepositories",
      "ecr-public:GetAuthorizationToken",
      "ecr-public:DescribeRegistries",
      "ecr-public:GetRepositoryCatalogData",
      "ecr-public:GetRegistryCatalogData",
      "ecr-public:ListTagsForResource",
      "ecr-public:GetRepositoryPolicy",
      "ecr-public:BatchCheckLayerAvailability",
    ]
  }
}

data "aws_iam_policy_document" "resource_full_access_public" {
  count = var.enable ? 1 : 0
  statement {
    sid    = "FullAccess"
    effect = "Allow"

    principals {
      type = "AWS"

      identifiers = var.principals_full_access
    }

    actions = [
      "ecr-public:*"
    ]
  }
}


data "aws_iam_policy_document" "resource_public" {
  count                     = var.enable ? 1 : 0
  source_policy_documents   = [local.principals_readonly_access_non_empty ? join("", data.aws_iam_policy_document.resource_readonly_access_public[*].json) : join("", data.aws_iam_policy_document.empty[*].json)]
  override_policy_documents = [local.principals_full_access_non_empty ? join("", data.aws_iam_policy_document.resource_full_access_public[*].json) : join("", data.aws_iam_policy_document.empty[*].json)]
}

resource "aws_ecr_repository_policy" "public" {
  count      = var.enable && local.ecr_need_policy && var.enable_public_ecr ? 1 : 0
  repository = join("", aws_ecrpublic_repository.this[*].repository_name)
  policy     = join("", data.aws_iam_policy_document.resource_public[*].json)
}

data "aws_iam_policy_document" "empty" {
  count = var.enable ? 1 : 0
}

// File: outputs.tf
output "registry_id" {
  value       = try(aws_ecr_repository.this[0].registry_id, aws_ecrpublic_repository.this[0].registry_id, null)
  description = "Registry ID."
}

output "registry_url" {
  value       = try(aws_ecr_repository.this[0].repository_url, aws_ecrpublic_repository.this[0].repository_uri, null)
  description = "Registry URL."
}

output "repository_name" {
  value       = join("", aws_ecr_repository.this[*].name)
  description = "Registry name."
}

output "arn" {
  value       = try(aws_ecr_repository.this[0].arn, aws_ecrpublic_repository.this[0].arn, null)
  description = "Registry ARN."
}

// File: variables.tf
variable "enable" {
  type        = bool
  default     = true
  description = "Set to false to prevent the module from creating any resources."
}

variable "repository_name" {
  type        = string
  default     = ""
  description = <<-EOT
The name to use for the repository.
The repository name may be specified on its own (such as `nginx-web-app`) or it can be prepended with a namespace to group the repository into a category (such as `project-a/nginx-web-app`).
If you don't specify a name, CFNlong generates a unique physical ID and uses that ID for the repository name. For more information, see Name type.
The repository name must start with a letter and can only contain lowercase letters, numbers, hyphens, underscores, and forward slashes.
If you specify a name, you cannot perform updates that require replacement of this resource.
You can perform updates that require no or some interruption.
If you must replace the resource, specify a new name.
  EOT
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "Tags map for resources"
}

variable "enable_private_ecr" {
  type        = bool
  default     = false
  description = "Set to false to prevent the module from creating any resources."
}

variable "max_image_count" {
  type        = number
  default     = 10
  description = "How many Docker Image versions AWS ECR will store."
}

variable "max_untagged_image_count" {
  type        = number
  default     = 1
  description = "How many Untagged Docker Image versions AWS ECR will store."
}

variable "principals_readonly_access" {
  type        = list(any)
  default     = []
  description = "Principal ARN to provide with readonly access to the ECR."
}

variable "principals_full_access" {
  type        = list(any)
  description = "Principal ARN to provide with full access to the ECR."
  default     = []
}

variable "scan_on_push" {
  type        = bool
  description = "Indicates whether images are scanned after being pushed to the repository (true) or not scanned (false)."
  default     = true
}

variable "image_tag_mutability" {
  type        = string
  default     = "IMMUTABLE"
  description = "The tag mutability setting for the repository."
}

variable "repository_force_delete" {
  type        = bool
  default     = false
  description = "If `true`, will delete the repository even if it contains images. Defaults to `false`"
}

variable "encryption_type" {
  type        = string
  default     = "KMS"
  description = "The encryption type for the repository. Must be one of: `KMS` or `AES256`. Defaults to `AES256`"
}

variable "kms_key" {
  type        = string
  default     = null
  description = "The ARN of the KMS key to use when encryption_type is `KMS`. If not specified, uses the default AWS managed key for ECR"
}

# Timeouts
variable "timeouts" {
  type        = map(any)
  default     = {}
  description = "Timeouts map."
}

# Public Repository
variable "enable_public_ecr" {
  type        = bool
  default     = false
  description = "Set to false to prevent the module from creating any resources."
}

variable "public_repository_catalog_data" {
  description = "Catalog data configuration for the repository"
  type        = any
  default     = {}
}

// File: versions.tf
terraform {
  required_providers {

    aws = {
      source  = "hashicorp/aws"
      version = ">= 2.0.0"
    }
  }

  required_version = ">= 0.14"
}

// File: defaults.tf
### default values

### aws partitions
module "aws" {
  source = "Young-ook/spinnaker/aws//modules/aws-partitions"
}

locals {
  aws = {
    dns       = module.aws.partition.dns_suffix
    partition = module.aws.partition.partition
    region    = module.aws.region.name
  }
}

locals {
  default_rule = {
    description         = null
    schedule_expression = null
    event_pattern       = null
  }
  default_bus = {
    event_source_name = null
  }
}

// File: labels.tf
### frigga name
module "frigga" {
  source  = "Young-ook/spinnaker/aws//modules/frigga"
  version = "2.3.5"
  name    = var.name == null || var.name == "" ? "default" : var.name
  petname = false
}

locals {
  name = module.frigga.name
  default-tags = merge(
    { "terraform.io" = "managed" },
    { "Name" = local.name },
  )
}

// File: main.tf
### features
locals {
  custom_bus = local.name != "default" ? true : false
}

### event rules
resource "aws_cloudwatch_event_bus" "bus" {
  for_each          = toset(local.custom_bus ? ["custom"] : [])
  name              = local.name
  tags              = merge(local.default-tags, var.tags)
  event_source_name = lookup(var.bus, "event_source_name", local.default_bus.event_source_name)
}

### event rules
### At least one of `schedule_expression` or `event_pattern` is required.
resource "aws_cloudwatch_event_rule" "rule" {
  for_each            = { for r in var.rules : r.name => r }
  name                = each.key
  tags                = merge(local.default-tags, var.tags)
  description         = lookup(each.value, "description", local.default_rule.description)
  event_bus_name      = local.custom_bus ? aws_cloudwatch_event_bus.bus["custom"].id : null
  event_pattern       = lookup(each.value, "event_pattern", local.default_rule.event_pattern)
  schedule_expression = lookup(each.value, "schedule_expression", local.default_rule.schedule_expression)
}

### security/policy
resource "aws_iam_role" "invoke" {
  name = join("-", [local.name, "invoke"])
  tags = merge(local.default-tags, var.tags)
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = format("events.%s", local.aws.dns)
      }
    }]
  })

  inline_policy {
    name = join("-", [local.name, "invoke-targets"])
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [{
        Action = [
          "lambda:InvokeFunction",
          "states:StartExecution",
        ]
        Effect   = "Allow"
        Resource = ["*"]
      }]
    })
  }
}

### https://docs.aws.amazon.com/eventbridge/latest/userguide/eb-targets.html
### choreography/route
resource "aws_cloudwatch_event_target" "target" {
  depends_on     = [aws_cloudwatch_event_rule.rule]
  for_each       = { for t in var.targets : t.name => t }
  event_bus_name = local.custom_bus ? aws_cloudwatch_event_bus.bus["custom"].id : null
  rule           = lookup(each.value, "rule")
  arn            = lookup(each.value, "arn")
  role_arn       = strcontains(lookup(each.value, "arn", ""), "stateMachine") ? aws_iam_role.invoke.arn : null
}

// File: outputs.tf
output "bus" {
  description = "The attributes of generated event bridge bus"
  value       = aws_cloudwatch_event_bus.bus
}

output "rules" {
  description = "The attributes of generated event bridge rules"
  value       = aws_cloudwatch_event_rule.rule
}

// File: variables.tf
### event bridge
variable "bus" {
  description = "Event bus configuration"
  default     = {}
  validation {
    condition     = var.bus != null
    error_message = "Configuration for custom eventbridge bus must not be null."
  }
}

variable "rules" {
  description = "A configuration list of event rules"
  default     = []
  validation {
    condition     = var.rules != null
    error_message = "List of eventbridge rules is not valid."
  }
}

variable "targets" {
  description = "A configuration list of event route target definitions"
  type        = any
  default     = []
  validation {
    condition     = var.targets != null
    error_message = "List of eventbridge rule targets is not valid."
  }
}

### description
variable "name" {
  description = "Event bus name"
  type        = string
  default     = null
}

### tags
variable "tags" {
  description = "The key-value maps for tagging"
  type        = map(string)
  default     = {}
}

// File: main.tf
locals {
  attach_policy = var.attach_elb_log_delivery_policy || var.attach_lb_log_delivery_policy || var.attach_deny_insecure_transport_policy || var.attach_policy
}

resource "aws_s3_bucket" "this" {
  count = var.create_bucket ? 1 : 0

  bucket        = var.bucket
  bucket_prefix = var.bucket_prefix

  # hack when `null` value can't be used (eg, from terragrunt, https://github.com/gruntwork-io/terragrunt/pull/1367)
  acl = var.acl != "null" ? var.acl : null

  tags                = var.tags
  force_destroy       = var.force_destroy
  acceleration_status = var.acceleration_status
  request_payer       = var.request_payer

  dynamic "website" {
    for_each = length(keys(var.website)) == 0 ? [] : [var.website]

    content {
      index_document           = lookup(website.value, "index_document", null)
      error_document           = lookup(website.value, "error_document", null)
      redirect_all_requests_to = lookup(website.value, "redirect_all_requests_to", null)
      routing_rules            = lookup(website.value, "routing_rules", null)
    }
  }

  dynamic "cors_rule" {
    for_each = try(jsondecode(var.cors_rule), var.cors_rule)

    content {
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      allowed_headers = lookup(cors_rule.value, "allowed_headers", null)
      expose_headers  = lookup(cors_rule.value, "expose_headers", null)
      max_age_seconds = lookup(cors_rule.value, "max_age_seconds", null)
    }
  }

  dynamic "versioning" {
    for_each = length(keys(var.versioning)) == 0 ? [] : [var.versioning]

    content {
      enabled    = lookup(versioning.value, "enabled", null)
      mfa_delete = lookup(versioning.value, "mfa_delete", null)
    }
  }

  dynamic "logging" {
    for_each = length(keys(var.logging)) == 0 ? [] : [var.logging]

    content {
      target_bucket = logging.value.target_bucket
      target_prefix = lookup(logging.value, "target_prefix", null)
    }
  }

  dynamic "grant" {
    for_each = try(jsondecode(var.grant), var.grant)

    content {
      id          = lookup(grant.value, "id", null)
      type        = grant.value.type
      permissions = grant.value.permissions
      uri         = lookup(grant.value, "uri", null)
    }
  }

  dynamic "lifecycle_rule" {
    for_each = try(jsondecode(var.lifecycle_rule), var.lifecycle_rule)

    content {
      id                                     = lookup(lifecycle_rule.value, "id", null)
      prefix                                 = lookup(lifecycle_rule.value, "prefix", null)
      tags                                   = lookup(lifecycle_rule.value, "tags", null)
      abort_incomplete_multipart_upload_days = lookup(lifecycle_rule.value, "abort_incomplete_multipart_upload_days", null)
      enabled                                = lifecycle_rule.value.enabled

      # Max 1 block - expiration
      dynamic "expiration" {
        for_each = length(keys(lookup(lifecycle_rule.value, "expiration", {}))) == 0 ? [] : [lookup(lifecycle_rule.value, "expiration", {})]

        content {
          date                         = lookup(expiration.value, "date", null)
          days                         = lookup(expiration.value, "days", null)
          expired_object_delete_marker = lookup(expiration.value, "expired_object_delete_marker", null)
        }
      }

      # Several blocks - transition
      dynamic "transition" {
        for_each = lookup(lifecycle_rule.value, "transition", [])

        content {
          date          = lookup(transition.value, "date", null)
          days          = lookup(transition.value, "days", null)
          storage_class = transition.value.storage_class
        }
      }

      # Max 1 block - noncurrent_version_expiration
      dynamic "noncurrent_version_expiration" {
        for_each = length(keys(lookup(lifecycle_rule.value, "noncurrent_version_expiration", {}))) == 0 ? [] : [lookup(lifecycle_rule.value, "noncurrent_version_expiration", {})]

        content {
          days = lookup(noncurrent_version_expiration.value, "days", null)
        }
      }

      # Several blocks - noncurrent_version_transition
      dynamic "noncurrent_version_transition" {
        for_each = lookup(lifecycle_rule.value, "noncurrent_version_transition", [])

        content {
          days          = lookup(noncurrent_version_transition.value, "days", null)
          storage_class = noncurrent_version_transition.value.storage_class
        }
      }
    }
  }

  # Max 1 block - replication_configuration
  dynamic "replication_configuration" {
    for_each = length(keys(var.replication_configuration)) == 0 ? [] : [var.replication_configuration]

    content {
      role = replication_configuration.value.role

      dynamic "rules" {
        for_each = replication_configuration.value.rules

        content {
          id                               = lookup(rules.value, "id", null)
          priority                         = lookup(rules.value, "priority", null)
          prefix                           = lookup(rules.value, "prefix", null)
          delete_marker_replication_status = lookup(rules.value, "delete_marker_replication_status", null)
          status                           = rules.value.status

          dynamic "destination" {
            for_each = length(keys(lookup(rules.value, "destination", {}))) == 0 ? [] : [lookup(rules.value, "destination", {})]

            content {
              bucket             = destination.value.bucket
              storage_class      = lookup(destination.value, "storage_class", null)
              replica_kms_key_id = lookup(destination.value, "replica_kms_key_id", null)
              account_id         = lookup(destination.value, "account_id", null)

              dynamic "access_control_translation" {
                for_each = length(keys(lookup(destination.value, "access_control_translation", {}))) == 0 ? [] : [lookup(destination.value, "access_control_translation", {})]

                content {
                  owner = access_control_translation.value.owner
                }
              }
            }
          }

          dynamic "source_selection_criteria" {
            for_each = length(keys(lookup(rules.value, "source_selection_criteria", {}))) == 0 ? [] : [lookup(rules.value, "source_selection_criteria", {})]

            content {

              dynamic "sse_kms_encrypted_objects" {
                for_each = length(keys(lookup(source_selection_criteria.value, "sse_kms_encrypted_objects", {}))) == 0 ? [] : [lookup(source_selection_criteria.value, "sse_kms_encrypted_objects", {})]

                content {

                  enabled = sse_kms_encrypted_objects.value.enabled
                }
              }
            }
          }

          # Send empty map if `filter` is an empty map or absent entirely
          dynamic "filter" {
            for_each = length(keys(lookup(rules.value, "filter", {}))) == 0 ? [{}] : []

            content {}
          }

          # Send `filter` if it is present and has at least one field
          dynamic "filter" {
            for_each = length(keys(lookup(rules.value, "filter", {}))) != 0 ? [lookup(rules.value, "filter", {})] : []

            content {
              prefix = lookup(filter.value, "prefix", null)
              tags   = lookup(filter.value, "tags", null)
            }
          }

        }
      }
    }
  }

  # Max 1 block - server_side_encryption_configuration
  dynamic "server_side_encryption_configuration" {
    for_each = length(keys(var.server_side_encryption_configuration)) == 0 ? [] : [var.server_side_encryption_configuration]

    content {

      dynamic "rule" {
        for_each = length(keys(lookup(server_side_encryption_configuration.value, "rule", {}))) == 0 ? [] : [lookup(server_side_encryption_configuration.value, "rule", {})]

        content {
          bucket_key_enabled = lookup(rule.value, "bucket_key_enabled", null)

          dynamic "apply_server_side_encryption_by_default" {
            for_each = length(keys(lookup(rule.value, "apply_server_side_encryption_by_default", {}))) == 0 ? [] : [
            lookup(rule.value, "apply_server_side_encryption_by_default", {})]

            content {
              sse_algorithm     = apply_server_side_encryption_by_default.value.sse_algorithm
              kms_master_key_id = lookup(apply_server_side_encryption_by_default.value, "kms_master_key_id", null)
            }
          }
        }
      }
    }
  }

  # Max 1 block - object_lock_configuration
  dynamic "object_lock_configuration" {
    for_each = length(keys(var.object_lock_configuration)) == 0 ? [] : [var.object_lock_configuration]

    content {
      object_lock_enabled = object_lock_configuration.value.object_lock_enabled

      dynamic "rule" {
        for_each = length(keys(lookup(object_lock_configuration.value, "rule", {}))) == 0 ? [] : [lookup(object_lock_configuration.value, "rule", {})]

        content {
          default_retention {
            mode  = lookup(lookup(rule.value, "default_retention", {}), "mode")
            days  = lookup(lookup(rule.value, "default_retention", {}), "days", null)
            years = lookup(lookup(rule.value, "default_retention", {}), "years", null)
          }
        }
      }
    }
  }

}

resource "aws_s3_bucket_policy" "this" {
  count = var.create_bucket && local.attach_policy ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  policy = data.aws_iam_policy_document.combined[0].json
}

data "aws_iam_policy_document" "combined" {
  count = var.create_bucket && local.attach_policy ? 1 : 0

  source_policy_documents = compact([
    var.attach_elb_log_delivery_policy ? data.aws_iam_policy_document.elb_log_delivery[0].json : "",
    var.attach_lb_log_delivery_policy ? data.aws_iam_policy_document.lb_log_delivery[0].json : "",
    var.attach_deny_insecure_transport_policy ? data.aws_iam_policy_document.deny_insecure_transport[0].json : "",
    var.attach_policy ? var.policy : ""
  ])
}

# AWS Load Balancer access log delivery policy
data "aws_elb_service_account" "this" {
  count = var.create_bucket && var.attach_elb_log_delivery_policy ? 1 : 0
}

data "aws_iam_policy_document" "elb_log_delivery" {
  count = var.create_bucket && var.attach_elb_log_delivery_policy ? 1 : 0

  statement {
    sid = ""

    principals {
      type        = "AWS"
      identifiers = data.aws_elb_service_account.this.*.arn
    }

    effect = "Allow"

    actions = [
      "s3:PutObject",
    ]

    resources = [
      "${aws_s3_bucket.this[0].arn}/*",
    ]
  }
}

# ALB/NLB

data "aws_iam_policy_document" "lb_log_delivery" {
  count = var.create_bucket && var.attach_lb_log_delivery_policy ? 1 : 0

  statement {
    sid = "AWSLogDeliveryWrite"

    principals {
      type        = "Service"
      identifiers = ["delivery.logs.amazonaws.com"]
    }

    effect = "Allow"

    actions = [
      "s3:PutObject",
    ]

    resources = [
      "${aws_s3_bucket.this[0].arn}/*",
    ]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }

  statement {
    sid = "AWSLogDeliveryAclCheck"

    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["delivery.logs.amazonaws.com"]
    }

    actions = [
      "s3:GetBucketAcl",
    ]

    resources = [
      aws_s3_bucket.this[0].arn,
    ]

  }
}

data "aws_iam_policy_document" "deny_insecure_transport" {
  count = var.create_bucket && var.attach_deny_insecure_transport_policy ? 1 : 0

  statement {
    sid    = "denyInsecureTransport"
    effect = "Deny"

    actions = [
      "s3:*",
    ]

    resources = [
      aws_s3_bucket.this[0].arn,
      "${aws_s3_bucket.this[0].arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values = [
        "false"
      ]
    }
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  count = var.create_bucket && var.attach_public_policy ? 1 : 0

  # Chain resources (s3_bucket -> s3_bucket_policy -> s3_bucket_public_access_block)
  # to prevent "A conflicting conditional operation is currently in progress against this resource."
  # Ref: https://github.com/hashicorp/terraform-provider-aws/issues/7628

  bucket = local.attach_policy ? aws_s3_bucket_policy.this[0].id : aws_s3_bucket.this[0].id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

resource "aws_s3_bucket_ownership_controls" "this" {
  count = var.create_bucket && var.control_object_ownership ? 1 : 0

  bucket = local.attach_policy ? aws_s3_bucket_policy.this[0].id : aws_s3_bucket.this[0].id

  rule {
    object_ownership = var.object_ownership
  }

  # This `depends_on` is to prevent "A conflicting conditional operation is currently in progress against this resource."
  depends_on = [
    aws_s3_bucket_policy.this,
    aws_s3_bucket_public_access_block.this,
    aws_s3_bucket.this
  ]
}

// File: outputs.tf
output "s3_bucket_id" {
  description = "The name of the bucket."
  value       = element(concat(aws_s3_bucket_policy.this.*.id, aws_s3_bucket.this.*.id, [""]), 0)
}

output "s3_bucket_arn" {
  description = "The ARN of the bucket. Will be of format arn:aws:s3:::bucketname."
  value       = element(concat(aws_s3_bucket.this.*.arn, [""]), 0)
}

output "s3_bucket_bucket_domain_name" {
  description = "The bucket domain name. Will be of format bucketname.s3.amazonaws.com."
  value       = element(concat(aws_s3_bucket.this.*.bucket_domain_name, [""]), 0)
}

output "s3_bucket_bucket_regional_domain_name" {
  description = "The bucket region-specific domain name. The bucket domain name including the region name, please refer here for format. Note: The AWS CloudFront allows specifying S3 region-specific endpoint when creating S3 origin, it will prevent redirect issues from CloudFront to S3 Origin URL."
  value       = element(concat(aws_s3_bucket.this.*.bucket_regional_domain_name, [""]), 0)
}

output "s3_bucket_hosted_zone_id" {
  description = "The Route 53 Hosted Zone ID for this bucket's region."
  value       = element(concat(aws_s3_bucket.this.*.hosted_zone_id, [""]), 0)
}

output "s3_bucket_region" {
  description = "The AWS region this bucket resides in."
  value       = element(concat(aws_s3_bucket.this.*.region, [""]), 0)
}

output "s3_bucket_website_endpoint" {
  description = "The website endpoint, if the bucket is configured with a website. If not, this will be an empty string."
  value       = element(concat(aws_s3_bucket.this.*.website_endpoint, [""]), 0)
}

output "s3_bucket_website_domain" {
  description = "The domain of the website endpoint, if the bucket is configured with a website. If not, this will be an empty string. This is used to create Route 53 alias records. "
  value       = element(concat(aws_s3_bucket.this.*.website_domain, [""]), 0)
}

// File: variables.tf
variable "create_bucket" {
  description = "Controls if S3 bucket should be created"
  type        = bool
  default     = true
}

variable "attach_elb_log_delivery_policy" {
  description = "Controls if S3 bucket should have ELB log delivery policy attached"
  type        = bool
  default     = false
}

variable "attach_lb_log_delivery_policy" {
  description = "Controls if S3 bucket should have ALB/NLB log delivery policy attached"
  type        = bool
  default     = false
}

variable "attach_deny_insecure_transport_policy" {
  description = "Controls if S3 bucket should have deny non-SSL transport policy attached"
  type        = bool
  default     = false
}

variable "attach_policy" {
  description = "Controls if S3 bucket should have bucket policy attached (set to `true` to use value of `policy` as bucket policy)"
  type        = bool
  default     = false
}

variable "attach_public_policy" {
  description = "Controls if a user defined public bucket policy will be attached (set to `false` to allow upstream to apply defaults to the bucket)"
  type        = bool
  default     = true
}

variable "bucket" {
  description = "(Optional, Forces new resource) The name of the bucket. If omitted, Terraform will assign a random, unique name."
  type        = string
  default     = null
}

variable "bucket_prefix" {
  description = "(Optional, Forces new resource) Creates a unique bucket name beginning with the specified prefix. Conflicts with bucket."
  type        = string
  default     = null
}

variable "acl" {
  description = "(Optional) The canned ACL to apply. Defaults to 'private'. Conflicts with `grant`"
  type        = string
  default     = "private"
}

variable "policy" {
  description = "(Optional) A valid bucket policy JSON document. Note that if the policy document is not specific enough (but still valid), Terraform may view the policy as constantly changing in a terraform plan. In this case, please make sure you use the verbose/specific version of the policy. For more information about building AWS IAM policy documents with Terraform, see the AWS IAM Policy Document Guide."
  type        = string
  default     = null
}

variable "tags" {
  description = "(Optional) A mapping of tags to assign to the bucket."
  type        = map(string)
  default     = {}
}

variable "force_destroy" {
  description = "(Optional, Default:false ) A boolean that indicates all objects should be deleted from the bucket so that the bucket can be destroyed without error. These objects are not recoverable."
  type        = bool
  default     = false
}

variable "acceleration_status" {
  description = "(Optional) Sets the accelerate configuration of an existing bucket. Can be Enabled or Suspended."
  type        = string
  default     = null
}

variable "request_payer" {
  description = "(Optional) Specifies who should bear the cost of Amazon S3 data transfer. Can be either BucketOwner or Requester. By default, the owner of the S3 bucket would incur the costs of any data transfer. See Requester Pays Buckets developer guide for more information."
  type        = string
  default     = null
}

variable "website" {
  description = "Map containing static web-site hosting or redirect configuration."
  type        = map(string)
  default     = {}
}

variable "cors_rule" {
  description = "List of maps containing rules for Cross-Origin Resource Sharing."
  type        = any
