  }))
  default = {
    iam_read_only = {
      actions = [
        "iam:Get*",
        "iam:List*"
      ]
      resources = ["*"]
      effect    = "Allow"
    },
    s3_full_access = {
      actions = [
        "s3:*"
      ]
      resources = ["*"]
      effect    = "Allow"
    }
  }
}

variable "users" {
