// File: variables.tf
#-----------------------------------------------------------
# Global or/and default variables
#-----------------------------------------------------------
variable "name" {
  description = "Name to be used on all resources as prefix"
  default     = "TEST"
}

variable "environment" {
  description = "Environment for service"
  default     = "STAGE"
}

variable "tags" {
  description = "A list of tag blocks. Each element should have keys named key, value, etc."
  type        = map(string)
  default     = {}
}

#---------------------------------------------------
# AWS Codebuild project
#---------------------------------------------------
variable "enable_codebuild_project" {
  description = "Enable codebuild project usage"
  default     = false
}

variable "codebuild_project_name" {
  description = "Set name for CodeBuild project"
  default     = ""
}

variable "codebuild_project_service_role" {
  description = "(Required) The Amazon Resource Name (ARN) of the AWS Identity and Access Management (IAM) role that enables AWS CodeBuild to interact with dependent AWS services on behalf of the AWS account."
  default     = null
}

variable "codebuild_project_environment" {
  description = "(Required) Configuration block for environment."
  default     = {}
}

variable "codebuild_project_source" {
  description = "(Required) Configuration block for source."
  default     = {}
}

variable "codebuild_project_artifacts" {
  description = "(Required) Configuration block for artifacts."
  default     = {}
}

variable "codebuild_project_cache" {
  description = "(Optional) Information about the cache storage for the project."
  default     = []
}

variable "codebuild_project_logs_config" {
  description = "(Optional) Configuration for the builds to store log data to S3 or CloudWatch."
  default     = []
}

variable "codebuild_project_vpc_config" {
  description = "(Optional) Configuration for the builds to run inside a VPC."
  default     = []
}

variable "codebuild_project_secondary_artifacts" {
  description = "(Optional) A set of secondary artifacts to be used inside the build."
  default     = []
}

variable "codebuild_project_secondary_sources" {
  description = "(Optional) A set of secondary sources to be used inside the build."
  default     = []
}

variable "codebuild_project_description" {
  description = "(Optional) A short description of the project."
  default     = null
}

variable "codebuild_project_badge_enabled" {
  description = "(Optional) Generates a publicly-accessible URL for the projects build badge. Available as badge_url attribute when enabled."
  default     = null
}

variable "codebuild_project_build_timeout" {
  description = "(Optional) How long in minutes, from 5 to 480 (8 hours), for AWS CodeBuild to wait until timing out any related build that does not get marked as completed. The default is 60 minutes."
  default     = null
}

variable "codebuild_project_queued_timeout" {
  description = "(Optional) How long in minutes, from 5 to 480 (8 hours), a build is allowed to be queued before it times out. The default is 8 hours."
  default     = null
}

variable "codebuild_project_encryption_key" {
  description = "(Optional) The AWS Key Management Service (AWS KMS) customer master key (CMK) to be used for encrypting the build project's build output artifacts."
  default     = null
}

variable "codebuild_project_source_version" {
  description = "(Optional) A version of the build input to be built for this project. If not specified, the latest version is used."
  default     = null
}

#---------------------------------------------------
# AWS Codebuild source credential
#---------------------------------------------------
variable "enable_codebuild_source_credential" {
  description = "Enable codebuild source credential usage"
  default     = false
}

variable "codebuild_source_credential_auth_type" {
  description = "(Required) The type of authentication used to connect to a GitHub, GitHub Enterprise, or Bitbucket repository. An OAUTH connection is not supported by the API. Ex: PERSONAL_ACCESS_TOKEN"
  default     = null
}

variable "codebuild_source_credential_server_type" {
  description = "(Required) The source provider used for this project. Ex: GITHUB"
  default     = null
}

variable "codebuild_source_credential_token" {
  description = "(Required) For GitHub or GitHub Enterprise, this is the personal access token. For Bitbucket, this is the app password."
  default     = null
}

variable "codebuild_source_credential_user_name" {
  description = "(Optional) The Bitbucket username when the authType is BASIC_AUTH. This parameter is not valid for other types of source providers or connections."
  default     = null
}

#---------------------------------------------------
# AWS Codebuild webhook
#---------------------------------------------------
variable "enable_codebuild_webhook" {
  description = "Enable codebuild webhook usage"
  default     = false
}

variable "codebuild_webhook_project_name" {
  description = "The name of the build project."
  default     = ""
}

variable "codebuild_webhook_branch_filter" {
  description = "(Optional) A regular expression used to determine which branches get built. Default is all branches are built. It is recommended to use filter_group over branch_filter."
  default     = null
}

variable "codebuild_webhook_filter_group" {
  description = "(Optional) Information about the webhook's trigger"
  default     = []
}

#---------------------------------------------------
# AWS Codebuild report group
#---------------------------------------------------
variable "enable_codebuild_report_group" {
  description = "Enable codebuild report group usage"
  default     = false
}

variable "codebuild_report_group_stack" {
  description = "Set properties for codebuild report group"
  default     = []
}

// File: main.tf
provider "aws" {
  region = local.region
}

data "aws_availability_zones" "available" {}

locals {
  cluster_name = format("%s-%s", basename(path.cwd), "shared")
  region       = "eu-west-1"

  vpc_cidr = "10.0.0.0/16"
  azs      = slice(data.aws_availability_zones.available.names, 0, 3)

  tags = {
    Blueprint  = local.cluster_name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

################################################################################
# VPC
################################################################################

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.0"

  name = local.cluster_name
  cidr = local.vpc_cidr

  azs             = local.azs
  private_subnets = [for k, v in local.azs : cidrsubnet(local.vpc_cidr, 4, k)]
  public_subnets  = [for k, v in local.azs : cidrsubnet(local.vpc_cidr, 8, k + 48)]

  enable_nat_gateway = true
  single_nat_gateway = true

  public_subnet_tags = {
    "kubernetes.io/role/elb" = 1
  }

  private_subnet_tags = {
    "kubernetes.io/role/internal-elb" = 1
  }

  tags = local.tags
}

################################################################################
# Cluster 1 additional security group for cross cluster communication
################################################################################

resource "aws_security_group" "cluster1_additional_sg" {
  name        = "cluster1_additional_sg"
  description = "Allow communication from cluster2 SG to cluster1 SG"
  vpc_id      = module.vpc.vpc_id
  tags = {
    Name = "cluster1_additional_sg"
  }
}

resource "aws_vpc_security_group_egress_rule" "cluster1_additional_sg_allow_all_4" {
  security_group_id = aws_security_group.cluster1_additional_sg.id

  ip_protocol = "-1"
  cidr_ipv4   = "0.0.0.0/0"
}

resource "aws_vpc_security_group_egress_rule" "cluster1_additional_sg_allow_all_6" {
  security_group_id = aws_security_group.cluster1_additional_sg.id

  ip_protocol = "-1"
  cidr_ipv6   = "::/0"
}

################################################################################
# Cluster 2 additional security group for cross cluster communication
################################################################################

resource "aws_security_group" "cluster2_additional_sg" {
  name        = "cluster2_additional_sg"
  description = "Allow communication from cluster1 SG to cluster2 SG"
  vpc_id      = module.vpc.vpc_id
  tags = {
    Name = "cluster2_additional_sg"
  }
}

resource "aws_vpc_security_group_egress_rule" "cluster2_additional_sg_allow_all_4" {
  security_group_id = aws_security_group.cluster2_additional_sg.id

  ip_protocol = "-1"
  cidr_ipv4   = "0.0.0.0/0"
}
resource "aws_vpc_security_group_egress_rule" "cluster2_additional_sg_allow_all_6" {
  security_group_id = aws_security_group.cluster2_additional_sg.id

  ip_protocol = "-1"
  cidr_ipv6   = "::/0"
}

################################################################################
# cross SG  ingress rules Cluster 2 allow to cluster 1
################################################################################

resource "aws_vpc_security_group_ingress_rule" "cluster2_to_cluster_1" {
  security_group_id = aws_security_group.cluster1_additional_sg.id

  referenced_security_group_id = aws_security_group.cluster2_additional_sg.id
  ip_protocol                  = "-1"
}

################################################################################
# cross SG  ingress rules Cluster 1 allow to cluster 2
################################################################################

resource "aws_vpc_security_group_ingress_rule" "cluster1_to_cluster_2" {
  security_group_id = aws_security_group.cluster2_additional_sg.id

  referenced_security_group_id = aws_security_group.cluster1_additional_sg.id
  ip_protocol                  = "-1"
}

// File: outputs.tf
output "vpc_id" {
  description = "Amazon EKS VPC ID"
  value       = module.vpc.vpc_id
}

output "subnet_ids" {
  description = "Amazon EKS Subnet IDs"
  value       = module.vpc.private_subnets
}

output "vpc_cidr" {
  description = "Amazon EKS VPC CIDR Block."
  value       = local.vpc_cidr
}

output "cluster1_additional_sg_id" {
  description = "Cluster1 additional SG"
  value       = aws_security_group.cluster1_additional_sg.id
}

output "cluster2_additional_sg_id" {
  description = "Cluster2 additional SG"
  value       = aws_security_group.cluster2_additional_sg.id
}

// File: versions.tf
terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.47"
    }
  }

  # ##  Used for end-to-end testing on project; update to suit your needs
  # backend "s3" {
  #   bucket = "<BUCKET_NAME>"
  #   region = "<AWS_REGION>"
  #   key    = "e2e/istio-multi-cluster-vpc/terraform.tfstate"
  # }
}

// File: main.tf
###########################################################################################
# Locals to uniformly combine both the newly created objects and the pre-existing objects.
# The former are `resources`, the latter are `data` for Terraform.
###########################################################################################

locals {
  transit_gateway              = var.create ? aws_ec2_transit_gateway.this[0] : data.aws_ec2_transit_gateway.this[0]
  transit_gateway_route_tables = { for k, v in var.route_tables : k => v.create ? aws_ec2_transit_gateway_route_table.this[k] : data.aws_ec2_transit_gateway_route_table.this[k] }
}

##############################################################################
# Transit Gateway (TGW)
##############################################################################

resource "aws_ec2_transit_gateway" "this" {
  count = var.create ? 1 : 0

  amazon_side_asn                 = var.asn
  auto_accept_shared_attachments  = var.auto_accept_shared_attachments
  default_route_table_association = "disable"
  default_route_table_propagation = "disable"
  transit_gateway_cidr_blocks     = var.transit_gateway_cidr_blocks
  dns_support                     = var.dns_support
  vpn_ecmp_support                = var.vpn_ecmp_support
  tags                            = merge(var.tags, { Name = var.name })
}

data "aws_ec2_transit_gateway" "this" {
  count = var.create == false ? 1 : 0

  # ID of an existing TGW. By default set to `null` hence can be referenced directly.
  id = var.id
  # Filtering existing TGWs by name, only in case no ID was provided.
  dynamic "filter" {
    for_each = var.id == null ? [1] : []
    content {
      name   = "tag:Name"
      values = [var.name]

    }
  }
}

#### Route Tables ####

resource "aws_ec2_transit_gateway_route_table" "this" {
  for_each = { for k, v in var.route_tables : k => v if v.create }

  transit_gateway_id = local.transit_gateway.id
  tags               = merge(var.tags, lookup(each.value, "local_tags", {}), { Name = coalesce(lookup(each.value, "name", ""), var.name) })
}

data "aws_ec2_transit_gateway_route_table" "this" {
  for_each = { for k, v in var.route_tables : k => v if v.create == false }

  filter {
    name   = "transit-gateway-id"
    values = [local.transit_gateway.id]
  }

  filter {
    name   = "tag:Name"
    values = [each.value.name]
  }
}

##############################################################################
# Resource Shares for TGW
##############################################################################

# Create Resource Share if shared_principals contains any entries.
resource "aws_ram_resource_share" "this" {
  count = length(var.shared_principals) != 0 ? 1 : 0

  name                      = coalesce(var.ram_resource_share_name, var.name)
  tags                      = merge(var.tags, { Name = coalesce(var.ram_resource_share_name, var.name) })
  allow_external_principals = true
}

# Associate TGW to the Share.
resource "aws_ram_resource_association" "this" {
  count = length(var.shared_principals) != 0 ? 1 : 0

  resource_arn       = local.transit_gateway.arn
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

# Associate each Account to the Share.
resource "aws_ram_principal_association" "this" {
  for_each = var.shared_principals

  principal          = each.value
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

// File: outputs.tf
output "name" {
  description = "Transit Gateway Name tag."
  # Referencing the actual NAME TAG gives us access to it's value for TGWs referenced only by ID.
  value = try(local.transit_gateway.tags.Name, null)
}

output "transit_gateway" {
  description = "The entire object `aws_ec2_transit_gateway`."
  value       = local.transit_gateway
}

output "route_tables" {
  description = "Transit Gateway's route tables."
  value       = local.transit_gateway_route_tables
}

// File: variables.tf
variable "create" {
  description = "Trigger module mode between creating a new TGW or retrieving an existing one."
  default     = true
  type        = bool
}

variable "name" {
  description = "Name tag for the Transit Gateway and associated resources."
  default     = null
  type        = string
}

variable "id" {
  description = "ID of an existing Transit Gateway. Used in conjunction with `create = false`. When set, takes precedence over `var.name`."
  default     = null
  type        = string
}

variable "asn" {
  description = "BGP Autonomous System Number of the AWS Transit Gateway."
  default     = 65200
}

variable "auto_accept_shared_attachments" {
  description = "See the [provider documentation](https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/ec2_transit_gateway)."
  default     = null
  type        = string
}

variable "dns_support" {
  description = "See the [provider documentation](https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/ec2_transit_gateway)."
  default     = null
  type        = string
}

variable "vpn_ecmp_support" {
  description = "See the [provider documentation](https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/ec2_transit_gateway)."
  default     = null
  type        = string
}

variable "route_tables" {
  default = {}
}

variable "ram_resource_share_name" {
  default = null
}

variable "shared_principals" {
  default = {}
}

variable "transit_gateway_cidr_blocks" {
  description = "One or more IPv4 or IPv6 CIDR blocks for the transit gateway. Must be a size /24 CIDR block or larger for IPv4, or a size /64 CIDR block or larger for IPv6."
  default     = []
  type        = set(string)
  validation {
    condition     = alltrue([for cidr in var.transit_gateway_cidr_blocks : can(cidrsubnet(cidr, 0, 0))])
    error_message = "Transit gateway CIDR blocks must contain valid IPv4 or IPv6 CIDR."
  }
}

variable "tags" {
  description = "Optional Map of arbitrary tags to apply to all resources"
  type        = map(string)
  default     = {}
}

// File: versions.tf
terraform {
  required_version = ">= 1.0.0, < 2.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.17"
    }
  }
}

// File: main.tf
###############
# VPC Section #
###############

# VPCs

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  awsAz1 = var.awsAz1 != null ? var.awsAz1 : data.aws_availability_zones.available.names[0]
  awsAz2 = var.awsAz2 != null ? var.awsAz1 : data.aws_availability_zones.available.names[1]
}
resource "aws_vpc" "vpcMain" {
  cidr_block = var.vpcMainCidr
  tags = {
    Name  = "${var.projectPrefix}-vpcMain-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

# Subnets

resource "aws_subnet" "vpcMainSubPubA" {
  vpc_id                  = aws_vpc.vpcMain.id
  cidr_block              = var.vpcMainSubPubACidr
  map_public_ip_on_launch = var.map_public_ip_on_launch
  availability_zone       = local.awsAz1

  tags = {
    Name  = "${var.projectPrefix}-vpcMainSubPubA-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_subnet" "vpcMainSubPubB" {
  vpc_id                  = aws_vpc.vpcMain.id
  cidr_block              = var.vpcMainSubPubBCidr
  map_public_ip_on_launch = var.map_public_ip_on_launch
  availability_zone       = local.awsAz2

  tags = {
    Name  = "${var.projectPrefix}-vpcMainSubPubB-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_subnet" "vpcMainSubMgmtA" {
  vpc_id            = aws_vpc.vpcMain.id
  cidr_block        = var.vpcMainSubMgmtACidr
  availability_zone = local.awsAz1

  tags = {
    Name  = "${var.projectPrefix}-vpcMainSubMgmtA-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_subnet" "vpcMainSubMgmtB" {
  vpc_id            = aws_vpc.vpcMain.id
  cidr_block        = var.vpcMainSubMgmtBCidr
  availability_zone = local.awsAz2

  tags = {
    Name  = "${var.projectPrefix}-vpcMainSubMgmtB-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_subnet" "vpcMainSubPrivA" {
  vpc_id            = aws_vpc.vpcMain.id
  cidr_block        = var.vpcMainSubPrivACidr
  availability_zone = local.awsAz1

  tags = {
    Name  = "${var.projectPrefix}-vpcMainSubPrivA-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

resource "aws_subnet" "vpcMainSubPrivB" {
  vpc_id            = aws_vpc.vpcMain.id
  cidr_block        = var.vpcMainSubPrivBCidr
  availability_zone = local.awsAz2

  tags = {
    Name  = "${var.projectPrefix}-vpcMainSubPrivB-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

# Internet Gateway

resource "aws_internet_gateway" "vpcMainIgw" {
  vpc_id = aws_vpc.vpcMain.id

  tags = {
    Name  = "${var.projectPrefix}-vpcMainIgw-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

# Main Route Tables Associations

resource "aws_main_route_table_association" "mainRtbAssoVpcMain" {
  vpc_id         = aws_vpc.vpcMain.id
  route_table_id = aws_route_table.vpcMainRtb.id
}

# Route Tables

resource "aws_route_table" "vpcMainRtb" {
  vpc_id = aws_vpc.vpcMain.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.vpcMainIgw.id
  }

  tags = {
    Name  = "${var.projectPrefix}-vpcMainRtb-${var.buildSuffix}"
    Owner = var.resourceOwner
  }
}

// File: outputs.tf
locals {
  vpcs = {
    "main" = aws_vpc.vpcMain.id
  }
  subnetsAz1 = {
    "public"  = aws_subnet.vpcMainSubPubA.id
    "private" = aws_subnet.vpcMainSubMgmtA.id
    "mgmt"    = aws_subnet.vpcMainSubPrivA.id
  }
  subnetsAz2 = {
    "public"  = aws_subnet.vpcMainSubPubB.id
    "private" = aws_subnet.vpcMainSubMgmtB.id
    "mgmt"    = aws_subnet.vpcMainSubPrivB.id
  }
}

output "vpcs" {
  value = local.vpcs
}

output "subnetsAz1" {
  value = local.subnetsAz1
}

output "subnetsAz2" {
  value = local.subnetsAz2
}

output "vpcMainIgw" {
  value = aws_internet_gateway.vpcMainIgw.id
}
output "vpcMainRtb" {
  value = aws_route_table.vpcMainRtb.id
}

// File: variables.tf
