// File: versions.tf
terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

// File: main.tf
locals {
  bucket_arn = coalesce(var.bucket_arn, "arn:aws:s3:::${var.bucket}")

  # Convert from "arn:aws:sqs:eu-west-1:835367859851:bold-starling-0" into "https://sqs.eu-west-1.amazonaws.com/835367859851/bold-starling-0" if queue_id was not specified
  # queue_url used in aws_sqs_queue_policy is not the same as arn which is used in all other places
  queue_ids = { for k, v in var.sqs_notifications : k => format("https://%s.%s.amazonaws.com/%s/%s", data.aws_arn.queue[k].service, data.aws_arn.queue[k].region, data.aws_arn.queue[k].account, data.aws_arn.queue[k].resource) if lookup(v, "queue_id", "") == "" }
}

resource "aws_s3_bucket_notification" "this" {
  count = var.create && (length(var.lambda_notifications) > 0 || length(var.sqs_notifications) > 0 || length(var.sns_notifications) > 0) ? 1 : 0

  bucket = var.bucket

  dynamic "lambda_function" {
    for_each = var.lambda_notifications

    content {
      id                  = lambda_function.key
      lambda_function_arn = lambda_function.value.function_arn
      events              = lambda_function.value.events
      filter_prefix       = lookup(lambda_function.value, "filter_prefix", null)
      filter_suffix       = lookup(lambda_function.value, "filter_suffix", null)
    }
  }

  dynamic "queue" {
    for_each = var.sqs_notifications

    content {
      id            = queue.key
      queue_arn     = queue.value.queue_arn
      events        = queue.value.events
      filter_prefix = lookup(queue.value, "filter_prefix", null)
      filter_suffix = lookup(queue.value, "filter_suffix", null)
    }
  }

  dynamic "topic" {
    for_each = var.sns_notifications

    content {
      id            = topic.key
      topic_arn     = topic.value.topic_arn
      events        = topic.value.events
      filter_prefix = lookup(topic.value, "filter_prefix", null)
      filter_suffix = lookup(topic.value, "filter_suffix", null)
    }
  }

  depends_on = [
    aws_lambda_permission.allow,
    aws_sqs_queue_policy.allow,
    aws_sns_topic_policy.allow,
  ]
}

# Lambda
resource "aws_lambda_permission" "allow" {
  for_each = var.lambda_notifications

  statement_id_prefix = "AllowLambdaS3BucketNotification-"
  action              = "lambda:InvokeFunction"
  function_name       = each.value.function_name
  qualifier           = lookup(each.value, "qualifier", null)
  principal           = "s3.amazonaws.com"
  source_arn          = local.bucket_arn
}

# SQS Queue
data "aws_arn" "queue" {
  for_each = var.sqs_notifications

  arn = each.value.queue_arn
}

data "aws_iam_policy_document" "sqs" {
  for_each = var.create_sqs_policy ? var.sqs_notifications : tomap({})

  statement {
    sid = "AllowSQSS3BucketNotification"

    effect = "Allow"

    actions = [
      "sqs:SendMessage",
    ]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    resources = [each.value.queue_arn]

    condition {
      test     = "ArnEquals"
      variable = "aws:SourceArn"
      values   = [local.bucket_arn]
    }
  }
}

resource "aws_sqs_queue_policy" "allow" {
  for_each = var.create_sqs_policy ? var.sqs_notifications : tomap({})

  queue_url = lookup(each.value, "queue_id", lookup(local.queue_ids, each.key, null))
  policy    = data.aws_iam_policy_document.sqs[each.key].json
}

# SNS Topic
data "aws_iam_policy_document" "sns" {
  for_each = var.create_sns_policy ? var.sns_notifications : tomap({})

  statement {
    sid = "AllowSNSS3BucketNotification"

    effect = "Allow"

    actions = [
      "sns:Publish",
    ]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    resources = [each.value.topic_arn]

    condition {
      test     = "ArnEquals"
      variable = "aws:SourceArn"
      values   = [local.bucket_arn]
    }
  }
}

resource "aws_sns_topic_policy" "allow" {
  for_each = var.create_sns_policy ? var.sns_notifications : tomap({})

  arn    = each.value.topic_arn
  policy = data.aws_iam_policy_document.sns[each.key].json
}

// File: outputs.tf
output "s3_bucket_notification_id" {
  description = "ID of S3 bucket"
  value       = element(concat(aws_s3_bucket_notification.this.*.id, [""]), 0)
}

// File: variables.tf
variable "create" {
  description = "Whether to create this resource or not?"
  type        = bool
  default     = true
}

variable "create_sns_policy" {
  description = "Whether to create a policy for SNS permissions or not?"
  type        = bool
  default     = true
}

variable "create_sqs_policy" {
  description = "Whether to create a policy for SQS permissions or not?"
  type        = bool
  default     = true
}

variable "bucket" {
  description = "Name of S3 bucket to use"
  type        = string
  default     = ""
}

variable "bucket_arn" {
  description = "ARN of S3 bucket to use in policies"
  type        = string
  default     = null
}

variable "lambda_notifications" {
  description = "Map of S3 bucket notifications to Lambda function"
  type        = any
  default     = {}
}

variable "sqs_notifications" {
  description = "Map of S3 bucket notifications to SQS queue"
  type        = any
  default     = {}
}

variable "sns_notifications" {
  description = "Map of S3 bucket notifications to SNS topic"
  type        = any
  default     = {}
}

// File: versions.tf
terraform {
  required_version = ">= 0.13.1"

  required_providers {
    aws = ">= 3.28"
  }
}

// File: main.tf
resource "random_pet" "random" {
  length = 2
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

resource "aws_iam_role" "execution_role" {
  name               = "api-gateway-kinesis-execution-role"
  assume_role_policy = <<EOF
{
    "Version": "2012-10-17",
    "Statement": [
        {
        "Sid": "",
        "Effect": "Allow",
        "Principal": {
            "Service": "apigateway.amazonaws.com"
        },
        "Action": "sts:AssumeRole"
        }
    ]
}
EOF
}

resource "aws_iam_role_policy_attachment" "execution_role" {
  role       = aws_iam_role.execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonKinesisFullAccess"
}

resource "aws_apigatewayv2_api" "websocket" {
  name                       = random_pet.random.id
  protocol_type              = "WEBSOCKET"
  route_selection_expression = "\\$default"
}

resource "aws_apigatewayv2_route" "default_route" {
  api_id             = aws_apigatewayv2_api.websocket.id
  route_key          = "$default"
  target             = "integrations/${aws_apigatewayv2_integration.integration.id}"
  authorization_type = "NONE"
  api_key_required   = false
}

# {
#  "deviceID": "$input.json('$.deviceID')",
#  "recordingID": "$input.json('$.recordingID')",
#  "stop": $input.json('$.stop'),
#  "deviceTimestamp": $input.json('$.deviceTimestamp'),
#  "payload": $input.json('$.payload'),
#  "connectionID": "$context.connectionId"
# }
resource "aws_apigatewayv2_integration" "integration" {
  api_id             = aws_apigatewayv2_api.websocket.id
  integration_type   = "AWS"
  integration_method = "POST"
  integration_uri    = "arn:aws:apigateway:${data.aws_region.current.name}:kinesis:action/PutRecord"
  credentials_arn    = aws_iam_role.execution_role.arn
  request_templates = {
    "default" = <<TEMPLATE
      #set($data = "{""deviceID"": $input.json('$.deviceID'), ""recordingID"": $input.json('$.recordingID'), ""stop"": $input.json('$.stop'), ""deviceTimestamp"": $input.json('$.deviceTimestamp'), ""payload"": $input.json('$.payload'), ""connectionID"": ""$context.connectionId""}")
      {
          "Data": "$util.base64Encode($data)",
          "PartitionKey": $input.json('$.deviceID'),
          "StreamName": "${aws_kinesis_stream.stream.name}"
      }
    TEMPLATE
  }
  template_selection_expression = "default"
}

resource "aws_apigatewayv2_integration_response" "response" {
  api_id                   = aws_apigatewayv2_api.websocket.id
  integration_id           = aws_apigatewayv2_integration.integration.id
  integration_response_key = "/200/"
}

resource "aws_apigatewayv2_route_response" "response" {
  api_id             = aws_apigatewayv2_api.websocket.id
  route_id           = aws_apigatewayv2_route.default_route.id
  route_response_key = "$default"
}

resource "aws_apigatewayv2_stage" "stage" {
  name          = "v1"
  api_id        = aws_apigatewayv2_api.websocket.id
  deployment_id = aws_apigatewayv2_deployment.deployment.id
  auto_deploy   = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.log_group.arn
    format = jsonencode({
      requestId               = "$context.requestId"
      sourceIp                = "$context.identity.sourceIp"
      requestTime             = "$context.requestTime"
      message                 = "$context.messageId"
      status                  = "$context.status"
      responseLength          = "$context.responseLength"
      integrationErrorMessage = "$context.integrationErrorMessage"
    })
  }

  default_route_settings {
    data_trace_enabled     = true
    logging_level          = "INFO"
    throttling_burst_limit = 100
    throttling_rate_limit  = 100
  }
}

resource "aws_apigatewayv2_deployment" "deployment" {
  api_id = aws_apigatewayv2_api.websocket.id

  triggers = {
    redeployment = sha1(join(",", tolist([
      jsonencode(aws_apigatewayv2_integration.integration),
    ])))
  }

  depends_on = [
    aws_apigatewayv2_api.websocket,
    aws_apigatewayv2_route.default_route,
    aws_apigatewayv2_integration.integration,
  ]
}

resource "aws_kinesis_stream" "stream" {
  name        = random_pet.random.id
  shard_count = 1
}

resource "aws_cloudwatch_log_group" "log_group" {
  name              = random_pet.random.id
  retention_in_days = 1
}

resource "aws_cloudwatch_log_stream" "log_stream" {
  name           = random_pet.random.id
  log_group_name = aws_cloudwatch_log_group.log_group.name

  depends_on = [
    aws_cloudwatch_log_group.log_group
  ]
}

output "ws_endpoint" {
  value = aws_apigatewayv2_stage.stage.invoke_url
}

// File: lambda.tf
# Configure Lambda function
resource "aws_lambda_function" "lambda" {
  for_each = { for i in local.lambda : i.function_name => i }

  architectures           = each.value.architectures
  code_signing_config_arn = each.value.code_signing_config_arn
  description             = each.value.description
  function_name           = each.value.function_name
  filename                = each.value.source
  handler                 = each.value.handler
  source_code_hash        = filebase64(each.value.source)
  role                    = aws_iam_role.lambda[each.value.function_name].arn
  runtime                 = each.value.runtime
  memory_size             = each.value.memory
  timeout                 = each.value.timeout

  environment {
    variables = each.value.variables
  }

  # Dynamically assign VPC configuration only when such are present
  dynamic "vpc_config" {
    for_each = each.value.vpc
    content {
      security_group_ids = vpc_config.value.security_group_ids
      subnet_ids         = vpc_config.value.subnet_ids
    }

  }

  # Logging dependencies
  depends_on = [
    aws_iam_role_policy_attachment.lambda_logs,
    aws_cloudwatch_log_group.lambda,
  ]

  tags = local.tags
}

// File: locals.tf
locals {

  file_config = try(yamldecode(file(var.config))["config"], [])
  raw_config  = yamldecode(var.raw_config)["config"]
  # Overwrite configurations (if applicable)
  config = length(local.raw_config) > 0 ? local.raw_config : local.file_config

  # === LAMBDA CONFIG ===

  lambda = flatten([
    for config in local.config : {

      function_name           = config.name
      handler                 = config.handler
      runtime                 = config.runtime
      source                  = config.source
      architectures           = lookup(config, "architectures", ["x86_64"])
      code_signing_config_arn = lookup(config, "code_signing_config_arn", null)
      description             = lookup(config, "description", "")
      memory                  = lookup(config, "memory", 128)
      timeout                 = lookup(config, "timeout", 3)
      variables = {
        for i in local.variables : i.name => i.value if i.function_name == config.name
      }
      vpc = [
        for i in local.vpc_config : {
          subnet_ids         = i.subnet_ids
          security_group_ids = i.security_group_ids
        } if i.function_name == config.name
      ]
      permissions = [
        for i in local.permissions : {
          role   = i.role
          path   = i.path
          policy = i.policy
        }
      ]
      logs = [
        for i in local.logs : {
          group_name = i.group_name
          retention  = i.retention
        } if i.function_name == config.name
      ]
    }
  ])

  # === ENVRIONMENT VARIABLES ===

  variables = flatten([
    for config in local.config : [
      for variable in lookup(config, "variables", []) : {
        function_name = config.name
        name          = variable.name
        value         = variable.value
      }
    ]
  ])

  # === VPC CONFIG ===

  vpc_config = flatten([
    for config in local.config : {
      function_name      = config.name
      subnet_ids         = lookup(config.vpc, "subnet_ids", [])
      security_group_ids = lookup(config.vpc, "security_group_ids", [])
  }])

  # === PERMISSIONS CONFIG ===

  permissions = flatten([
    for config in local.config : {
      function_name = config.name
      role          = lookup(config.permissions, "role", config.name)
      path          = lookup(config.permissions, "path", "/terrabits/lambda/")
      policy        = lookup(config.permissions, "policy", "")
    }
  ])

  # === LOGS ===

  logs = flatten([
    for config in local.config : {
      function_name = config.name
      group_name    = lookup(config.logs, "group_name", "/aws/lambda/${config.name}")
      retention     = lookup(config.logs, "retention", 7)
    }
  ])

  tags = merge(var.shared_tags, {
    Terraformed = true
  })
}

// File: logs.tf
# Logs configuration for Lambda function
# This is to manage the CloudWatch Log Group for the Lambda Function.
# If skipping this resource configuration, also add "logs:CreateLogGroup" to the IAM policy below.
resource "aws_cloudwatch_log_group" "lambda" {
  for_each = { for i in local.lambda : i.function_name => i }

  name              = lookup(each.value.logs[0], "group_name", null)
  retention_in_days = lookup(each.value.logs[0], "retention", null)

  tags = local.tags
}

data "aws_iam_policy_document" "lambda_logging" {
  statement {
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = [
      "arn:aws:logs:*:*:*"
    ]
  }
}

# See also the following AWS managed policy: AWSLambdaBasicExecutionRole
resource "aws_iam_policy" "lambda_logging" {
  for_each = { for i in local.lambda : i.function_name => i }

  name        = "${each.value.function_name}-logging"
  path        = lookup(each.value.permissions[0], "path", null)
  description = "IAM policy for logging from a lambda"

  policy = data.aws_iam_policy_document.lambda_logging.json

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "lambda_logs" {
  for_each = { for i in local.lambda : i.function_name => i }

  role       = aws_iam_role.lambda[each.value.function_name].name
  policy_arn = aws_iam_policy.lambda_logging[each.value.function_name].arn
}

// File: output.tf
output "lambda_arn" {
  description = "Amazon Resource Name (ARN)"
  value = [
    for i in aws_lambda_function.lambda : i.arn
  ]
}

output "lambda_invoke_arn" {
  description = "ARN to be used for invoking Lambda Function from API Gateway"
  value = [
    for i in aws_lambda_function.lambda : i.invoke_arn
  ]
}

output "lambda_id" {
  description = "Lambda function name"
  value = [
    for i in local.lambda : i.function_name
  ]
}

// File: permissions.tf
data "aws_iam_policy_document" "lambda_assume" {
  statement {
    actions = [
      "sts:AssumeRole",
    ]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

# A Lambda function may access to other AWS resources such as S3 bucket. So an
# IAM role needs to be defined.
resource "aws_iam_role" "lambda" {
  for_each = { for i in local.lambda : i.function_name => i }

  name = lookup(each.value.permissions[0], "role", null)
  path = lookup(each.value.permissions[0], "path", null)

  assume_role_policy = data.aws_iam_policy_document.lambda_assume.json

  tags = local.tags
}

# Optional IAM policy, which is used to extend lambda permissions
resource "aws_iam_role_policy" "permissions" {
  for_each = { for i in local.lambda : i.function_name => i if length(lookup(i.permissions[0], "policy", "")) > 0 }

  name   = each.value.function_name
  role   = aws_iam_role.lambda[each.value.function_name].id
  policy = lookup(each.value.permissions[0], "policy", "")
}

// File: variables.tf
# === Required variables ===

variable "config" {
  type    = string
  default = "Path to the pipeline configuration file"
}

# === Optional variables ===

variable "raw_config" {
  type        = string
  description = "RAW Yaml configuration for the module. **IMPORTANT** Overwrites 'config' variable"
  default     = "\"config\": []"
}

variable "shared_tags" {
  type        = map(any)
  description = "Additional shared resource tags"
  default     = {}
}

// File: config.tf
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

// File: data-availability_zones.tf
data "aws_availability_zones" "available" {
  state = "available"
}

// File: locals.tf
locals {
  total_subnets  = ((var.enable_public_subnets ? 1 : 0) + (var.enable_nat_subnets ? 1 : 0) + (var.enable_private_subnets ? 1 : 0)) * var.number_of_availability_zones
  subnet_newbits = ceil(log(local.total_subnets, 2))
}

// File: main.tf
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
}

resource "aws_security_group" "public" {
  count = var.enable_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id
}

output "public_sg" {
  value = var.enable_public_subnets ? aws_security_group.public[0].id : ""
  description = "Public Subnet IDs"
}

resource "aws_security_group_rule" "public_egress" {
  count = var.enable_public_subnets ? 1 : 0

  type = "egress"
  cidr_blocks = ["0.0.0.0/0"]
  description = "Allow internet egress"
  from_port = 0
  to_port = 65535
  protocol = "all"
  security_group_id = aws_security_group.public[0].id
}

resource "aws_internet_gateway" "main" {
  count = var.enable_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id
}

resource "aws_subnet" "public" {
  for_each = {
    for index, az_name in
    slice(data.aws_availability_zones.available.names, 0, var.number_of_availability_zones)
    : az_name => cidrsubnet(aws_vpc.main.cidr_block, local.subnet_newbits, index)
    if var.enable_public_subnets
  }

  vpc_id            = aws_vpc.main.id
  availability_zone = each.key
  cidr_block        = each.value

  map_public_ip_on_launch = true
}

output "public_subnet_ids" {
  value = values(aws_subnet.public)[*].id
  description = "Public Subnet IDs"
}

resource "aws_route_table" "public" {
  count = var.enable_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  route {
    cidr_block = aws_vpc.main.cidr_block
    gateway_id = "local"
  }
}

resource "aws_route_table_association" "public" {
  for_each = var.enable_public_subnets ? aws_subnet.public : {}

  subnet_id      = each.value.id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_subnet" "nat" {
  for_each = {
    for index, az_name in
    slice(data.aws_availability_zones.available.names, 0, var.number_of_availability_zones)
    : az_name => cidrsubnet(aws_vpc.main.cidr_block, local.subnet_newbits, index + var.number_of_availability_zones)
    if var.enable_nat_subnets
  }

  vpc_id            = aws_vpc.main.id
  availability_zone = each.key
  cidr_block        = each.value
}

resource "aws_subnet" "private" {
  for_each = {
    for index, az_name in
    slice(data.aws_availability_zones.available.names, 0, var.number_of_availability_zones)
    : az_name => cidrsubnet(aws_vpc.main.cidr_block, local.subnet_newbits, index + (2 * var.number_of_availability_zones))
    if var.enable_private_subnets
  }

  vpc_id            = aws_vpc.main.id
  availability_zone = each.key
  cidr_block        = each.value
}

// File: variables.tf
variable "vpc_cidr" {
  type        = string
  description = "IPv4 CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "number_of_availability_zones" {
  type        = number
  description = "Number of availabilitiy zones to use"
  default     = 2
}

variable "enable_public_subnets" {
  type        = bool
  description = "Whether to create public subnets"
  default     = false
}

variable "enable_nat_subnets" {
  type        = bool
  description = "Whether to create nat subnets"
  default     = false
}

variable "enable_private_subnets" {
  type        = bool
  description = "Whether to create private subnets"
  default     = false
}

// File: locals.tf
locals {
  create_account = var.name != null && var.email != null ? true : false
}

// File: main.tf
resource "aws_organizations_organization" "main" {
  count                         = var.create_organization ? 1 : 0
  aws_service_access_principals = var.aws_service_access_principals
  feature_set                   = var.feature_set
  enabled_policy_types          = var.enabled_policy_types
}

resource "aws_organizations_account" "main" {
  count                      = local.create_account ? 1 : 0
  name                       = var.name
  email                      = var.email
  close_on_deletion          = var.close_on_deletion
  create_govcloud            = var.create_govcloud
  iam_user_access_to_billing = var.iam_user_access_to_billing
  parent_id                  = var.parent_id
  role_name                  = var.role_name
  tags                       = var.tags

  lifecycle {
    ignore_changes = [role_name]
  }
}

resource "aws_organizations_delegated_administrator" "main" {
  count             = var.make_delegated_administrator ? 1 : 0
  account_id        = aws_organizations_account.main[0].id
  service_principal = var.administrator_service_principal
  depends_on        = [aws_organizations_organization.main]
}

resource "aws_organizations_organizational_unit" "main" {
  count     = var.ou_name != null ? 1 : 0
  name      = var.ou_name
  parent_id = var.ou_parent_id
  tags      = var.tags
}

