        for_each = length(keys(lookup(parameters_in_cache_key_and_forwarded_to_origin.value, "query_strings_config", {}))) > 0 ? [lookup(parameters_in_cache_key_and_forwarded_to_origin.value, "query_strings_config", {})] : []

        content {
