// File: gateway.tf
resource "aws_api_gateway_rest_api" "lambda" {
  name = local.full_name
  tags = {
    STAGE = var.stage
  }
}

resource "aws_lambda_permission" "api" {
  function_name = local.full_name
  principal = "apigateway.amazonaws.com"
  action = "lambda:InvokeFunction"
  source_arn = "${aws_api_gateway_rest_api.lambda.execution_arn}/*/*"
  depends_on = [aws_lambda_function.main]
}

resource "aws_api_gateway_resource" "proxy" {
  rest_api_id = aws_api_gateway_rest_api.lambda.id
  parent_id   = aws_api_gateway_rest_api.lambda.root_resource_id
  path_part   = "{proxy+}"
}

resource "aws_api_gateway_method" "proxy" {
  rest_api_id   = aws_api_gateway_rest_api.lambda.id
  resource_id   = aws_api_gateway_resource.proxy.id
  http_method   = var.method
  authorization = "NONE"
}

resource "aws_api_gateway_method" "root" {
  rest_api_id   = aws_api_gateway_rest_api.lambda.id
  resource_id   = aws_api_gateway_rest_api.lambda.root_resource_id
  http_method   = var.method
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "proxy" {
  rest_api_id = aws_api_gateway_rest_api.lambda.id
  resource_id = aws_api_gateway_resource.proxy.id
  http_method = aws_api_gateway_method.proxy.http_method
  integration_http_method = "POST"
  type = "AWS_PROXY"
  uri = aws_lambda_function.main.invoke_arn
}

resource "aws_api_gateway_integration" "root" {
  rest_api_id = aws_api_gateway_rest_api.lambda.id
  resource_id = aws_api_gateway_rest_api.lambda.root_resource_id
  http_method = aws_api_gateway_method.root.http_method
  integration_http_method = "POST"
  type = "AWS_PROXY"
  uri = aws_lambda_function.main.invoke_arn
}

resource "aws_api_gateway_deployment" "deployment" {
  rest_api_id = aws_api_gateway_rest_api.lambda.id
  stage_name = var.stage
  depends_on = [aws_api_gateway_integration.proxy]
  // TODO find way to signal recreation of deployment
//  stage_description = md5(file("gateway.tf"))
}

// File: iam.tf
data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    effect = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lambda" {
  name = "${local.full_name}-${var.region}-lambdaRole"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json
}

locals {
}

resource "aws_cloudwatch_log_group" "lambda" {
  name = "/aws/lambda/${local.full_name}"
}

// TODO RESTRICT THIS!
data "aws_iam_policy_document" "logs" {
  statement {
    effect = "Allow"
    actions = ["logs:*"]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "logs" {
  name = "${local.full_name}-${var.region}-policy"
  policy = data.aws_iam_policy_document.logs.json
  role = aws_iam_role.lambda.id
}

// File: lambda.tf
locals {
  root = "${path.root}/${var.root_nesting}"
  build = "${local.root}/${var.build_dir}"
  zip = "${local.root}/${var.zipfile}"
}

resource "null_resource" "npm" {
  provisioner "local-exec" {
    working_dir = local.root
    command = "npm install && npm run ${var.buildscript}"
  }
  triggers = {
    rerun_every_time = uuid()
  }
}

data "archive_file" "lambda_source" {
  type = "zip"
  source_dir = local.build
  output_path = local.zip
  depends_on = [null_resource.npm]
}

resource "aws_lambda_function" "main" {
  function_name = local.full_name
  filename = local.zip
  source_code_hash = data.archive_file.lambda_source.output_base64sha256
  handler = var.handler
  runtime = var.runtime
  publish = "true"
  role = aws_iam_role.lambda.arn
  depends_on = [
    aws_cloudwatch_log_group.lambda,
    data.archive_file.lambda_source
  ]
}

// File: outputs.tf
output "lambda_iam_role" {
  value = aws_iam_role.lambda
}

output "endpoint" {
  value = aws_api_gateway_deployment.deployment.invoke_url
}

output "lambda_console_url" {
  value = "https://console.aws.amazon.com/lambda/home?region=${var.region}#/functions/${local.full_name}?tab=overview"
}

output "build_path" {
  value = local.build
}

// File: variables.tf
/**
 * Not currently configurable: things will get spun up as e.g. `my-project-dev`
 */
locals {
  full_name = "${var.name}-${var.stage}"
}

/**
 * We assume that your terraform files are in e.g. `{root}/terraform` so we pop one directory to get at project.
 */
variable "root_nesting" {
  default = ".."
}

/**
 * e.g. my-project or best-dogs or something I don't know.
 */
variable "name" {
  description = "The basename for the Lambda function and most associated resources."
}

/**
 * Refer to AWS Lambda docs for supported node versions.
 */
variable "runtime" {
  default = "nodejs12.x"
}

/**
 * Starter projects will accept any http method. Feel free to change that here.
 */
variable "method" {
  default = "ANY"
}

/**
 * We assume your built files live in `{root}/lib`
 */
variable "build_dir" {
  default = "lib"
}

/**
 * AWS lambda handler path
 */
variable "handler" {
  default = "index.handler"
}

/**
 * We call `npm run {x}` to build your project.
 */
variable "buildscript" {
  default = "build"
}

/**
 * We assume your zipfile gets placed at `{root}/lambda.zip`
 */
variable "zipfile" {
  default = "lambda.zip"
}

/**
 * So you can feel the thrill of going down at the same time as netflix.
 */
variable "region" {
  default = "us-east-1"
}

/**
 * You'll get to prod one day little buddy.
 */
variable "stage" {
  default = "dev"
}

// File: data.tf
data "aws_region" "current" {}

# get list of available availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

// File: locals.tf
locals {
  region               = "eu-central-1"
  vpc_cidr             = "10.14.0.0/16"
  public_subnet_count  = 3
  private_subnet_count = 3
}

// File: terraform.tf
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = local.region

  default_tags {
    tags = var.default_tags
  }
}

// File: variables.tf
variable "default_tags" {
  type        = map(string)
  description = "Map of default tags to apply to resources"

  default = {
    Project     = "tf-eks-jofo"
    Owner       = "Jovan Zelincevic"
    Compliance  = "Nothing"
    Environment = "dev"
    Provider    = "Terraform"
  }
}

// File: vpc.tf
# Main VPC
resource "aws_vpc" "eks_main" {
  cidr_block           = local.vpc_cidr
  instance_tenancy     = "default"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-vpc"
  }
}

# Public Subnet
resource "aws_subnet" "eks_public_subnet" {
  # 10.14.0.0/16 -> [10.14.0.0/20, 10.14.16.0/20, 10.14.32.0/20]
  count                   = local.public_subnet_count
  vpc_id                  = aws_vpc.eks_main.id
  map_public_ip_on_launch = false
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.eks_main.cidr_block, 4, count.index)

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-public-${data.aws_availability_zones.available.names[count.index]}"
  }
}

# Public Route Table
resource "aws_route_table" "eks_public_rt" {
  vpc_id = aws_vpc.eks_main.id

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-public-route-table"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "eks_igw" {
  vpc_id = aws_vpc.eks_main.id

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-internet-gateway"
  }
}

# Public Routes
resource "aws_route" "eks_public_internet_access" {
  route_table_id         = aws_route_table.eks_public_rt.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.eks_igw.id
  depends_on             = [aws_route_table.eks_public_rt]
}

# Public Subnet Route Associations
resource "aws_route_table_association" "eks_public_rta" {
  count          = local.public_subnet_count
  subnet_id      = element(aws_subnet.eks_public_subnet.*.id, count.index)
  route_table_id = aws_route_table.eks_public_rt.id
}

# Private Subnet
resource "aws_subnet" "eks_private_subnet" {
  # 10.14.0.0/16 -> [10.14.48.0/20, 10.14.64.0/20, 10.14.80.0/20]
  count             = local.private_subnet_count
  vpc_id            = aws_vpc.eks_main.id
  availability_zone = data.aws_availability_zones.available.names[count.index]
  cidr_block        = cidrsubnet(aws_vpc.eks_main.cidr_block, 4, count.index + local.public_subnet_count)

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-private-${data.aws_availability_zones.available.names[count.index]}"
  }
}

# Private Route Table
resource "aws_route_table" "eks_private_rt" {
  vpc_id = aws_vpc.eks_main.id

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-private-route-table"
  }
}

# The NAT Elastic IP
resource "aws_eip" "eks_nat_eip" {
  domain = "vpc"

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-nat-eip"
  }
}

# The NAT Gateway
resource "aws_nat_gateway" "eks_nat" {
  allocation_id = aws_eip.eks_nat_eip.id
  subnet_id     = aws_subnet.eks_public_subnet.0.id

  tags = {
    Name = "${var.default_tags.Project}-${var.default_tags.Environment}-nat"
  }

  depends_on = [aws_eip.eks_nat_eip, aws_internet_gateway.eks_igw]
}

# Private Routes
resource "aws_route" "eks_private_internet_access" {
  route_table_id         = aws_route_table.eks_private_rt.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_nat_gateway.eks_nat.id
  depends_on             = [aws_route_table.eks_private_rt]
}

# Private Subnet Route Associations
resource "aws_route_table_association" "eks_private_rta" {
  count          = local.private_subnet_count
  subnet_id      = element(aws_subnet.eks_private_subnet.*.id, count.index)
  route_table_id = aws_route_table.eks_private_rt.id
}

// File: main.tf
data "aws_region" "current" {
  count = var.create ? 1 : 0

  region = var.region
}

data "aws_caller_identity" "current" {
  count = var.create ? 1 : 0
}

data "aws_partition" "current" {
  count = var.create ? 1 : 0
}

locals {
  region     = try(data.aws_region.current[0].region, "")
  account_id = try(data.aws_caller_identity.current[0].account_id, "")
  partition  = try(data.aws_partition.current[0].id, "aws")
}

################################################################################
# Queue
################################################################################

locals {
  name        = try(trimsuffix(var.name, ".fifo"), "")
  static_name = var.fifo_queue ? var.name : local.name
}

resource "aws_sqs_queue" "this" {
  count = var.create ? 1 : 0

  region = var.region

  content_based_deduplication       = var.content_based_deduplication
  deduplication_scope               = var.deduplication_scope
  delay_seconds                     = var.delay_seconds
  fifo_queue                        = var.fifo_queue
  fifo_throughput_limit             = var.fifo_throughput_limit
  kms_data_key_reuse_period_seconds = var.kms_data_key_reuse_period_seconds
  kms_master_key_id                 = var.kms_master_key_id
  max_message_size                  = var.max_message_size
  message_retention_seconds         = var.message_retention_seconds
  name                              = var.use_name_prefix ? null : (var.fifo_queue ? "${local.name}.fifo" : local.name)
  name_prefix                       = var.use_name_prefix ? "${local.name}-" : null
  receive_wait_time_seconds         = var.receive_wait_time_seconds
  sqs_managed_sse_enabled           = var.kms_master_key_id != null ? null : var.sqs_managed_sse_enabled
  visibility_timeout_seconds        = var.visibility_timeout_seconds

  tags = var.tags
}

################################################################################
# Queue Policy
################################################################################

data "aws_iam_policy_document" "this" {
  count = var.create && var.create_queue_policy ? 1 : 0

  source_policy_documents   = var.source_queue_policy_documents
  override_policy_documents = var.override_queue_policy_documents

  dynamic "statement" {
    for_each = var.queue_policy_statements != null ? var.queue_policy_statements : {}

    content {
      sid         = try(coalesce(statement.value.sid, statement.key))
      actions     = statement.value.actions
      not_actions = statement.value.not_actions
      effect      = statement.value.effect
      # This avoids the chicken vs the egg scenario since its embedded and can reference the queue
      resources     = statement.value.resources != null ? statement.value.resources : [aws_sqs_queue.this[0].arn]
      not_resources = statement.value.not_resources

      dynamic "principals" {
        for_each = statement.value.principals != null ? statement.value.principals : []

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = statement.value.not_principals != null ? statement.value.not_principals : []

        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = statement.value.condition != null ? statement.value.condition : []

        content {
          test     = condition.value.test
          values   = condition.value.values
          variable = condition.value.variable
        }
      }
      # TODO - remove at next breaking change
      dynamic "condition" {
        for_each = statement.value.conditions != null ? statement.value.conditions : []

        content {
          test     = condition.value.test
          values   = condition.value.values
          variable = condition.value.variable
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "this" {
  count = var.create && var.create_queue_policy ? 1 : 0

  region = var.region

  queue_url = aws_sqs_queue.this[0].url
  policy    = data.aws_iam_policy_document.this[0].json
}

################################################################################
# Re-drive Policy
################################################################################

resource "aws_sqs_queue_redrive_policy" "this" {
  count = var.create && !var.create_dlq && length(var.redrive_policy) > 0 ? 1 : 0

  region = var.region

  queue_url      = aws_sqs_queue.this[0].url
  redrive_policy = jsonencode(var.redrive_policy)
}

resource "aws_sqs_queue_redrive_policy" "dlq" {
  count = var.create && var.create_dlq ? 1 : 0

  region = var.region

  queue_url = aws_sqs_queue.this[0].url
  redrive_policy = jsonencode(
    merge(
      {
        deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
        maxReceiveCount     = 5
      },
      var.redrive_policy
    )
  )
}

################################################################################
# Dead Letter Queue
################################################################################

locals {
  stripped_dlq_name = try(trimsuffix(var.dlq_name, ".fifo"), "")
  inter_dlq_name    = try(coalesce(local.stripped_dlq_name, "${local.name}-dlq"), "")
  dlq_name          = var.fifo_queue && !var.use_name_prefix ? "${local.inter_dlq_name}.fifo" : local.inter_dlq_name

  dlq_kms_master_key_id       = try(coalesce(var.dlq_kms_master_key_id, var.kms_master_key_id), null)
  dlq_sqs_managed_sse_enabled = coalesce(var.dlq_sqs_managed_sse_enabled, var.sqs_managed_sse_enabled)
}

resource "aws_sqs_queue" "dlq" {
  count = var.create && var.create_dlq ? 1 : 0

  region = var.region

  content_based_deduplication = try(coalesce(var.dlq_content_based_deduplication, var.content_based_deduplication), null)
  deduplication_scope         = try(coalesce(var.dlq_deduplication_scope, var.deduplication_scope), null)
  delay_seconds               = try(coalesce(var.dlq_delay_seconds, var.delay_seconds), null)
  # If source queue is FIFO, DLQ must also be FIFO and vice versa
  fifo_queue                        = var.fifo_queue
  fifo_throughput_limit             = try(coalesce(var.dlq_fifo_throughput_limit, var.fifo_throughput_limit), null)
  kms_data_key_reuse_period_seconds = try(coalesce(var.dlq_kms_data_key_reuse_period_seconds, var.kms_data_key_reuse_period_seconds), null)
  kms_master_key_id                 = local.dlq_kms_master_key_id
  max_message_size                  = var.max_message_size
  message_retention_seconds         = try(coalesce(var.dlq_message_retention_seconds, var.message_retention_seconds), null)
  name                              = var.use_name_prefix ? null : local.dlq_name
  name_prefix                       = var.use_name_prefix ? "${local.dlq_name}-" : null
  receive_wait_time_seconds         = try(coalesce(var.dlq_receive_wait_time_seconds, var.receive_wait_time_seconds), null)
  sqs_managed_sse_enabled           = local.dlq_kms_master_key_id != null ? null : local.dlq_sqs_managed_sse_enabled
  visibility_timeout_seconds        = try(coalesce(var.dlq_visibility_timeout_seconds, var.visibility_timeout_seconds), null)

  tags = merge(var.tags, var.dlq_tags)
}

################################################################################
# Queue Policy
################################################################################

data "aws_iam_policy_document" "dlq" {
  count = var.create && var.create_dlq && var.create_dlq_queue_policy ? 1 : 0

  source_policy_documents   = var.source_dlq_queue_policy_documents
  override_policy_documents = var.override_dlq_queue_policy_documents

  dynamic "statement" {
    for_each = var.dlq_queue_policy_statements != null ? var.dlq_queue_policy_statements : {}

    content {
      sid         = try(coalesce(statement.value.sid, statement.key))
      actions     = statement.value.actions
      not_actions = statement.value.not_actions
      effect      = statement.value.effect
      # This avoids the chicken vs the egg scenario since its embedded and can reference the queue
      resources     = statement.value.resources != null ? statement.value.resources : [aws_sqs_queue.dlq[0].arn]
      not_resources = statement.value.not_resources

      dynamic "principals" {
        for_each = statement.value.principals != null ? statement.value.principals : []

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = statement.value.not_principals != null ? statement.value.not_principals : []

        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = statement.value.condition != null ? statement.value.condition : []

        content {
          test     = condition.value.test
          values   = condition.value.values
          variable = condition.value.variable
        }
      }
      # TODO - remove at next breaking change
      dynamic "condition" {
        for_each = statement.value.conditions != null ? statement.value.conditions : []

        content {
          test     = condition.value.test
          values   = condition.value.values
          variable = condition.value.variable
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "dlq" {
  count = var.create && var.create_dlq && var.create_dlq_queue_policy ? 1 : 0

  region = var.region

  queue_url = aws_sqs_queue.dlq[0].url
  policy    = data.aws_iam_policy_document.dlq[0].json
}

################################################################################
# Re-drive Allow Policy
################################################################################

resource "aws_sqs_queue_redrive_allow_policy" "this" {
  count = var.create && !var.create_dlq && length(var.redrive_allow_policy) > 0 ? 1 : 0

  region = var.region

  queue_url            = aws_sqs_queue.this[0].url
  redrive_allow_policy = jsonencode(var.redrive_allow_policy)
}

resource "aws_sqs_queue_redrive_allow_policy" "dlq" {
  count = var.create && var.create_dlq && var.create_dlq_redrive_allow_policy ? 1 : 0

  region = var.region

  queue_url = aws_sqs_queue.dlq[0].url
  redrive_allow_policy = jsonencode(merge(
    {
      redrivePermission = "byQueue",
      sourceQueueArns   = [aws_sqs_queue.this[0].arn]
    },
    var.dlq_redrive_allow_policy)
  )
}

// File: outputs.tf
################################################################################
