          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

data "aws_iam_policy" "AWSElasticDisasterRecoveryAgentPolicy" {
  name = "AWSElasticDisasterRecoveryAgentPolicy"
}

data "aws_iam_policy" "AWSElasticDisasterRecoveryFailbackPolicy" {
  name = "AWSElasticDisasterRecoveryFailbackPolicy"
}

data "aws_iam_policy" "AWSElasticDisasterRecoveryConversionServerPolicy" {
  name = "AWSElasticDisasterRecoveryConversionServerPolicy"
}

data "aws_iam_policy" "AWSElasticDisasterRecoveryRecoveryInstancePolicy" {
  name = "AWSElasticDisasterRecoveryRecoveryInstancePolicy"
}

data "aws_iam_policy" "AWSElasticDisasterRecoveryReplicationServerPolicy" {
  name = "AWSElasticDisasterRecoveryReplicationServerPolicy"
}

data "aws_iam_policy" "AmazonSSMManagedInstanceCore" {
  name = "AmazonSSMManagedInstanceCore"
}

resource "aws_iam_role_policy_attachment" "AWSElasticDisasterRecoveryAgentRole" {
  role       = aws_iam_role.AWSElasticDisasterRecoveryAgentRole.name
  policy_arn = data.aws_iam_policy.AWSElasticDisasterRecoveryAgentPolicy.arn
}

resource "aws_iam_role_policy_attachment" "AWSElasticDisasterRecoveryFailbackRole" {
  role       = aws_iam_role.AWSElasticDisasterRecoveryFailbackRole.name
  policy_arn = data.aws_iam_policy.AWSElasticDisasterRecoveryFailbackPolicy.arn
}

resource "aws_iam_role_policy_attachment" "AWSElasticDisasterRecoveryConversionServerRole" {
  role       = aws_iam_role.AWSElasticDisasterRecoveryConversionServerRole.name
  policy_arn = data.aws_iam_policy.AWSElasticDisasterRecoveryConversionServerPolicy.arn
}

resource "aws_iam_role_policy_attachment" "AWSElasticDisasterRecoveryRecoveryInstanceRole" {
  role       = aws_iam_role.AWSElasticDisasterRecoveryRecoveryInstanceRole.name
  policy_arn = data.aws_iam_policy.AWSElasticDisasterRecoveryRecoveryInstancePolicy.arn
}

resource "aws_iam_role_policy_attachment" "AWSElasticDisasterRecoveryReplicationServerRole" {
  role       = aws_iam_role.AWSElasticDisasterRecoveryReplicationServerRole.name
  policy_arn = data.aws_iam_policy.AWSElasticDisasterRecoveryReplicationServerPolicy.arn
}

resource "aws_iam_role_policy_attachment" "AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole1" {
  role       = aws_iam_role.AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole.name
  policy_arn = data.aws_iam_policy.AWSElasticDisasterRecoveryRecoveryInstancePolicy.arn
}

resource "aws_iam_role_policy_attachment" "AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole2" {
  role       = aws_iam_role.AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole.name
  policy_arn = data.aws_iam_policy.AmazonSSMManagedInstanceCore.arn
}


resource "aws_iam_role" "AWSElasticDisasterRecoveryInitializerRole" {
  name = "AWSElasticDisasterRecoveryInitializerRole"
  path = "/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = data.aws_caller_identity.current.user_id
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "InitializePolicy" {
  name        = "InitializePolicy"
  description = "Policy for initializing the AWS Elastic Disaster Recovery service"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "iam:AttachRolePolicy"
        Resource = "*"
        Condition = {
          "ForAnyValue:ArnEquals" = {
            "iam:PolicyARN" = [
              data.aws_iam_policy.AWSElasticDisasterRecoveryAgentPolicy.arn,
              data.aws_iam_policy.AWSElasticDisasterRecoveryFailbackPolicy.arn,
              data.aws_iam_policy.AWSElasticDisasterRecoveryConversionServerPolicy.arn,
              data.aws_iam_policy.AWSElasticDisasterRecoveryRecoveryInstancePolicy.arn,
              data.aws_iam_policy.AWSElasticDisasterRecoveryReplicationServerPolicy.arn
            ]
          }
        }
      },
      {
        Effect   = "Allow"
        Action   = "iam:PassRole"
        Resource = "arn:aws:iam::*:role/*"
        Condition = {
          "ForAnyValue:StringLike" = {
            "iam:PassedToService" = [
              "ec2.amazonaws.com",
              "drs.amazonaws.com"
            ]
          }
        }
      },
      {
        Effect = "Allow"
        Action = [
          "drs:InitializeService",
          "drs:ListTagsForResource",
          "drs:GetReplicationConfiguration",
          "drs:CreateLaunchConfigurationTemplate",
          "drs:GetLaunchConfiguration",
          "drs:CreateReplicationConfigurationTemplate",
          "drs:*ReplicationConfigurationTemplate*",
          "iam:TagRole",
          "iam:CreateRole",
          "iam:GetServiceLinkedRoleDeletionStatus",
          "iam:ListAttachedRolePolicies",
          "iam:ListRolePolicies",
          "iam:GetRole",
          "iam:DeleteRole",
          "iam:DeleteServiceLinkedRole",
          "ec2:*",
          "sts:DecodeAuthorizationMessage",
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = "iam:CreateServiceLinkedRole"
        Resource = "arn:aws:iam::*:role/aws-service-role/drs.amazonaws.com/AWSServiceRoleForElasticDisasterRecovery"
      },
      {
        Effect = "Allow"
        Action = [
          "iam:CreateInstanceProfile",
          "iam:ListInstanceProfilesForRole",
          "iam:GetInstanceProfile",
          "iam:ListInstanceProfiles",
          "iam:AddRoleToInstanceProfile"
        ]
        Resource = [
          "arn:aws:iam::*:instance-profile/*",
          "arn:aws:iam::*:role/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "Initializer" {
  role       = aws_iam_role.AWSElasticDisasterRecoveryInitializerRole.name
  policy_arn = aws_iam_policy.InitializePolicy.arn
}

// File: data.tf
data "aws_availability_zones" "available" {
  state = "available"
}

// File: locals.tf
locals {
  availability_zone           = data.aws_availability_zones.available.names[0]
  secondary_availability_zone = data.aws_availability_zones.available.names[1]
  vpc_cidr_block              = "10.32.0.0/20"
}

// File: outputs.tf
output "vpc" {
  description = "The dev VPC"
  value       = aws_vpc.dev-vpc
}

output "db_subnet_id_1" {
  description = "The subnet 1 id of the RDS cluster"
  value       = aws_subnet.lambda-rds-db-subnet-1.id
}

output "db_subnet_id_2" {
  description = "The subnet 2 id of the RDS cluster"
  value       = aws_subnet.lambda-rds-db-subnet-2.id
}

output "db_availability_zone" {
  description = "The availability zone id of the RDS cluster"
  value       = local.availability_zone
}

output "db_security_group_id" {
  description = "The security group id of the RDS cluster"
  value       = aws_security_group.postgres-db.id
}

output "bastion_host_subnet_id" {
  description = "The subnet id of the bastion host"
  value       = aws_subnet.lambda-rds-bastion-host-subnet.id
}

output "bastion_host_security_group_id" {
  description = "The security group id of the Bastion Host"
  value       = aws_security_group.bastion-host.id
}

output "lambda_functions_security_group_id" {
  description = "The security group id of the Lambda Functions"
  value       = aws_security_group.lambda-functions.id
}

output "lambda_functions_subnet_id" {
  description = "The subnet id of the Lambda Functions"
  value       = aws_subnet.lambda-rds-dev-lambda-subnet.id
}

// File: routing.tf
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.dev-vpc.id

  tags = {
    Name = "lambda-rds-dev-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.dev-vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "lambda-rds-public-subnet"
  }
}

resource "aws_route_table_association" "bastion-host-route-table" {
  subnet_id      = aws_subnet.lambda-rds-bastion-host-subnet.id
  route_table_id = aws_route_table.public.id
}

// File: security_groups.tf
resource "aws_security_group" "postgres-db" {
  description = "RDS PostgreSQL on dev VPC"
  name        = "lambda-rds-dev-postgres-db"
  vpc_id      = aws_vpc.dev-vpc.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = -1
    cidr_blocks = [
      local.vpc_cidr_block,
    ]
  }
}

resource "aws_security_group_rule" "postgres-db-ingress-bastion-rule" {
  security_group_id        = aws_security_group.postgres-db.id
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  type                     = "ingress"
  source_security_group_id = aws_security_group.bastion-host.id
}

resource "aws_security_group_rule" "postgres-db-ingress-lambda-rule" {
  security_group_id        = aws_security_group.postgres-db.id
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  type                     = "ingress"
  source_security_group_id = aws_security_group.lambda-functions.id
}

resource "aws_security_group" "lambda-functions" {
  description = "Lambda functions running on the dev VPC"
  name        = "lambda-rds-dev-lambda-functions"
  vpc_id      = aws_vpc.dev-vpc.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = -1
    cidr_blocks = [
      local.vpc_cidr_block,
    ]
  }
}

#tfsec:ignore:aws-ec2-no-public-ingress-sgr
resource "aws_security_group" "bastion-host" {
  description = "Bastion host to access RDS DB"
  name        = "lambda-rds-dev-bastion-host"
  vpc_id      = aws_vpc.dev-vpc.id

  egress {
    from_port       = 0
    to_port         = 0
    protocol        = -1
    security_groups = [
      aws_security_group.postgres-db.id
    ]
  }

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [
      "0.0.0.0/0"
    ]
  }
}

// File: subnets.tf
resource "aws_subnet" "lambda-rds-db-subnet-1" {
  vpc_id            = aws_vpc.dev-vpc.id
  availability_zone = local.availability_zone
  cidr_block        = "10.32.0.0/28"

  tags = {
    Name = "lambda-rds-db-subnet-1"
  }
}

resource "aws_subnet" "lambda-rds-db-subnet-2" {
  vpc_id            = aws_vpc.dev-vpc.id
  availability_zone = local.secondary_availability_zone
  cidr_block        = "10.32.0.16/28"

  tags = {
    Name = "lambda-rds-db-subnet-2"
  }
}

resource "aws_subnet" "lambda-rds-dev-lambda-subnet" {
  vpc_id            = aws_vpc.dev-vpc.id
  availability_zone = local.availability_zone
  cidr_block        = "10.32.1.0/24"

  tags = {
    Name = "lambda-rds-dev-lambda-subnet"
  }
}

#tfsec:ignore:aws-ec2-no-public-ip-subnet
resource "aws_subnet" "lambda-rds-bastion-host-subnet" {
  vpc_id                  = aws_vpc.dev-vpc.id
  availability_zone       = local.availability_zone
  cidr_block              = "10.32.15.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name = "lambda-rds-bastion-host-subnet"
  }
}

// File: vpc.tf
resource "aws_vpc" "dev-vpc" {
  cidr_block           = local.vpc_cidr_block
  enable_dns_hostnames = true

  tags = {
    Name = "lambda-rds-dev"
  }
}

/* Not allow ingress access in the default SG */
resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.dev-vpc.id

  egress {
    cidr_blocks = [
      "0.0.0.0/0"
    ]
    from_port = 0
    protocol  = -1
    to_port   = 0
  }

}

/* Manage default NACL
   Allow ingress and egress access */
resource "aws_default_network_acl" "default" {
  default_network_acl_id = aws_vpc.dev-vpc.default_network_acl_id

  ingress {
    protocol   = -1
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol   = -1
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  lifecycle {
    ignore_changes = [subnet_ids]
  }

  tags = {
    Name = "lambda-rds-dev-default-nacl"
  }
}

// File: main.tf
#############################################################################
# VARIABLES
#############################################################################

variable "aws_bucket_prefix" {
  type    = string
  default = "globo"
}

variable "region" {
  type    = string
  default = "us-east-1"
}

variable "state_bucket" {
  type        = string
  description = "Name of bucket for remote state"
}

variable "dynamodb_table_name" {
  type        = string
  description = "Name of dynamodb table for remote state locking"
}

variable "code_commit_user" {
  type        = string
  description = "Username of user to grant Power User access to Code Commit"
}

variable "codebuild_terraform_version" {
  type        = string
  description = "Version of Terraform to use for CodeBuild"
  default     = "1.2.3"
}

locals {
  bucket_name = "${var.aws_bucket_prefix}-build-logs-${random_integer.rand.result}"
}

#############################################################################
# PROVIDERS
#############################################################################

provider "aws" {
  region  = var.region
  profile = "infra"
}

#############################################################################
# DATA SOURCES
#############################################################################

data "aws_s3_bucket" "state_bucket" {
  bucket = var.state_bucket

}

data "aws_dynamodb_table" "state_table" {
  name = var.dynamodb_table_name
}

data "aws_iam_policy" "code_commit_power_user" {
  arn = "arn:aws:iam::aws:policy/AWSCodeCommitPowerUser"
}

#############################################################################
# RESOURCES
#############################################################################  

resource "random_integer" "rand" {
  min = 10000
  max = 99999
}

###################################################
# CODE COMMIT
###################################################

resource "aws_codecommit_repository" "vpc_code" {
  repository_name = "vpc-deploy"
  description     = "Code for deploying VPCs"
}

resource "aws_iam_user_policy_attachment" "code_commit_current" {
  user       = var.code_commit_user
  policy_arn = data.aws_iam_policy.code_commit_power_user.arn
}

###################################################
# CODE BUILD
###################################################

resource "aws_s3_bucket" "vpc_deploy_logs" {
  bucket        = local.bucket_name
  force_destroy = true
}

resource "aws_s3_bucket_acl" "vpc_deploy_logs" {
  bucket = aws_s3_bucket.vpc_deploy_logs.id
  acl    = "private"
}

resource "aws_iam_role" "code_build_assume_role" {
  name = "code-build-assume-role-${random_integer.rand.result}"

  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "codebuild.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
EOF
}

resource "aws_iam_role_policy" "cloud_build_policy" {
  role = aws_iam_role.code_build_assume_role.name

  policy = <<POLICY
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Resource": [
        "*"
      ],
      "Action": [
        "logs:CreateLogGroup",
        "logs:CreateLogStream",
        "logs:PutLogEvents"
      ]
    },
    {
      "Effect": "Allow",
      "Action": [
        "ec2:*"
      ],
      "Resource": "*"
    },
    {
            "Effect": "Allow",
            "Action": ["dynamodb:*"],
            "Resource": [
                "${data.aws_dynamodb_table.state_table.arn}"
            ]
        },
    {
      "Effect": "Allow",
      "Action": [
        "s3:*"
      ],
      "Resource": [
        "${data.aws_s3_bucket.state_bucket.arn}",
        "${data.aws_s3_bucket.state_bucket.arn}/*",
        "${aws_s3_bucket.vpc_deploy_logs.arn}",
        "${aws_s3_bucket.vpc_deploy_logs.arn}/*"
      ]
    },
    {
            "Effect": "Allow",
            "Resource": [
                "${aws_codecommit_repository.vpc_code.arn}"
            ],
            "Action": [
                "codecommit:GitPull"
            ]
        }
  ]
}
POLICY
}

resource "aws_codebuild_project" "build_project" {
  name          = "vpc-deploy-project"
  description   = "Project to deploy VPCs"
  build_timeout = "5"
  service_role  = aws_iam_role.code_build_assume_role.arn

  artifacts {
    type     = "S3"
    location = aws_s3_bucket.vpc_deploy_logs.bucket
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:2.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"

    environment_variable {
      name  = "TF_ACTION"
      value = "PLAN"
    }

    environment_variable {
      name  = "TF_VERSION_INSTALL"
      value = var.codebuild_terraform_version
    }

    environment_variable {
      name  = "TF_BUCKET"
      value = var.state_bucket
    }

    environment_variable {
      name  = "TF_TABLE"
      value = var.dynamodb_table_name
    }

    environment_variable {
      name  = "TF_REGION"
      value = var.region
    }

    environment_variable {
      name  = "WORKSPACE_NAME"
      value = "Default"
    }

  }

  logs_config {

    s3_logs {
      status   = "ENABLED"
      location = "${aws_s3_bucket.vpc_deploy_logs.id}/build-log"
    }
  }

  source {
    type     = "CODECOMMIT"
    location = aws_codecommit_repository.vpc_code.clone_url_http
  }

  source_version = "main"

}

###################################################
# CODE PIPELINE
###################################################

resource "aws_iam_role" "codepipeline_role" {
  name = "vpc-codepipeline-role-${random_integer.rand.result}"

  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "codepipeline.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
EOF
}

resource "aws_iam_role_policy" "codepipeline_policy" {
  name = "vpc-codepipeline_policy-${random_integer.rand.result}"
  role = aws_iam_role.codepipeline_role.id

  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
            "Action": [
                "iam:PassRole"
            ],
            "Resource": "*",
            "Effect": "Allow",
            "Condition": {
                "StringEqualsIfExists": {
                    "iam:PassedToService": [
                        "cloudformation.amazonaws.com",
                        "elasticbeanstalk.amazonaws.com",
                        "ec2.amazonaws.com",
                        "ecs-tasks.amazonaws.com"
                    ]
                }
            }
        },
                {
            "Action": [
                "codecommit:CancelUploadArchive",
                "codecommit:GetBranch",
                "codecommit:GetCommit",
                "codecommit:GetUploadArchiveStatus",
                "codecommit:UploadArchive"
            ],
            "Resource": "*",
            "Effect": "Allow"
        },
        {
            "Action": [
                "elasticbeanstalk:*",
                "ec2:*",
                "elasticloadbalancing:*",
                "autoscaling:*",
                "cloudwatch:*",
                "s3:*",
                "sns:*",
                "cloudformation:*",
                "rds:*",
                "sqs:*",
                "ecs:*"
            ],
            "Resource": "*",
            "Effect": "Allow"
        },
    {
      "Effect": "Allow",
      "Action": [
        "codebuild:BatchGetBuilds",
        "codebuild:StartBuild"
      ],
      "Resource": "*"
    }
  ]
}
EOF
}

resource "aws_codepipeline" "codepipeline" {
  name     = "vpc-deploy-pipeline"
  role_arn = aws_iam_role.codepipeline_role.arn

  artifact_store {
    location = aws_s3_bucket.vpc_deploy_logs.bucket
    type     = "S3"

  }

  stage {
    name = "Source"

    action {
      name             = "Source"
      category         = "Source"
      owner            = "AWS"
      provider         = "CodeCommit"
      version          = "1"
      output_artifacts = ["source_output"]

      configuration = {
        RepositoryName = aws_codecommit_repository.vpc_code.repository_name
        BranchName     = "main"
      }
    }
  }

  stage {
    name = "Development"

    action {
      name             = "Plan"
      category         = "Build"
      owner            = "AWS"
      provider         = "CodeBuild"
      input_artifacts  = ["source_output"]
      output_artifacts = ["Development_plan_output"]
      version          = "1"
      run_order        = "1"

      configuration = {
        ProjectName = aws_codebuild_project.build_project.name
        EnvironmentVariables = jsonencode(
          [
            {
              name  = "TF_ACTION"
              value = "PLAN"
              type  = "PLAINTEXT"
            },
            {
              name  = "WORKSPACE_NAME"
              value = "Development"
              type  = "PLAINTEXT"
            }
          ]
        )
      }
    }

    action {
      name             = "Apply"
      category         = "Build"
      owner            = "AWS"
      provider         = "CodeBuild"
      input_artifacts  = ["source_output"]
      output_artifacts = ["Development_apply_output"]
      version          = "1"
      run_order        = "2"

      configuration = {
        ProjectName = aws_codebuild_project.build_project.name
        EnvironmentVariables = jsonencode(
          [
            {
              name  = "TF_ACTION"
              value = "APPLY"
              type  = "PLAINTEXT"
            },
            {
              name  = "WORKSPACE_NAME"
              value = "Development"
              type  = "PLAINTEXT"
            }
          ]
        )
      }
    }
  }
  ################### Uncomment after first deployment ###########################
