#################
# Private routes A
# There are as many routing tables as the number of NAT gateways
#################
resource "aws_route_table" "private_A" {
  count = 2
  vpc_id = aws_vpc.main.id

 tags = {
    Name = "${var.name}_private_routes"
  }
}

################
# Public subnet
################
# resource "aws_subnet" "public" {
#   count = 2
