terraform {
  required_version = ">= 0.15.0"
  required_providers {
    aws = {
      version = ">= 4.0.0"
    }
  }
}

// File: _global.tf
data "aws_caller_identity" "current" {}

variable "name_prefix" {
  description = "A prefix that will be used on all named resources."
  type        = string
  default     = "pippi-"

  validation {
    condition     = length(regexall("^[a-zA-Z-]*$", var.name_prefix)) > 0
    error_message = "`name_prefix` must satisfy pattern `^[a-zA-Z-]+$`."
  }
}

variable "default_tags" {
  description = "A map of default tags, that will be applied to all resources applicable."
  type        = map(string)
  default     = {}
}

locals {
  name_prefix = var.name_prefix
  default_tags = merge(var.default_tags, {
    tf-module : "pippi.io/aws-ecr"
    tf-workspace = terraform.workspace
  })

  account_id = data.aws_caller_identity.current.account_id
}

// File: ecr.tf
# kics-scan ignore-block
resource "aws_ecr_repository" "this" {
  for_each = var.private_repositories

  name                 = each.key
  image_tag_mutability = each.value.image_tag_mutability != null ? each.value.image_tag_mutability : "MUTABLE"

  encryption_configuration {
    encryption_type = "KMS"
    kms_key         = aws_kms_key.ecr["private"].arn
  }

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = merge(local.default_tags, {
    "Name" = each.key
  })
}

resource "aws_ecr_repository_policy" "this" {
  for_each = aws_ecr_repository.this

  repository = each.value.name
  policy     = data.aws_iam_policy_document.private[each.key].json
}

resource "aws_ecrpublic_repository" "this" {
  for_each = var.public_repositories

  repository_name = each.key

  catalog_data {
    about_text        = each.value.about
    architectures     = each.value.architectures
    description       = each.value.description
    logo_image_blob   = each.value.logo_image_blob
    operating_systems = each.value.operating_systems
    usage_text        = each.value.usage_text
  }

  tags = merge(local.default_tags, {
    "Name" = each.key
  })
}

resource "aws_ecrpublic_repository_policy" "this" {
  for_each = aws_ecrpublic_repository.this

  repository_name = each.value.repository_name
  policy          = data.aws_iam_policy_document.public[each.key].json
}

// File: iam.tf
# kics-scan ignore-block
resource "aws_iam_user" "artifact_user" {
  for_each = local.create_iam_users

  name = "${local.name_prefix}${each.key}"
  path = "/artifact/"

  tags = merge(local.default_tags, {
    "Name" = "${local.name_prefix}${each.key}"
  })
}

resource "aws_iam_access_key" "artifact_user" {
  for_each = aws_iam_user.artifact_user

  user = each.value.name
}

# kics-scan ignore-block
resource "aws_iam_user_policy" "artifact_user" {
  for_each = aws_iam_user.artifact_user

  name   = "ECR"
  user   = each.value.name
  policy = try(data.aws_iam_policy_document.artifact_user_private[each.key].json, data.aws_iam_policy_document.artifact_user_public[each.key].json)
}

data "aws_iam_policy_document" "artifact_user_private" {
  for_each = aws_ecr_repository.this

  statement {
    sid       = "AllowECR"
    actions   = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:CompleteLayerUpload",
      "ecr:GetDownloadUrlForLayer",
      "ecr:InitiateLayerUpload",
      "ecr:PutImage",
      "ecr:UploadLayerPart"
    ]
    resources = [
      each.value.arn
    ]
  }

  statement {
    sid       = "AllowECRAuthorization" # needed to login to ecr
    actions   = [
      "ecr:GetAuthorizationToken"
    ]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "artifact_user_public" {
  for_each = aws_ecrpublic_repository.this

  statement {
    sid       = "AllowECRPublic"
    actions   = [
      "ecr-public:BatchCheckLayerAvailability",
      "ecr-public:BatchGetImage",
      "ecr-public:CompleteLayerUpload",
      "ecr-public:GetDownloadUrlForLayer",
      "ecr-public:InitiateLayerUpload",
      "ecr-public:PutImage",
      "ecr-public:UploadLayerPart",
    ]
    resources = [
      each.value.arn
    ]
  }

  statement {
    sid       = "AllowECRPublicAuthorization" # needed to login to ecr
    actions   = [
      "ecr-public:GetAuthorizationToken",
      "sts:GetServiceBearerToken"
    ]
    resources = ["*"]
  }
}

// File: kms.tf
data "aws_iam_policy_document" "kms" {
  for_each = length(var.private_repositories) > 0 ? toset(["private"]) : []

  statement {
    resources = ["*"]
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.id}:root"]
    }
  }
}

# kics-scan ignore-block
resource "aws_kms_key" "ecr" {
  for_each = data.aws_iam_policy_document.kms

  description         = "KMS CMK used by ecr"
  enable_key_rotation = true
  policy              = each.value.json

  tags = merge(local.default_tags, {
    "Name" = "${local.name_prefix}ecr-kms"
  })
}

// File: main.tf
locals {
  private_repo_pull_arns = { for k, repo in var.private_repositories : k => concat(
    [for index, account in repo.pull_accounts : "arn:aws:iam::${account}:root"],
    [for index, role in repo.pull_role_arns : role]
  ) }

  private_repo_push_arns = { for k, repo in var.private_repositories : k => concat(
    [for index, account in repo.push_accounts : "arn:aws:iam::${account}:root"],
    [for index, role in repo.push_role_arns : role]
  ) }

  public_repo_push_arns = { for k, repo in var.public_repositories : k => concat(
    [for index, account in repo.push_accounts : "arn:aws:iam::${account}:root"],
    [for index, role in repo.push_role_arns : role]
  ) }

  global_pull_account_arns = concat([for ac in var.global_pull_accounts : "arn:aws:iam::${ac}:root"], ["arn:aws:iam::${local.account_id}:root"])
  global_push_account_arns = concat([for ac in var.global_push_accounts : "arn:aws:iam::${ac}:root"], ["arn:aws:iam::${local.account_id}:root"])

  create_iam_users = toset([for k, repo in merge(var.private_repositories, var.public_repositories) : k if repo.create_iam_user])
}

// File: output.tf
output "private_repositories" {
  value       = aws_ecr_repository.this
  description = "List of private ECR repositories"
}

output "public_repositories" {
  value       = aws_ecrpublic_repository.this
  description = "List of public ECR repositories"
}

output "iam_users" {
  value = {
    for key, user in aws_iam_user.artifact_user :
    user.name => {
      user_arn          = user.arn
      access_key_id     = aws_iam_access_key.artifact_user[key].id
      secret_access_key = aws_iam_access_key.artifact_user[key].secret
    }
  }
  sensitive   = true
  description = "List of IAM users"
}

// File: policy.tf
data "aws_iam_policy_document" "private" {
  for_each = var.private_repositories

  statement {
    sid = "PullPolicy"

    principals {
      type        = "AWS"
      identifiers = sort(concat(concat(local.global_pull_account_arns, local.private_repo_pull_arns[each.key]), try([aws_iam_user.artifact_user[each.key].arn], [])))
    }

    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:DescribeImageScanFindings",
      "ecr:DescribeImages",
      "ecr:DescribeRepositories",
      "ecr:GetDownloadUrlForLayer",
      "ecr:GetLifecyclePolicy",
      "ecr:GetLifecyclePolicyPreview",
      "ecr:GetRepositoryPolicy",
      "ecr:ListImages",
      "ecr:ListTagsForResource",
    ]
  }

  statement {
    sid = "PushPolicy"

    principals {
      type        = "AWS"
      identifiers = sort(concat(concat(local.global_push_account_arns, local.private_repo_push_arns[each.key]), try([aws_iam_user.artifact_user[each.key].arn], [])))
    }

    actions = [
      "ecr:PutImage",
      "ecr:InitiateLayerUpload",
      "ecr:UploadLayerPart",
      "ecr:CompleteLayerUpload",
    ]
  }
}

data "aws_iam_policy_document" "public" {
  for_each = var.public_repositories

  statement {
    sid = "PushPolicy"

    principals {
      type        = "AWS"
      identifiers = sort(concat(concat(local.global_push_account_arns, local.public_repo_push_arns[each.key]), try([aws_iam_user.artifact_user[each.key].arn], [])))
    }

    actions = [
      "ecr:PutImage",
      "ecr:InitiateLayerUpload",
      "ecr:UploadLayerPart",
      "ecr:CompleteLayerUpload",
    ]
  }
}

// File: variables.tf
variable "private_repositories" {
  type = map(object({
    image_tag_mutability = optional(string)
    pull_accounts        = optional(list(string), [])
    pull_role_arns       = optional(list(string), [])
    push_accounts        = optional(list(string), [])
    push_role_arns       = optional(list(string), [])
    create_iam_user      = optional(bool, false)
  }))
  description = "List of private repositories that should be created"
  default     = {}
}

variable "public_repositories" {
  type = map(object({
    about             = optional(string)
    architectures     = optional(list(string))
    description       = optional(string)
    logo_image_blob   = optional(string)
    operating_systems = optional(list(string))
    usage_text        = optional(string)
    push_accounts     = optional(list(string), [])
    push_role_arns    = optional(list(string), [])
    create_iam_user   = optional(bool, false)
  }))
  description = "List of public repositories that should be created"
  default     = {}
}

variable "global_pull_accounts" {
  type        = list(string)
  description = "List of accounts that can pull from all the private repositories"
  default     = []
}

variable "global_push_accounts" {
  type        = list(string)
  description = "List of accounts that can push to all the repositories"
  default     = []
}

// File: version.tf
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

// File: context.tf
#
# ONLY EDIT THIS FILE IN github.com/cloudposse/terraform-null-label
# All other instances of this file should be a copy of that one
#
#
# Copy this file from https://github.com/cloudposse/terraform-null-label/blob/master/exports/context.tf
# and then place it in your Terraform module to automatically get
# Cloud Posse's standard configuration inputs suitable for passing
# to Cloud Posse modules.
#
# curl -sL https://raw.githubusercontent.com/cloudposse/terraform-null-label/master/exports/context.tf -o context.tf
#
# Modules should access the whole context as `module.this.context`
# to get the input variables with nulls for defaults,
# for example `context = module.this.context`,
# and access individual variables as `module.this.<var>`,
# with final values filled in.
#
# For example, when using defaults, `module.this.context.delimiter`
# will be null, and `module.this.delimiter` will be `-` (hyphen).
#

module "this" {
  source  = "cloudposse/label/null"
  version = "0.25.0" # requires Terraform >= 0.13.0

  enabled             = var.enabled
  namespace           = var.namespace
  tenant              = var.tenant
  environment         = var.environment
  stage               = var.stage
  name                = var.name
  delimiter           = var.delimiter
  attributes          = var.attributes
  tags                = var.tags
  additional_tag_map  = var.additional_tag_map
  label_order         = var.label_order
  regex_replace_chars = var.regex_replace_chars
  id_length_limit     = var.id_length_limit
  label_key_case      = var.label_key_case
  label_value_case    = var.label_value_case
  descriptor_formats  = var.descriptor_formats
  labels_as_tags      = var.labels_as_tags

  context = var.context
}

# Copy contents of cloudposse/terraform-null-label/variables.tf here

variable "context" {
  type = any
  default = {
    enabled             = true
    namespace           = null
    tenant              = null
    environment         = null
    stage               = null
    name                = "test-vpc"
    delimiter           = null
    attributes          = []
    tags                = {}
    additional_tag_map  = {}
    regex_replace_chars = null
    label_order         = []
    id_length_limit     = null
    label_key_case      = null
    label_value_case    = null
    descriptor_formats  = {}
    # Note: we have to use [] instead of null for unset lists due to
    # https://github.com/hashicorp/terraform/issues/28137
    # which was not fixed until Terraform 1.0.0,
    # but we want the default to be all the labels in `label_order`
    # and we want users to be able to prevent all tag generation
    # by setting `labels_as_tags` to `[]`, so we need
    # a different sentinel to indicate "default"
    labels_as_tags = ["unset"]
  }
  description = <<-EOT
    Single object for setting entire context at once.
    See description of individual variables for details.
    Leave string and numeric variables as `null` to use default value.
    Individual variable settings (non-null) override settings in context object,
    except for attributes, tags, and additional_tag_map, which are merged.
  EOT

  validation {
    condition     = lookup(var.context, "label_key_case", null) == null ? true : contains(["lower", "title", "upper"], var.context["label_key_case"])
    error_message = "Allowed values: `lower`, `title`, `upper`."
  }

  validation {
    condition     = lookup(var.context, "label_value_case", null) == null ? true : contains(["lower", "title", "upper", "none"], var.context["label_value_case"])
    error_message = "Allowed values: `lower`, `title`, `upper`, `none`."
  }
}

variable "enabled" {
  type        = bool
  default     = null
  description = "Set to false to prevent the module from creating any resources"
}

variable "namespace" {
  type        = string
  default     = null
  description = "ID element. Usually an abbreviation of your organization name, e.g. 'eg' or 'cp', to help ensure generated IDs are globally unique"
}

variable "tenant" {
  type        = string
  default     = null
  description = "ID element _(Rarely used, not included by default)_. A customer identifier, indicating who this instance of a resource is for"
}

variable "environment" {
  type        = string
  default     = null
  description = "ID element. Usually used for region e.g. 'uw2', 'us-west-2', OR role 'prod', 'staging', 'dev', 'UAT'"
}

variable "stage" {
  type        = string
  default     = null
  description = "ID element. Usually used to indicate role, e.g. 'prod', 'staging', 'source', 'build', 'test', 'deploy', 'release'"
}

variable "name" {
  type        = string
  default     = "rajesh-vpc"
  description = <<-EOT
    ID element. Usually the component or solution name, e.g. 'app' or 'jenkins'.
    This is the only ID element not also included as a `tag`.
    The "name" tag is set to the full `id` string. There is no tag with the value of the `name` input.
    EOT
}

variable "delimiter" {
  type        = string
  default     = null
  description = <<-EOT
    Delimiter to be used between ID elements.
    Defaults to `-` (hyphen). Set to `""` to use no delimiter at all.
  EOT
}

variable "attributes" {
  type        = list(string)
  default     = []
  description = <<-EOT
    ID element. Additional attributes (e.g. `workers` or `cluster`) to add to `id`,
    in the order they appear in the list. New attributes are appended to the
    end of the list. The elements of the list are joined by the `delimiter`
    and treated as a single ID element.
    EOT
}

variable "labels_as_tags" {
  type        = set(string)
  default     = ["default"]
  description = <<-EOT
    Set of labels (ID elements) to include as tags in the `tags` output.
    Default is to include all labels.
    Tags with empty values will not be included in the `tags` output.
    Set to `[]` to suppress all generated tags.
    **Notes:**
      The value of the `name` tag, if included, will be the `id`, not the `name`.
      Unlike other `null-label` inputs, the initial setting of `labels_as_tags` cannot be
      changed in later chained modules. Attempts to change it will be silently ignored.
    EOT
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = <<-EOT
    Additional tags (e.g. `{'BusinessUnit': 'XYZ'}`).
    Neither the tag keys nor the tag values will be modified by this module.
    EOT
}

variable "additional_tag_map" {
  type        = map(string)
  default     = {}
  description = <<-EOT
    Additional key-value pairs to add to each map in `tags_as_list_of_maps`. Not added to `tags` or `id`.
    This is for some rare cases where resources want additional configuration of tags
    and therefore take a list of maps with tag key, value, and additional configuration.
    EOT
}

variable "label_order" {
  type        = list(string)
  default     = null
  description = <<-EOT
    The order in which the labels (ID elements) appear in the `id`.
    Defaults to ["namespace", "environment", "stage", "name", "attributes"].
    You can omit any of the 6 labels ("tenant" is the 6th), but at least one must be present.
    EOT
}

variable "regex_replace_chars" {
  type        = string
  default     = null
  description = <<-EOT
    Terraform regular expression (regex) string.
    Characters matching the regex will be removed from the ID elements.
    If not set, `"/[^a-zA-Z0-9-]/"` is used to remove all characters other than hyphens, letters and digits.
  EOT
}

variable "id_length_limit" {
  type        = number
  default     = null
  description = <<-EOT
    Limit `id` to this many characters (minimum 6).
    Set to `0` for unlimited length.
    Set to `null` for keep the existing setting, which defaults to `0`.
    Does not affect `id_full`.
  EOT
  validation {
    condition     = var.id_length_limit == null ? true : var.id_length_limit >= 6 || var.id_length_limit == 0
    error_message = "The id_length_limit must be >= 6 if supplied (not null), or 0 for unlimited length."
  }
}

variable "label_key_case" {
  type        = string
  default     = null
  description = <<-EOT
    Controls the letter case of the `tags` keys (label names) for tags generated by this module.
    Does not affect keys of tags passed in via the `tags` input.
    Possible values: `lower`, `title`, `upper`.
    Default value: `title`.
  EOT

  validation {
    condition     = var.label_key_case == null ? true : contains(["lower", "title", "upper"], var.label_key_case)
    error_message = "Allowed values: `lower`, `title`, `upper`."
  }
}

variable "label_value_case" {
  type        = string
  default     = null
  description = <<-EOT
    Controls the letter case of ID elements (labels) as included in `id`,
    set as tag values, and output by this module individually.
    Does not affect values of tags passed in via the `tags` input.
    Possible values: `lower`, `title`, `upper` and `none` (no transformation).
    Set this to `title` and set `delimiter` to `""` to yield Pascal Case IDs.
    Default value: `lower`.
  EOT

  validation {
    condition     = var.label_value_case == null ? true : contains(["lower", "title", "upper", "none"], var.label_value_case)
    error_message = "Allowed values: `lower`, `title`, `upper`, `none`."
  }
}

variable "descriptor_formats" {
  type        = any
  default     = {}
  description = <<-EOT
    Describe additional descriptors to be output in the `descriptors` output map.
    Map of maps. Keys are names of descriptors. Values are maps of the form
    `{
       format = string
       labels = list(string)
    }`
    (Type is `any` so the map values can later be enhanced to provide additional options.)
    `format` is a Terraform format string to be passed to the `format()` function.
    `labels` is a list of labels, in order, to pass to `format()` function.
    Label values will be normalized before being passed to `format()` so they will be
    identical to how they appear in `id`.
    Default is `{}` (`descriptors` output will be empty).
    EOT
}

