// File: cria-cluster-ecs.tf
resource "aws_ecs_cluster" "cb_cluster" {
  name = "cb-cluster" # Nome do cluster
}

// File: cria-repo.tf
#provider "aws" {
#  version = "~> 2.0"
#  region  = "us-east-1" #  REGIAO DO REPOSITORIO
#}

resource "aws_ecr_repository" "nome-app" {
  name = var.proj-nome #  NOME DO REPOSITORIO ECR
}

// File: cria-servico-ecs-e-associa-LB-SeCurity-Group.tf
resource "aws_ecs_service" "service_aplicativos" {
  name            = "service-aplicativos" 
#  cluster         = "${aws_ecs_cluster.cb_cluster.id}"   
  cluster         = aws_ecs_cluster.cb_cluster.id   
  task_definition = aws_ecs_task_definition.task_aplicativos.arn 
  launch_type     = "FARGATE"
  desired_count   = 2  # QUANTIDADE DE CONTAINERS RODANDO

#### ASSOCIADO AO LOAD BALANCER
  depends_on	     = [aws_lb_listener.listener]
  load_balancer {
    target_group_arn = aws_lb_target_group.target_group.arn # APONTO o target group
    container_name   = aws_ecs_task_definition.task_aplicativos.family
    container_port   = 80 # Porta do container 
  }

  network_configuration {
    subnets          = [aws_default_subnet.default_subnet_a.id, aws_default_subnet.default_subnet_b.id, aws_default_subnet.default_subnet_c.id]
    assign_public_ip = true 
    security_groups = [aws_security_group.load_balancer_security_group.id]
  }
}


### CRIA SECURITY GROUP PARA O CONTAINER
resource "aws_security_group" "service_security_group" {
  ingress {
    from_port = 0
    to_port   = 0
    protocol  = "-1"
    # Permite trafego de entrada somente do LOAD BALANCER 
    security_groups = [aws_security_group.load_balancer_security_group.id]
  }

  egress {
    from_port   = 0 # PERMITINDO SAIDA de todas portas
    to_port     = 0 # PERMITINDO SAIDA por todas portas
    protocol    = "-1" #  PERMITINDO SAIDA por todas portas
    cidr_blocks = ["0.0.0.0/0"] # PERMITINDO SAIDA para todos os IPs
  }
}

// File: cria-task-ecs.tf
resource "aws_ecs_task_definition" "task_aplicativos" {
  family                   = "task-aplicativos" # Nome da ECS  task
  container_definitions    = <<DEFINITION
  [
    {
      "name": "task-aplicativos",
      "image": "${local.account_id}.dkr.ecr.${var.region}.amazonaws.com/${var.proj-nome}:latest",
      "essential": true,
      "portMappings": [
        {
          "containerPort": 80,
          "hostPort": 80
        }
      ],
      "memory": 512,
      "cpu": 256
    }
  ]
  DEFINITION
  requires_compatibilities = ["FARGATE"] # Definindo o uso do Fargate
  network_mode             = "awsvpc"    # Declara a awsvpc  para o Fargate
  memory                   = 512         # Memoria reservada para o container 
  cpu                      = 256         # CPU reservada para o container
  execution_role_arn       = data.aws_iam_role.ecs_task_execution_role.arn
}

data "aws_iam_role" "ecs_task_execution_role" {
  name = "ecs_task_execution_role"
  depends_on		= [ 
aws_iam_policy.ecs_permissions,
 ]
}

// File: cria-vpc.tf
resource "aws_default_vpc" "default_vpc" {
}

resource "aws_default_subnet" "default_subnet_a" {
  availability_zone = "us-east-1a"
}

resource "aws_default_subnet" "default_subnet_b" {
  availability_zone = "us-east-1b"
}

resource "aws_default_subnet" "default_subnet_c" {
  availability_zone = "us-east-1c"
}

// File: criando-lb-TARGET-group.tf
resource "aws_lb_target_group" "target_group" {
  name        = var.proj-nome
  port        = 80
  protocol    = "HTTP"
  target_type = "ip"
  vpc_id      = aws_default_vpc.default_vpc.id # Referenciando a default VPC
 health_check  {
    healthy_threshold = 3
    unhealthy_threshold = 3
    timeout = 5
    interval = 30
    matcher = "200-499"
    path = "/"
  }
}

resource "aws_lb_listener" "listener" {
  load_balancer_arn = aws_alb.application_load_balancer.arn # Referenciando Nosso load balance
  port              = "80"
  protocol          = "HTTP"
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.target_group.arn #  target group
  }
}

// File: criando-load-balancer.tf
resource "aws_alb" "application_load_balancer" {
  name               = "test-lb-tf" #  NOME DO LOAD BALANCER
  load_balancer_type = "application"
  subnets = [ # Referenciando as  subnets
    aws_default_subnet.default_subnet_a.id,
    aws_default_subnet.default_subnet_b.id,
    aws_default_subnet.default_subnet_c.id
  ]
  # Referenciando o  security group
  security_groups = [aws_security_group.load_balancer_security_group.id]
}

# Criando 1 security group, Especifico para o load balancer:
resource "aws_security_group" "load_balancer_security_group" {
  ingress {
    from_port   = 80 # Libera trafego na 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # trafego de todas as origens
  }

  egress {
    from_port   = 0 # SAIDA POR QUALQUER PORTA
    to_port     = 0 # SAIDA POR QUALQUER PORTA
    protocol    = "-1" # SAIDA POR QUALQUER PROTOCOLO
    cidr_blocks = ["0.0.0.0/0"] # SAIDA POR QUALQUER IP 
  }
}

