}

// File: vpc.tf
resource "aws_vpc" "vpc1" {
  cidr_block       = "192.168.0.0/16"
  instance_tenancy = "default"
  tags = {
    Name = "Terraform-vpc"
    env  = "dev"
    Team = "DevOps"
  }
}

# internet gateway
resource "aws_internet_gateway" "gwy1" {
  vpc_id = aws_vpc.vpc1.id
}


# public subnet
resource "aws_subnet" "public1" {
  availability_zone       = "us-east-1a"
  cidr_block              = "192.168.1.0/24"
  map_public_ip_on_launch = true
  vpc_id                  = aws_vpc.vpc1.id
  tags = {
    Name = "public-subnet-1"
    env  = "dev"
  }

}


resource "aws_subnet" "public2" {
  availability_zone       = "us-east-1b"
  cidr_block              = "192.168.2.0/24"
  vpc_id                  = aws_vpc.vpc1.id
  map_public_ip_on_launch = true
  tags = {
    Name = "public-subnet-2"
    env  = "dev"
  }

}
#Private subnet

resource "aws_subnet" "private1" {
  availability_zone = "us-east-1a"
  cidr_block        = "192.168.3.0/24"
  vpc_id            = aws_vpc.vpc1.id
  tags = {
    Name = "private-subnet-1"
    env  = "dev"
  }
}
resource "aws_subnet" "private2" {
  availability_zone = "us-east-1b"
  cidr_block        = "192.168.4.0/24"
  vpc_id            = aws_vpc.vpc1.id
  tags = {
    Name = "private-subnet-2"
    env  = "dev"
  }

}
#Elastic ip and Nat gateway
resource "aws_eip" "eip" {

}
resource "aws_nat_gateway" "nat1" {
  allocation_id = aws_eip.eip.id
  subnet_id     = aws_subnet.public1.id
}

#Public route table

resource "aws_route_table" "rtpublic" {
  vpc_id = aws_vpc.vpc1.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.gwy1.id
  }
}

#Private route

resource "aws_route_table" "rtprivate" {
  vpc_id = aws_vpc.vpc1.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_nat_gateway.nat1.id
  }
}

## Subnet association

resource "aws_route_table_association" "rta1" {
  subnet_id      = aws_subnet.private1.id
  route_table_id = aws_route_table.rtprivate.id
}
resource "aws_route_table_association" "rta2" {
  subnet_id      = aws_subnet.private2.id
  route_table_id = aws_route_table.rtprivate.id
}

resource "aws_route_table_association" "rta3" {
  subnet_id      = aws_subnet.public1.id
  route_table_id = aws_route_table.rtpublic.id
}
resource "aws_route_table_association" "rta4" {
  subnet_id      = aws_subnet.public2.id
  route_table_id = aws_route_table.rtpublic.id
}

// File: c2-01-versions.tf
provider "aws" {
  region = var.aws_region
}

# Terraform Settings Block
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

// File: c2-02-redis-variables.tf
# Input Variables - Placeholder file
# AWS Region
variable "aws_region" {
  description = "Region in which AWS Resources to be created"
  type        = string
  default     = "us-east-1"
}
# Environment Variable
variable "environment" {
  description = "Environment Variable used as a prefix"
  type        = string
  default     = "dev"
}
# Business Division
variable "business_divsion" {
  description = "Business Division in the large organization this Infrastructure belongs"
  type        = string
  default     = "SAP"
}


//checked
variable "automatic_failover_enabled" {
  default     = true
  description = "- (Optional) Specifies whether a read-only replica will be automatically promoted to read/write primary if the existing primary fails. If enabled, num_cache_clusters must be greater than 1. Must be enabled for Redis (cluster mode enabled) replication groups."
}

//checked
variable "cluster_mode" {
  type        = string
  default     = "disabled"
  description = "- (Optional) Specifies whether cluster mode is enabled or disabled. Valid values are enabled or disabled or compatible."
}

//checked
variable "apply_immediately" {
  type        = bool
  default     = false
  description = "- (Optional) Specifies whether any modifications are applied immediately, or during the next maintenance window. Default is false"
}


//checked
variable "multi_az_enabled" {
  default     = true
  description = "- (Optional) Specifies whether to enable Multi-AZ Support for the replication group. If true, automatic_failover_enabled must also be enabled. Defaults to true."
}

variable "alarm_memory_threshold" {
  # 10MB
  default     = "10000000"
  description = "- (Optional) The value against which the specified statistic is compared. This parameter is required for alarms based on static thresholds, but should not be used for alarms based on anomaly detection models."
}

variable "alarm_cpu_threshold" {
  default     = "75"
  description = "- (Optional) The value against which the specified statistic is compared. This parameter is required for alarms based on static thresholds, but should not be used for alarms based on anomaly detection models."
}

//checked
variable "num_nodes" {
  default     = "3"
  description = "- (Optional) Number nodes of cache clusters (primary and replicas) this replication group will have. If Multi-AZ is enabled, the value of this parameter must be at least 2. Updates will occur before other modifications. Conflicts with num_node_groups, the deprecatednumber_cache_clusters, or the deprecated cluster_mode."
}

//checked
variable "instance_type" {
  default     = "cache.t2.micro"
  description = "(Optional) Instance class to be used. See AWS documentation for information on supported node types and guidance on selecting node types. Required unless global_replication_group_id is set. Cannot be set if global_replication_group_id is set."
}

//checked
variable "engine_version" {
  default     = "5.0.6"
  description = "- (Optional) Version number of the cache engine to be used for the cache clusters in this replication group."
}

//checked
variable "maintenance_window" {
  default     = "sun:02:30-sun:03:30"
  description = "– (Optional) Specifies the weekly time range for when maintenance on the cache cluster is performed. The format is ddd:hh24:mi-ddd:hh24:mi (24H Clock UTC). The minimum maintenance window is a 60 minute period. Example: sun:05:00-sun:09:00."
}

//checked
variable "at_rest_encryption_enabled" {
  type        = bool
  default     = true
  description = "Enable encryption at rest"
}

//checked
variable "transit_encryption_enabled" {
  type        = bool
  default     = true
  description = <<-EOT
    Set `true` to enable encryption in transit. Forced `true` if `var.auth_token` is set.
    If this is enabled, use the [following guide](https://docs.aws.amazon.com/AmazonElastiCache/latest/red-ug/in-transit-encryption.html#connect-tls) to access redis.
    EOT
}

variable "elasticache_subnet_group_name" {
  type        = string
  default     = "Unknown"
  description = "- (Optional) Name of the cache subnet group to be used for the replication group."
}

variable "vpc_id" {
  type        = string
  default     = "Unknown"
  description = "- (Required) The ID of the VPC is to create Security Group."
}


variable "create_elasticache_subnet_group" {
  type        = bool
  default     = false
  description = "- (Required) The ID of the VPC is to create Security Group."
}

variable "private_subnets" {
  type        = list(any)
  description = "- (Optional) A list of private subnets inside the VPC."
  default     = []
}

variable "global_datastore" {
  type        = bool
  default     = false
  description = "- (Optional) Provides an ElastiCache Global Replication Group resource, which manages replication between two or more Replication Groups in different regions."
}

################################################################################
# Parameter Group
################################################################################
variable "create_parameter_group" {
  description = "Determines whether the ElastiCache parameter group will be created or not"
  type        = bool
  default     = true
}

variable "family" {
  type        = string
  default     = "redis5.0"
  description = "(Required) The family of the ElastiCache parameter group."
}

variable "parameter_group_name" {
  description = "The name of the parameter group. If `create_parameter_group` is `true`, this is the name assigned to the parameter group created. Otherwise, this is the name of an existing parameter group"
  type        = string
  default     = null
}

variable "parameters" {
  description = "List of ElastiCache parameters to apply"
  type        = list(map(string))
  default     = []
}

// File: c2-03-local-value.tf
# Define Local Values in Terraform
locals {
  owners = var.business_divsion
  environment = var.environment
  name = "redis-${var.business_divsion}-${var.environment}"
  common_tags = {
    owners = local.owners
    environment = local.environment
  }
  redis_cluster_name = "${var.global_datastore ? "${local.name}-primary" : local.name}"
}

// File: c2-04-sg.tf
#
# Security group resources
#
resource "aws_security_group" "redis" {
  vpc_id = var.vpc_id

  ingress {
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }


  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  #https://stackoverflow.com/questions/43980946/define-tags-in-central-section-in-terraform
  tags = merge(
    local.common_tags,
    tomap({
      "Name"      = "sgCacheCluster" ##look into
    })
  )

  # the "map" function was deprecated in Terraform v0.12
  # tags = merge(
  #   local.common_tags,
  #   map(
  #     "Name", "sgCacheCluster",
  #     "Project", var.project,
  #   )
  # )

  lifecycle {
      create_before_destroy = true
  } 

}

// File: c2-05-redis.tf
resource "aws_sns_topic" "redis" {
  name = lower(local.redis_cluster_name)

}

# #https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/elasticache_parameter_group
resource "aws_elasticache_parameter_group" "redis" {
  count  = var.create_parameter_group ? 1 : 0
  name   = var.parameter_group_name == null ? "cache-params-${lower(local.redis_cluster_name)}" : var.parameter_group_name
  family = var.family

  lifecycle {
    create_before_destroy = true
  }

  dynamic "parameter" {
    for_each = var.parameters

    content {
      name  = parameter.value.name
      value = parameter.value.value
    }
  }

}

#https://medium.com/swlh/terraform-how-to-use-conditionals-for-dynamic-resources-creation-6a191e041857
resource "aws_elasticache_subnet_group" "redis" {
  count      = var.create_elasticache_subnet_group ? 1 : 0
  name       = "subnet-group-${lower(local.redis_cluster_name)}"
  subnet_ids = var.private_subnets
}

# #
# # ElastiCache resources
# #
resource "aws_elasticache_replication_group" "redis" {
  depends_on = [aws_elasticache_parameter_group.redis]

  replication_group_id       = lower(local.redis_cluster_name)
  description                = "${var.environment}-redis"
  automatic_failover_enabled = var.automatic_failover_enabled
  multi_az_enabled           = var.multi_az_enabled

  cluster_mode      = var.cluster_mode
  apply_immediately = var.apply_immediately

  #availability_zones            =  var.availability_zones == [] ? null : var.availability_zones
  #preferred_cache_cluster_azs  = module.vpc.azs

  num_cache_clusters     = var.num_nodes
  node_type              = var.instance_type
  engine_version         = var.engine_version
  parameter_group_name   = var.create_parameter_group == true ? aws_elasticache_parameter_group.redis[0].name : var.parameter_group_name
  subnet_group_name      = var.create_elasticache_subnet_group ? aws_elasticache_subnet_group.redis[0].name : var.elasticache_subnet_group_name
  security_group_ids     = [aws_security_group.redis.id]
  maintenance_window     = var.maintenance_window
  notification_topic_arn = aws_sns_topic.redis.arn
  port                   = "6379"


  # cluster_mode {
  #   replicas_per_node_group = 1
  #   num_node_groups         = 2
  # }

  at_rest_encryption_enabled = var.at_rest_encryption_enabled
  transit_encryption_enabled = var.transit_encryption_enabled

  tags = merge(
    local.common_tags,
    tomap({
      "Name" = "CacheReplicationGroup"
    })
  )
}

#
# CloudWatch resources
#
resource "aws_cloudwatch_metric_alarm" "cache_cpu" {
  count = var.num_nodes

  alarm_name          = "alarm${var.environment}CacheCluster00${count.index + 1}CPUUtilization"
  alarm_description   = "Redis cluster CPU utilization"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = "1"
  metric_name         = "CPUUtilization"
  namespace           = "AWS/ElastiCache"
  period              = "300"
  statistic           = "Average"

  threshold = var.alarm_cpu_threshold

  dimensions = {
    CacheClusterId = "${aws_elasticache_replication_group.redis.id}-00${count.index + 1}"
  }

  alarm_actions = [aws_sns_topic.redis.arn]

}

resource "aws_cloudwatch_metric_alarm" "cache_memory" {
  count = var.num_nodes

  alarm_name          = "alarm${var.environment}CacheCluster00${count.index + 1}FreeableMemory"
  alarm_description   = "Redis cluster freeable memory"
  comparison_operator = "LessThanThreshold"
  evaluation_periods  = "1"
  metric_name         = "FreeableMemory"
  namespace           = "AWS/ElastiCache"
  period              = "60"
  statistic           = "Average"

  threshold = var.alarm_memory_threshold

  dimensions = {
    CacheClusterId = "${aws_elasticache_replication_group.redis.id}-00${count.index + 1}"
  }

  alarm_actions = [aws_sns_topic.redis.arn]

}

// File: c2-06-redis-output.tf
# https://stackoverflow.com/questions/56257169/terraform-how-to-use-conditionally-created-resources-output-in-conditional-op
output "global_replication_group_id" {
  value = length(aws_elasticache_global_replication_group.global_datastore) > 0 ? aws_elasticache_global_replication_group.global_datastore[0].id : null
  description = "The suffix name of a Global Datastore"
}

// File: c3-01-global-datastore.tf
resource "aws_elasticache_global_replication_group" "global_datastore" {
  count = var.global_datastore ? 1 : 0

  global_replication_group_id_suffix = lower(local.name)
  primary_replication_group_id       = aws_elasticache_replication_group.redis.id
}

