// File: main.tf
data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# Create an IAM role for API Gateway
resource "aws_iam_role" "APIGWRole" {
  assume_role_policy = <<POLICY1
{
  "Version" : "2012-10-17",
  "Statement" : [
    {
      "Effect" : "Allow",
      "Principal" : {
        "Service" : "apigateway.amazonaws.com"
      },
      "Action" : "sts:AssumeRole"
    }
  ]
}
POLICY1
}

# Create an IAM policy for API Gateway to PutItem & Query DynamoDB
resource "aws_iam_policy" "APIGWPolicy" {
  policy = <<POLICY2
{
  "Version" : "2012-10-17",
  "Statement" : [
    {
      "Effect" : "Allow",
      "Action" : [
        "dynamodb:PutItem",
        "dynamodb:Query"
      ],
      "Resource" : [ "${aws_dynamodb_table.MyDynamoDBTable.arn}",
      "${aws_dynamodb_table.MyDynamoDBTable.arn}/index/*" ]
    }
  ]
}
POLICY2
}

# Attach the IAM policies to the equivalent rule
resource "aws_iam_role_policy_attachment" "APIGWPolicyAttachment" {
  role       = aws_iam_role.APIGWRole.name
  policy_arn = aws_iam_policy.APIGWPolicy.arn
}

# Create a new DynamoDB table with all attributes and Indexes
resource "aws_dynamodb_table" "MyDynamoDBTable" {
  name           = "Pets"
  billing_mode   = "PROVISIONED"
  read_capacity  = 5
  write_capacity = 5
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }

  attribute {
    name = "PetType"
    type = "S"
  }

  global_secondary_index {
    name               = "PetType-index"
    hash_key           = "PetType"
    write_capacity     = 5
    read_capacity      = 5
    projection_type    = "INCLUDE"
    non_key_attributes = ["PetName", "PetPrice"]
  }

}

#Create a new API Gateway rest api with DynamoDB Integration that requires an API Key for security
resource "aws_api_gateway_rest_api" "MyApiGatewayRestApi" {
  name = "APIGW DynamoDB Serverless Pattern Demo"
  body = jsonencode({
    "swagger" : "2.0",
    "info" : {
      "version" : "2022-03-21T11:36:12Z",
      "title" : "APIGW DynamoDB Serverless Pattern Demo"
    },
    "basePath" : "/v1",
    "schemes" : ["https"],
    "paths" : {
      "/pets" : {
        "post" : {
          "consumes" : ["application/json"],
          "produces" : ["application/json"],
          "responses" : {
            "200" : {
              "description" : "200 response"
            }
          },
          "security" : [{
            "api_key" : []
          }],
          "x-amazon-apigateway-integration" : {
            "type" : "aws",
            "credentials" : "${aws_iam_role.APIGWRole.arn}",
            "httpMethod" : "POST",
            "uri" : "arn:aws:apigateway:${data.aws_region.current.name}:dynamodb:action/PutItem",
            "responses" : {
              "default" : {
                "statusCode" : "200",
                "responseTemplates" : {
                  "application/json" : "{}"
                }
              }
            },
            "requestTemplates" : {
              "application/json" : "{\"TableName\":\"Pets\",\"Item\":{\"id\":{\"S\":\"$context.requestId\"},\"PetType\":{\"S\":\"$input.path('$.PetType')\"},\"PetName\":{\"S\":\"$input.path('$.PetName')\"},\"PetPrice\":{\"N\":\"$input.path('$.PetPrice')\"},\"PetBoolean\":{\"BOOL\":true}}}"
            },
            "passthroughBehavior" : "when_no_templates"
          }
        }
      },
      "/pets/{PetType}" : {
        "get" : {
          "consumes" : ["application/json"],
          "produces" : ["application/json"],
          "parameters" : [{
            "name" : "PetType",
            "in" : "path",
            "required" : true,
            "PetType" : "string"
          }],
          "responses" : {
            "200" : {
              "description" : "200 response"
            }
          },
          "security" : [{
            "api_key" : []
          }],
          "x-amazon-apigateway-integration" : {
            "type" : "aws",
            "credentials" : "${aws_iam_role.APIGWRole.arn}",
            "httpMethod" : "POST",
            "uri" : "arn:aws:apigateway:${data.aws_region.current.name}:dynamodb:action/Query",
            "responses" : {
              "default" : {
                "statusCode" : "200",
                "responseTemplates" : {
                  "application/json" : "#set($inputRoot = $input.path('$'))\n{\n\t\"pets\": [\n\t\t#foreach($field in $inputRoot.Items) {\n\t\t\t\"id\": \"$field.id.S\",\n\t\t\t\"PetType\": \"$field.PetType.S\",\n\t\t\t\"PetName\": \"$field.PetName.S\",\n\t\t\t\"PetPrice\": \"$field.PetPrice.N\"\n\t\t}#if($foreach.hasNext),#end\n\t\t#end\n\t]\n}"
                }
              }
            },
            "requestParameters" : {
              "integration.request.path.PetType" : "method.request.path.PetType"
            },
            "requestTemplates" : {
              "application/json" : "{\"TableName\":\"Pets\",\"IndexName\":\"PetType-index\",\"KeyConditionExpression\":\"PetType=:v1\",\"ExpressionAttributeValues\":{\":v1\":{\"S\":\"$util.urlDecode($input.params('PetType'))\"}}}"
            },
            "passthroughBehavior" : "when_no_templates"
          }
        }
      }
    },
    "securityDefinitions" : {
      "api_key" : {
        "type" : "apiKey",
        "name" : "x-api-key",
        "in" : "header"
      }
    }
  })
}

# Create a new API Gateway deployment for the created rest api
resource "aws_api_gateway_deployment" "MyApiGatewayDeployment" {
  rest_api_id = aws_api_gateway_rest_api.MyApiGatewayRestApi.id
}

# Create a Log Group for API Gateway to push logs to
resource "aws_cloudwatch_log_group" "MyLogGroup" {
  name_prefix = "/aws/APIGW/terraform"
}

# Create a Log Policy to allow Cloudwatch to Create log streams and put logs
resource "aws_cloudwatch_log_resource_policy" "MyCloudWatchLogPolicy" {
  policy_name     = "Terraform-CloudWatchLogPolicy-${data.aws_caller_identity.current.account_id}"
  policy_document = <<POLICY3
{
  "Version": "2012-10-17",
  "Id": "CWLogsPolicy",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": [
          "apigateway.amazonaws.com",
          "delivery.logs.amazonaws.com"
          ]
      },
      "Action": [
        "logs:CreateLogStream",
        "logs:PutLogEvents"
        ],
      "Resource": "${aws_cloudwatch_log_group.MyLogGroup.arn}",
      "Condition": {
        "ArnEquals": {
          "aws:SourceArn": "${aws_api_gateway_rest_api.MyApiGatewayRestApi.arn}"
        }
      }
    }
  ]
}
POLICY3
}

# Create a new API Gateway stage with logging enabled
resource "aws_api_gateway_stage" "MyApiGatewayStage" {
  deployment_id = aws_api_gateway_deployment.MyApiGatewayDeployment.id
  rest_api_id   = aws_api_gateway_rest_api.MyApiGatewayRestApi.id
  stage_name    = "v1"
  depends_on    = [aws_api_gateway_account.ApiGatewayAccountSetting]

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.MyLogGroup.arn
    format          = "{ \"requestId\":\"$context.requestId\", \"ip\": \"$context.identity.sourceIp\", \"requestTime\":\"$context.requestTime\", \"httpMethod\":\"$context.httpMethod\",\"routeKey\":\"$context.routeKey\", \"status\":\"$context.status\",\"protocol\":\"$context.protocol\", \"responseLength\":\"$context.responseLength\" }"
  }
}

# If you are using apigateway and you have an existing cloudwatch role ARN set to your account delete the aws_api_gateway_account block, the aws_iam_role block & the aws_iam_role_policy block.

## delete if you have this configured in your account
resource "aws_api_gateway_account" "ApiGatewayAccountSetting" {
  cloudwatch_role_arn = aws_iam_role.APIGatewayCloudWatchRole.arn
}

## delete if you have this configured in your account
resource "aws_iam_role" "APIGatewayCloudWatchRole" {
  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "",
      "Effect": "Allow",
      "Principal": {
        "Service": "apigateway.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
EOF
}

## delete if you have this configured in your account
resource "aws_iam_role_policy" "APIGatewayCloudWatchPolicy" {
  role = aws_iam_role.APIGatewayCloudWatchRole.id

  policy = <<EOF
{
    "Version": "2012-10-17",
    "Statement": [
        {
            "Effect": "Allow",
            "Action": [
                "logs:CreateLogGroup",
                "logs:CreateLogStream",
                "logs:DescribeLogGroups",
                "logs:DescribeLogStreams",
                "logs:PutLogEvents",
                "logs:GetLogEvents",
                "logs:FilterLogEvents"
            ],
            "Resource": "*"
        }
    ]
}
EOF
}

# Configure API Gateway to push all logs to CloudWatch Logs
resource "aws_api_gateway_method_settings" "MyApiGatewaySetting" {
  rest_api_id = aws_api_gateway_rest_api.MyApiGatewayRestApi.id
  stage_name  = aws_api_gateway_stage.MyApiGatewayStage.stage_name
  method_path = "*/*"

  settings {
    # Enable CloudWatch logging and metrics
    metrics_enabled = true
    logging_level   = "INFO"
  }
}

# Create an API Gateway usage plan to use with the created REST API
resource "aws_api_gateway_usage_plan" "MyApiGatewayUsagePlan" {
  name = "apigw-dynamodb-terraform-usage-plan"

  quota_settings {
    limit  = 1000
    period = "MONTH"
  }

  throttle_settings {
    burst_limit = 20
    rate_limit  = 100
  }

  api_stages {
    api_id = aws_api_gateway_rest_api.MyApiGatewayRestApi.id
    stage  = aws_api_gateway_stage.MyApiGatewayStage.stage_name
  }
}

# Create an API Gateway Key
resource "aws_api_gateway_api_key" "MyAPIKey" {
  name = "apigw-dynamodb-terraform-api-key"
}

# Create an API Gateway Usage Plan key and associate it to the previously created API Key
resource "aws_api_gateway_usage_plan_key" "MyAPIGWUsagePlanKey" {
  key_id        = aws_api_gateway_api_key.MyAPIKey.id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.MyApiGatewayUsagePlan.id
}

# Display APIGW invocation URL
output "apigw_endpoint" {
  value       = "${aws_api_gateway_stage.MyApiGatewayStage.invoke_url}/pets"
  description = "The API Gateway Invocation URL"
}

# Display the APIGW Key to use for testing
output "apigw_key" {
  value       = aws_api_gateway_usage_plan_key.MyAPIGWUsagePlanKey.value
  description = "The APIGW Key to use for testing"
}

// File: data.tf
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_iam_policy_document" "assume_role" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

// File: outputs.tf
output "multi_access_point_status" {
  value = aws_s3control_multi_region_access_point.example.status
  description = "Status of multi_region_access_point"
}
output "multi_access_point_alias" {
  value = aws_s3control_multi_region_access_point.example.alias
  description = "alias of multi_region_access_point"
}
output "multi_access_point_domain_name" {
  value = aws_s3control_multi_region_access_point.example.domain_name
  description = "domain_name of multi_region_access_point"
}

output "multi_access_point_arn" {
  value = aws_s3control_multi_region_access_point.example.arn
  description = "arn of multi_region_access_point"
}

// File: provider.tf
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
  alias  = "primary_region"
  default_tags {
    tags = {
      Environment = "Primary-Region"
      Name        = "Devopscaptain"
    }
  }
}

provider "aws" {
  region = "us-west-2"
  alias  = "secondary_region"
  default_tags {
    tags = {
      Environment = "Secondary-Region"
      Name        = "Devopscaptain"
    }
  }
}

// File: replication-rule.tf
resource "aws_iam_role" "replication" {
  name               = "devopscaptain-tf-iam-role-replication"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json
}

data "aws_iam_policy_document" "replication" {
  statement {
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
    ]

    resources = [aws_s3_bucket.primary.arn]
  }

  statement {
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]

    resources = ["${aws_s3_bucket.primary.arn}/*"]
  }

  statement {
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]

    resources = ["${aws_s3_bucket.secondary.arn}/*"]
  }
}

resource "aws_iam_policy" "replication" {
  name   = "devopscaptain-iam-role-policy-replication"
  policy = data.aws_iam_policy_document.replication.json
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

resource "aws_s3_bucket_replication_configuration" "replication" {
  provider   = aws.primary_region
  depends_on = [aws_s3_bucket_versioning.primary]

  role   = aws_iam_role.replication.arn
  bucket = aws_s3_bucket.primary.id

  rule {
    id     = "rule-1"
    status = "Enabled"

    destination {
      bucket        = aws_s3_bucket.secondary.arn
      storage_class = "STANDARD"
    }
  }
}

// File: s3-bucket.tf
###### Create S3 Bucket in primary region ####

resource "aws_s3_bucket" "primary" {
  provider = aws.primary_region
  bucket   = var.primary_bucket_name
}

resource "aws_s3_bucket_ownership_controls" "primary" {
  bucket   = aws_s3_bucket.primary.id
  provider = aws.primary_region
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "primary" {
  depends_on = [aws_s3_bucket_ownership_controls.primary]
  bucket     = aws_s3_bucket.primary.id
  provider   = aws.primary_region
  acl        = "private"
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id
  versioning_configuration {
    status = "Enabled"
  }
  provider = aws.primary_region
}




###### Create S3 Bucket in  secondary region ####
resource "aws_s3_bucket" "secondary" {
  provider = aws.secondary_region
  bucket   = var.secondary_bucket_name
}

resource "aws_s3_bucket_ownership_controls" "secondary" {
  bucket   = aws_s3_bucket.secondary.id
  provider = aws.secondary_region
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "secondary" {
  depends_on = [aws_s3_bucket_ownership_controls.secondary]
  bucket     = aws_s3_bucket.secondary.id
  provider   = aws.secondary_region
  acl        = "private"
}

resource "aws_s3_bucket_versioning" "secondary" {
  bucket = aws_s3_bucket.secondary.id
  versioning_configuration {
    status = "Enabled"
  }
  provider = aws.secondary_region
}

// File: s3-m-r-acess-point.tf
resource "aws_s3control_multi_region_access_point" "example" {
  details {
    name = var.access_point_name

    region {
      bucket = aws_s3_bucket.primary.id
    }

    region {
      bucket = aws_s3_bucket.secondary.id
    }
  }
}

resource "aws_s3control_multi_region_access_point_policy" "example" {
  details {
    name = element(split(":", aws_s3control_multi_region_access_point.example.id), 1)
    policy = jsonencode({
      "Version" : "2012-10-17",
      "Statement" : [
        {
          "Sid" : "Example",
          "Effect" : "Allow",
          "Principal" : {
            "AWS" : data.aws_caller_identity.current.account_id
          },
          "Action" : ["s3:GetObject", "s3:PutObject"],
          "Resource" : "arn:${data.aws_partition.current.partition}:s3::${data.aws_caller_identity.current.account_id}:accesspoint/${aws_s3control_multi_region_access_point.example.alias}/object/*"
        }
      ]
    })
  }
}

// File: variables.tf
variable "primary_bucket_name" {
  type        = string
  default = "example1"
  description = "primary bucket name to be created for multi_region_access_point"
}

variable "secondary_bucket_name" {
  type        = string
  default = "example2"
  description = "secondary bucket name to be created for multi_region_access_point"
}

variable "access_point_name" {
  type    = string
  default = "example-mrap"
  description = "Name for multi_region_access_point"
}

// File: main.tf
/*
ECS Service
*/

// AWS IAM Linked Role used for ecs service
resource "aws_iam_role" "ecs_service" {
  name               = "ecsServiceRole"
  assume_role_policy = data.aws_iam_policy_document.ecs_service.json
}

// AWS IAM Role Policy used for ecs service
resource "aws_iam_role_policy" "ecs_service" {
  name   = "ecsTaskRolePolicy"
  policy = data.aws_iam_policy_document.ecs_service_policy.json
  role   = aws_iam_role.ecs_service.id
}

// AWS IAM Policy in format JSON for linked role ecs service
data "aws_iam_policy_document" "ecs_service_policy" {
  statement {
    effect    = "Allow"
    resources = ["*"]

    actions = [
      "elasticloadbalancing:Describe*",
      "elasticloadbalancing:DeregisterInstancesFromLoadBalancer",
      "elasticloadbalancing:RegisterInstancesWithLoadBalancer",
      "ec2:Describe*",
      "ec2:AuthorizeSecurityGroupIngress",
      "ssm:GetParameters",
      "secretsmanager:GetSecretValue",
      "kms:Decrypt",
      "codedeploy:CreateApplication",
      "codedeploy:CreateDeployment",
      "codedeploy:CreateDeploymentGroup",
      "codedeploy:GetApplication",
      "codedeploy:GetDeployment",
      "codedeploy:GetDeploymentGroup",
      "codedeploy:ListApplications",
      "codedeploy:ListDeploymentGroups",
      "codedeploy:ListDeployments",
      "codedeploy:StopDeployment",
      "codedeploy:GetDeploymentTarget",
      "codedeploy:ListDeploymentTargets",
      "codedeploy:GetDeploymentConfig",
      "codedeploy:GetApplicationRevision",
      "codedeploy:RegisterApplicationRevision",
      "codedeploy:BatchGetApplicationRevisions",
      "codedeploy:BatchGetDeploymentGroups",
      "codedeploy:BatchGetDeployments",
      "codedeploy:BatchGetApplications",
      "codedeploy:ListApplicationRevisions",
      "codedeploy:ListDeploymentConfigs",
      "codedpeloy:ContinueDeployment",
      "sns:ListTopics",
      "cloudwatch:DescribeAlarms",
      "lambda:ListFunctions",
    ]
  }
}

// AWS IAM Policy in format JSON for linked role ecs task
data "aws_iam_policy_document" "ecs_service" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type = "Service"

      identifiers = [
        "ecs.amazonaws.com",
        "s3.amazonaws.com",
      ]
    }
  }
}

/*
ECS Execution
*/

// IAM Policy for task execution role
data "aws_iam_policy_document" "ecs_exec" {
  statement {
    effect    = "Allow"
    resources = ["*"]

    actions = [
      "ecr:GetAuthorizationToken",
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
      "ecs:DescribeTaskDefinition",
      "ecs:ListServices",
      "ecs:DescribeServices",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "secretsmanager:GetSecretValue",
      "kms:Decrypt",
      "ssm:GetParameter",
      "ssm:GetParameters",
      "ssm:GetParameterHistory",
      "ssm:GetParametersByPath",
    ]
  }
}

// AWS IAM Role used for ecs task execution
resource "aws_iam_role" "ecs_exec" {
  name               = "ecsExecTaskRole"
  assume_role_policy = data.aws_iam_policy_document.ecs_task_exec.json
}

// AWS IAM Role Policy used for ecs task execution
resource "aws_iam_role_policy" "ecs_exec" {
  name   = "ecsExecRolePolicy"
  policy = data.aws_iam_policy_document.ecs_exec.json
  role   = aws_iam_role.ecs_exec.id
}

data "aws_iam_policy_document" "additional_permissions_ecs_execution" {
  statement {
    effect    = "Allow"
    resources = ["*"]

    actions = [
      "ecs:ListServices",
      "ecs:DescribeServices",
    ]
  }

  statement {
    effect    = "Allow"
    resources = ["*"]

    actions = ["s3:*"]
  }
}

// Additional permissions task execution
resource "aws_iam_role_policy" "additional_permissions_ecs_execution" {
  name   = "ecsExecution_additional"
  role   = aws_iam_role.ecs_exec.id
  policy = data.aws_iam_policy_document.additional_permissions_ecs_execution.json
}

/*
ECS Task
*/

// AWS IAM Policy in format JSON for linked role ecs task
data "aws_iam_policy_document" "ecs_task" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type = "Service"

      identifiers = [
        "ecs-tasks.amazonaws.com",
        "s3.amazonaws.com",
      ]
    }
  }
}

// - IAM role that the Amazon ECS container agent and the Docker daemon can assume
data "aws_iam_policy_document" "ecs_task_exec" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type = "Service"

      identifiers = [
        "ecs-tasks.amazonaws.com",
        "s3.amazonaws.com",
      ]
    }
  }
}

// AWS IAM Role used for ecs task
resource "aws_iam_role" "ecs_task" {
  name               = "ecsTaskRole"
  assume_role_policy = data.aws_iam_policy_document.ecs_task.json
}

// Additional permissions
resource "aws_iam_role_policy" "additional_permissions_task_exec" {
  name   = "ecsTaskRole_additional"
  role   = aws_iam_role.ecs_task.id
  policy = data.aws_iam_policy_document.additional_permissions_task_exec.json
}

data "aws_iam_policy_document" "additional_permissions_task_exec" {
  statement {
    effect    = "Allow"
    resources = ["*"]

    actions = [
      "ecs:ListServices",
      "ecs:DescribeServices",
    ]
  }

  statement {
    effect    = "Allow"
    resources = ["*"]

    actions = [
      "s3:*",
    ]
  }
}

/*
ECS Autoscaling
*/

// AWS IAM Role used for ecs autoscaling
resource "aws_iam_role" "ecs_autoscale_role" {
  name               = "ecs_autoscale_role"
  assume_role_policy = data.aws_iam_policy_document.ecs_autoscaling_policy.json
}

// AWS IAM Role Policy used for ecs autoscaling
resource "aws_iam_role_policy" "ecs_autoscale_role_policy" {
  name   = "ecs_autoscale_role_policy"
  policy = data.aws_iam_policy_document.ecs_autoscaling_role_policy.json
  role   = aws_iam_role.ecs_autoscale_role.id
}

// AWS IAM Linked Role in format JSON for autoscaling
data "aws_iam_policy_document" "ecs_autoscaling_policy" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["application-autoscaling.amazonaws.com"]
    }
  }
}

// AWS IAM Role Policy in format JSON for autoscaling
data "aws_iam_policy_document" "ecs_autoscaling_role_policy" {
  statement {
    effect    = "Allow"
    resources = ["*"]

    actions = [
      "ecs:DescribeServices",
      "ecs:UpdateService",
      "cloudwatch:DescribeAlarms",
    ]
  }
}

/*
ECS Codedeploy
*/

// AWS IAM Role used for ecs codedeploy
resource "aws_iam_role" "ecs_codedeploy" {
  name = "ecs_codedeploy_role"

  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "",
      "Effect": "Allow",
      "Principal": {
        "Service": "codedeploy.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
EOF

}

// AWS IAM Role Policy in format JSON for codeploy
data "aws_iam_policy_document" "ecs_codedeploy_role_policy" {
  statement {
    effect    = "Allow"
    resources = ["*"]

    actions = [
      "ecs:DescribeServices",
      "ecs:CreateTaskSet",
      "ecs:UpdateServicePrimaryTaskSet",
      "ecs:DeleteTaskSet",
      "elasticloadbalancing:DescribeTargetGroups",
      "elasticloadbalancing:DescribeListeners",
      "elasticloadbalancing:ModifyListener",
      "elasticloadbalancing:DescribeRules",
      "elasticloadbalancing:ModifyRule",
      "lambda:InvokeFunction",
      "cloudwatch:DescribeAlarms",
      "sns:Publish",
      "s3:GetObject",
      "s3:GetObjectMetadata",
      "s3:GetObjectVersion",
    ]
  }
}

// Aditional Role policy Iam:passROLE for execute task
data "aws_iam_policy_document" "ecs_codedeploy_role_policy_task" {
  statement {
    effect    = "Allow"
    resources = [aws_iam_role.ecs_task.arn]

    actions = [
      "iam:PassRole",
    ]
  }
}

// ECS Codedeploy policy to execute ecs task
data "aws_iam_policy_document" "ecs_codedeploy_role_policy_task_exec" {
  statement {
    effect    = "Allow"
    resources = [aws_iam_role.ecs_exec.arn]

    actions = [
      "iam:PassRole",
    ]
  }
}

// AWS IAM Role Policy used for codedeploy
resource "aws_iam_role_policy_attachment" "AWSCodeDeployRole" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeDeployRole"
  role       = aws_iam_role.ecs_codedeploy.name
}

// AWS IAM Role Policy used for ecs codedeploy
resource "aws_iam_role_policy" "ecs_codedeploy_role_policy" {
  name   = "ecs_codedeploy_role_policy"
  policy = data.aws_iam_policy_document.ecs_codedeploy_role_policy.json
  role   = aws_iam_role.ecs_codedeploy.id
}

// Attach policies for codedeploy run task, drain, etc
resource "aws_iam_role_policy" "ecs_codedeploy_role_policy_task" {
  name   = "ecs_codedeploy_role_policy_task"
  policy = data.aws_iam_policy_document.ecs_codedeploy_role_policy_task.json
  role   = aws_iam_role.ecs_codedeploy.id
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy_task_exec" {
  name   = "ecs_codedeploy_role_policy_task_exec"
  policy = data.aws_iam_policy_document.ecs_codedeploy_role_policy_task_exec.json
  role   = aws_iam_role.ecs_codedeploy.id
}

// File: outputs.tf
output "ecs_service" {
  value = aws_iam_role_policy.ecs_service.id
}

output "ecs_exec" {
  value = aws_iam_role.ecs_exec.arn
}

output "ecs_task" {
  value = aws_iam_role.ecs_task.arn
}

output "ecs_autoscale_role" {
  value = aws_iam_role.ecs_autoscale_role.arn
}

output "ecs_codedeploy" {
  value = aws_iam_role.ecs_codedeploy.arn
}

// File: data.tf
######## Region & Account Id

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

// File: main.tf
locals {
  region = data.aws_region.current.name
  account_id = data.aws_caller_identity.current.account_id
}

// File: provider.tf
terraform {

  # backend "s3" {
  # }
}

provider "aws" {
  region = "us-east-1"
}

// File: s3.tf
resource "aws_s3_bucket" "s3_frontend_nft_maker_v2" {
  bucket = "s3-frontend-nft-maker-v2"

}

resource "aws_s3_bucket_policy" "s3_frontend_nft_maker_v2_policy" {
  bucket = aws_s3_bucket.s3_frontend_nft_maker_v2.id
  policy = data.aws_iam_policy_document.s3_frontend_nft_maker_v2_policy_document.json
}

data "aws_iam_policy_document" "s3_frontend_nft_maker_v2_policy_document" {
  statement {

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = [
      "s3:GetObject",
      "s3:ListBucket",
    ]

    resources = [
      aws_s3_bucket.s3_frontend_nft_maker_v2.arn,
      "${aws_s3_bucket.s3_frontend_nft_maker_v2.arn}/*",
    ]
  }
}

resource "aws_s3_bucket_cors_configuration" "s3_frontend_nft_maker_v2_cors_config" {
  bucket = aws_s3_bucket.s3_frontend_nft_maker_v2.id

  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["PUT", "POST", "GET", "DELETE"]
    allowed_origins = ["*"]
    expose_headers  = ["ETag"]
    max_age_seconds = 3000
  }
}

resource "aws_s3_bucket_website_configuration" "s3_frontend_nft_maker_v2_website_config" {
  bucket = aws_s3_bucket.s3_frontend_nft_maker_v2.id

  index_document {
    suffix = "index.html"
  }

  error_document {
    key = "index.html"
  }
}

resource "aws_cloudfront_distribution" "s3_distribution" {
  origin {
    domain_name = aws_s3_bucket.s3_frontend_nft_maker_v2.bucket_regional_domain_name
    origin_id   = aws_s3_bucket.s3_frontend_nft_maker_v2.id

    s3_origin_config {
      origin_access_identity = "origin-access-identity/cloudfront/ABCDEFG1234567"
    }
  }

  enabled             = true
  is_ipv6_enabled     = true
  comment             = "Some comment"
  default_root_object = "index.html"

  # logging_config {
  #   include_cookies = false
  #   bucket          = "mylogs.s3.amazonaws.com"
  #   prefix          = "myprefix"
  # }

  # aliases = []

  default_cache_behavior {
    allowed_methods  = ["DELETE", "GET", "HEAD", "OPTIONS", "PATCH", "POST", "PUT"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = aws_s3_bucket.s3_frontend_nft_maker_v2.id

    forwarded_values {
      query_string = false

      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "allow-all"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
  }

  # Cache behavior with precedence 0
  ordered_cache_behavior {
    path_pattern     = "/content/immutable/*"
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD", "OPTIONS"]
    target_origin_id = aws_s3_bucket.s3_frontend_nft_maker_v2.id

    forwarded_values {
      query_string = false
      headers      = ["Origin"]

      cookies {
        forward = "none"
      }
    }

    min_ttl                = 0
    default_ttl            = 86400
    max_ttl                = 31536000
    compress               = true
    viewer_protocol_policy = "redirect-to-https"
  }

  # Cache behavior with precedence 1
  ordered_cache_behavior {
    path_pattern     = "/content/*"
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = aws_s3_bucket.s3_frontend_nft_maker_v2.id

    forwarded_values {
      query_string = false

      cookies {
        forward = "none"
      }
    }

    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
    compress               = true
    viewer_protocol_policy = "redirect-to-https"
  }

  price_class = "PriceClass_200"

  restrictions {
    geo_restriction {
      restriction_type = "none"
      # locations        = ["US", "CA", "GB", "DE"]
    }
  }

  tags = {
    Environment = "production"
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

// File: state-management.tf
######## Terraform State managemnet s3 bucket
resource "aws_s3_bucket" "terraform_state_bucket" {
    bucket = "near-frontend-${lower(var.AWS_ENVIRONMENT_NAME)}-terraform-state"

    tags = {
        Name = "S3 Remote Terraform State Store"
        Environment = var.AWS_ENVIRONMENT_NAME
    }
}


resource "aws_s3_bucket_acl" "terraform_state_bucket_securing" {
  bucket = aws_s3_bucket.terraform_state_bucket.id
  acl    = "private"
}

resource "aws_s3_bucket_versioning" "terraform_state_bucket_versioning" {
  bucket = aws_s3_bucket.terraform_state_bucket.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_kms_key" "terraform_state_bucket_kms_key" {
  description             = "This key is used to encrypt bucket objects"
  deletion_window_in_days = 10
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state_bucket_encryption" {
  bucket = aws_s3_bucket.terraform_state_bucket.bucket

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.terraform_state_bucket_kms_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

######## Terraform State managemnet dynmodb
resource "aws_dynamodb_table" "terraform-lock" {
    name           = "near-frontend-terraform-state"
    read_capacity  = 5
    write_capacity = 5
    hash_key       = "LockID"
    attribute {
        name = "LockID"
        type = "S"
    }
    tags = {
        "Name" = "DynamoDB Terraform State Lock Table"
        Environment = var.AWS_ENVIRONMENT_NAME
    }
}

// File: variables.tf
variable "AWS_ACCESS_KEY_ID" {
  type = string
  default = ""
}

variable "AWS_SECRET_ACCESS_KEY" {
  type = string
  default = ""
}

variable "AWS_ENVIRONMENT_NAME" {
  type = string
  default = ""
}

// File: main.tf
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
  required_version = ">= 1.7.0"
}

data "aws_region" "current" {}

resource "aws_vpc" "main" {
  for_each = var.vpc

  cidr_block           = each.value.cidr_block
  enable_dns_support   = each.value.enable_dns
  enable_dns_hostnames = each.value.enable_dns_hostnames

  tags = merge(
    var.tags,
    {
      "Name" = "vpc-${each.key}-${data.aws_region.current.name}"
    }
  )
}

resource "aws_subnet" "main" {
  for_each = {
    for key, value in var.subnets : key => value
  }

  vpc_id            = aws_vpc.main[each.value.vpc_name].id
  cidr_block        = each.value.cidr_block
  availability_zone = each.value.availability_zone

  tags = merge(
    var.tags,
    {
      "Name" = "sn-${each.key}-${each.value.availability_zone}-${data.aws_region.current.name}"
    }
  )
}

resource "aws_internet_gateway" "main" {
  for_each = var.internet_gateway

  vpc_id = aws_vpc.main[each.value.vpc_name].id

  tags = merge(
    var.tags,
    {
      "Name" = "igw-${each.key}-${data.aws_region.current.name}"
    }
  )
}

resource "aws_eip" "main" {
  for_each = var.nat_gateway

  domain = "vpc"
  tags = merge(
    var.tags,
    {
      "Name" = "eip-${each.key}-${data.aws_region.current.name}"
    }
  )
}

resource "aws_nat_gateway" "main" {
  depends_on = [aws_internet_gateway.main]
  for_each   = var.nat_gateway

  allocation_id = aws_eip.main[each.key].id
  subnet_id     = aws_subnet.main[each.value.subnet_name].id

  tags = merge(
    var.tags,
    {
      "Name" = "ngw-${each.key}-${data.aws_region.current.name}"
    }
  )
}

resource "aws_route_table" "main" {
  for_each = var.route_tables

  vpc_id = aws_vpc.main[each.value.vpc_name].id

  dynamic "route" {
    for_each = each.value.routes

    content {
      cidr_block     = route.value.cidr_block
      gateway_id     = route.value.use_igw ? aws_internet_gateway.main[route.value.igw_name].id : null
      nat_gateway_id = route.value.use_ngw ? aws_nat_gateway.main[route.value.ngw_name].id : null
      # network_interface_id      = route.value.use_ec2ni ? aws_network_interface.ec2ni[each.key].id : route.value.network_interface_id
      # vpc_peering_connection_id = route.value.use_vpcpc ? aws_vpc_peering_connection.vpcpc[each.key].id : route.value.vpc_peering_connection_id
      # vpc_endpoint_id           = route.value.use_vpce ? aws_vpc_endpoint.vpce[each.key].id : route.value.vpc_endpoint_id
    }
  }

  tags = merge(
    var.tags,
    {
      "Name" = "rt-${each.key}-${data.aws_region.current.name}"
    }
  )
}

resource "aws_route_table_association" "main" {
  for_each = var.route_table_associations

  subnet_id      = aws_subnet.main[each.value.subnet_name].id
  route_table_id = aws_route_table.main[each.value.route_table_name].id
}

resource "aws_security_group" "main" {
  for_each = var.security_groups

  description = "Security group for ${each.value.vpc_name} VPC"

  vpc_id = aws_vpc.main[each.value.vpc_name].id

  tags = merge(
    var.tags,
    {
      "Name" = "sg-${each.key}-${data.aws_region.current.name}"
    }
  )
}

resource "aws_vpc_security_group_ingress_rule" "main" {
  for_each = {
    for sg in flatten([
      for sg_name, sg_config in var.security_groups :
      [for rule_name, rule_config in sg_config.ingress :
        {
          sg_name     = sg_name
          rule_name   = rule_name
          rule_config = rule_config
      }]
    ]) : "${sg.sg_name}.${sg.rule_name}" => sg
  }

  security_group_id = aws_security_group.main[each.value.sg_name].id

  cidr_ipv4                    = try(each.value.rule_config.cidr_ipv4, null)
  from_port                    = each.value.rule_config.from_port
  to_port                      = each.value.rule_config.to_port
  ip_protocol                  = each.value.rule_config.protocol
  referenced_security_group_id = try(aws_security_group.main[each.value.rule_config.security_group_name].id, null)
}

resource "aws_vpc_security_group_egress_rule" "main" {
  for_each = {
    for sg in flatten([
      for sg_name, sg_config in var.security_groups :
      [for rule_name, rule_config in sg_config.egress :
        {
          sg_name     = sg_name
          rule_name   = rule_name
          rule_config = rule_config
      }]
    ]) : "${sg.sg_name}.${sg.rule_name}" => sg
  }

  security_group_id = aws_security_group.main[each.value.sg_name].id

  cidr_ipv4                    = try(each.value.rule_config.cidr_ipv4, null)
  from_port                    = each.value.rule_config.from_port
  to_port                      = each.value.rule_config.to_port
  ip_protocol                  = each.value.rule_config.protocol
  referenced_security_group_id = try(aws_security_group.main[each.value.rule_config.security_group_name].id, null)

}

resource "aws_default_security_group" "default" {
  for_each = var.vpc

  vpc_id = aws_vpc.main[each.key].id

  ingress {
    protocol  = -1
    self      = true
    from_port = 0
    to_port   = 0
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

// File: variables.tf
variable "region" {
  description = "AWS region"
  default     = "eu-west-1"
}

variable "vpc" {
  description = "VPC configuration"
  type = map(object({
    cidr_block           = string
    enable_dns           = optional(bool, true)
    enable_dns_hostnames = optional(bool, false)
  }))
  default = {}
}

variable "subnets" {
  description = "Subnet configuration"
  type = map(object({
    vpc_name          = string
    cidr_block        = string
    availability_zone = string
  }))
  default = {}
}

variable "internet_gateway" {
  description = "Internet gateway configuration"
  type = map(object({
    vpc_name = string
  }))
  default = {}
}

variable "nat_gateway" {
  description = "NAT gateway configuration"
  type = map(object({
    vpc_name    = string
    subnet_name = string
  }))
  default = {}
}

variable "route_tables" {
  description = "Route table configuration"
  type = map(object({
    vpc_name = string
    routes : list(object({
      cidr_block = string
      use_igw    = optional(bool, true)
      igw_name   = optional(string, "")
      use_ngw    = optional(bool, false)
      ngw_name   = optional(string, "")
      # use_ec2ni  = optional(bool, false)
      # use_vpcpc  = optional(bool, false)
      # use_vpce   = optional(bool, false)
    }))
  }))
  default = {}
}

variable "route_table_associations" {
  description = "Route table association configuration"
  type = map(object({
    subnet_name      = string
    route_table_name = string
  }))
  default = {}
}

variable "security_groups" {
  type = map(object({
    vpc_name = string
    ingress = map(object({
      from_port           = number
      to_port             = number
      protocol            = string
      cidr_ipv4           = optional(string)
      security_group_name = optional(string)
    }))
    egress = map(object({
      from_port           = number
      to_port             = number
      protocol            = string
      cidr_ipv4           = optional(string)
      security_group_name = optional(string)
    }))
  }))
  default = {}
}

variable "tags" {
  description = "Tags for resources"
  type        = map(string)
  default = {
    environment = "Dev"
    managedBy   = "Terraform"
  }
}

