// File: s3Bucket.tf
resource "aws_s3_bucket" "s3Bucket" {
  bucket              = var.bucket_name
  force_destroy       = var.force_destroy
  tags = {
      project = var.project
      app = var.app
      env = var.env
  }
}

resource "aws_s3_bucket_ownership_controls" "s3BucketOwnership" {
  bucket = aws_s3_bucket.s3Bucket.id
  rule {
    object_ownership = var.s3BucketOwnership
  }
}

resource "aws_s3_bucket_acl" "s3BucketAcl" {
  depends_on = [aws_s3_bucket_ownership_controls.s3BucketOwnership]

  bucket = aws_s3_bucket.s3Bucket.id
  acl    = var.s3BucketAcl
}

data "aws_caller_identity" "current" {}

locals {
    account_id = data.aws_caller_identity.current.account_id
}

resource "aws_s3_bucket_policy" "s3BucketPolicy" {
  bucket = aws_s3_bucket.s3Bucket.id

  policy = <<POLICY
{
  "Version": "2012-10-17",
  "Id": "Allow get and put objects",
  "Statement": [
    {
      "Sid": "Allow get and put objects",
      "Effect": "Allow",
      "Principal": {
        "AWS":[
          "${local.account_id}"
        ]
      },
      "Action": [
        "s3:GetObject",
        "s3:PutObject"
      ],
      "Resource": "${aws_s3_bucket.s3Bucket.arn}/*"
    }
  ]
}
POLICY
}

resource "aws_s3_bucket_accelerate_configuration" "s3BucketAccelerateConfig" {
  bucket = aws_s3_bucket.s3Bucket.id
  status = var.acceleration_status
}

resource "aws_s3_bucket_versioning" "s3BucketVersioning" {
  bucket = aws_s3_bucket.s3Bucket.id
  versioning_configuration {
    status = var.versioning
  }
}

resource "aws_kms_key" "mykmskey" {
  description             = "This key is used to encrypt bucket objects"
  deletion_window_in_days = var.deletion_window_in_days
}

resource "aws_s3_bucket_server_side_encryption_configuration" "s3_bucket_sse" {
  bucket = aws_s3_bucket.s3Bucket.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.mykmskey.arn
      sse_algorithm     = var.sse_algorithm
    }
  }
}

resource "aws_s3_bucket_website_configuration" "s3_bucket_website_config" {
  bucket = aws_s3_bucket.s3Bucket.id
  index_document {
    suffix = var.index_document_key
  }
  error_document {
    key = var.error_document_key
  }
  }

resource "aws_s3_bucket_public_access_block" "s3BucketAccess" {
  bucket = aws_s3_bucket.s3Bucket.id
  block_public_acls       = var.blockPublicACLs
  block_public_policy     = var.blockPublicPolicy
  ignore_public_acls      = var.ignorePublicACLs
  restrict_public_buckets = var.restrictPublicBuckets
}

// File: variables.tf
variable "project" {
  type = string
  description = "Project Name"
  default = "devops-poc"
}

variable "app" {
  type = string
  description = "Application Name"
  default = "app"
}

variable "env" {
  type = string
  description = "Environment Name"
  default = "dev"
  validation {
    condition = contains(["dev", "prod", "stag", "qa"], var.env)
    error_message = "Valid value is one of the following: dev, prod, stag, qa"
  }
}

variable "bucket_name" {
  type = string
  description = "Bucket Name"
  default = "devops-poc-app-dev-terraform-us-east-1"
}

variable "s3BucketAcl" {
  type = string
  description = "ACLs, Public or Private"
  default = "private"
  validation {
    condition = contains(["private", "public-read", "public-read-write", "aws-exec-read", "authenticated-read", "log-delivery-write"], var.s3BucketAcl)
    error_message = "Valid value is one of the following: dev, prod, stag, qa"
  }
}

variable "acceleration_status" {
  type = string
  description = "Acceleration status of s3 bucket"
  default = "Enabled"
  validation {
    condition = contains(["Enabled", "Suspended"], var.acceleration_status)
    error_message = "Valid value is one of the following: Enabled, Suspended"
  }
}

variable "versioning" {
  type = string
  description = "Versioning status of s3 bucket"
  default = "Enabled"
  validation {
    condition = contains(["Enabled", "Suspended", "Disabled"], var.versioning)
    error_message = "Valid value is one of the following: Enabled, Suspended, Disabled"
  }
}

variable "deletion_window_in_days" {
  type = number
  description = "After the specified waiting period, AWS KMS will delete the KMS key when the deletion window closes"
  default = "10"
}

variable "force_destroy" {
  type = string
  description = "Permanently remove objects upon bucket deletion"
  default = "true"
  validation {
    condition = contains(["true", "false"], var.force_destroy)
    error_message = "Valid value is one of the following: true, false"
  }
}

variable "sse_algorithm" {
  type = string
  description = "SSE Algorithm Name"
  default = "aws:kms"
}

variable "index_document_key" {
  type = string
  description = "Index key for static website hosting"
  default = "index.html"
}

variable "error_document_key" {
  type = string
  description = "Error key for static website hosting"
  default = "error.html"
}

variable "s3BucketOwnership" {
  type = string
  description = "Ownership of an S3 bucket"
  default = "BucketOwnerPreferred"
  validation {
    condition = contains(["BucketOwnerPreferred", "ObjectWriter", "BucketOwnerEnforced"], var.s3BucketOwnership)
    error_message = "Valid value is one of the following: BucketOwnerPreferred, ObjectWriter, BucketOwnerEnforced"
  }
}

variable "s3BucketPolicyName" {
  type = string
  description = "Name of S3 bucket policy"
  default = "devops-poc-dev-s3BucketPolicy-us-east-1"
}

variable "blockPublicACLs" {
  type = string
  description = "Select true to block public ACLs otherwise false"
  default = "true"
  validation {
    condition = contains(["true", "false"], var.blockPublicACLs)
    error_message = "Valid value is one of the following: true, false"
  }
}

variable "blockPublicPolicy" {
  type = string
  description = "Select true to block public policy otherwise false"
  default = "true"
  validation {
    condition = contains(["true", "false"], var.blockPublicPolicy)
    error_message = "Valid value is one of the following: true, false"
  }
}

variable "ignorePublicACLs" {
  type = string
  description = "Select true to ignore public ACLs otherwise false"
  default = "true"
  validation {
    condition = contains(["true", "false"], var.ignorePublicACLs)
    error_message = "Valid value is one of the following: true, false"
  }
} 

variable "restrictPublicBuckets" {
  type = string
  description = "Select true to restrict public buckets otherwise false"
  default = "true"
  validation {
    condition = contains(["true", "false"], var.restrictPublicBuckets)
    error_message = "Valid value is one of the following: true, false"
  }
}

// File: iam.tf
resource "aws_iam_role" "eks_cluster_role" {
  name = "EKSClusterRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = {
          Service = "eks.amazonaws.com"
        },
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "eks_cluster_policy" {
  name = "EKSClusterPolicy"

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Action = "eks:*",
        Effect = "Allow",
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy_attachment" "eks_cluster_attachment" {
  name       = "EKSClusterAttachment"
  roles      = [aws_iam_role.eks_cluster_role.name]
  policy_arn = aws_iam_policy.eks_cluster_policy.arn
}

data "aws_partition" "current" {}

resource "aws_iam_role" "node_instance_role" {
  name = "example-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Action = "sts:AssumeRole",
        Effect = "Allow",
        Principal = {
          Service = "ec2.amazonaws.com",
          AWS = "*",
        },
      },
    ],
  })

  tags = {
    Name = "ExampleRole",
  }
}

resource "aws_iam_policy_attachment" "eks_worker_node_policy" {
  name       = "eks-worker-node-policy-attachment"
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  roles      = [aws_iam_role.node_instance_role.name]
}

resource "aws_iam_policy_attachment" "eks_cni_policy" {
  name       = "eks-cni-policy-attachment"
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKS_CNI_Policy"
  roles      = [aws_iam_role.node_instance_role.name]
}

resource "aws_iam_policy_attachment" "ecr_readonly_policy" {
  name       = "ecr-readonly-policy-attachment"
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  roles      = [aws_iam_role.node_instance_role.name]
}

resource "aws_iam_policy" "node_instance_policy" {
  name = "NodeInstancePolicy"

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Action = "eks:DescribeCluster",
        Effect = "Allow",
        Resource = "*"
      },
      {
        Action = "ssm:GetParameter",
        Effect = "Allow",
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy_attachment" "node_instance_attachment" {
  name       = "NodeInstanceAttachment"
  roles      = [aws_iam_role.node_instance_role.name]
  policy_arn = aws_iam_policy.node_instance_policy.arn
}

// File: main.tf
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
  tags = {
    Name = "${var.environment_name}-VPC"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = var.environment_name
  }
}

resource "aws_subnet" "public_subnet1" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = element(var.availability_zones, 0)
  cidr_block              = var.subnet1_cidr
  map_public_ip_on_launch = true
  tags = {
    Name = "${var.environment_name}-public-subnet1"
  }
}

resource "aws_subnet" "public_subnet2" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = element(var.availability_zones, 1)
  cidr_block              = var.subnet2_cidr
  map_public_ip_on_launch = true
  tags = {
    Name = "${var.environment_name}-public-subnet2"
  }
}

resource "aws_eip" "nat_gateway1_eip" {
  domain = "vpc"
  tags   = {
    Name = "NatGateway1EIP"
  }
}

resource "aws_eip" "nat_gateway2_eip" {
  domain = "vpc"
  tags   = {
    Name = "NatGateway2EIP"
  }
}

resource "aws_nat_gateway" "nat_gateway1" {
  allocation_id = aws_eip.nat_gateway1_eip.id
  subnet_id     = aws_subnet.public_subnet1.id
}

resource "aws_nat_gateway" "nat_gateway2" {
  allocation_id = aws_eip.nat_gateway2_eip.id
  subnet_id     = aws_subnet.public_subnet2.id
}

resource "aws_route_table" "public_route_table" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "${var.environment_name}-public-route-table"
  }
}

resource "aws_route" "default_public_route" {
  route_table_id         = aws_route_table.public_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public_subnet1_association" {
  subnet_id      = aws_subnet.public_subnet1.id
  route_table_id = aws_route_table.public_route_table.id
}

resource "aws_route_table_association" "public_subnet2_association" {
  subnet_id      = aws_subnet.public_subnet2.id
  route_table_id = aws_route_table.public_route_table.id
}

// File: outputs.tf
output "stack_name" {
  description = "project and stack name"
  value       = aws_vpc.main.tags.Name
}

output "stack_vpc" {
  description = "A reference to the created VPC"
  value       = aws_vpc.main.id
}

output "stack_public_subnet_1" {
  description = "A reference to the created public subnet 1"
  value       = aws_subnet.public_subnet1.id
}

output "stack_public_subnet_2" {
  description = "A reference to the created public subnet 2"
  value       = aws_subnet.public_subnet2.id
}

output "stack_public_subnets" {
  description = "A list of the public subnets"
  value       = join(",", [aws_subnet.public_subnet1.id, aws_subnet.public_subnet2.id])
}

output "cluster_role_arn" {
  description = "The role that Amazon EKS will use to create AWS resources for Kubernetes clusters"
  value       = aws_iam_role.eks_cluster_role.arn
}

output "node_group_arn" {
  description = "The instance role that Amazon EKS will use to create AWS resources for Kubernetes clusters"
  value       = aws_iam_role.node_instance_role.arn
}

// File: variables.tf
variable "environment_name" {
  description = "An environment prefix for all resource names"
  type        = string
  default     = "capstone-project-terraform"
}

variable "vpc_cidr" {
  description = "IP range (CIDR notation) for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet1_cidr" {
  description = "IP range (CIDR notation) for public subnet 1"
  type        = string
  default     = "10.0.0.0/24"
}

variable "subnet2_cidr" {
  description = "IP range (CIDR notation) for public subnet 2"
  type        = string
  default     = "10.0.1.0/24"
}

variable "availability_zones" {
  description = "List of availability zones"
  type        = list(string)
  default     = [  "us-west-2a",  "us-west-2b",  "us-west-2c"]
}

// File: main.tf
locals {
  tags = {
    terraform = true
  }
}

resource "null_resource" "previous" {}

resource "time_sleep" "wait_60_seconds" {
  count      = var.create_syn_canary ? 1 : 0
  depends_on = [null_resource.previous]

  create_duration = "60s"
}

resource "aws_cloudwatch_dashboard" "cw_dashboard" {
  count          = var.create_dashboard ? 1 : 0
  dashboard_name = var.dashboard_name
  dashboard_body = var.dashboard_body

}

resource "aws_cloudwatch_composite_alarm" "composite_alarm" {
  count             = var.create_composite_alarm ? 1 : 0
  actions_enabled = var.com_actions_enabled
  alarm_description = var.com_alarm_description
  alarm_name        = "${var.com_alarm_name}-comp"
  alarm_actions = var.com_alarm_actions
  alarm_rule    = var.com_alarm_rule


  depends_on = [
    aws_cloudwatch_metric_alarm.default_dynamic,
    aws_cloudwatch_metric_alarm.defalut
  ]


}


#Module      : CLOUDWATCH METRIC ALARM
#Description : Terraform module creates Cloudwatch Alarm on AWS for monitoriing AWS services.
resource "aws_cloudwatch_metric_alarm" "defalut" {
  count = var.enabled_basic ? 1 : 0

  alarm_name                = var.alarm_name
  alarm_description         = var.alarm_description
  comparison_operator       = var.comparison_operator
  evaluation_periods        = var.evaluation_periods
  metric_name               = var.metric_name
  namespace                 = var.namespace
  period                    = var.period
  statistic                 = var.statistic
  threshold                 = var.threshold
  treat_missing_data        = var.treat_missing_data
  alarm_actions             = var.alarm_actions
  actions_enabled           = var.actions_enabled
  insufficient_data_actions = var.insufficient_data_actions
  ok_actions                = var.ok_actions
  dimensions                = var.dimensions
  tags                      = merge(local.tags )

}
resource "aws_cloudwatch_metric_alarm" "default_dynamic" {  
  for_each = var.enabled_dynamic ? var.alarm_list : {}


  alarm_name                = each.value.alarm_name
  alarm_description         = each.value.alarm_description
  comparison_operator       = each.value.comparison_operator
  evaluation_periods        = each.value.evaluation_periods
  metric_name               = each.value.metric_name
  namespace                 = each.value.namespace
  period                    = each.value.period
  statistic                 = each.value.statistic
  threshold                 = each.value.threshold
  treat_missing_data        = each.value.treat_missing_data
  alarm_actions             = length(each.value.alarm_actions) == 0 ? [] : each.value.alarm_actions
  actions_enabled           = each.value.actions_enabled
  insufficient_data_actions = each.value.insufficient_data_actions
  ok_actions                = each.value.ok_actions
  dimensions                = each.value.dimensions
  tags                      = merge(local.tags )

}

resource "aws_cloudwatch_metric_alarm" "expression" {
  count = var.create_metric_alarm_expression ? 1 : 0

  alarm_name                = var.alarm_name
  alarm_description         = var.alarm_description
  comparison_operator       = var.comparison_operator
  evaluation_periods        = var.evaluation_periods
  threshold                 = var.threshold
  treat_missing_data        = var.treat_missing_data
  alarm_actions             = var.alarm_actions
  actions_enabled           = var.actions_enabled
  insufficient_data_actions = var.insufficient_data_actions
  ok_actions                = var.ok_actions
  tags                      = merge(local.tags )
  dynamic "metric_query" {
    for_each = var.query_expressions
    content {
      id          = metric_query.value["id"]
      expression  = metric_query.value["expression"]
      label       = metric_query.value["label"]
      return_data = metric_query.value["return_data"]
    }
  }

  dynamic "metric_query" {
    for_each = var.query_metrics
    content {
      id          = metric_query.value["id"]
      return_data = metric_query.value["return_data"]
      metric {
       metric_name = metric_query.value["metric_name"]
       namespace   = metric_query.value["namespace"]
       period      = metric_query.value["period"]
       stat        = metric_query.value["stat"]
       unit        = metric_query.value["unit"]
       dimensions  = metric_query.value["dimensions"]
      }
    }
  }
  threshold_metric_id = var.threshold_metric_id

}


resource "aws_synthetics_canary" "canary_watch_service" {
  count                = var.create_syn_canary ? 1 : 0
  name                 = var.syn_canary_name
  artifact_s3_location = "s3://${var.syn_s3_canary_bucket_name}/canary/${var.syn_canary_name}"
  execution_role_arn   = var.syn_role_arn
  handler              = var.syn_handler
  s3_bucket            = var.syn_s3_canary_file_bucket_name
  s3_key               = var.syn_s3_key_file
  s3_version           = var.syn_s3_version
  start_canary         = var.syn_start_canary
  #zip_file             = "${var.zip_file}"
  runtime_version      = var.syn_runtime_version
  delete_lambda        = var.syn_delete_lambda

  success_retention_period = var.syn_success_retention_period

  run_config {
    active_tracing     = var.syn_rc_active_tracing
    timeout_in_seconds = var.syn_rc_timeout_in_seconds
    memory_in_mb = var.syn_rc_memory_in_mb
    environment_variables = var.syn_rc_environment_variables

  }


  schedule {
    expression = "rate(${var.syn_sch_expression} ${var.syn_sch_expression == 1 ? "minute" : "minutes"})"
    duration_in_seconds = var.syn_sch_duration_in_seconds

  }

  depends_on = [time_sleep.wait_60_seconds]
}

resource "aws_cloudwatch_log_group" "log_group" {
  count             = var.create_log_group ? 1 : 0
  name              = var.log_group_name
  retention_in_days = var.retention_days
}


resource "aws_cloudwatch_log_stream" "log_stream" {
  count          = var.create_log_group ? 1 : 0
  name           = var.log_stream_name
  log_group_name = aws_cloudwatch_log_group.log_group[count.index].name

  depends_on = [
    aws_cloudwatch_log_group.log_group
  ]

}

// File: outputs.tf
output "cloudwatch_metric_alarm_arn" {
  description = "The ARN of the Cloudwatch metric alarm."
  value       = try(aws_cloudwatch_metric_alarm.default_dynamic[0].arn, "")
}

output "cloudwatch_metric_alarm_id" {
  description = "The ID of the Cloudwatch metric alarm."
  value       = try(aws_cloudwatch_metric_alarm.default_dynamic[0].id, "")
}

output "log_group_arn" {
  description = "The Amazon Resource Name (ARN) specifying the log group."
  #value       = aws_cloudwatch_log_group.log_group.*.arn
  value = element(concat(aws_cloudwatch_log_group.log_group.*.arn, [""]), 0)
}

output "log_group_name" {
  description = "The name of the log group."
  #value       = aws_cloudwatch_log_group.log_group.*.name
  value = element(concat(aws_cloudwatch_log_group.log_group.*.name, [""]), 0)
}

// File: variables.tf
#Module      : CLOUDWATCH METRIC ALARM
#Description : Provides a CloudWatch Metric Alarm resource.

variable "enabled_basic" {
  type        = bool
  default     = false
  description = "Create a specific alarm, if true."
}

variable "alarm_name" {
  type        = string
  default     = ""
  description = "The descriptive name for the alarm."
}

variable "alarm_description" {
  type        = string
  default     = ""
  description = "The description for the alarm."
}

variable "comparison_operator" {
  type        = string
  description = "The arithmetic operation to use when comparing the specified Statistic and Threshold."
  default     = "GreaterThanOrEqualToThreshold"
  sensitive   = true
}

variable "evaluation_periods" {
  type        = number
  default    = "60"
  description = "The number of periods over which data is compared to the specified threshold."
}

variable "metric_name" {
  type        = string
  default     = "CPUUtilization"
  description = "The name for the alarm's associated metric."
}

variable "namespace" {
  type        = string
  default     = "AWS/EC2"
  description = "The namespace for the alarm's associated metric."
  sensitive   = true
}

variable "period" {
  type        = number
  default     = 120
  description = "The period in seconds over which the specified statistic is applied."
}

variable "statistic" {
  type        = string
  default     = "Average"
  description = "The statistic to apply to the alarm's associated metric."
}

variable "threshold" {
  type        = number
  default     = 40
  description = "The value against which the specified statistic is compared."
}
variable "treat_missing_data" {
  type        = string
  default     = "missing"
  description = " (Optional) Sets how this alarm is to handle missing data points. The following values are supported: missing, ignore, breaching and notBreaching. Defaults to missing."
}

variable "alarm_actions" {
  type        = list(any)
  default     = []
  description = "The list of actions to execute when this alarm transitions into an ALARM state from any other state."
}

variable "actions_enabled" {
  type        = bool
  default     = true
  description = "Indicates whether or not actions should be executed during any changes to the alarm's state."
}

variable "insufficient_data_actions" {
  type        = list(any)
  default     = []
  description = "The list of actions to execute when this alarm transitions into an INSUFFICIENT_DATA state from any other state."
}

variable "ok_actions" {
  type        = list(any)
  default     = []
  description = "The list of actions to execute when this alarm transitions into an OK state from any other state."
}

variable "instance_id" {
  type        = string
  default     = ""
  description = "The instance ID."
  sensitive   = true
}

variable "dimensions" {
  default     = {}
  description = "Dimensions for metrics."
}


# It will allow the creation of several alarms
variable "enabled_dynamic" {
  type        = bool
  default     = false
  description = "Creates a list of alarms, if true, consider the alarm_list variable."
}

variable "alarm_list" {
  type        = any
  default     = null
  description = <<-EOT
    type = map(object({
        alarm-cpu = {
        alarm_name      = "alarm_cpu"
        alarm_description = "This metric monitors ec2 cpu utilization exceeding 70%"
        comparison_operator = "GreaterThanOrEqualToThreshold"
        evaluation_periods  = "2"
        metric_name = "CPUUtilization"
        namespace = "AWS/EC2"
        period    = "60"
        statistic = "Average"
        # CPU Utilization threshold is set to 10 percent
        threshold         = "70"
        alarm_actions = null
        actions_enabled = null
        insufficient_data_actions = null
        ok_actions = null
        dimensions = {
            InstanceId = "i-082cb76ca0e5b43a7"   OR
            AutoScalingGroupName = "casper-aws-autoscaling"
        }
    }
    }))
    Required configuration for attach rule to Sg
    EOT
}

# A composite alarm

variable "create_composite_alarm" {
  type        = bool
  default     = false
  description = "Create alarm composite."
}
variable "com_actions_enabled" {
  type        = bool
  default     = true
  description = "(Optional, Forces new resource) Indicates whether actions should be executed during any changes to the alarm state of the composite alarm. Defaults to true."
}

variable "com_alarm_description" {
  description = "(Optional) The description for the composite alarm."
  default     = null
  type        = string
}

variable "com_alarm_name" {
  type        = string
  default     = null
  description = "(Required) The name for the composite alarm. This name must be unique within the region."
}

variable "com_alarm_actions" {
  type        = list(any)
  default     = []
  description = "(Optional) The set of actions to execute when this alarm transitions to the ALARM state from any other state. Each action is specified as an ARN. Up to 5 actions are allowed."
}
variable "com_alarm_rule" {
  type        = string
  default     = ""
  description = "(Required) An expression that specifies which other alarms are to be evaluated to determine this composite alarm's state. For syntax, see Creating a Composite Alarm. The maximum length is 10240 characters."
}

# CW dashboard

variable "create_dashboard" {
  type        = bool
  default     = false
  description = "if true, enable create cloudwatch dashboard"
}

variable "dashboard_name" {
  description = "(Required) The name of the dashboard."
  default     = null
  type        = string
}

variable "dashboard_body" {
  type        = string
  default     = null
  description = "(Required) The detailed information about the dashboard, including what widgets are included and their location on the dashboard. You can read more about the body structure in the documentation."
}

