    label       = "CPUUtilization (Expected)"
    return_data = "true"
  }]
  description = "values for metric query expression."
}

variable "query_metrics" {
  type = any
  default = [{
    id          = "m1"
    return_data = "true"
    metric_name = "CPUUtilization"
    namespace   = "AWS/EC2"
    period      = "120"
    stat        = "Average"
    unit        = "Count"
    dimensions = {
      InstanceId = "i-abc123"
    }
  }]
