// File: outputs.tf
output "codedeploy_app_name" {
  description = "Name of CodeDeploy application"
  value       = local.app_name
}

output "codedeploy_deployment_group_name" {
  description = "CodeDeploy deployment group name"
  value       = local.deployment_group_name
}

output "codedeploy_deployment_group_id" {
  description = "CodeDeploy deployment group id"
  value       = try(aws_codedeploy_deployment_group.this[0].id, "")
}

output "codedeploy_iam_role_name" {
  description = "Name of IAM role used by CodeDeploy"
  value       = try(aws_iam_role.codedeploy[0].name, "")
}

output "appspec" {
  description = "Appspec data as HCL"
  value       = local.appspec
}

output "appspec_content" {
  description = "Appspec data as valid JSON"
  value       = local.appspec_content
}

output "appspec_sha256" {
  description = "SHA256 of Appspec JSON"
  value       = local.appspec_sha256
}

output "script" {
  description = "Deployment script"
  value       = local.script
}

output "deploy_script" {
  description = "Path to a deployment script"
  value       = try(local_file.deploy_script[0].filename, "")
}

// File: variables.tf
variable "create" {
  description = "Controls whether resources should be created"
  type        = bool
  default     = true
}

variable "tags" {
  description = "A map of tags to assign to resources."
  type        = map(string)
  default     = {}
}

variable "alias_name" {
  description = "Name for the alias"
  type        = string
  default     = ""
}

variable "function_name" {
  description = "The name of the Lambda function to deploy"
  type        = string
  default     = ""
}

variable "current_version" {
  description = "Current version of Lambda function version to deploy (can't be $LATEST)"
  type        = string
  default     = ""
}

variable "target_version" {
  description = "Target version of Lambda function version to deploy"
  type        = string
  default     = ""
}

variable "before_allow_traffic_hook_arn" {
  description = "ARN of Lambda function to execute before allow traffic during deployment. This function should be named CodeDeployHook_, to match the managed AWSCodeDeployForLambda policy, unless you're using a custom role"
  type        = string
  default     = ""
}

variable "after_allow_traffic_hook_arn" {
  description = "ARN of Lambda function to execute after allow traffic during deployment. This function should be named CodeDeployHook_, to match the managed AWSCodeDeployForLambda policy, unless you're using a custom role"
  type        = string
  default     = ""
}

variable "interpreter" {
  description = "List of interpreter arguments used to execute deploy script, first arg is path"
  type        = list(string)
  default     = ["/bin/bash", "-c"]
}

variable "description" {
  description = "Description to use for the deployment"
  type        = string
  default     = ""
}

#########################
# CodeDeploy Application
#########################

variable "create_app" {
  description = "Whether to create new AWS CodeDeploy app"
  type        = bool
  default     = false
}

variable "use_existing_app" {
  description = "Whether to use existing AWS CodeDeploy app"
  type        = bool
  default     = false
}

variable "app_name" {
  description = "Name of AWS CodeDeploy application"
  type        = string
  default     = ""
}

##############################
# CodeDeploy Deployment Group
##############################

variable "create_deployment_group" {
  description = "Whether to create new AWS CodeDeploy Deployment Group"
  type        = bool
  default     = false
}

variable "use_existing_deployment_group" {
  description = "Whether to use existing AWS CodeDeploy Deployment Group"
  type        = bool
  default     = false
}

variable "deployment_group_name" {
  description = "Name of deployment group to use"
  type        = string
  default     = ""
}

variable "deployment_config_name" {
  description = "Name of deployment config to use"
  type        = string
  default     = "CodeDeployDefault.LambdaAllAtOnce"
}

variable "auto_rollback_enabled" {
  description = "Indicates whether a defined automatic rollback configuration is currently enabled for this Deployment Group."
  type        = bool
  default     = true
}

variable "auto_rollback_events" {
  description = "List of event types that trigger a rollback. Supported types are DEPLOYMENT_FAILURE and DEPLOYMENT_STOP_ON_ALARM."
  type        = list(string)
  default     = ["DEPLOYMENT_STOP_ON_ALARM"]
}

variable "alarm_enabled" {
  description = "Indicates whether the alarm configuration is enabled. This option is useful when you want to temporarily deactivate alarm monitoring for a deployment group without having to add the same alarms again later."
  type        = bool
  default     = false
}

variable "alarms" {
  description = "A list of alarms configured for the deployment group. A maximum of 10 alarms can be added to a deployment group."
  type        = list(string)
  default     = []
}

variable "alarm_ignore_poll_alarm_failure" {
  description = "Indicates whether a deployment should continue if information about the current state of alarms cannot be retrieved from CloudWatch."
  type        = bool
  default     = false
}

variable "triggers" {
  description = "Map of triggers which will be notified when event happens. Valid options for event types are DeploymentStart, DeploymentSuccess, DeploymentFailure, DeploymentStop, DeploymentRollback, DeploymentReady (Applies only to replacement instances in a blue/green deployment), InstanceStart, InstanceSuccess, InstanceFailure, InstanceReady. Note that not all are applicable for Lambda deployments."
  type        = map(any)
  default     = {}
}

########################
# CodeDeploy Deployment
########################

variable "aws_cli_command" {
  description = "Command to run as AWS CLI. May include extra arguments like region and profile."
  type        = string
  default     = "aws"
}

variable "save_deploy_script" {
  description = "Save deploy script locally"
  type        = bool
  default     = false
}

variable "create_deployment" {
  description = "Create the AWS resources and script for CodeDeploy"
  type        = bool
  default     = false
}

variable "run_deployment" {
  description = "Run AWS CLI command to start the deployment"
  type        = bool
  default     = false
}

variable "force_deploy" {
  description = "Force deployment every time (even when nothing changes)"
  type        = bool
  default     = false
}

variable "wait_deployment_completion" {
  description = "Wait until deployment completes. It can take a lot of time and your terraform process may lock execution for long time."
  type        = bool
  default     = false
}

######################
# CodeDeploy IAM role
######################

variable "create_codedeploy_role" {
  description = "Whether to create new AWS CodeDeploy IAM role"
  type        = bool
  default     = true
}

variable "codedeploy_role_name" {
  description = "IAM role name to create or use by CodeDeploy"
  type        = string
  default     = ""
}

variable "codedeploy_principals" {
  description = "List of CodeDeploy service principals to allow. The list can include global or regional endpoints."
  type        = list(string)
  default     = ["codedeploy.amazonaws.com"]
}

variable "attach_hooks_policy" {
  description = "Whether to attach Invoke policy to CodeDeploy role when before allow traffic or after allow traffic hooks are defined."
  type        = bool
  default     = true
}

variable "attach_triggers_policy" {
  description = "Whether to attach SNS policy to CodeDeploy role when triggers are defined"
  type        = bool
  default     = false
}

variable "get_deployment_sleep_timer" {
  description = "Adds additional sleep time to get-deployment command to avoid the service throttling"
  type        = number
  default     = 5
}

// File: versions.tf
terraform {
  required_version = ">= 0.13.1"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 3.35"
    }
    local = {
      source  = "hashicorp/local"
      version = ">= 1.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 2.0"
    }
  }
}

// File: alarm.tf
locals {
  filter_metrics_type = {
    "security_group_change" = {
      metric_description         = "Secuity group update alert",
      pattern                    = "{($.eventName=AuthorizeSecurityGroupIngress)||($.eventName=AuthorizeSecurityGroupEgress)||($.eventName=RevokeSecurityGroupIngress)||($.eventName=RevokeSecurityGroupEgress)||($.eventName=CreateSecurityGroup)||($.eventName=DeleteSecurityGroup)}",
      metric_transformation_name = "SecurityGroupEventCount"
    },
    "user_creation_or_deletion" = {
      metric_description         = "User creation or deletion alert",
      pattern                    = "{($.eventName=CreateUser)||($.eventName=DeleteUser)}",
      metric_transformation_name = "UserCreationOrDeletionEvent"
    },
    "console_login_failed" = {
      metric_description         = "Console login failed alert",
      pattern                    = "{($.eventName=ConsoleLogin)&&($.errorMessage=\"Failed authentication\")}",
      metric_transformation_name = "ConsoleLoginFailedEvent"
    },
    "iam_group_policy_change" = {
      metric_description         = "IAM Group policy update alert",
      pattern                    = "{ ($.eventName=DeleteGroupPolicy)||($.eventName=PutGroupPolicy)||($.eventName=AttachGroupPolicy)||($.eventName=DetachGroupPolicy) }",
      metric_transformation_name = "IAMGroupPolicyChange"
    },
    "iam_role_policy_change" = {
      metric_description         = "IAM Role policy update alert",
      pattern                    = "{($.eventName=DeleteRolePolicy)||($.eventName=PutRolePolicy)||($.eventName=AttachRolePolicy)||($.eventName=DetachRolePolicy)}",
      metric_transformation_name = "IAMRolePolicyChange"
    },
    "iam_user_policy_change" = {
      metric_description         = "IAM User policy update alert",
      pattern                    = "{($.eventName=DeleteUserPolicy)||($.eventName=PutUserPolicy)||($.eventName=AttachUserPolicy)||($.eventName=DetachUserPolicy)}",
      metric_transformation_name = "IAMUserPolicyChange"
    },
    "iam_policy_change" = {
      metric_description         = "IAM policy update alert",
      pattern                    = "{($.eventName=CreatePolicy)||($.eventName=DeletePolicy)||($.eventName=CreatePolicyVersion)||($.eventName=DeletePolicyVersion)}",
      metric_transformation_name = "IAMPolicyChange"
    },
    "iam_user_added_to_group" = {
      metric_description         = "IAM user is added to a group alert",
      pattern                    = "{($.eventName=AddUserToGroup)}",
      metric_transformation_name = "IAMUserAddedToGroup"
    },
    "role_creation_or_deletion" = {
      metric_description         = "IAM role creation or deletion alert",
      pattern                    = "{($.eventName=CreateRole)||($.eventName=DeleteRole)}",
      metric_transformation_name = "IAMRoleCreationOrDeletionEvent"
    }

  }
}

resource "aws_cloudwatch_log_metric_filter" "management_activities_filter" {
  for_each       = local.filter_metrics_type
  name           = each.key
  pattern        = each.value.pattern
  log_group_name = aws_cloudwatch_log_group.cloudtrail_event_logs.name

  metric_transformation {
    name      = each.value.metric_transformation_name
    namespace = var.metric_namespace
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "management_activities_alarm" {
  for_each            = local.filter_metrics_type
  depends_on          = [aws_sns_topic.sg_sns_topic]
  alarm_name          = "${each.key}_alarm"
  metric_name         = each.value.metric_transformation_name
  threshold           = "1"
  statistic           = "Average"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  datapoints_to_alarm = "1"
  evaluation_periods  = "1"
  period              = "60"
  namespace           = var.metric_namespace
  alarm_actions       = [aws_sns_topic.sg_sns_topic.arn]
  alarm_description   = each.value.metric_description
}

// File: main.tf
resource "aws_iam_role" "cloudtrail_cloudwatch_role" {
  name = var.cloudtrail_role_name

  assume_role_policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "Service": "cloudtrail.amazonaws.com"
      },
      "Action": "sts:AssumeRole"
    }
  ]
}
EOF
}

resource "aws_iam_role_policy" "cloudtrail_role_policy" {
  name = var.cloudtrail_role_policy_name
  role = aws_iam_role.cloudtrail_cloudwatch_role.id

  # "arn:aws:logs:us-east-1:000000000000:log-group:${aws_cloudwatch_log_group.cloudtrail_event_logs.id}:*"
  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "AWSCloudTrailCreateLogStream2014110",
      "Effect": "Allow",
      "Action": [
        "logs:CreateLogStream"
      ],
      "Resource": [
        "${aws_cloudwatch_log_group.cloudtrail_event_logs.arn}:*"
      ]
    },
    {
      "Sid": "AWSCloudTrailPutLogEvents20141101",
      "Effect": "Allow",
      "Action": [
        "logs:PutLogEvents"
      ],
      "Resource": [
        "${aws_cloudwatch_log_group.cloudtrail_event_logs.arn}:*"
      ]
    }
  ]
}
EOF
}

resource "aws_cloudwatch_log_group" "cloudtrail_event_logs" {
  name = var.log_group_name
}

resource "aws_cloudtrail" "event_logs" {
  depends_on                    = [aws_s3_bucket_policy.cloudtrail_access_s3]
  name                          = var.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail_event_logs.id
  s3_key_prefix                 = ""
  include_global_service_events = true # Default is true
  is_multi_region_trail         = true # Default is false
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.cloudtrail_event_logs.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cloudwatch_role.arn

  # Exclude KMS and RDS event logs.
  event_selector {
    read_write_type                  = "All"
    include_management_events        = true
    exclude_management_event_sources = ["kms.amazonaws.com", "rdsdata.amazonaws.com"]
  }
}

resource "aws_s3_bucket" "cloudtrail_event_logs" {
  bucket        = var.trail_bucket_name
  force_destroy = true
}

data "aws_caller_identity" "current" {}

# Attach S3 bucket policy
resource "aws_s3_bucket_policy" "cloudtrail_access_s3" {
  bucket     = aws_s3_bucket.cloudtrail_event_logs.id
  depends_on = [aws_s3_bucket.cloudtrail_event_logs]
  policy     = <<POLICY
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "AWSCloudTrailAclCheck",
      "Effect": "Allow",
      "Principal": { "Service": "cloudtrail.amazonaws.com" },
      "Action": "s3:GetBucketAcl",
      "Resource": "${aws_s3_bucket.cloudtrail_event_logs.arn}"
    },
    {
      "Sid": "AWSCloudTrailWrite",
      "Effect": "Allow",
      "Principal": { "Service": "cloudtrail.amazonaws.com" },
      "Action": "s3:PutObject",
      "Resource": "${aws_s3_bucket.cloudtrail_event_logs.arn}/AWSLogs/${data.aws_caller_identity.current.account_id}/*",
      "Condition": {
        "StringEquals": {
          "s3:x-amz-acl": "bucket-owner-full-control"
        }
      }
    }
  ]
}
POLICY
}

// File: providers.tf
provider "aws" {
  region = var.awsRegion
}

