#############################
# PASSWORD POLICY BEGINNING
#############################

resource "aws_iam_account_password_policy" "password_policy" {
  allow_users_to_change_password = var.allow_users_to_change_password
  hard_expiry                    = var.hard_expiry
  max_password_age               = var.max_password_age
  minimum_password_length        = var.minimum_password_length
  password_reuse_prevention      = var.password_reuse_prevention
  require_lowercase_characters   = var.require_lowercase_characters
  require_numbers                = var.require_numbers
  require_uppercase_characters   = var.require_uppercase_characters
  require_symbols                = var.require_symbols
}

#############################
# PASSWORD POLICY END
#############################

variable "allow_users_to_change_password" {
  type        = bool
  default     = true
  description = "Whether to allow users to change their own password"
}

variable "hard_expiry" {
  type        = string
  default     = false
  description = "Whether users are prevented from setting a new password after their password"
}

variable "max_password_age" {
  type        = number
  default     = 90
  description = "The number of days that an user password is valid."
}

variable "minimum_password_length" {
  type        = number
  default     = 14
  description = "Minimum length to require for user passwords."
}

variable "password_reuse_prevention" {
  type        = number
  default     = 24
  description = "The number of previous passwords that users are prevented from reusing."
}

variable "require_lowercase_characters" {
  type        = bool
  default     = true
  description = "Whether to require lowercase characters for user passwords."
}

variable "require_numbers" {
  type        = bool
  default     = true
  description = "Whether to require numbers for user passwords."
}

variable "require_symbols" {
  type        = bool
  default     = true
  description = "Whether to require symbols for user passwords."
}

variable "require_uppercase_characters" {
  type        = bool
  default     = true
  description = "Whether to require uppercase characters for user passwords."
}

variable "tags" {
  description = "A mapping of tags to iam resources."
  default     = { Automation = "Terraform" }
  type        = map(string)
}

// File: lambda_alias.tf
#---------------------------------------------------
# AWS lambda alias
#---------------------------------------------------
resource "aws_lambda_alias" "lambda_alias" {
  count = var.enable_lambda_alias ? 1 : 0

  name             = var.lambda_alias_name != "" ? var.lambda_alias_name : "${lower(var.name)}-lambda-alias-${lower(var.environment)}"
  description      = var.lambda_alias_description
  function_name    = var.lambda_alias_function_name != "" && !var.enable_lambda_function ? var.lambda_alias_function_name : element(concat(aws_lambda_function.lambda_function.*.arn, [""]), 0)
  function_version = var.lambda_alias_function_version

  dynamic "routing_config" {
    iterator = routing_config
    for_each = [var.lambda_alias_routing_config]

    content {
      additional_version_weights = lookup(routing_config.value, "additional_version_weights", {})
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = [routing_config]
  }

  depends_on = [
    aws_lambda_function.lambda_function
  ]
}

// File: lambda_code_signing_config.tf
#---------------------------------------------------
# AWS lambda code signing config
#---------------------------------------------------
resource "aws_lambda_code_signing_config" "lambda_code_signing_config" {
  count = var.enable_code_signing_config ? 1 : 0

  description = var.lambda_code_signing_config_description

  dynamic "allowed_publishers" {
    iterator = allowed_publishers
    for_each = var.lambda_code_signing_config_allowed_publishers

    content {
      signing_profile_version_arns = lookup(allowed_publishers.value, "signing_profile_version_arns", null)
    }
  }

  dynamic "policies" {
    iterator = policies
    for_each = var.lambda_code_signing_config_policies

    content {
      untrusted_artifact_on_deployment = lookup(policies.value, "untrusted_artifact_on_deployment", null)
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: lambda_event_source_mapping.tf
#---------------------------------------------------
# AWS lambda event source mapping
#---------------------------------------------------
resource "aws_lambda_event_source_mapping" "lambda_event_source_mapping" {
  count = var.enable_lambda_event_source_mapping ? 1 : 0

  event_source_arn = var.lambda_event_source_mapping_event_source_arn
  function_name    = var.lambda_event_source_mapping_function_name != "" && !var.enable_lambda_function ? var.lambda_event_source_mapping_function_name : element(concat(aws_lambda_function.lambda_function.*.arn, [""]), 0)

  starting_position = var.lambda_event_source_mapping_starting_position

  batch_size                         = var.lambda_event_source_mapping_batch_size
  maximum_batching_window_in_seconds = var.lambda_event_source_mapping_maximum_batching_window_in_seconds
  enabled                            = var.lambda_event_source_mapping_enabled
  starting_position_timestamp        = var.lambda_event_source_mapping_starting_position_timestamp
  parallelization_factor             = var.lambda_event_source_mapping_parallelization_factor
  maximum_retry_attempts             = var.lambda_event_source_mapping_maximum_retry_attempts
  maximum_record_age_in_seconds      = var.lambda_event_source_mapping_maximum_record_age_in_seconds
  bisect_batch_on_function_error     = var.lambda_event_source_mapping_bisect_batch_on_function_error

  dynamic "destination_config" {
    iterator = destination_config
    for_each = var.lambda_event_source_mapping_destination_config

    content {
      dynamic "on_failure" {
        iterator = on_failure
        for_each = length(keys(lookup(destination_config.value, "on_failure", {}))) > 0 ? [lookup(destination_config.value, "on_failure", {})] : []

        content {
          destination_arn = lookup(on_failure.value, "destination_arn", null)
        }
      }
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_lambda_function.lambda_function
  ]
}

// File: lambda_function.tf
#---------------------------------------------------
# AWS Lambda function
#---------------------------------------------------
resource "aws_lambda_function" "lambda_function" {
  count = var.enable_lambda_function ? 1 : 0

  function_name = var.lambda_function_name != "" ? var.lambda_function_name : "${lower(var.name)}-lambda-fun-${lower(var.environment)}"
  handler       = var.lambda_function_handler
  role          = var.lambda_function_role
  runtime       = var.lambda_function_runtime

  filename                       = var.lambda_function_filename
  s3_bucket                      = var.lambda_function_s3_bucket
  s3_key                         = var.lambda_function_s3_key
  s3_object_version              = var.lambda_function_s3_object_version
  description                    = var.lambda_function_description
  layers                         = var.lambda_function_layers
  memory_size                    = var.lambda_function_memory_size
  timeout                        = var.lambda_function_timeout
  reserved_concurrent_executions = var.lambda_function_reserved_concurrent_executions
  publish                        = var.lambda_function_publish
  kms_key_arn                    = var.lambda_function_kms_key_arn
  source_code_hash               = var.lambda_function_source_code_hash

  dynamic "dead_letter_config" {
    iterator = dead_letter_config
    for_each = var.lambda_function_dead_letter_config

    content {
      target_arn = lookup(dead_letter_config.value, "target_arn", null)
    }
  }

  dynamic "tracing_config" {
    iterator = tracing_config
    for_each = var.lambda_function_tracing_config

    content {
      mode = lookup(tracing_config.value, "mode", null)
    }
  }

  dynamic "vpc_config" {
    iterator = vpc_config
    for_each = var.lambda_function_vpc_config

    content {
      subnet_ids         = lookup(vpc_config.value, "subnet_ids", null)
      security_group_ids = lookup(vpc_config.value, "security_group_ids", null)
    }
  }

  dynamic "environment" {
    for_each = var.lambda_function_environment == null ? [] : [var.lambda_function_environment]

    content {
      variables = var.lambda_function_environment
    }
  }

  dynamic "timeouts" {
    iterator = timeouts
    for_each = length(keys(var.lambda_function_timeouts)) > 0 ? [var.lambda_function_timeouts] : []

    content {
      create = lookup(timeouts.value, "create", null)
    }
  }

  tags = merge(
    {
      Name = var.lambda_function_name != "" ? var.lambda_function_name : "${lower(var.name)}-lambda-fun-${lower(var.environment)}"
    },
    var.tags
  )

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = []
}

// File: lambda_function_event_invoke_config.tf
#---------------------------------------------------
# AWS lambda function event invoke config
#---------------------------------------------------
resource "aws_lambda_function_event_invoke_config" "lambda_function_event_invoke_config" {
  count = var.enable_lambda_function_event_invoke_config ? 1 : 0

  function_name = var.lambda_function_event_invoke_config_function_name != "" && !var.enable_lambda_function && !var.enable_lambda_alias ? var.lambda_function_event_invoke_config_function_name : (var.enable_lambda_function && !var.enable_lambda_alias ? element(concat(aws_lambda_function.lambda_function.*.function_name, [""]), 0) : element(concat(aws_lambda_alias.lambda_alias.*.function_name, [""]), 0))

  qualifier                    = var.lambda_function_event_invoke_config_qualifier != "" && !var.enable_lambda_function && !var.enable_lambda_alias ? var.lambda_function_event_invoke_config_qualifier : (var.enable_lambda_function && !var.enable_lambda_alias ? element(concat(aws_lambda_function.lambda_function.*.version, [""]), 0) : element(concat(aws_lambda_alias.lambda_alias.*.name, [""]), 0))
  maximum_event_age_in_seconds = var.lambda_function_event_invoke_config_maximum_event_age_in_seconds
  maximum_retry_attempts       = var.lambda_function_event_invoke_config_maximum_retry_attempts

  dynamic "destination_config" {
    iterator = destination_config
    for_each = var.lambda_function_event_invoke_config_destination_config

    content {
      dynamic "on_success" {
        iterator = on_success
        for_each = length(keys(lookup(destination_config.value, "on_success", {}))) > 0 ? [lookup(destination_config.value, "on_success", {})] : []

        content {
          destination = lookup(on_success.value, "destination", null)
        }
      }

      dynamic "on_failure" {
        iterator = on_failure
        for_each = length(keys(lookup(destination_config.value, "on_failure", {}))) > 0 ? [lookup(destination_config.value, "on_failure", {})] : []

        content {
          destination = lookup(on_failure.value, "destination", null)
        }
      }
    }
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = []
  }

  depends_on = [
    aws_lambda_function.lambda_function,
    aws_lambda_alias.lambda_alias
  ]
}

