    public  = aws_subnet.subnet-az1-public.cidr_block
    private = aws_subnet.subnet-az1-private.cidr_block
    bastion = aws_subnet.subnet-az1-bastion.cidr_block
  }
}


output "subnet_az1_ids" {
  value = {
