// File: outputs.tf
output "prefix_list_id" {
  value       = var.prefix_list_enabled && length(var.prefix_list_ids) < 1 ? aws_ec2_managed_prefix_list.prefix_list[0].id : null
  description = "The ID of the prefix list."
}

output "security_group_id" {
  value       = var.new_sg ? aws_security_group.default[0].id : null
  description = "IDs on the AWS Security Groups associated with the instance."
}

output "security_group_arn" {
  value       = var.new_sg ? aws_security_group.default[0].arn : null
  description = "IDs on the AWS Security Groups associated with the instance."
}

output "security_group_tags" {
  value       = var.new_sg ? aws_security_group.default[0].tags : null
  description = "A mapping of public tags to assign to the resource."
}

// File: variables.tf
variable "name" {
  type        = string
  default     = ""
  description = "Name  (e.g. `app` or `cluster`)."
}

variable "environment" {
  type        = string
  default     = ""
  description = "Environment (e.g. `prod`, `dev`, `staging`)."
}

variable "label_order" {
  type        = list(any)
  default     = ["name", "environment"]
  description = "Label order, e.g. `name`,`application`."
}

variable "repository" {
  type        = string
  default     = "https://github.com/opsstation/terraform-aws-security_group"
  description = "Terraform current module repo"
}

variable "managedby" {
  type        = string
  default     = "opsstation"
  description = "ManagedBy, eg 'cypik'."
}

variable "vpc_id" {
  type        = string
  default     = ""
  description = "The ID of the VPC that the instance security group belongs to."
  sensitive   = true
}

variable "prefix_list_ids" {
  type        = list(string)
  default     = []
  description = "The ID of the prefix list."
}

variable "prefix_list_enabled" {
  type        = bool
  default     = false
  description = "Enable prefix_list."
}

variable "max_entries" {
  type        = number
  default     = 5
  description = "The maximum number of entries that this prefix list can contain."
}

variable "entry" {
  type        = list(any)
  default     = []
  description = "Can be specified multiple times for each prefix list entry."
}

variable "existing_sg_id" {
  type        = string
  default     = null
  description = "Provide existing security group id for updating existing rule"
}

variable "new_sg_ingress_rules_with_cidr_blocks" {
  type        = any
  default     = {}
  description = "Ingress rules with only cidr blocks. Should be used when new security group is been deployed."
}

variable "new_sg_ingress_rules_with_self" {
