// File: versions.tf
# Terraform version
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.1.0"
    }
  }
}

// File: fn1-privesc3-multiple-policies.tf
# Tools that assess privesc risk from a policy perspective will miss roles that have privesc potential as a result of two or more policies. This partial policy helps you figure out which tools will alert on this. 

resource "aws_iam_policy" "fn1-privesc3-partial" {
  name        = "fn1-privesc3-partial"
  path        = "/"
  description = "Allows ec2:RunInstances, but missing iam:passrole"

  # Terraform's "jsonencode" function converts a
  # Terraform expression result to valid JSON syntax.
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [	      
        "ec2:DescribeInstances",
        "ec2:RunInstances"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_policy" "fn1-passrole-star" {
  name        = "fn1-passrole-star"
  path        = "/"
  description = "By itself iam:passrole does not allow privesc, but combined certain sensitive permissions it can"

  # Terraform's "jsonencode" function converts a
  # Terraform expression result to valid JSON syntax.
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
	      "iam:PassRole"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
    ]
  })
}


resource "aws_iam_role" "fn1-privesc3-partial-role" {
  name                = "fn1-privesc3-partial-role"
  assume_role_policy  = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Sid    = ""
        Principal = {
          AWS = var.aws_assume_role_arn
        }
      },
    ]
  })
}

resource "aws_iam_user" "fn1-privesc3-partial-user" {
  name = "fn1-privesc3-partial-user"
  path = "/"
}

resource "aws_iam_access_key" "fn1-privesc3-partial-user" {
 user = aws_iam_user.fn1-privesc3-partial-user.name
}


resource "aws_iam_user_policy_attachment" "fn1-privesc3-partial-user-attach-policy" {
  user       = aws_iam_user.fn1-privesc3-partial-user.name
  policy_arn = aws_iam_policy.fn1-privesc3-partial.arn
}

resource "aws_iam_user_policy_attachment" "privesc3-passrole-user-attach-policy" {
  user       = aws_iam_user.fn1-privesc3-partial-user.name
  policy_arn = aws_iam_policy.fn1-passrole-star.arn

}


resource "aws_iam_role_policy_attachment" "fn1-privesc3-partial-role-attach-policy" {
  role       = aws_iam_role.fn1-privesc3-partial-role.name
  policy_arn = aws_iam_policy.fn1-privesc3-partial.arn

}

resource "aws_iam_role_policy_attachment" "privesc3-passrole-role-attach-policy" {
  role       = aws_iam_role.fn1-privesc3-partial-role.name
  policy_arn = aws_iam_policy.fn1-passrole-star.arn

}

// File: fn2-ExploitableResourceConstraint.tf
resource "aws_iam_policy" "fn2-exploitableResourceConstraint" {
  name        = "fn2-exploitableResourceConstraint"
  path        = "/"
  description = "Allows privesc via iam:CreatePolicyVersion"

  # Terraform's "jsonencode" function converts a
  # Terraform expression result to valid JSON syntax.
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "iam:CreatePolicyVersion"
        Effect   = "Allow"
        Resource = "arn:aws:iam::*:policy/fn2-*"
      },
    ]
  })
}

resource "aws_iam_role" "fn2-exploitableResourceConstraint-role" {
  name                = "fn2-exploitableResourceConstraint-role"
  assume_role_policy  = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Sid    = ""
        Principal = {
          AWS = var.aws_assume_role_arn
        }
      },
    ]
  })
}


resource "aws_iam_user" "fn2-exploitableResourceConstraint-user" {
  name = "fn2-exploitableResourceConstraint-user"
  path = "/"
}

resource "aws_iam_access_key" "fn2-exploitableResourceConstraint-user" {
 user = aws_iam_user.fn2-exploitableResourceConstraint-user.name
}


resource "aws_iam_user_policy_attachment" "fn2-exploitableResourceConstraint-user-attach-policy" {
  user       = aws_iam_user.fn2-exploitableResourceConstraint-user.name
  policy_arn = aws_iam_policy.fn2-exploitableResourceConstraint.arn
}

resource "aws_iam_role_policy_attachment" "fn2-exploitableResourceConstraint-role-attach-policy" {
  role       = aws_iam_role.fn2-exploitableResourceConstraint-role.name
  policy_arn = aws_iam_policy.fn2-exploitableResourceConstraint.arn

}

// File: fn3-ExploitableConditionConstraint.tf
data "aws_iam_policy_document" "fn3-exploitableConditionConstraint-policy-document" {

  statement {

    actions = [
      "iam:CreatePolicyVersion",
    ]

    effect = "Allow"

    resources = [
      "*",
