// File: privesc-permissive-role-trust.tf
# This is a role that does not have any policies attached, but it demonstrates a bad practice. You should never trust the root of an account. That means that anyone who can assume any role can automatically assume this role. You shoul always limit who can assume the role using the principal of least privilege. 

resource "aws_iam_role" "privesc-permissive-role-trust" {
  name                = "privesc-permissive-role-trust"
  assume_role_policy  = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Sid    = ""
        Principal = {
          AWS = var.aws_root_user
        }
      },
    ]
  })
}

// File: variables.tf
variable "aws_local_profile" {
  description = "What local profile should terraform use to interact with your AWS account(s)"
  type        = string
  default     = "default"
}

variable "aws_local_creds_file" {
  description = "Location of your local credentials file"
  type        = string
  default     = "~/.aws/credentials"
}

variable "aws_assume_role_arn" {
  description = "This is the arn of an already existing principal that can assume into any roles that are created"
  type        = string
  default     = ""
}

variable "aws_root_user" {
  description = "This is the root user of the calling account"
  type        = string
  default     = ""
}

// File: groups.tf
resource "aws_iam_group" "this" {
  for_each = { for g in local.groups : g.name => format("%s%s", local.prefix, g.name) }
  name     = each.value
  path     = "/"
}

resource "aws_iam_group" "admins" {
  name = format("%s%s", local.prefix, "admins")
  path = "/"
}

resource "aws_iam_group" "users" {
  name = format("%s%s", local.prefix, "users")
  path = "/"
}

resource "aws_iam_group" "read-only" {
  name = format("%s%s", local.prefix, "read-only")
  path = "/"
}

resource "aws_iam_group_policy_attachment" "admins-assume-admin" {
  group      = aws_iam_group.admins.id
  policy_arn = aws_iam_policy.assume-admin.arn
}

resource "aws_iam_group_policy_attachment" "admins-read-only" {
  group      = aws_iam_group.admins.id
  policy_arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

resource "aws_iam_role_policy_attachment" "admin" {
  role       = aws_iam_role.admin.name
  policy_arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

resource "aws_iam_group_policy_attachment" "users" {
  group      = aws_iam_group.users.id
  policy_arn = aws_iam_policy.users-default.arn
}

resource "aws_iam_role_policy_attachment" "read-only" {
  role       = aws_iam_role.read-only.name
  policy_arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

resource "aws_iam_group_policy_attachment" "read-only-assume-read-only" {
  group      = aws_iam_group.read-only.id
  policy_arn = aws_iam_policy.assume-read-only.arn
}

data "aws_iam_group" "admins" {
  group_name = aws_iam_group.admins.name
  depends_on = [
    aws_iam_user_group_membership.this
  ]
}

data "aws_iam_group" "read-only" {
  group_name = aws_iam_group.read-only.name
  depends_on = [
    aws_iam_user_group_membership.this
  ]
}

resource "aws_iam_group" "billing" {
  name = format("%s%s", local.prefix, "billing")
  path = "/"
}

resource "aws_iam_group_policy_attachment" "billing" {
  group      = aws_iam_group.billing.id
  policy_arn = "arn:aws:iam::aws:policy/job-function/Billing"
}

resource "aws_iam_group" "billing-ro" {
  name = format("%s%s", local.prefix, "billing-ro")
  path = "/"
}

resource "aws_iam_group_policy_attachment" "billing-ro" {
  group      = aws_iam_group.billing-ro.id
  policy_arn = "arn:aws:iam::aws:policy/AWSBillingReadOnlyAccess"
}

// File: locals.tf
locals {
  users  = var.users
  groups = var.groups
  labels = var.labels

  config_password_policy = var.config_password_policy

  use_prefix = var.use_prefix

  admin_role_args = {
    max_session_duration = try(var.config_role.admin.max_session_duration, var.config_role.global.max_session_duration, 3600)
  }
  read_only_role_args = {
    max_session_duration = try(var.config_role.read_only.max_session_duration, var.config_role.global.max_session_duration, 3600)
  }
}

locals {
  prefix = length(local.labels.id) == 0 && local.use_prefix ? "" : "${local.labels.id}-"
}

// File: main.tf
resource "aws_iam_account_password_policy" "this" {
  count = local.config_password_policy.enable ? 1 : 0
  #checkov:skip=CKV_AWS_9
  #checkov:skip=CKV_AWS_11
  #checkov:skip=CKV_AWS_12
  #checkov:skip=CKV_AWS_14
  #checkov:skip=CKV_AWS_15
  minimum_password_length        = local.config_password_policy.minimum_password_length
  require_lowercase_characters   = local.config_password_policy.require_lowercase_characters
  require_numbers                = local.config_password_policy.require_numbers
  require_uppercase_characters   = local.config_password_policy.require_uppercase_characters
  require_symbols                = local.config_password_policy.require_symbols
  allow_users_to_change_password = local.config_password_policy.allow_users_to_change_password
  password_reuse_prevention      = local.config_password_policy.password_reuse_prevention
}

// File: outputs.tf
output "groups" {
  description = "List of group objects with keys 'arn', 'name'(prefixed by labels.id if applicable) and 'unique_id'"
  value = merge(
    {
      for name, group in aws_iam_group.this : name => {
        name : group.name
        arn : group.arn
        unique_id : group.unique_id
      }
    },
    {
      "admins" = {
        name : aws_iam_group.admins.name
        arn : aws_iam_group.admins.arn
        unique_id : aws_iam_group.admins.unique_id
      },
      "users" = {
        name : aws_iam_group.users.name
        arn : aws_iam_group.users.arn
        unique_id : aws_iam_group.users.unique_id
      },
      "read-only" = {
        name : aws_iam_group.read-only.name
        arn : aws_iam_group.read-only.arn
        unique_id : aws_iam_group.read-only.unique_id
      },
    }
  )
}

output "users" {
  description = "List of users objects with keys 'arn', 'name' and 'unique_id'"
  value = {
    for name, user in aws_iam_user.this : name => {
      name : name
      arn : user.arn
      unique_id : user.unique_id
    }
  }
}

output "admin_users" {
  description = "List of users arns that are part of the admin group."
  value       = [for user in data.aws_iam_group.admins.users : user.arn]
}

output "admin_role" {
  description = "The admin role object."
  value       = aws_iam_role.admin
}

// File: policies.tf
locals {
  iam-self      = "arn:aws:iam::*:user/&{aws:username}"
  mfa-self      = "arn:aws:iam::*:mfa/&{aws:username}"
  mfa-self-star = "arn:aws:iam::*:mfa/&{aws:username}-*"
}

data "aws_iam_policy_document" "users" {
  # AllowViewAccountInfo
  statement {
    actions = [
      "iam:GetAccountPasswordPolicy",
      "iam:GetAccountSummary",
      "iam:ListVirtualMFADevices",
    ]

    resources = ["*"]
  }

  # AllowManageOwnPasswords
  statement {
    actions = [
      "iam:ChangePassword",
      "iam:GetUser",
    ]

    resources = [local.iam-self]
  }

  # AllowManageOwnAccessKeys
  statement {
    actions = [
      "iam:CreateAccessKey",
      "iam:DeleteAccessKey",
      "iam:ListAccessKeys",
      "iam:UpdateAccessKey",
    ]

    resources = [local.iam-self]
  }

  # AllowManageOwnSigningCertificates
  statement {
    actions = [
      "iam:DeleteSigningCertificate",
      "iam:ListSigningCertificates",
      "iam:UpdateSigningCertificate",
      "iam:UploadSigningCertificate",
    ]

    resources = [local.iam-self]
  }

  # AllowManageOwnSSHPublicKeys
  statement {
    actions = [
      "iam:DeleteSSHPublicKey",
      "iam:GetSSHPublicKey",
      "iam:ListSSHPublicKeys",
      "iam:UpdateSSHPublicKey",
      "iam:UploadSSHPublicKey",
    ]

    resources = [local.iam-self]
  }

  # AllowManageOwnGitCredentials
  statement {
    actions = [
      "iam:CreateServiceSpecificCredential",
      "iam:DeleteServiceSpecificCredential",
      "iam:ListServiceSpecificCredentials",
      "iam:ResetServiceSpecificCredential",
      "iam:UpdateServiceSpecificCredential",
    ]

    resources = [local.iam-self]
  }

  # AllowManageOwnVirtualMFADevice
  statement {
    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:DeleteVirtualMFADevice",
    ]

    resources = [local.iam-self, local.mfa-self, local.mfa-self-star]
  }

  # AllowManageOwnUserMFA
  statement {
    actions = [
      "iam:DeactivateMFADevice",
      "iam:EnableMFADevice",
      "iam:ListMFADevices",
      "iam:ResyncMFADevice",
    ]

    resources = [local.iam-self, local.mfa-self, local.mfa-self-star]
  }

  # DenyAllExceptListedIfNoMFA
  statement {
    effect = "Deny"
    not_actions = [
      "iam:CreateVirtualMFADevice",
      "iam:DeleteVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:GetUser",
      "iam:ListMFADevices",
      "iam:ListVirtualMFADevices",
      "iam:ResyncMFADevice",
      "sts:GetSessionToken",
      "iam:GetAccountPasswordPolicy",
      "iam:ChangePassword",
    ]

    resources = ["*"]

    condition {
      test     = "BoolIfExists"
      variable = "aws:MultiFactorAuthPresent"
      values   = [false]
    }
  }
}

resource "aws_iam_policy" "users-default" {
  name_prefix = format("%s%s", local.prefix, "default-users-policy")
  path        = "/users/"
  description = "Default policy for a user to self manage"
  policy      = data.aws_iam_policy_document.users.json
  tags        = local.labels.tags
}

resource "aws_iam_policy" "assume-admin" {
  name_prefix = format("%s%s", local.prefix, "assume-admin")
  description = "Assume Admin Role"
  policy      = data.aws_iam_policy_document.assume-admin.json
  tags        = local.labels.tags
}

resource "aws_iam_policy" "assume-read-only" {
  name_prefix = format("%s%s", local.prefix, "assume-read-only")
  description = "Assume Read Only Role"
  policy      = data.aws_iam_policy_document.assume-read-only.json
  tags        = local.labels.tags
}

data "aws_iam_policy_document" "admin-assume-role" {
  statement {
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = [for user in data.aws_iam_group.admins.users : user.arn]
    }

    condition {
      test     = "BoolIfExists"
      variable = "aws:MultiFactorAuthPresent"
      values   = [true]
    }
  }
}

data "aws_iam_policy_document" "read-only-assume-role" {
  statement {
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = [for user in data.aws_iam_group.read-only.users : user.arn]
    }

    condition {
      test     = "BoolIfExists"
      variable = "aws:MultiFactorAuthPresent"
      values   = [true]
    }
  }
}

data "aws_iam_policy_document" "assume-admin" {
  statement {
    effect = "Allow"

    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.admin.arn]
  }
}

data "aws_iam_policy_document" "assume-read-only" {
  statement {
    effect = "Allow"

    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.read-only.arn]
  }
}

// File: roles.tf
resource "aws_iam_role" "admin" {
  name_prefix          = format("%s%s", local.prefix, "admin")
  assume_role_policy   = data.aws_iam_policy_document.admin-assume-role.json
  tags                 = local.labels.tags
  max_session_duration = local.admin_role_args.max_session_duration

  depends_on = [
    data.aws_iam_policy_document.admin-assume-role
  ]
}

resource "aws_iam_role" "read-only" {
  name_prefix          = format("%s%s", local.prefix, "read-only")
  assume_role_policy   = data.aws_iam_policy_document.read-only-assume-role.json
  tags                 = local.labels.tags
  max_session_duration = local.read_only_role_args.max_session_duration


  depends_on = [
    data.aws_iam_policy_document.read-only-assume-role
  ]
}

// File: users.tf
resource "aws_iam_user" "this" {
  for_each = { for x in local.users : x.name => x }

  name          = each.value.name
  path          = each.value.path
  force_destroy = each.value.force_destroy == null ? true : each.value.force_destroy
  tags          = local.labels.tags
}

resource "aws_iam_user_group_membership" "this" {
  for_each = { for x in local.users : x.name => x }

  user   = each.value.name
  groups = [for x in each.value.groups : format("%s%s", local.prefix, x)]

  depends_on = [
    aws_iam_user.this,
    aws_iam_group.this,
    aws_iam_group.admins,
    aws_iam_group.users
  ]
}

// File: variables.tf
variable "users" {
  description = "List of user objects"
  type = list(object({
    name          = string
    path          = optional(string, "/")
    groups        = optional(list(string))
    force_destroy = optional(bool)
  }))
  default = []
}

variable "groups" {
  description = "List of group objects. Protected group names: ['admins', 'users', 'billing', 'billing-ro']"

  type = list(object({
    name = string
  }))

  default = []

  validation {
    condition     = alltrue([for group in var.groups : !contains(["users", "admins", "billing", "billing-ro", "read-only"], group.name)])
    error_message = "The `groups` variable elements cannot contain the values `[\"users\", \"admins\", \"billing\", \"billing-ro\", \"read-only\"]`."
  }
}

variable "labels" {
  description = "Instance of Labels Module"
  type = object(
    {
      id   = optional(string, "")
      tags = optional(any, {})
    }
  )
  default = {}
}

variable "config_password_policy" {
  description = "Password Policy"

  type = object({
    enable                         = optional(bool, true)
    minimum_password_length        = optional(number, 14)
    require_lowercase_characters   = optional(bool, true)
    require_numbers                = optional(bool, true)
    require_uppercase_characters   = optional(bool, true)
    require_symbols                = optional(bool, true)
    allow_users_to_change_password = optional(bool, true)
    password_reuse_prevention      = optional(number, 24)
  })

  default = {}
}


variable "use_prefix" {
  description = "Prefix Resources"
  type        = bool
  default     = true
}

variable "config_terraform_user" {
  description = "Create Terraform User/Role"
  type = object({
    enable_user = optional(bool, false)
    enable_role = optional(bool, false)
  })
  default = {}
}

variable "config_role" {
  description = "Builtin role configurations exposed. `admin` and `read-only` share same type as `global` but will override `global`."
  type = object({
    global = optional(object({
      max_session_duration = optional(number, 3600)
    }))
    admin     = optional(map(any))
    read_only = optional(map(any))
  })
  default = {}
}

// File: versions.tf
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }

  required_version = ">= 1.3.0"
}

// File: iam.tf
data "aws_partition" "current" {}

data "aws_iam_policy_document" "ab_role_assume_role_policy" {
  count = var.enabled && var.iam_role_arn == null ? 0 : 1
  statement {
    actions = ["sts:AssumeRole"]
    effect  = "Allow"
    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ab_role" {
  count              = var.enabled && var.iam_role_arn == null ? 0 : 1
  name               = var.iam_role_name == "" ? "aws-backup-plan-${var.plan_name}-role" : var.iam_role_name
  assume_role_policy = data.aws_iam_policy_document.ab_role_assume_role_policy[0].json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "ab_policy_attach" {
  count      = var.enabled && var.iam_role_arn == null ? 0 : 1
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
  role       = aws_iam_role.ab_role[0].name
}

resource "aws_iam_role_policy_attachment" "ab_backup_s3_policy_attach" {
  count      = var.enabled && var.iam_role_arn == null ? 0 : 1
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSBackupServiceRolePolicyForS3Backup"
  role       = aws_iam_role.ab_role[0].name
}

# Tag policy
data "aws_iam_policy_document" "ab_tag_policy_document" {
  count = var.enabled && var.iam_role_arn == null ? 0 : 1
  statement {
    effect    = "Allow"
    resources = ["*"]
    actions = [
      "backup:TagResource",
      "backup:ListTags",
      "backup:UntagResource",
      "tag:GetResources"
    ]
  }
}

resource "aws_iam_policy" "ab_tag_policy" {
  count       = var.enabled && var.iam_role_arn == null ? 0 : 1
  description = "AWS Backup Tag policy"
  policy      = data.aws_iam_policy_document.ab_tag_policy_document[0].json
}

resource "aws_iam_role_policy_attachment" "ab_tag_policy_attach" {
  count      = var.enabled && var.iam_role_arn == null ? 0 : 1
  policy_arn = aws_iam_policy.ab_tag_policy[0].arn
  role       = aws_iam_role.ab_role[0].name
}

# Restores policy
resource "aws_iam_role_policy_attachment" "ab_restores_policy_attach" {
  count      = var.enabled && var.iam_role_arn == null ? 0 : 1
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
  role       = aws_iam_role.ab_role[0].name
}

resource "aws_iam_role_policy_attachment" "ab_restores_s3_policy_attach" {
  count      = var.enabled && var.iam_role_arn == null ? 0 : 1
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSBackupServiceRolePolicyForS3Restore"
  role       = aws_iam_role.ab_role[0].name
}

// File: main.tf
# AWS Backup vault
resource "aws_backup_vault" "ab_vault" {
  count       = var.enabled && var.vault_name != null ? 1 : 0
  name        = var.vault_name
  kms_key_arn = var.vault_kms_key_arn
  tags        = var.tags
}

# AWS Backup plan
resource "aws_backup_plan" "ab_plan" {
  count = var.enabled ? 0 : 1
  name  = var.plan_name

  # Rules
  dynamic "rule" {
    for_each = local.rules
    content {
      rule_name                = lookup(rule.value, "name", generalRule)
      target_vault_name        = lookup(rule.value, "target_vault_name", ab_vault) != null ? rule.value.target_vault_name : var.vault_name != null ? var.vault_name : "Default"
      schedule                 = lookup(rule.value, "schedule", null)
      start_window             = lookup(rule.value, "start_window", null)
      completion_window        = lookup(rule.value, "completion_window", null)
      enable_continuous_backup = lookup(rule.value, "enable_continuous_backup", null)
      recovery_point_tags      = length(lookup(rule.value, "recovery_point_tags", {})) == 0 ? var.tags : lookup(rule.value, "recovery_point_tags")

      # Lifecycle
      dynamic "lifecycle" {
        for_each = length(lookup(rule.value, "lifecycle", {})) == 0 ? [] : [lookup(rule.value, "lifecycle", {})]
        content {
          cold_storage_after = lookup(lifecycle.value, "cold_storage_after", 30)
          delete_after       = lookup(lifecycle.value, "delete_after", 180)
        }
      }

      # Copy action
      dynamic "copy_action" {
        for_each = lookup(rule.value, "copy_actions", [])
        content {
          destination_vault_arn = lookup(copy_action.value, "destination_vault_arn", null)

          # Copy Action Lifecycle
          dynamic "lifecycle" {
            for_each = length(lookup(copy_action.value, "lifecycle", {})) == 0 ? [] : [lookup(copy_action.value, "lifecycle", {})]
            content {
              cold_storage_after = lookup(lifecycle.value, "cold_storage_after", 30)
              delete_after       = lookup(lifecycle.value, "delete_after", 180)
            }
          }
        }
      }
    }
  }

  # Advanced backup setting
  dynamic "advanced_backup_setting" {
    for_each = var.windows_vss_backup ? [1] : []
    content {
      backup_options = {
        WindowsVSS = "enabled"
      }
      resource_type = "EC2"
    }
  }

  # Tags
  tags = var.tags

  # First create the vault if needed
  depends_on = [aws_backup_vault.ab_vault]
}

locals {

  # Rule
  rule = var.rule_name == null ? [] : [
    {
      name              = var.rule_name
      target_vault_name = var.vault_name != null ? var.vault_name : "Default"
      schedule          = var.rule_schedule
      start_window      = var.rule_start_window
      completion_window = var.rule_completion_window
      lifecycle = var.rule_lifecycle_cold_storage_after == null ? {} : {
        cold_storage_after = var.rule_lifecycle_cold_storage_after
        delete_after       = var.rule_lifecycle_delete_after
      }
      enable_continuous_backup = var.rule_enable_continuous_backup
      recovery_point_tags      = var.rule_recovery_point_tags
    }
  ]

  # Rules
  rules = concat(local.rule, var.rules)

}

// File: notification.tf
data "aws_iam_policy_document" "backup_events" {
  count = var.enabled && length(var.notifications) > 0 ? 1 : 0
  statement {
    actions = [
      "SNS:Publish",
    ]
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
    resources = [
      lookup(var.notifications, "sns_topic_arn", null)
    ]
    sid = "BackupPublishEvents"
  }
}

resource "aws_sns_topic_policy" "backup_events" {
  count  = var.enabled && length(var.notifications) > 0 ? 1 : 0
  arn    = lookup(var.notifications, "sns_topic_arn", null)
  policy = data.aws_iam_policy_document.backup_events[0].json
}

resource "aws_backup_vault_notifications" "backup_events" {
  count               = var.enabled && length(var.notifications) > 0 ? 1 : 0
  backup_vault_name   = var.vault_name != null ? var.vault_name : "Default"
  sns_topic_arn       = lookup(var.notifications, "sns_topic_arn", null)
  backup_vault_events = lookup(var.notifications, "backup_vault_events", [])
}

// File: outputs.tf
# Vault
output "vault_id" {
  description = "The name of the vault"
  value       = join("", aws_backup_vault.ab_vault.*.id)
}

output "vault_arn" {
  description = "The ARN of the vault"
  value       = join("", aws_backup_vault.ab_vault.*.arn)
}

# Plan
output "plan_id" {
  description = "The id of the backup plan"
  value       = join("", aws_backup_plan.ab_plan.*.id)
}

output "plan_arn" {
  description = "The ARN of the backup plan"
  value       = join("", aws_backup_plan.ab_plan.*.arn)
}

output "plan_version" {
  description = "Unique, randomly generated, Unicode, UTF-8 encoded string that serves as the version ID of the backup plan"
  value       = join("", aws_backup_plan.ab_plan.*.version)
}

output "plan_role" {
  description = "The service role of the backup plan"
  value       = var.iam_role_arn == null ? join("", aws_iam_role.ab_role.*.name) : var.iam_role_arn
}

// File: selection.tf
resource "aws_backup_selection" "ab_selection" {
  count = var.enabled ? length(local.selections) : 0

  iam_role_arn = var.iam_role_arn != null ? var.iam_role_arn : aws_iam_role.ab_role[0].arn
  name         = lookup(element(local.selections, count.index), "name", null)
  plan_id      = aws_backup_plan.ab_plan[0].id

  resources     = lookup(element(local.selections, count.index), "resources", null)
  not_resources = lookup(element(local.selections, count.index), "not_resources", null)

  dynamic "selection_tag" {
    for_each = length(lookup(element(local.selections, count.index), "selection_tags", [])) == 0 ? [] : lookup(element(local.selections, count.index), "selection_tags", [])
    content {
      type  = lookup(selection_tag.value, "type", null)
      key   = lookup(selection_tag.value, "key", null)
      value = lookup(selection_tag.value, "value", null)
    }
  }

  condition {
    dynamic "string_equals" {
      for_each = lookup(lookup(element(local.selections, count.index), "conditions", {}), "string_equals", [])
      content {
        key   = lookup(string_equals.value, "key", null)
        value = lookup(string_equals.value, "value", null)
      }
    }
    dynamic "string_like" {
      for_each = lookup(lookup(element(local.selections, count.index), "conditions", {}), "string_like", [])
      content {
        key   = lookup(string_like.value, "key", null)
        value = lookup(string_like.value, "value", null)
      }
    }
    dynamic "string_not_equals" {
      for_each = lookup(lookup(element(local.selections, count.index), "conditions", {}), "string_not_equals", [])
      content {
        key   = lookup(string_not_equals.value, "key", null)
        value = lookup(string_not_equals.value, "value", null)
      }
    }
    dynamic "string_not_like" {
      for_each = lookup(lookup(element(local.selections, count.index), "conditions", {}), "string_not_like", [])
      content {
        key   = lookup(string_not_like.value, "key", null)
        value = lookup(string_not_like.value, "value", null)
      }
    }
  }
}

locals {

  # Selection
  selection = var.selection_name == null ? [] : [
    {
      name           = var.selection_name
      resources      = var.selection_resources
      not_resources  = var.selection_not_resources
      conditions     = var.selection_conditions
      selection_tags = var.selection_tags
    }
  ]

  # Selections
  selections = concat(local.selection, var.selections)

  # Make sure the role can get tag resources
  depends_on = [aws_iam_role_policy_attachment.ab_tag_policy_attach]
}

// File: variables.tf
#
# AWS Backup vault
#
variable "vault_name" {
  description = "Name of the backup vault to create. If not given, AWS use default"
  type        = string
  default     = null
}

variable "vault_kms_key_arn" {
  description = "The server-side encryption key that is used to protect your backups"
  type        = string
  default     = null
}

variable "tags" {
  description = "A mapping of tags to assign to the resource"
  type        = map(string)
  default     = {}
}

#
# AWS Backup plan
#
variable "plan_name" {
  description = "The display name of a backup plan"
  type        = string
  default     = null
}

# Default rule
variable "rule_name" {
  description = "An display name for a backup rule"
  type        = string
  default     = null
}

variable "rule_schedule" {
  description = "A CRON expression specifying when AWS Backup initiates a backup job"
  type        = string
  default     = null
}

variable "rule_start_window" {
  description = "The amount of time in minutes before beginning a backup"
  type        = number
  default     = null
}

variable "rule_completion_window" {
  description = "The amount of time AWS Backup attempts a backup before canceling the job and returning an error"
  type        = number
  default     = null
}

variable "rule_recovery_point_tags" {
  description = "Metadata that you can assign to help organize the resources that you create"
  type        = map(string)
  default     = {}
}

# Rule lifecycle
variable "rule_lifecycle_cold_storage_after" {
  description = "Specifies the number of days after creation that a recovery point is moved to cold storage"
  type        = number
  default     = null
}

variable "rule_lifecycle_delete_after" {
  description = "Specifies the number of days after creation that a recovery point is deleted. Must be 90 days greater than `cold_storage_after`"
  type        = number
  default     = null
}

# Rule copy action
variable "rule_copy_action_lifecycle" {
  description = "The lifecycle defines when a protected resource is copied over to a backup vault and when it expires."
  type        = map(any)
  default     = {}
}

variable "rule_copy_action_destination_vault_arn" {
  description = "An Amazon Resource Name (ARN) that uniquely identifies the destination backup vault for the copied backup."
  type        = string
  default     = null
}

variable "rule_enable_continuous_backup" {
  description = " Enable continuous backups for supported resources."
  type        = bool
  default     = false
}


# Rules
variable "rules" {
  description = "A list of rule maps"
  type        = any
  default     = []
}

# Selection
variable "selection_name" {
  description = "The display name of a resource selection document"
  type        = string
  default     = null
}

variable "selection_resources" {
  description = "An array of strings that either contain Amazon Resource Names (ARNs) or match patterns of resources to assign to a backup plan"
  type        = list(any)
  default     = []
}

variable "selection_not_resources" {
  description = "An array of strings that either contain Amazon Resource Names (ARNs) or match patterns of resources to exclude from a backup plan."
  type        = list(any)
  default     = []
}

variable "selection_conditions" {
  description = "A map of conditions that you define to assign resources to your backup plans using tags."
  type        = map(any)
  default     = {}
}

variable "selection_tags" {
  description = "List of tags for `selection_name` var, when using variable definition."
  type        = list(any)
  default     = []
}

# Selection
variable "selections" {
  description = "A list of selction maps"
  type        = any
  default     = []
}

variable "enabled" {
  description = "Change to false to avoid deploying any AWS Backup resources"
  type        = bool
  default     = true
}

# Windows Backup parameter
variable "windows_vss_backup" {
  description = "Enable Windows VSS backup option and create a VSS Windows backup"
  type        = bool
  default     = false
}

#
# Notifications
#
variable "notifications" {
  description = "Notification block which defines backup vault events and the SNS Topic ARN to send AWS Backup notifications to. Leave it empty to disable notifications"
  type        = any
  default     = {}
}

#
# IAM
#
variable "iam_role_arn" {
  description = "If configured, the module will attach this role to selections, instead of creating IAM resources by itself"
  type        = string
  default     = null
}

variable "iam_role_name" {
  description = "Allow to set IAM role name, otherwise use predefined default"
  type        = string
  default     = ""
}

// File: versions.tf
terraform {
  required_version = ">= 0.12.31"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 3.0"
    }
  }
}

// File: ami.tf
data "aws_ami" "amazon_linux" {
  most_recent = true
  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-gp2"]
  }
  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
  filter {
    name   = "architecture"
    values = ["x86_64"]
  }
  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
  owners = ["amazon"]
}

// File: ec2-bastion.tf
// bastion instance
resource "aws_instance" "bastion" {
  ami           = data.aws_ami.amazon_linux.id
  instance_type = "t2.micro"
  key_name      = aws_key_pair.acloudkey.key_name
  tags = {
    Name = "bastion01"
  }
  subnet_id = aws_subnet.public1a.id
  vpc_security_group_ids = [
    aws_security_group.bastion_sg.id
  ]
  user_data = <<-EOT
    #!/bin/bash
    sudo yum update -y
    sudo amazon-linux-extras install ansible2 vim postgresql14 python3.8
  EOT
}

resource "aws_security_group" "bastion_sg" {
  name        = "allow_bastion"
  description = "Allow Bastion"
  vpc_id      = aws_vpc.main.id
  ingress {
    description      = "SSH"
    from_port        = 22
    to_port          = 22
    protocol         = "tcp"
    cidr_blocks      = ["0.0.0.0/0"]
    ipv6_cidr_blocks = ["::/0"]
  }
  egress {
    from_port        = 0
    to_port          = 0
    protocol         = "-1"
    cidr_blocks      = ["0.0.0.0/0"]
    ipv6_cidr_blocks = ["::/0"]
  }
  tags = {
    Name = "allow_bastion"
  }
}

output "bastion_public_ip" {
  value = aws_instance.bastion.public_ip
}

output "bastion_private_ip" {
  value = aws_instance.bastion.private_ip
}

// File: ec2-db.tf
// the postgres database instance
resource "aws_instance" "db" {
  ami           = data.aws_ami.amazon_linux.id
  instance_type = "t2.micro"
  key_name      = aws_key_pair.acloudkey.key_name
  tags = {
    Name = "dbserver01"
  }
  subnet_id = aws_subnet.private1a.id
  vpc_security_group_ids = [
    aws_security_group.allow_db.id
  ]
  user_data = <<-EOT
  #!/bin/bash
  sudo tee /etc/yum.repos.d/pgdg.repo<<EOF
  [pgdg14]
  name=PostgreSQL 14 for RHEL/CentOS 7 - x86_64
  baseurl=https://download.postgresql.org/pub/repos/yum/14/redhat/rhel-7-x86_64
  enabled=1
  gpgcheck=0
  EOF
  sudo yum update -y
  sudo yum install -y postgresql14 postgresql14-server
  sudo /usr/pgsql-14/bin/postgresql-14-setup initdb
  sudo systemctl enable postgresql-14
  sudo systemctl start postgresql-14
  sleep 15
  sudo -u postgres psql -c "ALTER USER postgres WITH PASSWORD 'postgres';"
  echo "listen_addresses = '*'" |sudo tee -a /var/lib/pgsql/14/data/postgresql.conf
  echo "host    all             all              0.0.0.0/0                       md5" |sudo tee -a /var/lib/pgsql/14/data/pg_hba.conf
  sudo systemctl restart postgresql-14
  EOT
}


resource "aws_security_group" "allow_db" {
  name        = "allow_db"
  description = "Allow DB"
  vpc_id      = aws_vpc.main.id
  ingress {
    description = "SSH From Bastion"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    security_groups = [
      aws_security_group.bastion_sg.id
    ]
  }
  ingress {
    description = "Postgres From Bastion"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    security_groups = [
      aws_security_group.bastion_sg.id
    ]
  }
  egress {
    from_port        = 0
    to_port          = 0
    protocol         = "-1"
    cidr_blocks      = ["0.0.0.0/0"]
    ipv6_cidr_blocks = ["::/0"]
  }
  tags = {
    Name = "allow_db"
  }
}

output "db_private_ip" {
  value = aws_instance.db.private_ip
}

// File: ec2-web.tf
// the nginx web instances
resource "aws_instance" "web" {
  for_each      = toset(["webserver01", "webserver02", "webserver03"])
  ami           = data.aws_ami.amazon_linux.id
  instance_type = "t2.micro"
  key_name      = aws_key_pair.acloudkey.key_name
  tags = {
    Name = each.key
  }
  subnet_id = aws_subnet.private1a.id
  vpc_security_group_ids = [
    aws_security_group.allow_web.id
  ]
  user_data = <<-EOT
    #!/bin/bash
    # install nginx
    sudo yum update -y
    sudo amazon-linux-extras install nginx1
    echo "<html><body><h1>Hello from NGINX ${each.key} </h1></body></html>" >/usr/share/nginx/html/index.html
    # make sure nginx is started
    sudo service nginx start
  EOT
}

resource "aws_security_group" "allow_web" {
  name        = "allow_web"
  description = "Allow Web inbound"
  vpc_id      = aws_vpc.main.id
  ingress {
    description     = "SSH From Bastion"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion_sg.id]
  }
  ingress {
    description = "Web From Public"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }
  egress {
    from_port        = 0
    to_port          = 0
    protocol         = "-1"
    cidr_blocks      = ["0.0.0.0/0"]
    ipv6_cidr_blocks = ["::/0"]
  }
  tags = {
    Name = "allow_web"
  }
}

output "web_private_ip" {
  value = [
    for i in aws_instance.web : i.private_ip
  ]
}

