// File: outputs.tf
output "codedeploy_role_arn" {
  description = "ARN of CodeDeploy role"
  value       = aws_iam_role.codedeploy_role.arn
}

output "codedeploy_instance_profile" {
  description = "Name of CodeDeploy instance profile"
  value       = aws_iam_instance_profile.ec2_code_deploy_instance_profile.name
}

output "cw_agent_instance_profile" {
  description = "Name of CloudWatch instance profile"
  value       = aws_iam_instance_profile.ec2_cw_instance_profile.name
}

output "codebuild_role_arn" {
  description = "ARN of CodeBuild role"
  value       = aws_iam_role.codebuildrole.arn
}

output "codepipeline_role_arn" {
  description = "ARN of CodePipeline role"
  value       = aws_iam_role.codepipeline.arn
}

// File: variables.tf
variable "project" {
  description = "The name of the project"
  default     = "Cv-React-App"
  type        = string
}

// File: aplication_lb.tf
#fourth step

# ELB will sit in front of our instances to balance traffic between running EC2 instances
resource "aws_lb" "ecs-load-balancer" {
  load_balancer_type = "application"
  name = "ecs-lb"
  security_groups = [aws_security_group.ecs_test_sg.id]
  subnets = aws_subnet.ecs_subnets.*.id
  tags = {
    name = "ecs-application-load-balancer"
  }
}

# target group with health_check
resource "aws_lb_target_group" "ecs-target-group-lb" {
  name = "ecs-target-group"
  port = "80"
  protocol = "HTTP"
  vpc_id = aws_vpc.ecs_test.id
  depends_on = [aws_lb.ecs-load-balancer]
  health_check {
    path = "/"
    protocol = "HTTP"
    matcher = "200"
    interval = 15
    timeout = 10
    healthy_threshold = 2
    unhealthy_threshold = 2
 }
  tags = {
    Name = "ecs-target-group-lb"
  }
}

# We need a listener to be able to connect to LB
resource "aws_lb_listener" "alb-listener" {
  load_balancer_arn = aws_lb.ecs-load-balancer.arn
  port = "80"
  protocol = "HTTP"
  default_action {
    type = "forward"
    target_group_arn = aws_lb_target_group.ecs-target-group-lb.arn
  }
}

// File: ec2.tf
# Launch configuration defines the Ec2 instances that will be started to support our cluster (instance type and AMI).
# On top of that, it:
# a) allows us do attach instance profile to each instance that will be started
# b) security group
# c) it sends user-defined data to EC2 instance. This data will be run as a script after instance will be booted up.
resource "aws_launch_configuration" "ecs-launch-config" {
  image_id = data.aws_ami.ecs-ami.id
  instance_type = var.instance_type
# Using AMI id in launch config name is a workaround for problems with recreating the autoscaling group
  iam_instance_profile = aws_iam_instance_profile.ecs-instance-profile.id
  security_groups = [aws_security_group.ecs_test_sg.id]
  # Please attach public IP only if needed...
  associate_public_ip_address = "true"

  lifecycle {
    create_before_destroy = true
  }

  user_data = <<EOF
    #!/bin/bash
    echo ECS_CLUSTER=${var.ecs_cluster} >> /etc/ecs/ecs.config
    EOF
}

# Thanks to autoscaling group we will be able to define how many EC2 instances we need
# define where (network-wise) instances should be started (subnets) and allows us to attach instances to LB target group
# attach launch configuration, define health check for our instances
resource "aws_autoscaling_group" "ecs-autoscaling-group" {
# Using AMI id in launch config name is a workaround for problems with recreating the autoscaling group
  name = "ecs-autoscaling-group-${data.aws_ami.ecs-ami.id}"
  max_size = var.max_instances
  min_size = var.min_instances
  vpc_zone_identifier = aws_subnet.ecs_subnets.*.id
  launch_configuration = aws_launch_configuration.ecs-launch-config.name
# Use health_check_type = "EC2" if not using Elastic Load Balancer
  health_check_type = "ELB"
  # Dont use target group if not using ELB
  target_group_arns = [aws_lb_target_group.ecs-target-group-lb.arn]
}

// File: ecs.tf
# Yes, the cluster itself is that simple :)
resource "aws_ecs_cluster" "ecs-cluster" {
  name = var.ecs_cluster
}

# Task is more complex :)
resource "aws_ecs_task_definition" "esc_test_task" {
  family = "ecs-testing"
  execution_role_arn = aws_iam_role.ecs-task-execution-role.arn
  task_role_arn = aws_iam_role.ecs-task.arn
  container_definitions = <<DEFINITION
[
  {
    "name": "nginx",
    "image": "nginx",
    "cpu" : 1024,
    "memory" : 800,
    "essential": true,
    "portMappings": [
      {
        "containerPort": 80,
        "hostPort": 80
      }
    ],
    "environment": [
      {
        "Name": "AWS_DEFAULT_REGION",
        "Value": "eu-central-1"
      },
      {
        "Name": "AWESOME_VAR",
        "Value": "AWESOME_VALUE_1"
      }
    ],
    "logConfiguration": {
      "logDriver": "awslogs",
      "options": {
        "awslogs-group": "/ecs/test-cluster",
        "awslogs-region": "eu-central-1",
        "awslogs-stream-prefix": "awslogs-example"
        }
    }
  }
]
DEFINITION
}

resource "aws_ecs_service" "ecs-service" {
  name = "ecs-service"
  # Attach IAM role only if you use ELB otherwise resource will not be created.
  iam_role = aws_iam_role.ecs_service_role.name
  cluster = aws_ecs_cluster.ecs-cluster.id
  task_definition = aws_ecs_task_definition.esc_test_task.arn
  desired_count = var.desired_task_count
  deployment_minimum_healthy_percent = var.deployment_minimum_healthy_percent
  deployment_maximum_percent = var.deployment_maximum_percent
  load_balancer {
    target_group_arn = aws_lb_target_group.ecs-target-group-lb.arn
    container_name = "nginx"
    container_port = 80
  }
}

// File: iam_ec2.tf
# Used for EC2 instances
# Creates a role that will be attached to instances
resource "aws_iam_role" "ecs-instance-role" {
  name = "ecs-instance-role"
  path = "/"
  assume_role_policy = data.aws_iam_policy_document.ecs-instance-policy.json
}

# We don't need to create policy since there is already an AWS managed policy that fits perfectly.
# We only need to attach it to a role that was created
resource "aws_iam_role_policy_attachment" "ecs-instance-role-att" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role"
  role = aws_iam_role.ecs-instance-role.name
}

# Need instance profile to be able to attach a role to instances.
resource "aws_iam_instance_profile" "ecs-instance-profile" {
  name = "ecs-instance-profile"
  path = "/"
  role = aws_iam_role.ecs-instance-role.id
}

data "aws_iam_policy_document" "ecs-instance-policy" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      identifiers = ["ec2.amazonaws.com"]
      type = "Service"
    }
  }
}

// File: iam_service.tf
#Third step is to handle IAM
# Do bear in mind that roles attached to services are needed only when using Load Balancer in front of the EC2 instances
# If there is no LB used (that Use Case is described in the article) there is no need to create any of those.
# If you will create those resources you will not be able to attach them to service...

resource "aws_iam_role" "ecs_service_role" {
  name = "ecs-service-role"
  path = "/"
  assume_role_policy = data.aws_iam_policy_document.ecs-service-policy.json
}

resource "aws_iam_role_policy_attachment" "ecs-service-role-att" {
  role = aws_iam_role.ecs_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceRole"
}

data "aws_iam_policy_document" "ecs-service-policy" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      identifiers = ["ecs.amazonaws.com"]
      type = "Service"
    }
  }
}

// File: iam_task.tf
#Task execution role is a role that that can be assumed by ECS container agent
resource "aws_iam_role" "ecs-task-execution-role" {
  name = "ecs-taskexec-role"
  assume_role_policy = data.aws_iam_policy_document.ecs-task-policy.json
}

data "aws_iam_policy_document" "ecs-task-policy" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      identifiers = ["ecs-tasks.amazonaws.com"]
      type = "Service"
    }
  }
}

resource "aws_iam_role_policy_attachment" "ecs-taskexec" {
  role = aws_iam_role.ecs-task-execution-role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

#This role is used by task to allow the container to be able to access AWS resources
resource "aws_iam_role" "ecs-task" {
  name = "ecs-task-role"
  assume_role_policy = data.aws_iam_policy_document.ecs-task-policy.json
}

// File: logging.tf
# We'll need it in the ECS to allow it to log into CloudWatch
# If logging to CloudWatch is not configured correctly ECS will work it will be just hell of a lot of much more difficult
# to find what caused problems.
resource "aws_cloudwatch_log_group" "ecs_log" {
  name = "/ecs/test-cluster"
}

// File: main.tf
#First -> configuring provider and backend

provider "aws" {
    region = "eu-central-1"
}

#In real use case we should configure S3 backend for Your cluster.tfstate file in examle like that (just S3 backend):
#cluster {
#    backend "s3" {
