}

variable "default_route_table_tags" {
  description = "Additional tags for the default route table"
  type        = map(string)
  default     = {}
}

################################################################################
# Flow Log
################################################################################
variable "aws_flow_logs" {
  description = "A map of maps describing what flow logs to create for each subnet"
